// ---- helpers reused by both runtime probe and smoke shim ----

// The application-level scheduler supports one, two and four windows in the
// same process. This remains a fixed native capacity so create failure is
// deterministic and no AppKit/Metal session table can grow without bound.
static const NSUInteger kCjguiSessionCapacity = 4;
static const NSTimeInterval kCjguiPumpTimeoutMaxSeconds = 0.016; // 16 ms bound
static BOOL CjguiIsMainThread(void);

// This is an operator-controlled diagnostic only. It deliberately logs before
// destination filtering so a failed cross-window drag can distinguish "AppKit
// never dispatched to this view" from a type/hit/identity rejection without
// changing any drag, FIFO or owner behavior.
static BOOL CjguiDataTransferTraceEnabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("CJGUI_DATA_TRANSFER_TRACE");
        enabled = value && strcmp(value, "1") == 0 ? 1 : 0;
    }
    return enabled != 0;
}

#ifdef CJGUI_INTERNAL_TESTING
static uint64_t CjguiMonotonicMicros(void) {
    static mach_timebase_info_data_t timebase;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ mach_timebase_info(&timebase); });
    uint64_t ticks = mach_continuous_time();
    return (ticks / 1000) * timebase.numer / MAX((uint32_t)1, timebase.denom);
}

static uint64_t CjguiSaturatingAddU64(uint64_t value, uint64_t delta) {
    return delta > UINT64_MAX - value ? UINT64_MAX : value + delta;
}
#else
// Interval probes are TESTING-only. Keep their call sites compile-time inert
// in the exported renderer rather than adding clock reads to production draw.
#define CjguiMonotonicMicros() 0ULL
#endif

@class CJGuiInternalComposableSceneNode;

enum { CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY = 4 };
// Apple documents a 4 KiB upper bound for setVertexBytes. This renderer uses
// it only for short-lived shape data, so split consecutive shape commands at
// that byte boundary rather than retaining a Metal buffer across frames. A
// triangle batches must remain whole to preserve painter ordering. Ordinary
// rectangles contribute six vertices; bounded vector geometry may contribute
// more but still splits only at complete-triangle boundaries.
enum {
    CJGUI_INTERNAL_METAL_SET_VERTEX_BYTES_CAPACITY = 4 * 1024,
    CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS = 12,
    CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS = 32,
};

enum {
    CJGUI_INTERNAL_VECTOR_LINE = 1,
    CJGUI_INTERNAL_VECTOR_POLYLINE = 2,
    CJGUI_INTERNAL_VECTOR_ELLIPSE = 3,
    CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON = 4,
    CJGUI_INTERNAL_VECTOR_CAP_BUTT = 1,
    CJGUI_INTERNAL_VECTOR_CAP_ROUND = 2,
    CJGUI_INTERNAL_VECTOR_CAP_SQUARE = 3,
    CJGUI_INTERNAL_VECTOR_JOIN_MITER = 1,
    CJGUI_INTERNAL_VECTOR_JOIN_BEVEL = 2,
    CJGUI_INTERNAL_VECTOR_JOIN_ROUND = 3,
};

#ifdef CJGUI_INTERNAL_TESTING
// Bounded attribution for real text bitmap/texture work. Unknown is retained
// as an honest bucket whenever a refresh cannot prove its triggering change.
typedef enum CjguiInternalTextWorkReason {
    CjguiInternalTextWorkReasonUnknown = 0,
    CjguiInternalTextWorkReasonStaticCandidate = 1,
    CjguiInternalTextWorkReasonActiveContent = 2,
    CjguiInternalTextWorkReasonSelectionCaret = 3,
    CjguiInternalTextWorkReasonVisibleTileScroll = 4,
    CjguiInternalTextWorkReasonRetry = 5,
    // A projection-driven geometry/scale change refreshed the focused input, or
    // an external owner replaced its value while focused. Without these buckets
    // such refreshes fall into Unknown and attribution cannot distinguish
    // static-candidate work from active work.
    CjguiInternalTextWorkReasonProjectionGeometry = 6,
    CjguiInternalTextWorkReasonExternalProjectionContent = 7,
    CjguiInternalTextWorkReasonCount = 8,
} CjguiInternalTextWorkReason;
typedef struct CjguiInternalTextWorkReasonCounters {
    uint64_t raster[CjguiInternalTextWorkReasonCount];
    uint64_t upload[CjguiInternalTextWorkReasonCount];
} CjguiInternalTextWorkReasonCounters;
#endif

typedef struct CJGuiInternalMetalVertex {
    vector_float2 position;
    vector_float2 scenePoint;
    vector_float2 localPoint;
    vector_float2 size;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    // Keep the count vector-aligned so the C and Metal layouts stay identical.
    vector_float4 clipCount;
    float cornerRadius;
    float borderWidth;
    // Shapes emitted for vector geometry already have exact triangle bounds;
    // the fragment still applies the shared rounded clip chain, but bypasses
    // the rectangle signed-distance/border calculation below.
    float isVectorShape;
    float vectorPadding;
    vector_float4 fill;
    vector_float4 border;
    // ---- P1 shape effects (vertex payload) ----
    // `passKind` selects the fragment path: 0 = ordinary fill/border quad,
    // 1 = outer shadow quad. A shadow vertex carries no gradient; it reuses
    // localPoint/size as the expanded shadow-shape SDF space and reads only
    // shadowBlurRadius/shadowColor. Gradient vertices carry the normalized
    // endpoints plus up to four stops (xyz = sRGB color, w of the parallel
    // alphas vector = stop alpha). Field order is mirrored verbatim in the
    // Metal struct inside `CjguiEncodeComposableNodes`.
    float passKind;
    float shadowBlurRadius;
    float gradientPresent;
    float gradientStopCount;
    vector_float2 gradientStart;
    vector_float2 gradientEnd;
    vector_float4 shadowColor;
    vector_float4 gradientStop0;
    vector_float4 gradientStop1;
    vector_float4 gradientStop2;
    vector_float4 gradientStop3;
    vector_float4 gradientStopAlphas;
} CJGuiInternalMetalVertex;

typedef struct CjguiInternalComposableVectorPoint {
    double x;
    double y;
} CjguiInternalComposableVectorPoint;

typedef struct CjguiInternalComposableVectorGeometry {
    uint32_t kind;
    uint32_t pointCount;
    uint32_t cap;
    uint32_t join;
    double viewBoxWidth;
    double viewBoxHeight;
    double strokeWidth;
    double fillRed, fillGreen, fillBlue, fillAlpha;
    double strokeRed, strokeGreen, strokeBlue, strokeAlpha;
    CjguiInternalComposableVectorPoint center;
    double radiusX;
    double radiusY;
    CjguiInternalComposableVectorPoint points[CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS];
    // Ear clipping is performed once when the copied scene payload changes.
    // Each triplet indexes `points`; a 12-point simple polygon has at most
    // ten triangles, so this remains a fixed 30-byte bound.
    uint8_t triangleIndices[(CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS - 2) * 3];
    uint32_t triangleIndexCount;
} CjguiInternalComposableVectorGeometry;

typedef struct CJGuiInternalMetalTextureVertex {
    vector_float2 position;
    vector_float2 texCoord;
    vector_float2 scenePoint;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
    vector_float4 nodeRect;
    float nodeCornerRadius;
    // Per-draw alpha multiplier applied to the sampled texel. Text glyph
    // textures are rasterized with an opaque colour so a dynamic opacity
    // animation changes this multiplier, not the cached texture; image quads
    // pass 1.0 and keep their texel alpha untouched.
    float paintAlpha;
} CJGuiInternalMetalTextureVertex;

@class CJGuiInternalComposableEffectTarget;

static BOOL CjguiEncodeComposableNodes(id view, id<MTLRenderCommandEncoder> encoder, CGSize drawableSize);
static uint32_t CjguiComposableClipConstraintCount(CjguiInternalRendererComposableNode value);
static void CjguiComposableClipConstraintAt(CjguiInternalRendererComposableNode value, uint32_t index,
                                             CGFloat *x, CGFloat *y, CGFloat *width, CGFloat *height, CGFloat *radius);

static uint8_t CjguiColorChannelToByte(double value) {
    if (value <= 0.0) return 0;
    if (value >= 1.0) return 255;
    return (uint8_t)(value * 255.0 + 0.5);
}

static BOOL CjguiColorByteMatches(uint8_t actual, uint8_t expected) {
    const int tolerance = 3;
    int delta = (int)actual - (int)expected;
    if (delta < 0) delta = -delta;
    return delta <= tolerance;
}

// ---- Metal view ----

@interface CJGuiInternalMetalView : NSView
// The session this view belongs to. Binds session-scoped presentation data
// (a node's style-run table) to the view that rasterizes it.
@property(nonatomic, assign) uint64_t sessionToken;
@property(nonatomic, strong) id<MTLDevice> device;
@property(nonatomic, strong) id<MTLCommandQueue> commandQueue;
@property(nonatomic, strong) CAMetalLayer *metalLayer;
@property(nonatomic, assign) BOOL invalidated;
@property(nonatomic, assign) BOOL readbackProbeCompleted;
@property(nonatomic, assign) uint64_t frameIndex;
@property(nonatomic, assign) CGSize lastSubmittedDrawableSize;
@property(nonatomic, assign) NSSize lastSubmittedPointSize;
@property(nonatomic, strong) id<MTLRenderPipelineState> composablePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableImagePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableVectorPipeline;
// Ordinary form/text/image scenes render directly to the drawable. A vector
// scene selects the matching reusable 4x states below for that frame only;
// a sample-count mismatch is not valid Metal pipeline reuse.
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisamplePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisampleImagePipeline;
@property(nonatomic, strong) id<MTLRenderPipelineState> composableMultisampleVectorPipeline;
@property(nonatomic, strong) id<MTLTexture> composableMultisampleTexture;
@property(nonatomic, assign) BOOL composableUsesMultisampling;
@property(nonatomic, strong) NSArray<CJGuiInternalComposableSceneNode *> *composableNodes;
// Only accepted groups are cached here. Candidate targets live on their
// staged node until presentation succeeds; in-flight command buffers retain
// their exact generation independently of later accepted replacements.
@property(nonatomic, strong) NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *effectGroupCache;
@property(nonatomic, strong) NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *backdropCache;
@property(nonatomic, strong) NSHashTable<CJGuiInternalComposableEffectTarget *> *effectTargetLedger;
// Transient collector for the current command buffer. The submitted callback
// takes an immutable copy of exactly the image textures encoded into it.
@property(nonatomic, strong) NSMutableArray<id<MTLTexture>> *encodedImageTextures;
@property(nonatomic, strong) NSMutableDictionary<NSString *, id<MTLRenderPipelineState>> *effectPipelines;
@property(nonatomic, strong) id<MTLComputePipelineState> backdropHorizontalPipeline;
@property(nonatomic, strong) id<MTLComputePipelineState> backdropVerticalPipeline;
#ifdef CJGUI_INTERNAL_TESTING
// A probe may select a controlled backing scale only to exercise the normal
// backing-properties notification route on a single-display machine. The
// production scale always comes from the attached NSWindow/NSScreen.
@property(nonatomic, assign) CGFloat testBackingScaleOverride;
// Scalar encoder work facts for the focused renderer probe.  They expose no
// Metal object and deliberately distinguish shape-node count from contiguous
// batch submissions and texture boundaries.
// 0 = capacity-bounded consecutive rectangles (production path), 1 = one
// complete rectangle per legal setVertexBytes submission (comparison path).
@property(nonatomic, assign) uint8_t testComposableShapeSubmissionMode;
@property(nonatomic, assign) uint32_t testComposableShapeNodeCount;
@property(nonatomic, assign) uint32_t testComposableShapeBatchCount;
@property(nonatomic, assign) uint32_t testComposableTextureDrawCount;
@property(nonatomic, assign) uint64_t testComposableShapeVertexBytes;
@property(nonatomic, assign) uint64_t testComposableMaxShapeBatchVertexBytes;
@property(nonatomic, assign) uint32_t testComposableShapeVertexStride;
// Wall time inside CjguiEncodeComposableNodes for this submitted frame. It is
// CPU encoder work only: it excludes command-buffer completion and display.
@property(nonatomic, assign) uint64_t testComposableEncoderCpuMicros;
// Direct per-frame native spans. The final readback field records only an
// explicit synchronous diagnostic wait, never asynchronous Metal completion.
@property(nonatomic, assign) uint64_t testComposableNextDrawableMicros;
@property(nonatomic, assign) uint64_t testComposableCommandBufferMicros;
@property(nonatomic, assign) uint64_t testComposablePresentMicros;
@property(nonatomic, assign) uint64_t testComposableCommitMicros;
@property(nonatomic, assign) uint64_t testComposableReadbackWaitMicros;
@property(nonatomic, assign) uint8_t testComposableReadbackWaited;
// These scalar diagnostics describe attachment ownership, lazy pipeline
// construction and accepted-node local vector preparation. They are not GPU
// completion or physical presentation timings.
@property(nonatomic, assign) uint8_t testComposableRenderSampleCount;
@property(nonatomic, assign) uint64_t testComposableMultisampleAttachmentBytes;
@property(nonatomic, assign) uint64_t testComposablePipelineBuildCount;
@property(nonatomic, assign) uint64_t testComposableVectorGeometryPreparationCount;
@property(nonatomic, assign) uint64_t testComposableVectorGeometryPreparedBytes;
// Latest-frame submission facts for the compact resident vector buffers.
// Uploads occur only when topology changes; reuses are ordinary paint/layout
// draws of a previously accepted immutable buffer.
@property(nonatomic, assign) uint32_t testComposableVectorDrawCount;
@property(nonatomic, assign) uint32_t testComposableVectorBufferUploadCount;
@property(nonatomic, assign) uint32_t testComposableVectorBufferReuseCount;
@property(nonatomic, assign) uint64_t testComposableVectorBufferUploadBytes;
// Text preparation is deliberately reported apart from command encoding:
// an AppKit bitmap raster and `replaceRegion` are real work with different
// owners and neither implies a completed/presented Metal frame.
@property(nonatomic, assign) uint64_t testComposableTextRasterCount;
@property(nonatomic, assign) uint64_t testComposableTextRasterBytes;
@property(nonatomic, assign) uint64_t testComposableTextRasterMicros;
@property(nonatomic, assign) uint64_t testComposableTextUploadCount;
@property(nonatomic, assign) uint64_t testComposableTextUploadBytes;
@property(nonatomic, assign) uint64_t testComposableTextUploadMicros;
@property(nonatomic, assign) CjguiInternalTextWorkReasonCounters testComposableTextWorkReasonCounters;
@property(nonatomic, assign) uint64_t testComposableTextLastProjectionVersion;
@property(nonatomic, assign) uint64_t testComposableTextLastContentUtf8Bytes;
// One candidate-only failure at the shared-layout boundary. The ordinary
// preparation-failure hook returns earlier and cannot exercise its nil guard.
@property(nonatomic, assign) BOOL testForceSharedTextLayoutNilOnce;
// Candidate text preparation's CPU scratch is the shared BGRA bitmap. It is
// allocated and released inside every raster; these counters make that visible
// instead of inferred. Current must return to zero after each raster; peak is
// a high-water mark and is reported separately from Metal texture bytes.
@property(nonatomic, assign) uint64_t testComposableTextCpuScratchCurrentBytes;
@property(nonatomic, assign) uint64_t testComposableTextCpuScratchPeakBytes;
// Sub-interval attribution. The per-reason raster counters are outer wall time
// per prepared node; the intervals below cover distinct sub-steps and MUST NOT
// be summed with them into a total.
@property(nonatomic, assign) uint64_t testComposableTextStaticDrawWithLayoutMicros;
@property(nonatomic, assign) uint64_t testComposableTextNormalizeMicros;
@property(nonatomic, assign) uint64_t testComposableTextTextureCreateMicros;
@property(nonatomic, assign) uint64_t testEffectTargetAllocationCount;
@property(nonatomic, assign) uint64_t testEffectTargetReuseCount;
@property(nonatomic, assign) uint64_t testEffectTargetCurrentBytes;
@property(nonatomic, assign) uint64_t testEffectTargetPeakBytes;
@property(nonatomic, assign) uint64_t testEffectContentRedrawCount;
@property(nonatomic, assign) uint64_t testEffectPassCount;
@property(nonatomic, assign) uint64_t testEffectCompositeDrawCount;
@property(nonatomic, assign) uint64_t testBackdropPrefixPassCount;
@property(nonatomic, assign) uint64_t testBackdropHorizontalPassCount;
@property(nonatomic, assign) uint64_t testBackdropVerticalPassCount;
@property(nonatomic, assign) uint64_t testBackdropCacheHitCount;
@property(nonatomic, assign) uint64_t testBackdropFallbackCount;
#endif
- (instancetype)initWithFrame:(NSRect)frame
                       device:(id<MTLDevice>)device
                 commandQueue:(id<MTLCommandQueue>)commandQueue;
- (void)updateDrawableSize;
- (void)invalidateBridgeResources;
- (BOOL)encodeComposableNodes:(id<MTLRenderCommandEncoder>)encoder drawableSize:(CGSize)drawableSize;
@end

#ifdef CJGUI_INTERNAL_TESTING
// Detailed glyph dumps are useful only when diagnosing text geometry. Keep
// default probe stderr scalar-friendly so concurrent runner output cannot
// corrupt performance samples. The opt-in is process-scoped and test-only.
static BOOL CjguiTestVerboseGlyphDiagnosticsEnabled(void) {
    return [NSProcessInfo.processInfo.environment[@"CJGUI_INTERNAL_VERBOSE_GLYPH_DIAGNOSTICS"] boolValue];
}
static BOOL CjguiTestTileCostDiagnosticsEnabled(void) {
    return [NSProcessInfo.processInfo.environment[@"CJGUI_INTERNAL_TRACE_TILE_COST"] boolValue];
}

static void CjguiRecordTextWork(CJGuiInternalMetalView *metalView,
                                uint64_t projectionVersion,
                                uint64_t contentUtf8Bytes,
                                CjguiInternalTextWorkReason reason) {
    if (!metalView) return;
    if (reason >= CjguiInternalTextWorkReasonCount) reason = CjguiInternalTextWorkReasonUnknown;
    // Objective-C struct properties are returned by value. Mutate a local
    // copy, then assign it back, so attribution is retained across events.
    CjguiInternalTextWorkReasonCounters counters = metalView.testComposableTextWorkReasonCounters;
    counters.raster[reason] = CjguiSaturatingAddU64(counters.raster[reason], 1);
    counters.upload[reason] = CjguiSaturatingAddU64(counters.upload[reason], 1);
    metalView.testComposableTextWorkReasonCounters = counters;
    metalView.testComposableTextLastProjectionVersion = projectionVersion;
    metalView.testComposableTextLastContentUtf8Bytes = contentUtf8Bytes;
}

// The shared BGRA bitmap is the only CPU staging a text raster owns. Bump on
// allocation and drop on every exit so `current` honestly returns to zero;
// `peak` records the high-water mark separately from Metal texture bytes.
static void CjguiAddTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) {
    if (!metalView || byteCount == 0) return;
    metalView.testComposableTextCpuScratchCurrentBytes = CjguiSaturatingAddU64(
        metalView.testComposableTextCpuScratchCurrentBytes, byteCount);
    if (metalView.testComposableTextCpuScratchCurrentBytes > metalView.testComposableTextCpuScratchPeakBytes) {
        metalView.testComposableTextCpuScratchPeakBytes = metalView.testComposableTextCpuScratchCurrentBytes;
    }
}

static void CjguiDropTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) {
    if (!metalView || byteCount == 0) return;
    if (metalView.testComposableTextCpuScratchCurrentBytes >= byteCount) {
        metalView.testComposableTextCpuScratchCurrentBytes -= byteCount;
    } else {
        metalView.testComposableTextCpuScratchCurrentBytes = 0;
    }
}
#else
__attribute__((unused)) static void CjguiAddTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) { (void)metalView; (void)byteCount; }
__attribute__((unused)) static void CjguiDropTextCpuScratch(CJGuiInternalMetalView *metalView, uint64_t byteCount) { (void)metalView; (void)byteCount; }
#endif

@implementation CJGuiInternalMetalView

- (CGFloat)currentBackingScale {
#ifdef CJGUI_INTERNAL_TESTING
    if (self.testBackingScaleOverride > 0.0) return self.testBackingScaleOverride;
#endif
    return self.window ? self.window.backingScaleFactor : NSScreen.mainScreen.backingScaleFactor;
}

- (instancetype)initWithFrame:(NSRect)frame
                       device:(id<MTLDevice>)device
                 commandQueue:(id<MTLCommandQueue>)commandQueue {
    self = [super initWithFrame:frame];
    if (!self || !device || !commandQueue) {
        return nil;
    }

    self.wantsLayer = YES;
    self.device = device;
    self.commandQueue = commandQueue;
    self.effectGroupCache = [NSMutableDictionary dictionary];
    self.backdropCache = [NSMutableDictionary dictionary];
    self.effectTargetLedger = [NSHashTable weakObjectsHashTable];
    self.effectPipelines = [NSMutableDictionary dictionary];

    self.metalLayer = [CAMetalLayer layer];
    if (!self.metalLayer) {
        return nil;
    }

    self.metalLayer.device = self.device;
    self.metalLayer.pixelFormat = MTLPixelFormatBGRA8Unorm;
    // Readback probe requires a blit-readable drawable.
    self.metalLayer.framebufferOnly = NO;
    self.metalLayer.opaque = NO;
    self.metalLayer.backgroundColor = NSColor.clearColor.CGColor;
    self.metalLayer.contentsScale = [self currentBackingScale];
    self.layer = self.metalLayer;
    [self updateDrawableSize];

    return self;
}

- (void)setFrameSize:(NSSize)newSize {
    [super setFrameSize:newSize];
    [self updateDrawableSize];
}

- (void)viewDidMoveToWindow {
    [super viewDidMoveToWindow];
    // The view overrides mouseMoved: to drive hover enter/leave, but AppKit only
    // delivers mouseMoved while the window opts in. Without this, hover was
    // observable ONLY on the mouseDown path (which calls updateHoverAtPoint
    // directly), so UI-only consumers saw no HOVER_ENTER/LEAVE on a plain move.
    if (self.window) {
        self.window.acceptsMouseMovedEvents = YES;
    }
    [self updateDrawableSize];
}

- (void)updateDrawableSize {
    if (!self.metalLayer || self.invalidated) {
        return;
    }
    CGFloat scale = [self currentBackingScale];
    CGSize pointSize = self.bounds.size;
    self.metalLayer.frame = self.bounds;
    self.metalLayer.contentsScale = scale;
    self.metalLayer.drawableSize = CGSizeMake(pointSize.width * scale,
                                              pointSize.height * scale);
}

- (void)invalidateBridgeResources {
    if (self.invalidated) {
        return;
    }
    self.invalidated = YES;
    self.layer = nil;
    self.metalLayer = nil;
    self.commandQueue = nil;
    self.device = nil;
    self.composableImagePipeline = nil;
    self.composablePipeline = nil;
    self.composableVectorPipeline = nil;
    self.composableMultisampleImagePipeline = nil;
    self.composableMultisamplePipeline = nil;
    self.composableMultisampleVectorPipeline = nil;
    self.composableMultisampleTexture = nil;
    self.composableUsesMultisampling = NO;
    [self.effectGroupCache removeAllObjects];
    [self.backdropCache removeAllObjects];
    self.effectPipelines = nil;
}

- (BOOL)encodeComposableNodes:(id<MTLRenderCommandEncoder>)encoder drawableSize:(CGSize)drawableSize {
    return CjguiEncodeComposableNodes(self, encoder, drawableSize);
}

@end

