@implementation CJGuiInternalSession

- (instancetype)init {
    self = [super init];
    if (!self) return nil;
    self.pendingInteractions = [NSMutableArray array];
    self.rangeTextEditDeltaDeliveryEnabled = NO;
    self.ownedTextSessionEnabled = NO;
    self.ownedTextSessionNodeId = 0;
    self.ownedTextSessionResourceId = -1;
    self.ownedTextSessionNodeKind = 0;
    self.ownedTextSessionBindingEpoch = 0;
    self.nextCompositionId = 0;
    self.composableNodes = [NSMutableArray array];
    self.stagedComposableNodes = [NSMutableArray array];
    self.composableDataTransferItems = [NSMutableArray array];
    self.stagedComposableDataTransferItems = [NSMutableArray array];
    self.composableCommandMenuItems = [NSMutableArray array];
    self.stagedComposableCommandMenuItems = [NSMutableArray array];
    self.pumpedFormText = @"";
    self.pumpedFormTextUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferFormat = @"";
    self.pumpedDataTransferFormatUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceKind = @"";
    self.pumpedDataTransferSourceKindUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceIdentity = @"";
    self.pumpedDataTransferSourceIdentityUtf8 = [NSData dataWithBytes:"" length:1];
    self.pumpedDataTransferSourceId = -1;
    self.observedMetalGpuDurationMicros = -1;
    return self;
}

- (BOOL)windowShouldClose:(id)sender {
    (void)sender;
    if (self.closeRequested) return YES;
    (void)CjguiEnqueueInteraction(self, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CLOSE,
                                  0, @"", 0, 0);
    NSLog(@"cjgui: user close deferred to collection domain");
    return NO;
}

- (void)windowWillClose:(NSNotification *)notification {
    (void)notification;
    if (!self.closeRequested) {
        self.closeRequested = YES;
        NSLog(@"cjgui: close requested: window");
    }
    NSLog(@"cjgui: window will close");
    CjguiRebuildComposableCommandMenuForKeyWindow();
}

- (void)windowDidBecomeKey:(NSNotification *)notification {
    (void)notification;
    self.windowBackgroundWindowActive = self.window.isKeyWindow && self.app.isActive;
    self.windowBackgroundEnvironmentRevision += 1;
    self.windowBackgroundObservationRevision += 1;
    CjguiRebuildComposableCommandMenuForKeyWindow();
}

- (void)windowDidResignKey:(NSNotification *)notification {
    (void)notification;
    self.windowBackgroundWindowActive = NO;
    self.windowBackgroundEnvironmentRevision += 1;
    self.windowBackgroundObservationRevision += 1;
    id overlay = self.composableSceneOverlay;
    if (overlay && [overlay respondsToSelector:@selector(cancelPointerCaptureForPlatformLoss)]) {
        [overlay performSelector:@selector(cancelPointerCaptureForPlatformLoss)];
    }
}

- (void)windowBackgroundEnvironmentDidChange:(NSNotification *)notification {
    (void)notification;
    BOOL reduce = CjguiWindowReduceTransparency(self);
    BOOL active = self.window.isKeyWindow && self.app.isActive;
    if (reduce != self.windowBackgroundReduceTransparency || active != self.windowBackgroundWindowActive) {
        self.windowBackgroundReduceTransparency = reduce;
        self.windowBackgroundWindowActive = active;
        self.windowBackgroundEnvironmentRevision += 1;
        self.windowBackgroundObservationRevision += 1;
    }
    if (reduce && self.windowBackgroundHostAppliedSystem) {
        self.windowMaterialView.hidden = YES;
        self.windowOpaqueFallbackView.hidden = NO;
        self.windowBackgroundHostAppliedSystem = NO;
        self.windowBackgroundActualMode = 2;
        self.windowBackgroundFallbackReason = 2;
        self.windowBackgroundObservationRevision += 1;
    }
}

- (void)windowDidResize:(NSNotification *)notification {
    (void)notification;
    [self windowGeometryDidChange];
}

- (void)windowDidChangeBackingProperties:(NSNotification *)notification {
    if (notification.object != self.window) return;
    [self windowGeometryDidChange];
}

- (void)windowGeometryDidChange {
    self.resizeVersion += 1;
    [self.view updateDrawableSize];
    if (self.composableSceneOverlay) {
        (void)CjguiEnqueueComposableInteraction(self, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_RESIZED,
                                                0, @"", NSMakeRange(0, 0));
    }
}

@end

// The fixed session table is also the only application-domain membership
// index. Resource helpers use it for bounded, non-retaining inspection of
// live sessions; no process-global application-data dictionary is created.
static CJGuiInternalSession *gCjguiSessions[4];
static BOOL gCjguiSessionOccupied[4];
static uint64_t gCjguiNextSessionGeneration = 1;
static char CJGuiSessionWindowAssociationKey;
static BOOL gCjguiMainThreadDispatchEnabled;
// Standard Quit may reach AppKit several times before the Cangjie application
// worker gets its next bounded turn. Retain only one process-level intent;
// completion is acknowledged by that owner after it accepts or rejects.
static _Atomic(bool) gCjguiApplicationExitRequestPending;
static _Atomic(bool) gCjguiApplicationExitRequestWasUnkeyed;
static _Atomic(uint32_t) gCjguiApplicationExitLifecycleOwnerCount;

// Modifier state belongs to the pointer gesture that produced an intent, not
// to the session. An activation queued by a mouse press/complete carries the
// modifiers observed for that gesture; a keyboard or accessibility activation
// carries none, so it can never inherit the Command/Shift of an earlier mouse
// click. `session.pointerModifierFlags` is still refreshed by every pointer
// event, and only pointer-originated enqueues copy it onto their own intent.
static void CjguiStampPointerModifiersOnQueuedInteraction(CJGuiInternalSession *session,
                                                          uint32_t kind, uint32_t nodeIndex) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    last.modifierFlags = session.pointerModifierFlags;
}

// The same rule for keyboard-produced intents: a navigation/select-all queued
// by a keyDown carries the modifiers observed on THAT key event (Shift extends
// a range, Command selects all), while a programmatic or accessibility enqueue
// keeps zero and can never inherit an earlier gesture's state.
// A mouse-down on a pointer-reporting, non-input node must carry WHERE it
// happened: the controller resolves the display offset from that point through
// the framework's hit test, so an ACTIVATE without coordinates is useless.
static void CjguiStampPointerPositionOnQueuedInteraction(CJGuiInternalSession *session,
                                                         uint32_t kind, uint32_t nodeIndex,
                                                         NSPoint point) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    last.pointerX = (int64_t)llround(point.x);
    last.pointerY = (int64_t)llround(point.y);
}

static void CjguiStampKeyboardModifiersOnQueuedInteraction(CJGuiInternalSession *session,
                                                           uint32_t kind, uint32_t nodeIndex,
                                                           NSEventModifierFlags flags) {
    if (!session || session.destroyed) return;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (!last || last.kind != kind || last.recordIndex != nodeIndex) return;
    last.modifierFlags = (int64_t)flags;
}

// Consecutive text notifications for one field are a single logical input
// stream and may be coalesced. No focus, button, checkbox or cross-field
// boundary is crossed, so an Apply always remains after the text it applies.
// Once full, the queue refuses the new interaction and schedules an explicit
// retry notice instead of overwriting an already accepted event.
static BOOL CjguiEnqueueInteraction(CJGuiInternalSession *session,
                                    uint32_t kind, uint32_t recordIndex,
                                    NSString *formText,
                                    uint32_t selectionStart,
                                    uint32_t selectionEnd) {
    if (!session || session.destroyed) return NO;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_TEXT_CHANGED &&
        last && last.kind == kind && last.recordIndex == recordIndex) {
        last.selectionStart = selectionStart;
        last.selectionEnd = selectionEnd;
        last.formText = [formText copy] ?: @"";
        return YES;
    }
    if (session.pendingInteractions.count >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind
                                                  recordIndex:recordIndex
                                               selectionStart:selectionStart
                                                 selectionEnd:selectionEnd
                                                     formText:formText nodeId:0 projectionVersion:0 resourceId:-1 nodeKind:0];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    // Ordinary form input may arrive from a mouse click as well as from the
    // keyboard/AX proxy; it carries no pointer-gesture modifiers.
    interaction.modifierFlags = 0;
    [session.pendingInteractions addObject:interaction];
    return YES;
}

static BOOL CjguiEnqueueComposableInteraction(CJGuiInternalSession *session,
                                              uint32_t kind, uint32_t nodeIndex,
                                              NSString *text, NSRange selection) {
    if (!session || session.destroyed) return NO;
    uint64_t nodeId = 0;
    int64_t resourceId = -1;
    uint32_t nodeKind = 0;
    if (kind != CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_RESIZED) {
        if (nodeIndex >= session.composableNodes.count) return NO;
        nodeId = CjguiComposableNodeIdAtIndex(session, nodeIndex);
        resourceId = CjguiComposableNodeResourceIdAtIndex(session, nodeIndex);
        nodeKind = CjguiComposableNodeKindAtIndex(session, nodeIndex);
        if (nodeId == 0) return NO;
    }
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    if ((kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED ||
         kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED) &&
        last && last.kind == kind && last.recordIndex == nodeIndex &&
        last.nodeId == nodeId &&
        last.projectionVersion == session.composableSceneVersion &&
        last.resourceId == resourceId && last.nodeKind == nodeKind) {
        last.selectionStart = (uint32_t)MIN(selection.location, UINT32_MAX);
        last.selectionEnd = (uint32_t)MIN(NSMaxRange(selection), UINT32_MAX);
        last.formText = [text copy] ?: @"";
        return YES;
    }
    if (session.pendingInteractions.count >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind recordIndex:nodeIndex
                                               selectionStart:(uint32_t)MIN(selection.location, UINT32_MAX)
                                                 selectionEnd:(uint32_t)MIN(NSMaxRange(selection), UINT32_MAX)
                                                     formText:text nodeId:nodeId projectionVersion:session.composableSceneVersion
                                                   resourceId:resourceId nodeKind:nodeKind];
    if (!interaction) { session.pendingInputQueueFullNotice = YES; return NO; }
    // Non-pointer enqueue: a keyboard/AX activation, focus transfer or
    // declared shortcut must not inherit an earlier mouse gesture's modifiers.
    // Pointer-originated intents are stamped by their own handler.
    interaction.modifierFlags = 0;
    [session.pendingInteractions addObject:interaction];
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = kind;
    session.testComposableLastEnqueuedNodeId = nodeId;
    session.testComposableLastEnqueuedProjectionVersion = session.composableSceneVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

static BOOL CjguiEnqueueCompositionPhase(CJGuiInternalSession *session, uint32_t phase,
                                         uint32_t nodeIndex, NSString *text, NSRange inner,
                                         int64_t replacementStart, int64_t replacementLength,
                                         int64_t markedStart, int64_t markedLength,
                                         uint64_t compositionId, uint64_t bindingEpoch) {
    if (!session || session.destroyed) return NO;
    if (session.pendingInteractions.count >= kCjguiPendingInteractionCapacity) {
        // A dropped terminal is never treated as delivered: the same notice the
        // ordinary path raises tells the owner the edit did not reach it.
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_COMPOSITION
            recordIndex:nodeIndex
            selectionStart:(uint32_t)MIN(inner.location, UINT32_MAX)
            selectionEnd:(uint32_t)MIN(NSMaxRange(inner), UINT32_MAX)
            formText:text
            nodeId:CjguiComposableNodeIdAtIndex(session, nodeIndex)
            projectionVersion:session.composableSceneVersion
            resourceId:CjguiComposableNodeResourceIdAtIndex(session, nodeIndex)
            nodeKind:CjguiComposableNodeKindAtIndex(session, nodeIndex)];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    interaction.modifierFlags = 0;
    interaction.compositionPhase = phase;
    interaction.replacementStart16 = replacementStart;
    interaction.replacementLength16 = replacementLength;
    interaction.markedStart16 = markedStart;
    interaction.markedLength16 = markedLength;
    interaction.compositionId = compositionId;
    interaction.bindingEpoch = bindingEpoch;
    [session.pendingInteractions addObject:interaction];
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = interaction.kind;
    session.testComposableLastEnqueuedNodeId = interaction.nodeId;
    session.testComposableLastEnqueuedProjectionVersion = session.composableSceneVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

// Bodies live after the overlay/scene-node interfaces; these forward
// declarations keep the enqueue helpers in their existing section.
static NSInteger CjguiIndexOfComposableNodeIdentity(CJGuiInternalComposableSceneOverlay *overlay,
                                                    uint64_t nodeId, int64_t resourceId,
                                                    uint32_t nodeKind);
static BOOL CjguiEmitProxyCompositionPhase(CJGuiInternalComposableInputProxy *proxy, uint32_t phase,
                                           NSString *text, NSRange inner, NSRange replacement,
                                           NSRange marked);

// The text an NSTextInputClient argument carries. The protocol declares `id`
// because an attributed string is allowed for richer input; the composition
// record always needs its plain string.
static NSString *CjguiInputArgumentText(id string) {
    if ([string isKindOfClass:[NSAttributedString class]]) return [(NSAttributedString *)string string];
    if ([string isKindOfClass:[NSString class]]) return (NSString *)string;
    return nil;
}

// AppKit resolves a not-specified replacement range BEFORE mutating: the
// current marked range while composing, otherwise the selection. Recording the
// resolution keeps the session's frozen owner range comparable with what the
// platform actually replaces.
static NSRange CjguiResolvedPlatformReplacement(NSTextView *proxy, NSRange replacementRange) {
    if (replacementRange.location != NSNotFound) return replacementRange;
    if (proxy.hasMarkedText) return proxy.markedRange;
    return proxy.selectedRange;
}

#ifdef CJGUI_INTERNAL_TESTING
static uint64_t CjguiTestUtf8ByteCount(NSString *value) {
    NSData *bytes = [(value ?: @"") dataUsingEncoding:NSUTF8StringEncoding];
    return bytes ? (uint64_t)bytes.length : 0;
}

static BOOL CjguiTestIsDataTransferKind(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_COPY ||
        kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_PASTE ||
        kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_DROP;
}

static uint64_t CjguiTestTransferItemRetainedBytes(CJGuiInternalComposableDataTransferItem *item) {
    if (!item) return 0;
    return CjguiTestUtf8ByteCount(item.format) + CjguiTestUtf8ByteCount(item.payload) +
        item.binaryPayload.length +
        CjguiTestUtf8ByteCount(item.sourceKind) + CjguiTestUtf8ByteCount(item.sourceIdentity);
}

static uint64_t CjguiTestTransferSourcePayloadBytes(NSArray<CJGuiInternalComposableDataTransferItem *> *items) {
    uint64_t total = 0;
    for (CJGuiInternalComposableDataTransferItem *item in items) {
        if (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE) {
            total += CjguiTestUtf8ByteCount(item.payload) + item.binaryPayload.length;
        }
    }
    return total;
}

static uint64_t CjguiTestTransferDeclarationBytes(NSArray<CJGuiInternalComposableDataTransferItem *> *items) {
    uint64_t total = 0;
    for (CJGuiInternalComposableDataTransferItem *item in items) {
        total += CjguiTestTransferItemRetainedBytes(item);
    }
    return total;
}

static uint64_t CjguiTestTransferFifoBytes(CJGuiInternalSession *session, uint32_t *outEvents) {
    uint64_t total = 0;
    uint32_t events = 0;
    if (session) {
        for (CJGuiInternalQueuedInteraction *interaction in session.pendingInteractions) {
            if (!CjguiTestIsDataTransferKind(interaction.kind)) continue;
            events += 1;
            total += CjguiTestUtf8ByteCount(interaction.formText) + interaction.dataTransferBytes.length +
                CjguiTestUtf8ByteCount(interaction.dataTransferFormat) +
                CjguiTestUtf8ByteCount(interaction.dataTransferSourceKind) +
                CjguiTestUtf8ByteCount(interaction.dataTransferSourceIdentity);
        }
    }
    if (outEvents) *outEvents = events;
    return total;
}

static void CjguiUpdateTestDataTransferRetentionPeaks(CJGuiInternalSession *session) {
    if (!session) return;
    uint64_t source = CjguiTestTransferSourcePayloadBytes(session.composableDataTransferItems);
    uint64_t accepted = CjguiTestTransferDeclarationBytes(session.composableDataTransferItems);
    uint64_t candidate = CjguiTestTransferDeclarationBytes(session.stagedComposableDataTransferItems);
    uint32_t fifoEvents = 0;
    uint64_t fifoBytes = CjguiTestTransferFifoBytes(session, &fifoEvents);
    session.testDataTransferSourcePeakBytes = MAX(session.testDataTransferSourcePeakBytes, source);
    session.testDataTransferAcceptedPeakBytes = MAX(session.testDataTransferAcceptedPeakBytes, accepted);
    session.testDataTransferCandidatePeakBytes = MAX(session.testDataTransferCandidatePeakBytes, candidate);
    session.testDataTransferFifoPeakEvents = (uint32_t)MIN(UINT32_MAX,
        MAX((NSUInteger)session.testDataTransferFifoPeakEvents, (NSUInteger)fifoEvents));
    session.testDataTransferFifoPeakBytes = MAX(session.testDataTransferFifoPeakBytes, fifoBytes);
}
#endif

// ---- generic composable-scene data and native projection ----

static const NSUInteger CjguiComposableImageTextureCacheCapacity = 8;
static const NSUInteger CjguiComposableImageTextureCacheByteCapacity = 32u * 1024u * 1024u;
static const NSUInteger CjguiComposableImageInFlightCapacity = 4;
static const NSUInteger CjguiComposableImagePendingCapacity = 16;
static const NSUInteger CjguiComposableImageRecordCapacity = 64;
// Text is derived presentation, not document storage.  Keep a single scene
// bounded even when a malformed projection supplies enormous logical bounds.
// A Retina normal Host can expose several dozen short text rows at once.
// 24 MiB stays explicitly bounded (and below the existing image-cache
// envelope) while admitting that ordinary 256-node viewport during resize.
// A 1000x400pt editor is 6.4 MiB at 2x, so a 4 MiB per-tile limit rejected a
// normal fully visible editor.  Keep one CPU bitmap + one scene texture
// bounded at 8 MiB; the scene admission check still caps all live text at
// 24 MiB rather than letting individual controls grow without limit.
static const NSUInteger CjguiComposableTextTextureByteCapacity = 24u * 1024u * 1024u;
static const NSUInteger CjguiComposableTextTexturePerNodeByteCapacity = 8u * 1024u * 1024u;
static const NSUInteger CjguiComposableTextTextureDimensionCapacity = 4096u;

// A group target is an immutable content generation once submitted. Its
// resolved texture holds premultiplied BGRA8Unorm pixels; a 4x attachment is
// retained only when the scene contains vectors. No pool is used in P4: reuse
// means the accepted content target was proven unchanged, never that a retired
// in-flight allocation was recycled for different pixels.
@interface CJGuiInternalComposableEffectTarget : NSObject
@property(nonatomic, strong) id<MTLTexture> resolvedTexture;
@property(nonatomic, strong) id<MTLTexture> multisampleTexture;
@property(nonatomic, copy) NSString *contentSignature;
@property(nonatomic, assign) uint32_t pixelX;
@property(nonatomic, assign) uint32_t pixelY;
@property(nonatomic, assign) uint32_t pixelWidth;
@property(nonatomic, assign) uint32_t pixelHeight;
// Exact backdrop dependency halo used when this target was allocated. A
// cache hit retains these facts rather than recomputing them at read time.
@property(nonatomic, assign) uint32_t samplePixelX;
@property(nonatomic, assign) uint32_t samplePixelY;
@property(nonatomic, assign) uint32_t samplePixelWidth;
@property(nonatomic, assign) uint32_t samplePixelHeight;
@property(nonatomic, assign) uint64_t lastRedrawnFrameIndex;
@property(nonatomic, assign) uint64_t byteCount;
@property(nonatomic, assign) BOOL needsRedraw;
@property(nonatomic, assign) BOOL invalidatedByGpuFailure;
// A completion callback can run off the main thread before its main-queue
// bookkeeping turn. The atomic one-way success bit admits safe cache hits
// without blocking a following main-thread frame on that bookkeeping turn.
@property(atomic, assign) BOOL gpuCompleted;
@end

@implementation CJGuiInternalComposableEffectTarget
@end

typedef NS_ENUM(uint32_t, CjguiComposableImageResourceState) {
    CjguiComposableImageResourceUnrequested = 0,
    CjguiComposableImageResourceLoading = 1,
    CjguiComposableImageResourceReady = 2,
    CjguiComposableImageResourceFailed = 3,
    // Admission is temporarily full. This is not a file/decode failure;
    // visible scene references are promoted fairly by the next completion.
    CjguiComposableImageResourceBusy = 4,
};

@class CjguiPreparedTextNodeLayout;   // 2026-09-26 B2:accepted 文本几何索引(前置声明)

@interface CJGuiInternalComposableSceneNode : NSObject
// The style-run string this node was last staged with. It belongs in the text
// texture key, otherwise a run-only change reuses the previous texture.
@property(nonatomic, copy) NSString *styleRunsSignature;
@property(nonatomic, assign) CjguiInternalRendererComposableNode node;
@property(nonatomic, copy) NSString *label;
@property(nonatomic, copy) NSString *value;
// The accepted public semantic identity of this node. It is the exact address a
// human-facing driver or assistant uses to target one instance; the rendered
// label is a projection and two instances can share a caption.
@property(nonatomic, copy) NSString *semanticId;
@property(nonatomic, copy) NSString *semanticBindingKey;
@property(nonatomic, copy) NSString *semanticRowKey;
@property(nonatomic, copy) NSString *semanticParentRowKey;
@property(nonatomic, copy) NSString *semanticLabel;
@property(nonatomic, copy) NSString *imageResourcePath;
@property(nonatomic, copy) NSData *imageEncodedData;
@property(nonatomic, copy) NSString *imageResourceId;
@property(nonatomic, assign) uint64_t imageResourceVersion;
// The declared key can advance while an old texture is intentionally retained
// as a loading fallback. Keep the actual texture provenance separate so a
// cache eviction never relabels that old texture as the new declaration.
@property(nonatomic, copy) NSString *imageTextureCacheKey;
@property(nonatomic, copy) NSString *imageTextureContentKey;
@property(nonatomic, strong) id<MTLTexture> imageTexture;
// Raster text is an implementation-local GPU resource.  It contains no
// writable document state: the composable overlay retains the sole TextKit
// input proxy and redraws this immutable projection when content/style/scale
// changes.
@property(nonatomic, copy) NSString *textTextureCacheKey;
@property(nonatomic, strong) id<MTLTexture> textTexture;
// A large visible text area is split into independently bounded texture
// allocations. Small controls continue to use textTexture directly.
@property(nonatomic, copy) NSArray<id<MTLTexture>> *textTileTextures;
@property(nonatomic, copy) NSArray<NSValue *> *textTileRects;
@property(nonatomic, assign) uint64_t textTextureByteCount;
// Logical scene rectangle represented by textTexture. It may be a clipped
// tile of the node rather than the whole node bounds.
@property(nonatomic, assign) NSRect textTextureRect;
// Selection, marked-range and caret pixels are presentation-only geometry.
// They stay in the scene node's existing clip chain and sandwich the immutable
// body texture in painter order, so a caret move never allocates/reuploads the
// body tile or adds a second text/layout owner.
@property(nonatomic, copy) NSArray<NSValue *> *textSelectionRects;
@property(nonatomic, copy) NSArray<NSValue *> *textMarkedRects;
@property(nonatomic, assign) NSRect textCaretRect;
// Distinguishes the caret the OWNER declared (accepted-layout geometry, drawn in the
// node's own text colour) from the one the hidden proxy derived for itself (accent
// colour). Both live in `textCaretRect`; only their presentation differs.
@property(nonatomic, assign) BOOL textCaretIsDeclared;
@property(nonatomic, assign) NSRect textScrollbarRect;
@property(nonatomic, assign) uint32_t index;
@property(nonatomic, strong) CJGuiInternalComposableEffectTarget *effectTarget;
@property(nonatomic, strong) CJGuiInternalComposableEffectTarget *backdropTarget;
// Parsed once from the existing copied `value` string. The retained struct is
// pure scalar geometry, not a Cangjie pointer, Metal buffer or AppKit object.
@property(nonatomic, assign) BOOL hasVectorGeometry;
@property(nonatomic, assign) CjguiInternalComposableVectorGeometry vectorGeometry;
// Accepted-node cache: local fill/stroke triangles only. It intentionally
// excludes paint, layout, clip and backing scale so a color/local projection
// update can reuse preparation while the normal encoder reapplies its current
// transform and clip chain.
@property(nonatomic, copy) NSData *vectorPreparedTriangles;
@property(nonatomic, assign) BOOL hasVectorPreparedGeometry;
@property(nonatomic, assign) CjguiInternalComposableVectorGeometry vectorPreparedGeometry;

// 2026-09-26(B2):把**候选准备期的排版产物**持留在节点上,使其在 accept 后仍可被**只读查询**
// (契约 implementation order 1–2:随 accept 发布不可变几何索引;查询不得新建临时布局)。
// 与既有 vectorPreparedTriangles(:1427)同法,纯附加、不改既有函数体。
@property(nonatomic, strong) CjguiPreparedTextNodeLayout *preparedTextLayout;
// The buffer is native-only and COW-shared with an unchanged accepted node.
// `present_clear` retains its submitted node array through command-buffer
// completion, so a later geometry replacement cannot release an in-flight
// buffer generation.
@property(nonatomic, strong) id<MTLBuffer> vectorPreparedVertexBuffer;
@property(nonatomic, assign) NSUInteger vectorPreparedVertexCount;
@property(nonatomic, assign) NSUInteger vectorPreparedVertexBytes;
@end

@implementation CJGuiInternalComposableSceneNode
@end

static const double CjguiComposableVectorEpsilon = 1.0e-9;
static const double CjguiComposableVectorMiterLimit = 4.0;

static BOOL CjguiComposableVectorFiniteUnit(double value) {
    return isfinite(value) && value >= 0.0 && value <= 1.0;
}

static BOOL CjguiComposableVectorParseDouble(NSString *token, double *outValue) {
    if (!token || !outValue) return NO;
    const char *bytes = token.UTF8String;
    if (!bytes || bytes[0] == '\0') return NO;
    char *end = NULL;
    double value = strtod(bytes, &end);
    if (!end || end == bytes || *end != '\0' || !isfinite(value)) return NO;
    *outValue = value;
    return YES;
}

static BOOL CjguiComposableVectorParseUInt(NSString *token, uint32_t *outValue) {
    double value = 0.0;
    if (!outValue || !CjguiComposableVectorParseDouble(token, &value) || value < 0.0 ||
        value > (double)UINT32_MAX || floor(value) != value) return NO;
    *outValue = (uint32_t)value;
    return YES;
}

static double CjguiComposableVectorCross(CjguiInternalComposableVectorPoint a,
                                         CjguiInternalComposableVectorPoint b,
                                         CjguiInternalComposableVectorPoint c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static BOOL CjguiComposableVectorSamePoint(CjguiInternalComposableVectorPoint a,
                                           CjguiInternalComposableVectorPoint b) {
    return a.x == b.x && a.y == b.y;
}

static BOOL CjguiComposableVectorPointInViewBox(CjguiInternalComposableVectorPoint point,
                                                CjguiInternalComposableVectorGeometry geometry) {
    return isfinite(point.x) && isfinite(point.y) && point.x >= 0.0 && point.y >= 0.0 &&
        point.x <= geometry.viewBoxWidth && point.y <= geometry.viewBoxHeight;
}

static BOOL CjguiComposableVectorBetween(double value, double first, double second) {
    return value >= MIN(first, second) && value <= MAX(first, second);
}

static BOOL CjguiComposableVectorSegmentsIntersect(CjguiInternalComposableVectorPoint a,
                                                   CjguiInternalComposableVectorPoint b,
                                                   CjguiInternalComposableVectorPoint c,
                                                   CjguiInternalComposableVectorPoint d) {
    double abC = CjguiComposableVectorCross(a, b, c);
    double abD = CjguiComposableVectorCross(a, b, d);
    double cdA = CjguiComposableVectorCross(c, d, a);
    double cdB = CjguiComposableVectorCross(c, d, b);
    if (fabs(abC) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(c.x, a.x, b.x) &&
        CjguiComposableVectorBetween(c.y, a.y, b.y)) return YES;
    if (fabs(abD) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(d.x, a.x, b.x) &&
        CjguiComposableVectorBetween(d.y, a.y, b.y)) return YES;
    if (fabs(cdA) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(a.x, c.x, d.x) &&
        CjguiComposableVectorBetween(a.y, c.y, d.y)) return YES;
    if (fabs(cdB) <= CjguiComposableVectorEpsilon && CjguiComposableVectorBetween(b.x, c.x, d.x) &&
        CjguiComposableVectorBetween(b.y, c.y, d.y)) return YES;
    return ((abC > 0.0 && abD < 0.0) || (abC < 0.0 && abD > 0.0)) &&
        ((cdA > 0.0 && cdB < 0.0) || (cdA < 0.0 && cdB > 0.0));
}

static BOOL CjguiComposableVectorPointInTriangle(CjguiInternalComposableVectorPoint point,
                                                 CjguiInternalComposableVectorPoint a,
                                                 CjguiInternalComposableVectorPoint b,
                                                 CjguiInternalComposableVectorPoint c,
                                                 double winding) {
    double first = CjguiComposableVectorCross(a, b, point) * winding;
    double second = CjguiComposableVectorCross(b, c, point) * winding;
    double third = CjguiComposableVectorCross(c, a, point) * winding;
    return first >= -CjguiComposableVectorEpsilon && second >= -CjguiComposableVectorEpsilon &&
        third >= -CjguiComposableVectorEpsilon;
}

static BOOL CjguiComposableVectorTriangulate(CjguiInternalComposableVectorGeometry *geometry) {
    if (!geometry || geometry->kind != CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ||
        geometry->pointCount < 3 || geometry->pointCount > CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS) return NO;
    double signedArea = 0.0;
    for (uint32_t index = 0; index < geometry->pointCount; index++) {
        uint32_t next = index + 1 == geometry->pointCount ? 0 : index + 1;
        signedArea += geometry->points[index].x * geometry->points[next].y -
            geometry->points[next].x * geometry->points[index].y;
    }
    if (fabs(signedArea) <= CjguiComposableVectorEpsilon) return NO;
    double winding = signedArea > 0.0 ? 1.0 : -1.0;
    uint8_t remaining[CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS] = {0};
    uint32_t remainingCount = geometry->pointCount;
    for (uint32_t index = 0; index < remainingCount; index++) remaining[index] = (uint8_t)index;
    geometry->triangleIndexCount = 0;
    while (remainingCount > 3) {
        BOOL foundEar = NO;
        for (uint32_t position = 0; position < remainingCount; position++) {
            uint32_t before = position == 0 ? remainingCount - 1 : position - 1;
            uint32_t after = position + 1 == remainingCount ? 0 : position + 1;
            uint8_t first = remaining[before];
            uint8_t middle = remaining[position];
            uint8_t last = remaining[after];
            CjguiInternalComposableVectorPoint a = geometry->points[first];
            CjguiInternalComposableVectorPoint b = geometry->points[middle];
            CjguiInternalComposableVectorPoint c = geometry->points[last];
            if (CjguiComposableVectorCross(a, b, c) * winding <= CjguiComposableVectorEpsilon) continue;
            BOOL containsOther = NO;
            for (uint32_t candidate = 0; candidate < remainingCount; candidate++) {
                uint8_t candidateIndex = remaining[candidate];
                if (candidateIndex == first || candidateIndex == middle || candidateIndex == last) continue;
                if (CjguiComposableVectorPointInTriangle(geometry->points[candidateIndex], a, b, c, winding)) {
                    containsOther = YES;
                    break;
                }
            }
            if (containsOther) continue;
            if (geometry->triangleIndexCount + 3 > sizeof(geometry->triangleIndices)) return NO;
            geometry->triangleIndices[geometry->triangleIndexCount++] = first;
            geometry->triangleIndices[geometry->triangleIndexCount++] = middle;
            geometry->triangleIndices[geometry->triangleIndexCount++] = last;
            for (uint32_t shift = position; shift + 1 < remainingCount; shift++) remaining[shift] = remaining[shift + 1];
            remainingCount -= 1;
            foundEar = YES;
            break;
        }
        if (!foundEar) return NO;
    }
    if (geometry->triangleIndexCount + 3 > sizeof(geometry->triangleIndices)) return NO;
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[0];
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[1];
    geometry->triangleIndices[geometry->triangleIndexCount++] = remaining[2];
    return YES;
}

static BOOL CjguiParseComposableVectorGeometry(NSString *payload,
                                               CjguiInternalComposableVectorGeometry *outGeometry) {
    if (!payload || !outGeometry) return NO;
    NSArray<NSString *> *parts = [payload componentsSeparatedByString:@";"];
    if (parts.count < 20 || ![parts[0] isEqualToString:@"cg1"]) return NO;
    CjguiInternalComposableVectorGeometry geometry = {0};
    if (!CjguiComposableVectorParseUInt(parts[1], &geometry.kind) ||
        !CjguiComposableVectorParseDouble(parts[2], &geometry.viewBoxWidth) ||
        !CjguiComposableVectorParseDouble(parts[3], &geometry.viewBoxHeight) ||
        !CjguiComposableVectorParseDouble(parts[4], &geometry.strokeWidth) ||
        !CjguiComposableVectorParseUInt(parts[5], &geometry.cap) ||
        !CjguiComposableVectorParseUInt(parts[6], &geometry.join) ||
        !CjguiComposableVectorParseDouble(parts[7], &geometry.fillRed) ||
        !CjguiComposableVectorParseDouble(parts[8], &geometry.fillGreen) ||
        !CjguiComposableVectorParseDouble(parts[9], &geometry.fillBlue) ||
        !CjguiComposableVectorParseDouble(parts[10], &geometry.fillAlpha) ||
        !CjguiComposableVectorParseDouble(parts[11], &geometry.strokeRed) ||
        !CjguiComposableVectorParseDouble(parts[12], &geometry.strokeGreen) ||
        !CjguiComposableVectorParseDouble(parts[13], &geometry.strokeBlue) ||
        !CjguiComposableVectorParseDouble(parts[14], &geometry.strokeAlpha) ||
        !CjguiComposableVectorParseDouble(parts[15], &geometry.center.x) ||
        !CjguiComposableVectorParseDouble(parts[16], &geometry.center.y) ||
        !CjguiComposableVectorParseDouble(parts[17], &geometry.radiusX) ||
        !CjguiComposableVectorParseDouble(parts[18], &geometry.radiusY) ||
        !CjguiComposableVectorParseUInt(parts[19], &geometry.pointCount)) return NO;
    if (geometry.kind < CJGUI_INTERNAL_VECTOR_LINE || geometry.kind > CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ||
        geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0 || geometry.strokeWidth < 0.0 ||
        geometry.cap < CJGUI_INTERNAL_VECTOR_CAP_BUTT || geometry.cap > CJGUI_INTERNAL_VECTOR_CAP_SQUARE ||
        geometry.join < CJGUI_INTERNAL_VECTOR_JOIN_MITER || geometry.join > CJGUI_INTERNAL_VECTOR_JOIN_ROUND ||
        !CjguiComposableVectorFiniteUnit(geometry.fillRed) || !CjguiComposableVectorFiniteUnit(geometry.fillGreen) ||
        !CjguiComposableVectorFiniteUnit(geometry.fillBlue) || !CjguiComposableVectorFiniteUnit(geometry.fillAlpha) ||
        !CjguiComposableVectorFiniteUnit(geometry.strokeRed) || !CjguiComposableVectorFiniteUnit(geometry.strokeGreen) ||
        !CjguiComposableVectorFiniteUnit(geometry.strokeBlue) || !CjguiComposableVectorFiniteUnit(geometry.strokeAlpha)) return NO;
    if (geometry.pointCount > CJGUI_INTERNAL_COMPOSABLE_VECTOR_MAX_POINTS ||
        parts.count != 20 + geometry.pointCount * 2) return NO;
    for (uint32_t index = 0; index < geometry.pointCount; index++) {
        if (!CjguiComposableVectorParseDouble(parts[20 + index * 2], &geometry.points[index].x) ||
            !CjguiComposableVectorParseDouble(parts[21 + index * 2], &geometry.points[index].y) ||
            !CjguiComposableVectorPointInViewBox(geometry.points[index], geometry)) return NO;
        if (index > 0 && CjguiComposableVectorSamePoint(geometry.points[index - 1], geometry.points[index])) return NO;
    }
    BOOL fillVisible = geometry.fillAlpha > 0.0;
    BOOL strokeVisible = geometry.strokeAlpha > 0.0;
    if ((strokeVisible && geometry.strokeWidth <= 0.0) || (!fillVisible && !strokeVisible)) return NO;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        if (geometry.pointCount != 1 || !CjguiComposableVectorPointInViewBox(geometry.center, geometry) ||
            geometry.radiusX <= 0.0 || geometry.radiusY <= 0.0 || geometry.center.x - geometry.radiusX < 0.0 ||
            geometry.center.y - geometry.radiusY < 0.0 || geometry.center.x + geometry.radiusX > geometry.viewBoxWidth ||
            geometry.center.y + geometry.radiusY > geometry.viewBoxHeight) return NO;
    } else {
        uint32_t minimum = geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON ? 3u : 2u;
        if (geometry.pointCount < minimum || (geometry.kind == CJGUI_INTERNAL_VECTOR_LINE && geometry.pointCount != 2)) return NO;
        if ((geometry.kind == CJGUI_INTERNAL_VECTOR_LINE || geometry.kind == CJGUI_INTERNAL_VECTOR_POLYLINE) &&
            !strokeVisible) return NO;
        if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
            if (CjguiComposableVectorSamePoint(geometry.points[0], geometry.points[geometry.pointCount - 1])) return NO;
            for (uint32_t index = 0; index < geometry.pointCount; index++) {
                uint32_t next = index + 1 == geometry.pointCount ? 0 : index + 1;
                for (uint32_t other = index + 1; other < geometry.pointCount; other++) {
                    if (other == index + 1 || (index == 0 && other == geometry.pointCount - 1)) continue;
                    uint32_t nextOther = other + 1 == geometry.pointCount ? 0 : other + 1;
                    if (CjguiComposableVectorSegmentsIntersect(geometry.points[index], geometry.points[next],
                                                               geometry.points[other], geometry.points[nextOther])) return NO;
                }
            }
            if (!CjguiComposableVectorTriangulate(&geometry)) return NO;
        }
    }
    *outGeometry = geometry;
    return YES;
}

static BOOL CjguiEnqueueComposablePointerInteraction(CJGuiInternalSession *session,
                                                     uint32_t kind,
                                                     CJGuiInternalComposableSceneNode *node,
                                                     NSPoint point) {
    if (!session || session.destroyed || !node || !isfinite(point.x) || !isfinite(point.y)) return NO;
    uint32_t nodeIndex = node.index;
    uint64_t nodeId = node.node.nodeId;
    int64_t resourceId = node.node.resourceId;
    uint32_t nodeKind = node.node.nodeKind;
    if (nodeId == 0 || nodeIndex >= session.composableNodes.count) return NO;
    CJGuiInternalQueuedInteraction *last = session.pendingInteractions.lastObject;
    // Only adjacent updates for exactly one captured identity can merge. A
    // terminal end/cancel is deliberately never coalesced behind a move.
    if (kind == CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE && last &&
        last.kind == kind && last.nodeId == nodeId && last.resourceId == resourceId &&
        last.nodeKind == nodeKind && last.projectionVersion == session.composableSceneVersion) {
        last.pointerX = (int64_t)llround(point.x);
        last.pointerY = (int64_t)llround(point.y);
        last.modifierFlags = session.pointerModifierFlags;
        return YES;
    }
    if (session.pendingInteractions.count >= kCjguiPendingInteractionCapacity) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    CJGuiInternalQueuedInteraction *interaction =
        [[CJGuiInternalQueuedInteraction alloc] initWithKind:kind recordIndex:nodeIndex
                                               selectionStart:0 selectionEnd:0 formText:@""
                                                       nodeId:nodeId projectionVersion:session.composableSceneVersion
                                                   resourceId:resourceId nodeKind:nodeKind];
    if (!interaction) {
        session.pendingInputQueueFullNotice = YES;
        return NO;
    }
    interaction.pointerX = (int64_t)llround(point.x);
    interaction.pointerY = (int64_t)llround(point.y);
    interaction.modifierFlags = session.pointerModifierFlags;
    [session.pendingInteractions addObject:interaction];
#ifdef CJGUI_INTERNAL_TESTING
    session.testComposableLastEnqueuedKind = kind;
    session.testComposableLastEnqueuedNodeId = nodeId;
    session.testComposableLastEnqueuedProjectionVersion = session.composableSceneVersion;
    session.testComposableMaxPendingInteractionCount = (uint32_t)MIN(
        UINT32_MAX, MAX((NSUInteger)session.testComposableMaxPendingInteractionCount, session.pendingInteractions.count));
#endif
    return YES;
}

static void CjguiClearComposableTextDecorations(CJGuiInternalComposableSceneNode *node) {
    if (!node) return;
    node.textSelectionRects = @[];
    node.textMarkedRects = @[];
    node.textCaretRect = NSZeroRect;
    node.textCaretIsDeclared = NO;
    node.textScrollbarRect = NSZeroRect;
}

@interface CJGuiInternalComposableImageResource : NSObject
@property(nonatomic, copy) NSString *cacheKey;
@property(nonatomic, copy) NSString *resolvedPath;
@property(nonatomic, copy) NSData *encodedData;
@property(nonatomic, assign) NSUInteger transferPreparationCount;
@property(nonatomic, assign) uint32_t state;
@property(nonatomic, assign) uint64_t lastAccess;
@property(nonatomic, strong) id<MTLTexture> texture;
// Every subscriber is only a slot token plus that session's non-reusable
// generation.  The application domain never retains an NSWindow/session, so
// a closed window cannot be revived by a late loader callback.
@property(nonatomic, strong) NSMutableArray *subscribers;
// Explicit preparation may start real work before a candidate scene is
// accepted. Requesters are therefore distinct from committed subscribers:
// they may lead a bounded load, but never receive a completion invalidation.
@property(nonatomic, strong) NSMutableArray *requesters;
@property(nonatomic, assign) uint64_t loadGeneration;
@property(nonatomic, assign) uint64_t loadSessionToken;
@property(nonatomic, assign) uint64_t loadSessionGeneration;
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint64_t launchMicros;
#endif
@end

@implementation CJGuiInternalComposableImageResource
- (instancetype)init {
    self = [super init];
    if (!self) return nil;
    self.subscribers = [NSMutableArray array];
    self.requesters = [NSMutableArray array];
    return self;
}
@end

@interface CJGuiInternalComposableImageSubscription : NSObject
@property(nonatomic, assign) uint64_t sessionToken;
@property(nonatomic, assign) uint64_t sessionGeneration;
// A direct public prepare request is independent of a staged scene candidate.
// It is retained across a later scene commit and released with its session.
@property(nonatomic, assign) BOOL explicitPreload;
@end

@implementation CJGuiInternalComposableImageSubscription
@end

// This is deliberately a finite native application resource domain, not a
// process-wide cache keyed by application data. Domains are associated with
// NSApplication and partitioned by the exact MTLDevice. At most the existing
// fixed session capacity can be live, while per-domain cache/record/queue
// limits remain the established 8 / 32MiB / 4 / 16 / 64 limits.
@interface CJGuiInternalComposableImageResourceDomain : NSObject
@property(nonatomic, strong) id<MTLDevice> device;
@property(nonatomic, strong) NSMutableDictionary<NSString *, id<MTLTexture>> *textureCache;
// Allocation ledger, deliberately weak: cache, scene and GPU submissions are
// the strong owners. Repeated references to one texture cost one allocation.
@property(nonatomic, strong) NSHashTable<id<MTLTexture>> *textureLedger;
@property(nonatomic, strong) NSMutableDictionary<NSString *, CJGuiInternalComposableImageResource *> *resources;
@property(nonatomic, strong) NSMutableDictionary<NSString *, MTKTextureLoader *> *loaders;
@property(nonatomic, strong) NSMutableArray<NSString *> *pendingKeys;
@property(nonatomic, assign) uint64_t accessClock;
@property(nonatomic, assign) NSUInteger sessionCount;
@property(nonatomic, assign) BOOL destroyed;
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint64_t testPathResolveMicros;
@property(nonatomic, assign) uint64_t testCacheHitCount;
@property(nonatomic, assign) uint64_t testActualLoadCount;
@property(nonatomic, assign) uint64_t testActualDecodeCount;
@property(nonatomic, assign) uint64_t testAsyncTotalMicros;
@property(nonatomic, assign) uint32_t testPeakInFlight;
@property(nonatomic, assign) uint32_t testPeakPending;
#endif
- (instancetype)initWithDevice:(id<MTLDevice>)device;
@end

@implementation CJGuiInternalComposableImageResourceDomain
- (instancetype)initWithDevice:(id<MTLDevice>)device {
    self = [super init];
    if (!self || !device) return nil;
    self.device = device;
    self.textureCache = [NSMutableDictionary dictionary];
    self.textureLedger = [NSHashTable hashTableWithOptions:
        NSHashTableWeakMemory | NSHashTableObjectPointerPersonality];
    self.resources = [NSMutableDictionary dictionary];
    self.loaders = [NSMutableDictionary dictionary];
    self.pendingKeys = [NSMutableArray array];
    return self;
}
@end

static NSString *CjguiComposableImageResolvedPath(NSString *resourcePath) {
    if (resourcePath.length == 0) return nil;
    if ([resourcePath hasPrefix:@"cjgui-transfer:"]) return resourcePath;
    NSString *resolved = resourcePath;
    if (![resolved isAbsolutePath]) {
        NSString *fromWorkingDirectory = [NSFileManager.defaultManager.currentDirectoryPath stringByAppendingPathComponent:resolved];
        if ([NSFileManager.defaultManager fileExistsAtPath:fromWorkingDirectory]) {
            resolved = fromWorkingDirectory;
        } else if (NSBundle.mainBundle.resourcePath.length > 0) {
            resolved = [NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:resolved];
        } else {
            resolved = fromWorkingDirectory;
        }
    }
    return resolved.stringByStandardizingPath;
}

static NSString *CjguiComposableImageCacheKey(NSString *resourcePath, NSString *resourceId,
                                              uint64_t resourceVersion, NSString **outResolved) {
    if (outResolved) *outResolved = nil;
    NSString *resolved = CjguiComposableImageResolvedPath(resourcePath);
    if (!resolved) return nil;
    NSString *logicalId = resourceId.length > 0 ? resourceId : resolved;
    NSString *cacheKey = [NSString stringWithFormat:@"%@\n%llu\n%@", logicalId, resourceVersion, resolved];
    if (outResolved) *outResolved = resolved;
    return cacheKey;
}

// A committed/staged node owns its texture independently of the reusable
// cache. This is the only internal path that may reuse that strong reference;
// callers still receive only scalar resource states across the ABI.
static id<MTLTexture> CjguiComposableImageBoundTexture(CJGuiInternalSession *session, NSString *cacheKey) {
    if (!session || cacheKey.length == 0) return nil;
    for (CJGuiInternalComposableSceneNode *node in session.stagedComposableNodes) {
        if ([node.imageTextureContentKey isEqualToString:cacheKey] && node.imageTexture) return node.imageTexture;
    }
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if ([node.imageTextureContentKey isEqualToString:cacheKey] && node.imageTexture) return node.imageTexture;
    }
    return nil;
}

// Reusable-cache eviction removes only the cache's own strong reference. A
// texture retained by a committed/staged node is still a safe application
// domain source for another window on the same device; scanning the fixed
// session table avoids turning that eviction into a duplicate decode.
static id<MTLTexture> CjguiComposableImageDomainBoundTexture(
    CJGuiInternalComposableImageResourceDomain *domain, NSString *cacheKey) {
    if (!domain || cacheKey.length == 0) return nil;
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *session = gCjguiSessions[index];
        if (!session || session.destroyed || session.composableImageDomain != domain) continue;
        id<MTLTexture> texture = CjguiComposableImageBoundTexture(session, cacheKey);
        if (texture) return texture;
    }
    return nil;
}

static CJGuiInternalComposableImageResourceDomain *CjguiComposableImageDomainForSession(
    CJGuiInternalSession *session) {
    if (!session || session.destroyed) return nil;
    CJGuiInternalComposableImageResourceDomain *domain = session.composableImageDomain;
    if (!domain || domain.destroyed || domain.device != session.device) return nil;
    return domain;
}

static uint64_t CjguiComposableImageNextAccess(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain) return 0;
    if (domain.accessClock < UINT64_MAX) domain.accessClock += 1;
    return domain.accessClock;
}

static void CjguiSubscribeComposableImageResource(CJGuiInternalSession *session,
                                                   CJGuiInternalComposableImageResource *resource) {
    if (!session || session.destroyed || !resource || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageSubscription *subscriber in resource.subscribers) {
        if (subscriber.sessionToken == session.rendererSessionToken &&
            subscriber.sessionGeneration == session.sessionGeneration) return;
    }
    CJGuiInternalComposableImageSubscription *subscriber = [[CJGuiInternalComposableImageSubscription alloc] init];
    subscriber.sessionToken = session.rendererSessionToken;
    subscriber.sessionGeneration = session.sessionGeneration;
    [resource.subscribers addObject:subscriber];
}

static void CjguiRequestComposableImageResource(CJGuiInternalSession *session,
                                                 CJGuiInternalComposableImageResource *resource,
                                                 BOOL explicitPreload) {
    if (!session || session.destroyed || !resource || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageSubscription *requester in resource.requesters) {
        if (requester.sessionToken == session.rendererSessionToken &&
            requester.sessionGeneration == session.sessionGeneration) {
            // A later scene request must not downgrade an explicit preload.
            requester.explicitPreload = requester.explicitPreload || explicitPreload;
            return;
        }
    }
    CJGuiInternalComposableImageSubscription *requester = [[CJGuiInternalComposableImageSubscription alloc] init];
    requester.sessionToken = session.rendererSessionToken;
    requester.sessionGeneration = session.sessionGeneration;
    requester.explicitPreload = explicitPreload;
    [resource.requesters addObject:requester];
}

static NSUInteger CjguiComposableImageTextureBytes(id<MTLTexture> texture) {
    if (!texture) return 0;
    NSUInteger width = texture.width;
    NSUInteger height = texture.height;
    if (width == 0 || height == 0 || width > NSUIntegerMax / height) return NSUIntegerMax;
    NSUInteger pixels = width * height;
    return pixels > NSUIntegerMax / 4 ? NSUIntegerMax : pixels * 4;
}

static BOOL CjguiComposableImageKeyIsReferenced(CJGuiInternalSession *session, NSString *cacheKey) {
    if (!session || cacheKey.length == 0) return NO;
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if ([node.imageTextureCacheKey isEqualToString:cacheKey]) return YES;
    }
    return NO;
}

static NSMutableSet<NSString *> *CjguiComposableImageProtectedKeys(
    CJGuiInternalComposableImageResourceDomain *domain, BOOL preserveSceneReferences) {
    NSMutableSet<NSString *> *keys = [NSMutableSet set];
    if (!domain) return keys;
    if (preserveSceneReferences) {
        for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
            CJGuiInternalSession *session = gCjguiSessions[index];
            if (!session || session.destroyed || session.composableImageDomain != domain) continue;
            for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
                if (node.imageTextureCacheKey.length > 0) [keys addObject:node.imageTextureCacheKey];
            }
            for (CJGuiInternalComposableSceneNode *node in session.stagedComposableNodes) {
                if (node.imageTextureCacheKey.length > 0) [keys addObject:node.imageTextureCacheKey];
            }
        }
    }
    [keys addObjectsFromArray:domain.loaders.allKeys];
    [keys addObjectsFromArray:domain.pendingKeys];
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        if (resource.transferPreparationCount > 0) [keys addObject:resource.cacheKey];
    }
    return keys;
}

static void CjguiPruneComposableImageTextureCache(CJGuiInternalComposableImageResourceDomain *domain,
                                                   BOOL preserveSceneReferences) {
    if (!domain || domain.destroyed) return;
    NSMutableSet<NSString *> *protectedKeys = CjguiComposableImageProtectedKeys(domain, preserveSceneReferences);
    NSUInteger totalBytes = 0;
    for (id<MTLTexture> texture in domain.textureCache.allValues) {
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        totalBytes = bytes > NSUIntegerMax - totalBytes ? NSUIntegerMax : totalBytes + bytes;
    }
    while (domain.textureCache.count > CjguiComposableImageTextureCacheCapacity ||
           totalBytes > CjguiComposableImageTextureCacheByteCapacity) {
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.textureCache) {
            if ([protectedKeys containsObject:key]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[key];
            uint64_t access = resource ? resource.lastAccess : 0;
            if (!victim || access < oldest) { victim = key; oldest = access; }
        }
        if (!victim) break;
        id<MTLTexture> texture = domain.textureCache[victim];
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        [domain.textureCache removeObjectForKey:victim];
        CJGuiInternalComposableImageResource *resource = domain.resources[victim];
        if (resource) { resource.texture = nil; resource.state = CjguiComposableImageResourceUnrequested; }
        totalBytes = bytes > totalBytes ? 0 : totalBytes - bytes;
    }
    while (domain.resources.count > CjguiComposableImageRecordCapacity) {
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.resources) {
            if ([protectedKeys containsObject:key] || domain.textureCache[key]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[key];
            if (!victim || resource.lastAccess < oldest) { victim = key; oldest = resource.lastAccess; }
        }
        if (!victim) break;
        [domain.resources removeObjectForKey:victim];
    }
}

static void CjguiStartNextComposableImageLoads(CJGuiInternalComposableImageResourceDomain *domain);

static void CjguiEnqueueComposableImageResource(CJGuiInternalComposableImageResourceDomain *domain,
                                                 CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return;
    if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) {
        resource.state = CjguiComposableImageResourceBusy;
        return;
    }
    if (![domain.pendingKeys containsObject:resource.cacheKey]) [domain.pendingKeys addObject:resource.cacheKey];
    resource.state = CjguiComposableImageResourceLoading;
#ifdef CJGUI_INTERNAL_TESTING
    domain.testPeakPending = (uint32_t)MIN(UINT32_MAX, MAX((NSUInteger)domain.testPeakPending, domain.pendingKeys.count));
#endif
}

static BOOL CjguiComposableImageHasExplicitPreloadForSession(
    CJGuiInternalSession *session, CJGuiInternalComposableImageResource *resource) {
    if (!session || !resource) return NO;
    for (CJGuiInternalComposableImageSubscription *requester in resource.requesters) {
        if (requester.sessionToken == session.rendererSessionToken &&
            requester.sessionGeneration == session.sessionGeneration && requester.explicitPreload) {
            return YES;
        }
    }
    return NO;
}

// Promote busy demand from a current/staged scene or an explicit public
// preload in this exact domain.  Scan fixed sessions rather than retaining a
// window from the resource domain; stable slot order bounds progression across
// windows.  Candidate-scoped requesters are reconciled separately at commit
// or rollback, while explicit preloads remain eligible until session close.
static void CjguiPromoteReferencedBusyImageResources(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain || domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
    NSMutableSet<NSString *> *seen = [NSMutableSet set];
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *session = gCjguiSessions[index];
        if (!session || session.destroyed || session.composableImageDomain != domain) continue;
        NSArray<NSArray<CJGuiInternalComposableSceneNode *> *> *nodeSets = @[
            session.stagedComposableNodes ?: @[], session.composableNodes ?: @[]
        ];
        for (NSArray<CJGuiInternalComposableSceneNode *> *nodes in nodeSets) {
            for (CJGuiInternalComposableSceneNode *node in nodes) {
                NSString *cacheKey = node.imageTextureCacheKey;
                if (cacheKey.length == 0 || [seen containsObject:cacheKey]) continue;
                [seen addObject:cacheKey];
                CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
                if (!resource || resource.state != CjguiComposableImageResourceBusy) continue;
                resource.lastAccess = CjguiComposableImageNextAccess(domain);
                CjguiEnqueueComposableImageResource(domain, resource);
                if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
            }
        }
        // A public prepare may intentionally run before there is a scene node.
        // Once a queued item starts, such overflow requests must not remain
        // permanently busy merely because no current/staged node references
        // them yet. Sort the bounded record keys for deterministic selection.
        NSArray<NSString *> *resourceKeys = [domain.resources.allKeys sortedArrayUsingSelector:@selector(compare:)];
        for (NSString *cacheKey in resourceKeys) {
            if ([seen containsObject:cacheKey]) continue;
            CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
            if (!resource || resource.state != CjguiComposableImageResourceBusy ||
                !CjguiComposableImageHasExplicitPreloadForSession(session, resource)) continue;
            [seen addObject:cacheKey];
            resource.lastAccess = CjguiComposableImageNextAccess(domain);
            CjguiEnqueueComposableImageResource(domain, resource);
            if (domain.pendingKeys.count >= CjguiComposableImagePendingCapacity) return;
        }
    }
}

static void CjguiRemoveComposableImageSubscriptions(CJGuiInternalSession *session) {
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        [resource.subscribers removeObjectsAtIndexes:[resource.subscribers indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *subscriber, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return subscriber.sessionToken == session.rendererSessionToken &&
                    subscriber.sessionGeneration == session.sessionGeneration;
            }]];
        [resource.requesters removeObjectsAtIndexes:[resource.requesters indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *requester, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return requester.sessionToken == session.rendererSessionToken &&
                    requester.sessionGeneration == session.sessionGeneration;
            }]];
    }
}

// Rebuild one session's scene-owned demand from its accepted native scene.
// Candidate-scoped requesters are cleared with subscribers, but an explicit
// public preload remains live until its owning session closes.  Do not call
// this from configure/set, where staged candidate nodes have not yet crossed
// the native acceptance boundary.
static void CjguiRestoreAcceptedComposableImageDemand(CJGuiInternalSession *session) {
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken == 0) return;
    for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
        [resource.subscribers removeObjectsAtIndexes:[resource.subscribers indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *subscriber, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return subscriber.sessionToken == session.rendererSessionToken &&
                    subscriber.sessionGeneration == session.sessionGeneration;
            }]];
        [resource.requesters removeObjectsAtIndexes:[resource.requesters indexesOfObjectsPassingTest:
            ^BOOL(CJGuiInternalComposableImageSubscription *requester, NSUInteger index, BOOL *stop) {
                (void)index; (void)stop;
                return requester.sessionToken == session.rendererSessionToken &&
                    requester.sessionGeneration == session.sessionGeneration &&
                    !requester.explicitPreload;
            }]];
    }
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE || node.imageTextureCacheKey.length == 0) continue;
        CJGuiInternalComposableImageResource *resource = domain.resources[node.imageTextureCacheKey];
        if (resource) {
            CjguiSubscribeComposableImageResource(session, resource);
            CjguiRequestComposableImageResource(session, resource, NO);
        }
    }
    CjguiStartNextComposableImageLoads(domain);
}

// Called after a native scene replacement commits, and after native present
// rollback has restored the prior accepted scene.  Both paths have the same
// durable owner: `composableNodes`, never the staged candidate.
static void CjguiReconcileCommittedComposableImageSubscribers(CJGuiInternalSession *session) {
    CjguiRestoreAcceptedComposableImageDemand(session);
}

static void CjguiNotifyComposableImageSubscribers(CJGuiInternalComposableImageResourceDomain *domain,
                                                  CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return;
    for (NSInteger index = (NSInteger)resource.subscribers.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *subscriber = resource.subscribers[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(subscriber.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != subscriber.sessionGeneration) {
            [resource.subscribers removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
        if (CjguiComposableImageKeyIsReferenced(session, resource.cacheKey) &&
            session.composableImageResourceCompletionVersion < UINT64_MAX) {
            session.composableImageResourceCompletionVersion += 1;
        }
    }
}

static CJGuiInternalSession *CjguiComposableImageLiveLaunchSession(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return nil;
    for (NSInteger index = (NSInteger)resource.requesters.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *requester = resource.requesters[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(requester.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != requester.sessionGeneration) {
            [resource.requesters removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (session.testComposableImageLaunchGateHeld) continue;
#endif
        return session;
    }
    return nil;
}

// A held test gate pauses an otherwise live requester; it is not equivalent to
// the requester having gone away.  Keep this check separate from launch
// selection so an unstarted orphan can be removed without cancelling a live,
// deliberately paused request.
static BOOL CjguiComposableImageHasLiveRequester(
    CJGuiInternalComposableImageResourceDomain *domain, CJGuiInternalComposableImageResource *resource) {
    if (!domain || !resource) return NO;
    BOOL hasLiveRequester = NO;
    for (NSInteger index = (NSInteger)resource.requesters.count - 1; index >= 0; index--) {
        CJGuiInternalComposableImageSubscription *requester = resource.requesters[(NSUInteger)index];
        CJGuiInternalSession *session = CjguiLookupSession(requester.sessionToken);
        if (!session || session.destroyed || session.composableImageDomain != domain ||
            session.sessionGeneration != requester.sessionGeneration) {
            [resource.requesters removeObjectAtIndex:(NSUInteger)index];
            continue;
        }
        hasLiveRequester = YES;
    }
    return hasLiveRequester;
}

static void CjguiCompleteComposableImageLoad(CJGuiInternalComposableImageResourceDomain *domain,
                                             CJGuiInternalComposableImageResource *resource,
                                             uint64_t loadGeneration, id<MTLTexture> texture, NSError *error) {
    if (!domain || domain.destroyed || !resource || resource.loadGeneration != loadGeneration ||
        domain.resources[resource.cacheKey] != resource) return;
    [domain.loaders removeObjectForKey:resource.cacheKey];
    if (resource.state != CjguiComposableImageResourceLoading) {
        CjguiStartNextComposableImageLoads(domain);
        return;
    }
    CJGuiInternalSession *launchSession = CjguiLookupSession(resource.loadSessionToken);
    if (!launchSession || launchSession.destroyed || launchSession.composableImageDomain != domain ||
        launchSession.sessionGeneration != resource.loadSessionGeneration) launchSession = nil;
#ifdef CJGUI_INTERNAL_TESTING
    if (resource.launchMicros > 0 && CjguiMonotonicMicros() >= resource.launchMicros) {
        uint64_t elapsed = CjguiMonotonicMicros() - resource.launchMicros;
        if (launchSession) launchSession.testComposableImageAsyncTotalMicros += elapsed;
        domain.testAsyncTotalMicros += UINT64_MAX - domain.testAsyncTotalMicros < elapsed ? 0 : elapsed;
    }
#endif
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    if (texture) {
        [domain.textureLedger addObject:texture];
        resource.texture = texture;
        resource.state = CjguiComposableImageResourceReady;
        domain.textureCache[resource.cacheKey] = texture;
        if (launchSession && launchSession.composableImageDecodeCount < UINT32_MAX) {
            launchSession.composableImageDecodeCount += 1;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (domain.testActualDecodeCount < UINT64_MAX) domain.testActualDecodeCount += 1;
#endif
        NSLog(@"cjgui: composable image preparation ready path=%@", resource.resolvedPath);
    } else {
        resource.texture = nil;
        resource.state = CjguiComposableImageResourceFailed;
        NSLog(@"cjgui: composable image texture load failed path=%@ error=%@", resource.resolvedPath, error);
    }
    CjguiNotifyComposableImageSubscribers(domain, resource);
    CjguiPruneComposableImageTextureCache(domain, YES);
    CjguiStartNextComposableImageLoads(domain);
}

static void CjguiStartNextComposableImageLoads(CJGuiInternalComposableImageResourceDomain *domain) {
    if (!domain || domain.destroyed || !domain.device) return;
    CjguiPromoteReferencedBusyImageResources(domain);
    while (domain.loaders.count < CjguiComposableImageInFlightCapacity && domain.pendingKeys.count > 0) {
        CJGuiInternalComposableImageResource *resource = nil;
        CJGuiInternalSession *launchSession = nil;
        NSUInteger pendingCount = domain.pendingKeys.count;
        while (pendingCount-- > 0) {
            NSString *cacheKey = domain.pendingKeys.firstObject;
            [domain.pendingKeys removeObjectAtIndex:0];
            CJGuiInternalComposableImageResource *candidate = domain.resources[cacheKey];
            if (!candidate || candidate.state != CjguiComposableImageResourceLoading || domain.loaders[cacheKey]) continue;
            CJGuiInternalSession *candidateSession = CjguiComposableImageLiveLaunchSession(domain, candidate);
            if (!candidateSession) {
                if (!CjguiComposableImageHasLiveRequester(domain, candidate)) {
                    // No native loader has been started for this record.  Its
                    // owner closed before launch, so release the queue slot and
                    // record rather than treating a full queue as live demand.
                    candidate.state = CjguiComposableImageResourceUnrequested;
                    candidate.loadSessionToken = 0;
                    candidate.loadSessionGeneration = 0;
                    [domain.resources removeObjectForKey:cacheKey];
                    continue;
                }
                [domain.pendingKeys addObject:cacheKey];
                continue;
            }
            resource = candidate;
            launchSession = candidateSession;
            break;
        }
        if (!resource || !launchSession) break;
        MTKTextureLoader *loader = [[MTKTextureLoader alloc] initWithDevice:domain.device];
        if (!loader) {
            resource.state = CjguiComposableImageResourceFailed;
            CjguiNotifyComposableImageSubscribers(domain, resource);
            continue;
        }
        if (resource.loadGeneration < UINT64_MAX) resource.loadGeneration += 1;
        if (resource.loadGeneration == 0) resource.loadGeneration = 1;
        const uint64_t loadGeneration = resource.loadGeneration;
        resource.loadSessionToken = launchSession.rendererSessionToken;
        resource.loadSessionGeneration = launchSession.sessionGeneration;
        domain.loaders[resource.cacheKey] = loader;
#ifdef CJGUI_INTERNAL_TESTING
        resource.launchMicros = CjguiMonotonicMicros();
        if (launchSession.testComposableImageAsyncLaunchCount < UINT64_MAX) {
            launchSession.testComposableImageAsyncLaunchCount += 1;
        }
        domain.testActualLoadCount += domain.testActualLoadCount < UINT64_MAX ? 1 : 0;
        domain.testPeakInFlight = (uint32_t)MIN(UINT32_MAX, MAX((NSUInteger)domain.testPeakInFlight, domain.loaders.count));
        launchSession.testComposableImagePeakInFlight = (uint32_t)MIN(
            UINT32_MAX, MAX((NSUInteger)launchSession.testComposableImagePeakInFlight, domain.loaders.count));
#endif
        NSLog(@"cjgui: composable image preparation started path=%@", resource.resolvedPath);
        void (^completed)(id<MTLTexture>, NSError *) = ^(id<MTLTexture> texture, NSError *error) {
            CFRunLoopPerformBlock(CFRunLoopGetMain(), kCFRunLoopDefaultMode, ^{
                CjguiCompleteComposableImageLoad(domain, resource, loadGeneration, texture, error);
            });
            CFRunLoopWakeUp(CFRunLoopGetMain());
        };
        NSDictionary *options = @{ MTKTextureLoaderOptionSRGB: @NO,
                                   MTKTextureLoaderOptionGenerateMipmaps: @NO };
        if (resource.encodedData) {
            // The resource and callback both retain the immutable encoded
            // bytes until this started load completes, including after close.
            [loader newTextureWithData:resource.encodedData options:options completionHandler:completed];
        } else {
            NSURL *url = [NSURL fileURLWithPath:resource.resolvedPath];
            [loader newTextureWithContentsOfURL:url options:options completionHandler:completed];
        }
    }
    CjguiPromoteReferencedBusyImageResources(domain);
}

static uint32_t CjguiPrepareComposableImageResourceOnMain(CJGuiInternalSession *session, uint64_t sessionToken,
                                                          NSString *resourcePath, NSString *resourceId,
                                                          uint64_t resourceVersion, NSData *encodedData,
                                                          BOOL retriesFailed,
                                                          BOOL explicitPreload,
                                                          NSString **outCacheKey) {
    if (outCacheKey) *outCacheKey = nil;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain || session.rendererSessionToken != sessionToken) return CjguiComposableImageResourceFailed;
    NSString *resolved = nil;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t resolveStarted = CjguiMonotonicMicros();
#endif
    NSString *cacheKey = CjguiComposableImageCacheKey(resourcePath, resourceId, resourceVersion, &resolved);
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t resolveElapsed = CjguiMonotonicMicros() - resolveStarted;
    session.testComposableImagePathResolveMicros += resolveElapsed;
    domain.testPathResolveMicros += UINT64_MAX - domain.testPathResolveMicros < resolveElapsed ? 0 : resolveElapsed;
#endif
    if (!cacheKey) return CjguiComposableImageResourceFailed;
    if (outCacheKey) *outCacheKey = cacheKey;
    CJGuiInternalComposableImageResource *resource = domain.resources[cacheKey];
    id<MTLTexture> cached = domain.textureCache[cacheKey];
    if (!resource) {
        resource = [[CJGuiInternalComposableImageResource alloc] init];
        resource.cacheKey = cacheKey;
        resource.resolvedPath = resolved;
        resource.encodedData = [encodedData copy];
        domain.resources[cacheKey] = resource;
    } else if (encodedData && resource.encodedData && ![resource.encodedData isEqualToData:encodedData]) {
        return CjguiComposableImageResourceFailed;
    } else if (encodedData && !resource.encodedData) {
        resource.encodedData = [encodedData copy];
    }
    if ([resourcePath hasPrefix:@"cjgui-transfer:"] && !resource.encodedData) {
        return CjguiComposableImageResourceFailed;
    }
    CjguiRequestComposableImageResource(session, resource, explicitPreload);
    if (cached) {
        resource.texture = cached;
        resource.state = CjguiComposableImageResourceReady;
        resource.lastAccess = CjguiComposableImageNextAccess(domain);
#ifdef CJGUI_INTERNAL_TESTING
        if (session.testComposableImageCacheHitCount < UINT64_MAX) session.testComposableImageCacheHitCount += 1;
        if (domain.testCacheHitCount < UINT64_MAX) domain.testCacheHitCount += 1;
#endif
        return resource.state;
    }
    id<MTLTexture> boundTexture = CjguiComposableImageDomainBoundTexture(domain, cacheKey);
    if (boundTexture) {
        resource.texture = nil;
        resource.state = CjguiComposableImageResourceReady;
        resource.lastAccess = CjguiComposableImageNextAccess(domain);
        return resource.state;
    }
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    if (resource.state == CjguiComposableImageResourceUnrequested ||
        resource.state == CjguiComposableImageResourceBusy ||
        (retriesFailed && resource.state == CjguiComposableImageResourceFailed)) {
        CjguiEnqueueComposableImageResource(domain, resource);
    }
    CjguiStartNextComposableImageLoads(domain);
    CjguiPruneComposableImageTextureCache(domain, NO);
    return resource.state;
}

static id<MTLTexture> CjguiComposableImageTexture(CJGuiInternalSession *session, uint64_t sessionToken,
                                                  NSString *resourcePath, NSString *resourceId,
                                                  uint64_t resourceVersion, NSData *encodedData,
                                                  NSString **outCacheKey,
                                                  uint32_t *outState) {
    NSString *cacheKey = nil;
    uint32_t state = CjguiPrepareComposableImageResourceOnMain(session, sessionToken, resourcePath, resourceId,
                                                               resourceVersion, encodedData, NO, NO, &cacheKey);
    if (outState) *outState = state;
    if (outCacheKey) *outCacheKey = cacheKey;
    if (!cacheKey || state != CjguiComposableImageResourceReady) return nil;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    return domain.textureCache[cacheKey] ?: CjguiComposableImageDomainBoundTexture(domain, cacheKey);
}

static uint32_t CjguiPngBigEndian32(const uint8_t *bytes) {
    return ((uint32_t)bytes[0] << 24) | ((uint32_t)bytes[1] << 16) |
           ((uint32_t)bytes[2] << 8) | (uint32_t)bytes[3];
}

static uint32_t CjguiPngCrc32(const uint8_t *bytes, NSUInteger length) {
    uint32_t crc = UINT32_MAX;
    for (NSUInteger index = 0; index < length; index++) {
        crc ^= bytes[index];
        for (uint32_t bit = 0; bit < 8; bit++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? 0xEDB88320u : 0u);
        }
    }
    return ~crc;
}

// This first PNG exchange supports static 8-bit RGB/RGBA images. A complete
// chunk/CRC walk runs before ImageKit's actual decode so a header-only or
// truncated source never reaches the owner. Dimensions use divide-before-
// multiply checks; the sync Metal decode below validates compressed pixels.
static CjguiInternalRendererStatus CjguiValidateComposableTransferPng(
    const uint8_t *bytes, NSUInteger length, uint32_t *outWidth, uint32_t *outHeight) {
    static const uint8_t signature[8] = {137, 80, 78, 71, 13, 10, 26, 10};
    if (!bytes || length < 8 + 25 + 12 || length > 512u * 1024u ||
        memcmp(bytes, signature, sizeof(signature)) != 0) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    NSUInteger offset = 8;
    BOOL sawIHDR = NO, sawIDAT = NO, sawIEND = NO;
    uint32_t width = 0, height = 0;
    while (offset < length) {
        if (length - offset < 12) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        uint32_t chunkLength = CjguiPngBigEndian32(bytes + offset);
        if ((NSUInteger)chunkLength > length - offset - 12) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        const uint8_t *type = bytes + offset + 4;
        const uint8_t *payload = bytes + offset + 8;
        if (CjguiPngCrc32(type, (NSUInteger)chunkLength + 4) !=
            CjguiPngBigEndian32(payload + chunkLength)) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        if (!sawIHDR) {
            if (memcmp(type, "IHDR", 4) != 0 || chunkLength != 13) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            width = CjguiPngBigEndian32(payload);
            height = CjguiPngBigEndian32(payload + 4);
            if (width == 0 || height == 0 || width > 2048 || height > 2048 ||
                height > 1048576u / width) return CJGUI_INTERNAL_RENDERER_PNG_DIMENSION_EXCEEDED;
            if (payload[8] != 8 || (payload[9] != 2 && payload[9] != 6) ||
                payload[10] != 0 || payload[11] != 0 || payload[12] > 1) {
                return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            }
            sawIHDR = YES;
        } else if (memcmp(type, "IHDR", 4) == 0 || memcmp(type, "acTL", 4) == 0) {
            return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
        } else if (memcmp(type, "IDAT", 4) == 0) {
            sawIDAT = sawIDAT || chunkLength > 0;
        } else if (memcmp(type, "IEND", 4) == 0) {
            if (chunkLength != 0 || !sawIDAT || offset + 12 != length) {
                return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
            }
            sawIEND = YES;
        }
        offset += (NSUInteger)chunkLength + 12;
        if (sawIEND) break;
    }
    if (!sawIHDR || !sawIDAT || !sawIEND || offset != length) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    if (outWidth) *outWidth = width;
    if (outHeight) *outHeight = height;
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Count actual live allocations, not the number of strong references. The
// weak table does not itself extend a texture's lifetime. In particular, a
// texture in the cache, two scene nodes and an in-flight command is charged
// once; an evicted but still submitted generation remains charged.
static NSUInteger CjguiComposableImageConservativeLiveBytes(
    CJGuiInternalComposableImageResourceDomain *domain) {
    NSUInteger total = 0;
    for (id<MTLTexture> texture in domain.textureLedger) {
        NSUInteger bytes = CjguiComposableImageTextureBytes(texture);
        if (bytes > NSUIntegerMax - total) return NSUIntegerMax;
        total += bytes;
    }
    return total;
}

// Make room before allocating a PNG texture or record. Cache ownership is
// reclaimable; scene, preparation and GPU owners are not. Recount the weak
// allocation ledger after every actual eviction so a submitted old generation
// cannot be credited as free merely because its cache key was removed.
static BOOL CjguiReclaimComposablePngHeadroom(
    CJGuiInternalComposableImageResourceDomain *domain, NSString *incomingKey,
    NSUInteger incomingEncodedBytes, NSUInteger incomingTextureBytes) {
    if (!domain || incomingEncodedBytes > 8u * 1024u * 1024u ||
        incomingTextureBytes > CjguiComposableImageTextureCacheByteCapacity) return NO;
    NSMutableSet<NSString *> *protected = CjguiComposableImageProtectedKeys(domain, YES);
    if (incomingKey) [protected addObject:incomingKey];
    for (NSUInteger attempt = 0; attempt <= CjguiComposableImageRecordCapacity +
         CjguiComposableImageTextureCacheCapacity; attempt++) {
        NSUInteger encoded = 0;
        for (CJGuiInternalComposableImageResource *resource in domain.resources.allValues) {
            if ([resource.cacheKey isEqualToString:incomingKey]) continue;
            if (resource.encodedData.length > NSUIntegerMax - encoded) return NO;
            encoded += resource.encodedData.length;
        }
        NSUInteger live = CjguiComposableImageConservativeLiveBytes(domain);
        BOOL slotFits = domain.resources[incomingKey] != nil ||
            domain.resources.count < CjguiComposableImageRecordCapacity;
        if (slotFits && encoded <= 8u * 1024u * 1024u - incomingEncodedBytes &&
            live <= CjguiComposableImageTextureCacheByteCapacity - incomingTextureBytes) return YES;
        NSString *victim = nil;
        uint64_t oldest = UINT64_MAX;
        for (NSString *key in domain.resources) {
            if ([protected containsObject:key]) continue;
            CJGuiInternalComposableImageResource *candidate = domain.resources[key];
            if (!victim || candidate.lastAccess < oldest) {
                victim = key;
                oldest = candidate.lastAccess;
            }
        }
        if (!victim) {
            for (NSString *key in domain.textureCache) {
                if (![protected containsObject:key]) { victim = key; break; }
            }
        }
        if (!victim) return NO;
        CJGuiInternalComposableImageResource *retired = domain.resources[victim];
        retired.texture = nil;
        retired.encodedData = nil;
        [domain.textureCache removeObjectForKey:victim];
        [domain.resources removeObjectForKey:victim];
    }
    return NO;
}

static CjguiInternalRendererStatus CjguiPrepareComposablePngTransferOnMain(
    uint64_t sessionToken, const char *resourceIdentity, const uint8_t *bytes, uint32_t length,
    uint32_t *outWidth, uint32_t *outHeight, uint64_t *outDecodeMicros) {
    if (!outWidth || !outHeight || !outDecodeMicros) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outWidth = 0; *outHeight = 0; *outDecodeMicros = 0;
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    NSString *identity = resourceIdentity ? [NSString stringWithUTF8String:resourceIdentity] : nil;
    if (!identity || ![identity hasPrefix:@"cjgui-transfer:"] || identity.length > 96) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    uint32_t width = 0, height = 0;
    CjguiInternalRendererStatus valid = CjguiValidateComposableTransferPng(bytes, length, &width, &height);
    if (valid != CJGUI_INTERNAL_RENDERER_OK) return valid;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    if (!domain) return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    NSString *resolved = nil;
    NSString *key = CjguiComposableImageCacheKey(identity, identity, 0, &resolved);
    if (!key) return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    NSData *data = [NSData dataWithBytes:bytes length:length];
    if (!data) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableImageResource *existing = domain.resources[key];
    if (existing && existing.encodedData && ![existing.encodedData isEqualToData:data]) {
        return CJGUI_INTERNAL_RENDERER_PNG_INVALID;
    }
    id<MTLTexture> texture = domain.textureCache[key] ?: CjguiComposableImageDomainBoundTexture(domain, key);
    BOOL cacheHit = texture && texture.width == width && texture.height == height;
    CjguiPruneComposableImageTextureCache(domain, YES);
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: PNG admission identity=%@ records=%lu textures=%lu encoded=%lu pixels=%ux%u",
              identity, (unsigned long)domain.resources.count,
              (unsigned long)domain.textureCache.count, (unsigned long)data.length, width, height);
    }
    NSUInteger budgetedTextureBytes = cacheHit ? 0 : (NSUInteger)width * (NSUInteger)height * 4u;
    if (!CjguiReclaimComposablePngHeadroom(domain, key, data.length, budgetedTextureBytes)) {
        return CJGUI_INTERNAL_RENDERER_PNG_RESOURCE_BUDGET_EXCEEDED;
    }
    if (cacheHit) {
        if (!existing) {
            existing = [[CJGuiInternalComposableImageResource alloc] init];
            if (!existing) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            existing.cacheKey = key;
            existing.resolvedPath = resolved;
            domain.resources[key] = existing;
        }
        existing.encodedData = data;
        existing.texture = texture;
        existing.state = CjguiComposableImageResourceReady;
        existing.lastAccess = CjguiComposableImageNextAccess(domain);
        existing.transferPreparationCount += 1;
        [domain.textureLedger addObject:texture];
        *outWidth = width; *outHeight = height;
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    MTKTextureLoader *loader = [[MTKTextureLoader alloc] initWithDevice:domain.device];
    if (!loader) return CJGUI_INTERNAL_RENDERER_PNG_DECODE_FAILED;
    NSError *error = nil;
    uint64_t started = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    texture = [loader newTextureWithData:data options:@{ MTKTextureLoaderOptionSRGB: @NO,
        MTKTextureLoaderOptionGenerateMipmaps: @NO } error:&error];
    uint64_t ended = (uint64_t)(CACurrentMediaTime() * 1000000.0);
    *outDecodeMicros = ended >= started ? ended - started : 0;
    if (!texture || texture.width != width || texture.height != height ||
        (texture.pixelFormat != MTLPixelFormatRGBA8Unorm && texture.pixelFormat != MTLPixelFormatBGRA8Unorm)) {
        NSLog(@"cjgui: PNG transfer decode rejected error=%@", error);
        return CJGUI_INTERNAL_RENDERER_PNG_DECODE_FAILED;
    }
    [domain.textureLedger addObject:texture];
    CJGuiInternalComposableImageResource *resource = existing;
    if (!resource) {
        resource = [[CJGuiInternalComposableImageResource alloc] init];
        if (!resource) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        resource.cacheKey = key;
        resource.resolvedPath = resolved;
        domain.resources[key] = resource;
    }
    resource.encodedData = data;
    resource.texture = texture;
    resource.state = CjguiComposableImageResourceReady;
    resource.lastAccess = CjguiComposableImageNextAccess(domain);
    resource.transferPreparationCount += 1;
    domain.textureCache[key] = texture;
    *outWidth = width; *outHeight = height;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_prepare_composable_png_transfer(
    uint64_t session, const char *resourceIdentity, const uint8_t *bytes, uint32_t length,
    uint32_t *outWidth, uint32_t *outHeight, uint64_t *outDecodeMicros) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiPrepareComposablePngTransferOnMain(session, resourceIdentity, bytes, length,
                outWidth, outHeight, outDecodeMicros);
        });
        return status;
    }
    return CjguiPrepareComposablePngTransferOnMain(session, resourceIdentity, bytes, length,
        outWidth, outHeight, outDecodeMicros);
}

CjguiInternalRendererStatus cjgui_internal_renderer_finish_composable_png_transfer(
    uint64_t sessionToken, const char *resourceIdentity, uint8_t accepted) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_finish_composable_png_transfer(sessionToken, resourceIdentity, accepted);
        });
        return status;
    }
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    CJGuiInternalComposableImageResourceDomain *domain = CjguiComposableImageDomainForSession(session);
    NSString *identity = resourceIdentity ? [NSString stringWithUTF8String:resourceIdentity] : nil;
    NSString *key = CjguiComposableImageCacheKey(identity, identity, 0, NULL);
    CJGuiInternalComposableImageResource *resource = domain.resources[key];
    if (!resource || resource.transferPreparationCount == 0) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    resource.transferPreparationCount -= 1;
    if (!accepted && resource.transferPreparationCount == 0 &&
        !CjguiComposableImageDomainBoundTexture(domain, key)) {
        [domain.textureCache removeObjectForKey:key];
        [domain.resources removeObjectForKey:key];
    }
    CjguiPruneComposableImageTextureCache(domain, YES);
    return CJGUI_INTERNAL_RENDERER_OK;
}

// A source-verified image frame is useful after a dynamic resource or
// fit/fill change, but forcing a synchronous readback for unrelated text
// edits would make ordinary refreshes unnecessarily expensive.
static BOOL CjguiComposableImageContentChanged(NSArray<CJGuiInternalComposableSceneNode *> *before,
                                               NSArray<CJGuiInternalComposableSceneNode *> *after) {
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableSceneNode *> *oldByNodeId = [NSMutableDictionary dictionary];
    for (CJGuiInternalComposableSceneNode *node in before) {
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE) oldByNodeId[@(node.node.nodeId)] = node;
    }
    NSUInteger oldImageCount = oldByNodeId.count;
    NSUInteger newImageCount = 0;
    for (CJGuiInternalComposableSceneNode *node in after) {
        if (node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE) continue;
        newImageCount += 1;
        CJGuiInternalComposableSceneNode *previous = oldByNodeId[@(node.node.nodeId)];
        if (!previous || ![previous.imageTextureCacheKey isEqualToString:node.imageTextureCacheKey] ||
            previous.node.imageContentMode != node.node.imageContentMode ||
            previous.node.x != node.node.x || previous.node.y != node.node.y ||
            previous.node.width != node.node.width || previous.node.height != node.node.height ||
            previous.node.clipX != node.node.clipX || previous.node.clipY != node.node.clipY ||
            previous.node.clipWidth != node.node.clipWidth || previous.node.clipHeight != node.node.clipHeight) return YES;
    }
    return oldImageCount != newImageCount;
}

// A generic first-frame readback is intentionally much narrower than the
// renderer: it may only compare a pixel when the final Metal value is fully
// determined by an opaque, unclipped rectangle.  In particular, never clamp
// a centre outside a scroll clip, and never infer an alpha/image result from
// a lower layer.  Exact transparent and image pixels use the testing asset
// path below instead of making this diagnostic guess.
typedef struct {
    // This is the logical centre of the exact drawable texel that the blit
    // will read. It is deliberately not the mathematical centre of a node:
    // at an odd width or non-integral scale those can select different pixels.
    CGFloat logicalX;
    CGFloat logicalY;
    NSUInteger sampleX;
    NSUInteger sampleY;
} CjguiComposableReadbackProbePoint;

static BOOL CjguiComposablePointInInterval(CGFloat point, int64_t start, int64_t length) {
    return length > 0 && point >= (CGFloat)start && point < (CGFloat)start + (CGFloat)length;
}

static BOOL CjguiComposablePointInRoundedComponents(CGFloat pointX, CGFloat pointY,
                                                     CGFloat x, CGFloat y, CGFloat width, CGFloat height,
                                                     CGFloat cornerRadius) {
    if (width <= 0.0 || height <= 0.0 || pointX < x || pointY < y || pointX >= x + width || pointY >= y + height) return NO;
    CGFloat radius = MIN(MAX(0.0, cornerRadius), MIN(width, height) / 2.0);
    if (radius <= 0.0 || (pointX >= x + radius && pointX < x + width - radius) ||
        (pointY >= y + radius && pointY < y + height - radius)) return YES;
    CGFloat centreX = pointX < x + radius ? x + radius : x + width - radius;
    CGFloat centreY = pointY < y + radius ? y + radius : y + height - radius;
    CGFloat dx = pointX - centreX, dy = pointY - centreY;
    return dx * dx + dy * dy <= radius * radius;
}

static BOOL CjguiComposablePointInClipChain(CGFloat pointX, CGFloat pointY,
                                             CjguiInternalRendererComposableNode value) {
    uint32_t count = CjguiComposableClipConstraintCount(value);
    for (uint32_t i = 0; i < count; i++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableClipConstraintAt(value, i, &x, &y, &width, &height, &radius);
        if (!CjguiComposablePointInRoundedComponents(pointX, pointY, x, y, width, height, radius)) return NO;
    }
    return YES;
}

static BOOL CjguiComposableNodeContainsVisiblePoint(CJGuiInternalComposableSceneNode *node,
                                                     CGFloat pointX, CGFloat pointY, NSSize viewSize) {
    if (!node || viewSize.width <= 0.0 || viewSize.height <= 0.0) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    return CjguiComposablePointInInterval(pointX, value.x, value.width) &&
        CjguiComposablePointInInterval(pointY, value.y, value.height) &&
        CjguiComposablePointInClipChain(pointX, pointY, value) &&
        pointX >= 0 && pointY >= 0 &&
        pointX < viewSize.width && pointY < viewSize.height;
}

static BOOL CjguiComposableRectContainsPoint(NSRect rect, CGFloat pointX, CGFloat pointY) {
    return !NSIsEmptyRect(rect) && pointX >= NSMinX(rect) && pointX < NSMaxX(rect) &&
        pointY >= NSMinY(rect) && pointY < NSMaxY(rect);
}

// The text body and its active decorations are ordinary Metal commands in a
// node's resolved clip chain. They do not identify a predictable colour from
// the public scene scalar, so they must make the generic opaque probe decline
// that texel. This is intentionally a bounds-only rejection: the exact glyph
// alpha belongs to the immutable native texture and is verified through the
// explicit testing readback path rather than guessed here.
static BOOL CjguiComposableTextPresentationMayAffectVisiblePoint(CJGuiInternalComposableSceneNode *node,
                                                                 CGFloat pointX, CGFloat pointY,
                                                                 NSSize viewSize) {
    if (!CjguiComposableNodeContainsVisiblePoint(node, pointX, pointY, viewSize)) return NO;
    if ((node.textTexture || node.textTileTextures.count > 0) &&
        CjguiComposableRectContainsPoint(node.textTextureRect, pointX, pointY)) return YES;
    for (NSValue *valueRect in node.textSelectionRects) {
        if (CjguiComposableRectContainsPoint(valueRect.rectValue, pointX, pointY)) return YES;
    }
    for (NSValue *valueRect in node.textMarkedRects) {
        if (CjguiComposableRectContainsPoint(valueRect.rectValue, pointX, pointY)) return YES;
    }
    return CjguiComposableRectContainsPoint(node.textCaretRect, pointX, pointY);
}

static BOOL CjguiComposableBorderMayAffectVisiblePoint(CjguiInternalRendererComposableNode value,
                                                        CGFloat pointX, CGFloat pointY) {
    if (value.borderWidth == 0 || value.borderAlpha <= 0.0) return NO;
    int64_t border = MIN((int64_t)value.borderWidth, MIN(value.width / 2, value.height / 2));
    return pointX < (CGFloat)value.x + border || pointX >= (CGFloat)value.x + value.width - border ||
        pointY < (CGFloat)value.y + border || pointY >= (CGFloat)value.y + value.height - border;
}

static BOOL CjguiComposableNodeMayAffectVisiblePoint(CJGuiInternalComposableSceneNode *node,
                                                      CGFloat pointX, CGFloat pointY, NSSize viewSize) {
    if (!CjguiComposableNodeContainsVisiblePoint(node, pointX, pointY, viewSize)) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    if (value.fillAlpha > 0.0 ||
        (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture)) return YES;
    if (CjguiComposableTextPresentationMayAffectVisiblePoint(node, pointX, pointY, viewSize)) return YES;
    return CjguiComposableBorderMayAffectVisiblePoint(value, pointX, pointY);
}

static BOOL CjguiComposableSceneHasPotentialMetalDraw(NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        CjguiInternalRendererComposableNode value = node.node;
        if (value.width <= 0 || value.height <= 0 || value.clipWidth <= 0 || value.clipHeight <= 0) continue;
        if (value.fillAlpha > 0.0 || (value.borderWidth > 0 && value.borderAlpha > 0.0) ||
            (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture) ||
            ((node.textTexture || node.textTileTextures.count > 0) && !NSIsEmptyRect(node.textTextureRect)) ||
            node.textSelectionRects.count > 0 || node.textMarkedRects.count > 0 ||
            !NSIsEmptyRect(node.textCaretRect)) return YES;
    }
    return NO;
}

static BOOL CjguiComposableReadbackProbePointForNode(CjguiInternalRendererComposableNode value,
                                                      NSSize viewSize, CGSize drawableSize,
                                                      CjguiComposableReadbackProbePoint *outPoint) {
    if (!outPoint || viewSize.width <= 0.0 || viewSize.height <= 0.0 ||
        drawableSize.width < 1.0 || drawableSize.height < 1.0) return NO;
    CGFloat scaleX = drawableSize.width / viewSize.width;
    CGFloat scaleY = drawableSize.height / viewSize.height;
    if (!isfinite(scaleX) || !isfinite(scaleY) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    CGFloat centreX = (CGFloat)value.x + (CGFloat)value.width / 2.0;
    CGFloat centreY = (CGFloat)value.y + (CGFloat)value.height / 2.0;
    NSInteger pixelX = (NSInteger)floor(centreX * scaleX);
    NSInteger pixelY = (NSInteger)floor(centreY * scaleY);
    if (pixelX < 0 || pixelY < 0 || pixelX >= (NSInteger)drawableSize.width || pixelY >= (NSInteger)drawableSize.height) return NO;
    outPoint->sampleX = (NSUInteger)pixelX;
    outPoint->sampleY = (NSUInteger)pixelY;
    outPoint->logicalX = ((CGFloat)pixelX + 0.5) / scaleX;
    outPoint->logicalY = ((CGFloat)pixelY + 0.5) / scaleY;
    return isfinite(outPoint->logicalX) && isfinite(outPoint->logicalY);
}

static CJGuiInternalComposableSceneNode *CjguiComposableSafeOpaqueProbeNode(
    NSArray<CJGuiInternalComposableSceneNode *> *nodes, NSSize viewSize, CGSize drawableSize,
    CjguiComposableReadbackProbePoint *outPoint) {
    // Walk from the top of z order. A later transparent/image/border draw can
    // still change a lower opaque centre, so reject that lower candidate
    // rather than reporting a false colour mismatch.
    for (NSInteger candidateIndex = (NSInteger)nodes.count - 1; candidateIndex >= 0; candidateIndex--) {
        CJGuiInternalComposableSceneNode *candidate = nodes[(NSUInteger)candidateIndex];
        CjguiInternalRendererComposableNode value = candidate.node;
        // An image node first paints its declared fill and then samples an
        // arbitrary (possibly transparent) texture. Its centre is therefore
        // never a generic colour oracle even when the fill itself is opaque.
        if (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE ||
            value.fillAlpha < 1.0 || value.width <= 0 || value.height <= 0) continue;
        CjguiComposableReadbackProbePoint point = {0};
        if (!CjguiComposableReadbackProbePointForNode(value, viewSize, drawableSize, &point) ||
            !CjguiComposableNodeContainsVisiblePoint(candidate, point.logicalX, point.logicalY, viewSize) ||
            CjguiComposableTextPresentationMayAffectVisiblePoint(candidate, point.logicalX, point.logicalY, viewSize) ||
            CjguiComposableBorderMayAffectVisiblePoint(value, point.logicalX, point.logicalY)) continue;
        BOOL covered = NO;
        for (NSUInteger upperIndex = (NSUInteger)candidateIndex + 1; upperIndex < nodes.count; upperIndex++) {
            if (CjguiComposableNodeMayAffectVisiblePoint(nodes[upperIndex], point.logicalX, point.logicalY, viewSize)) {
                covered = YES;
                break;
            }
        }
        if (!covered) {
            *outPoint = point;
            return candidate;
        }
    }
    return nil;
}

// A staged replacement must never mutate the live input/overlay snapshot.
// COW callers retain an immutable current node until a Cangjie setter changes
// that index, at which point this copies native-owned scalar/string/texture
// references into one staged node. The texture remains a normal strong
// Objective-C reference and no native handle crosses the ABI.
static CJGuiInternalComposableSceneNode *CjguiCloneComposableSceneNode(
    CJGuiInternalSession *session, CJGuiInternalComposableSceneNode *source, uint32_t index, uint64_t projectionVersion) {
    if (!source) return nil;
    CJGuiInternalComposableSceneNode *copy = [[CJGuiInternalComposableSceneNode alloc] init];
    if (!copy) return nil;
    CjguiInternalRendererComposableNode copiedValue = source.node;
    copiedValue.projectionVersion = projectionVersion;
    copy.node = copiedValue;
    copy.index = index;
    copy.label = [source.label copy] ?: @"";
    copy.value = [source.value copy] ?: @"";
    copy.semanticId = [source.semanticId copy] ?: @"";
    copy.semanticBindingKey = [source.semanticBindingKey copy] ?: @"";
    copy.semanticRowKey = [source.semanticRowKey copy] ?: @"";
    copy.semanticParentRowKey = [source.semanticParentRowKey copy] ?: @"";
    copy.semanticLabel = [source.semanticLabel copy] ?: @"";
    copy.imageResourcePath = [source.imageResourcePath copy] ?: @"";
    copy.imageEncodedData = [source.imageEncodedData copy];
    copy.imageResourceId = [source.imageResourceId copy] ?: @"";
    copy.imageResourceVersion = source.imageResourceVersion;
    copy.imageTextureCacheKey = [source.imageTextureCacheKey copy] ?: @"";
    copy.imageTextureContentKey = [source.imageTextureContentKey copy] ?: @"";
    copy.imageTexture = source.imageTexture;
    copy.styleRunsSignature = [source.styleRunsSignature copy];
    copy.textTextureCacheKey = [source.textTextureCacheKey copy] ?: @"";
    copy.textTexture = source.textTexture;
    copy.textTileTextures = source.textTileTextures;
    copy.textTileRects = source.textTileRects;
    copy.textTextureByteCount = source.textTextureByteCount;
    copy.textTextureRect = source.textTextureRect;
    copy.hasVectorGeometry = source.hasVectorGeometry;
    copy.vectorGeometry = source.vectorGeometry;
    copy.vectorPreparedTriangles = source.vectorPreparedTriangles;
    copy.hasVectorPreparedGeometry = source.hasVectorPreparedGeometry;
    copy.vectorPreparedGeometry = source.vectorPreparedGeometry;
    copy.vectorPreparedVertexBuffer = source.vectorPreparedVertexBuffer;
    copy.vectorPreparedVertexCount = source.vectorPreparedVertexCount;
    copy.vectorPreparedVertexBytes = source.vectorPreparedVertexBytes;
    copy.textSelectionRects = [source.textSelectionRects copy] ?: @[];
    copy.textMarkedRects = [source.textMarkedRects copy] ?: @[];
    copy.textCaretRect = source.textCaretRect;
    copy.textCaretIsDeclared = source.textCaretIsDeclared;
    copy.textScrollbarRect = source.textScrollbarRect;
    copy.effectTarget = source.effectTarget;
    copy.backdropTarget = source.backdropTarget;
#ifdef CJGUI_INTERNAL_TESTING
    if (session) {
        if (session.testComposableSceneCloneCount < UINT64_MAX) session.testComposableSceneCloneCount += 1;
        if (session.testComposableSceneNodeAllocationCount < UINT64_MAX) session.testComposableSceneNodeAllocationCount += 1;
    }
#endif
    return copy;
}

static uint64_t CjguiComposableNodeIdAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return 0;
    return session.composableNodes[nodeIndex].node.nodeId;
}

static int64_t CjguiComposableNodeResourceIdAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return -1;
    return session.composableNodes[nodeIndex].node.resourceId;
}

static uint32_t CjguiComposableNodeKindAtIndex(CJGuiInternalSession *session, uint32_t nodeIndex) {
    if (!session || nodeIndex >= session.composableNodes.count) return 0;
    return session.composableNodes[nodeIndex].node.nodeKind;
}

static CJGuiInternalComposableDataTransferItem *CjguiComposableDataTransferItemForNode(
    CJGuiInternalSession *session, uint64_t nodeId, int64_t resourceId,
    uint32_t nodeKind, uint32_t role) {
    if (!session || session.destroyed || session.composableDataTransferVersion != session.composableSceneVersion) {
        return nil;
    }
    for (CJGuiInternalComposableDataTransferItem *candidate in session.composableDataTransferItems) {
        CjguiInternalRendererComposableDataTransferItem item = candidate.item;
        if (item.nodeId == nodeId && item.resourceId == resourceId && item.nodeKind == nodeKind &&
            item.projectionVersion == session.composableSceneVersion && item.role == role) {
            return candidate;
        }
    }
    return nil;
}

static NSPasteboardType CjguiPasteboardTypeForDataTransferFormat(NSString *format) {
    if ([format isEqualToString:@"text/plain"]) return NSPasteboardTypeString;
    if ([format isEqualToString:@"image/png"]) return NSPasteboardTypePNG;
    NSData *bytes = [format dataUsingEncoding:NSUTF8StringEncoding];
    if (!bytes || bytes.length == 0) return nil;
    // NSPasteboardType is a UTI, not an RFC 2046 MIME string.  Preserve the
    // complete declared identifier in a private, valid UTI rather than
    // casting `application/vnd…` directly (which AppKit rejects). Hex is
    // intentionally injective over the already bounded ASCII format value,
    // so two declared structured formats can never alias one pasteboard type.
    NSMutableString *type = [NSMutableString stringWithString:@"org.cangjie.cjgui.transfer.f"];
    const uint8_t *raw = bytes.bytes;
    for (NSUInteger index = 0; index < bytes.length; index++) {
        [type appendFormat:@"%02x", (unsigned int)raw[index]];
    }
    return (NSPasteboardType)type;
}


// This private type carries only copied source provenance alongside the
// declared public payload type. It is never decoded as a command, used as an
// authorization token, or retained past the FIFO event; the receiving owner
// still validates the immutable offer and its own CAS boundary.
static NSPasteboardType const kCjguiDataTransferSourceMetadataType = @"org.cangjie.cjgui.transfer-source";

static NSData *CjguiDataTransferSourceMetadata(CJGuiInternalComposableDataTransferItem *item) {
    if (!item || item.sourceKind.length == 0 || item.sourceIdentity.length == 0 || item.item.sourceId < 0) return nil;
    NSDictionary *metadata = @{ @"kind": item.sourceKind, @"identity": item.sourceIdentity,
                                @"id": @(item.item.sourceId), @"format": item.format ?: @"" };
    NSError *error = nil;
    return [NSPropertyListSerialization dataWithPropertyList:metadata format:NSPropertyListBinaryFormat_v1_0
                                                      options:0 error:&error];
}

static void CjguiReadDataTransferSourceMetadata(NSPasteboard *pasteboard, NSString *format,
                                                NSString **outKind, NSString **outIdentity, int64_t *outId) {
    if (outKind) *outKind = @"external_pasteboard";
    if (outIdentity) *outIdentity = @"macos";
    if (outId) *outId = 0;
    NSData *data = [pasteboard dataForType:kCjguiDataTransferSourceMetadataType];
    if (!data || data.length > 1024) return;
    NSError *error = nil;
    id value = [NSPropertyListSerialization propertyListWithData:data options:NSPropertyListImmutable format:nil error:&error];
    if (![value isKindOfClass:[NSDictionary class]]) return;
    NSDictionary *metadata = (NSDictionary *)value;
    NSString *kind = metadata[@"kind"];
    NSString *identity = metadata[@"identity"];
    NSNumber *identifier = metadata[@"id"];
    NSString *metadataFormat = metadata[@"format"];
    if (![kind isKindOfClass:[NSString class]] || ![identity isKindOfClass:[NSString class]] ||
        ![identifier isKindOfClass:[NSNumber class]] || ![metadataFormat isEqualToString:format] ||
        kind.length == 0 || kind.length > 128 || identity.length == 0 || identity.length > 256 ||
        identifier.longLongValue < 0) return;
    if (outKind) *outKind = [kind copy];
    if (outIdentity) *outIdentity = [identity copy];
    if (outId) *outId = identifier.longLongValue;
}

static BOOL CjguiTransferQueueCanRetain(NSUInteger incoming) {
    const NSUInteger budget = 2u * 1024u * 1024u;
    if (incoming > budget) return NO;
    NSUInteger retained = 0;
    for (NSUInteger index = 0; index < kCjguiSessionCapacity; index++) {
        CJGuiInternalSession *live = gCjguiSessions[index];
        if (!live || live.destroyed) continue;
        retained += live.pumpedDataTransferBytes.length;
        for (CJGuiInternalQueuedInteraction *queued in live.pendingInteractions) {
            retained += queued.dataTransferBytes.length;
        }
        if (retained > budget - incoming) return NO;
    }
    return YES;
}

static BOOL CjguiEnqueueComposableDataTransferInteraction(
    CJGuiInternalSession *session, uint32_t kind,
    CJGuiInternalComposableDataTransferItem *item, NSString *payload, NSData *binaryData,
    NSString *sourceKind, NSString *sourceIdentity, int64_t sourceId) {
    if (!session || !item || !payload) return NO;
    if (binaryData && !CjguiTransferQueueCanRetain(binaryData.length)) return NO;
    if (session.nextDataTransferEventId == UINT64_MAX) return NO;
    for (CJGuiInternalComposableSceneNode *node in session.composableNodes) {
        if (node.node.nodeId != item.item.nodeId || node.node.resourceId != item.item.resourceId ||
            node.node.nodeKind != item.item.nodeKind) continue;
        if (!CjguiEnqueueComposableInteraction(session, kind, node.index, payload, NSMakeRange(0, 0))) return NO;
        CJGuiInternalQueuedInteraction *queued = session.pendingInteractions.lastObject;
        if (!queued || queued.kind != kind || queued.nodeId != item.item.nodeId ||
            queued.projectionVersion != session.composableSceneVersion) return NO;
        queued.dataTransferFormat = [item.format copy] ?: @"";
        queued.dataTransferBytes = [binaryData copy];
        queued.bindingEpoch = item.item.bindingEpoch;
        queued.dataTransferEventId = ++session.nextDataTransferEventId;
        queued.dataTransferSourceKind = [sourceKind copy] ?: @"external_pasteboard";
        queued.dataTransferSourceIdentity = [sourceIdentity copy] ?: @"macos";
        queued.dataTransferSourceId = sourceId >= 0 ? sourceId : 0;
#ifdef CJGUI_INTERNAL_TESTING
        CjguiUpdateTestDataTransferRetentionPeaks(session);
#endif
        return YES;
    }
    return NO;
}

static CjguiInternalRendererStatus CjguiCopyComposableDataTransferItem(
    CJGuiInternalSession *session, CJGuiInternalComposableDataTransferItem *item) {
    if (!session || !item || item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    BOOL png = [item.format isEqualToString:@"image/png"];
    NSData *payload = png ? item.binaryPayload : [item.payload dataUsingEncoding:NSUTF8StringEncoding];
    if (!payload || payload.length > item.item.maximumPayloadBytes) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferSourceWriteCount += 1;
    session.testDataTransferSourceWriteBytes += (uint64_t)payload.length;
    session.testDataTransferSourceWritePeakBytes = MAX(session.testDataTransferSourceWritePeakBytes,
        (uint64_t)payload.length);
#endif
    NSPasteboardItem *pasteboardItem = [[NSPasteboardItem alloc] init];
    NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
    if (!pasteboardItem || !type) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    [pasteboardItem setData:payload forType:type];
    NSData *metadata = CjguiDataTransferSourceMetadata(item);
    if (metadata) [pasteboardItem setData:metadata forType:kCjguiDataTransferSourceMetadataType];
    NSPasteboard *pasteboard = NSPasteboard.generalPasteboard;
    if (![pasteboard clearContents] || ![pasteboard writeObjects:@[pasteboardItem]]) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    return CjguiEnqueueComposableDataTransferInteraction(session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_COPY, item, item.payload, nil,
        item.sourceKind, item.sourceIdentity, item.item.sourceId)
        ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
}

static CjguiInternalRendererStatus CjguiReadComposableDataTransferItem(
    CJGuiInternalSession *session, CJGuiInternalComposableDataTransferItem *item,
    NSPasteboard *pasteboard, uint32_t kind) {
    if (!session || !item || !pasteboard || item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
    BOOL png = [item.format isEqualToString:@"image/png"];
    if (png && !CjguiTransferQueueCanRetain(item.item.maximumPayloadBytes)) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    NSData *data = [pasteboard dataForType:type];
    if (!data || data.length > item.item.maximumPayloadBytes) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferReadCount += 1;
    session.testDataTransferReadBytes += (uint64_t)data.length;
    session.testDataTransferReadPeakBytes = MAX(session.testDataTransferReadPeakBytes, (uint64_t)data.length);
#endif
    NSString *payload = png ? @"" : [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    if (!payload) return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
#ifdef CJGUI_INTERNAL_TESTING
    session.testDataTransferParseCount += 1;
    session.testDataTransferParseBytes += (uint64_t)data.length;
    session.testDataTransferParsePeakBytes = MAX(session.testDataTransferParsePeakBytes, (uint64_t)data.length);
#endif
    NSString *sourceKind = nil;
    NSString *sourceIdentity = nil;
    int64_t sourceId = 0;
    CjguiReadDataTransferSourceMetadata(pasteboard, item.format, &sourceKind, &sourceIdentity, &sourceId);
    return CjguiEnqueueComposableDataTransferInteraction(session, kind, item, payload,
                                                         png ? data : nil,
                                                         sourceKind, sourceIdentity, sourceId)
        ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
}

static NSFont *CjguiComposableFont(CJGuiInternalComposableSceneNode *node);
static NSFont *CjguiComposableFontForStyle(double requested, uint32_t fontWeight, uint32_t fontFamily);

static uint32_t CjguiComposableClipConstraintCount(CjguiInternalRendererComposableNode value) {
    if (value.clipConstraintCount > 0 &&
        value.clipConstraintCount <= CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY) return value.clipConstraintCount;
    return 1;
}

static void CjguiComposableClipConstraintAt(CjguiInternalRendererComposableNode value, uint32_t index,
                                             CGFloat *x, CGFloat *y, CGFloat *width, CGFloat *height, CGFloat *radius) {
    if (value.clipConstraintCount == 0 || value.clipConstraintCount > CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY) {
        *x = value.clipX; *y = value.clipY; *width = value.clipWidth; *height = value.clipHeight;
        *radius = value.clipCornerRadius;
        return;
    }
    switch (index) {
        case 0: *x = value.clip0X; *y = value.clip0Y; *width = value.clip0Width; *height = value.clip0Height; *radius = value.clip0CornerRadius; break;
        case 1: *x = value.clip1X; *y = value.clip1Y; *width = value.clip1Width; *height = value.clip1Height; *radius = value.clip1CornerRadius; break;
        case 2: *x = value.clip2X; *y = value.clip2Y; *width = value.clip2Width; *height = value.clip2Height; *radius = value.clip2CornerRadius; break;
        default: *x = value.clip3X; *y = value.clip3Y; *width = value.clip3Width; *height = value.clip3Height; *radius = value.clip3CornerRadius; break;
    }
}

static void CjguiPopulateMetalClipChain(vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY],
                                        vector_float4 *radii, vector_float4 *count,
                                        CjguiInternalRendererComposableNode value) {
    uint32_t clipCount = CjguiComposableClipConstraintCount(value);
    *radii = (vector_float4){ 0, 0, 0, 0 };
    *count = (vector_float4){ (float)clipCount, 0, 0, 0 };
    for (uint32_t i = 0; i < CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY; i++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        if (i < clipCount) CjguiComposableClipConstraintAt(value, i, &x, &y, &width, &height, &radius);
        clips[i] = (vector_float4){ (float)x, (float)y, (float)MAX(0.0, width), (float)MAX(0.0, height) };
        if (i < clipCount) (*radii)[i] = (float)MIN(MAX(0.0, radius), MIN(MAX(0.0, width), MAX(0.0, height)) / 2.0);
    }
}

static void CjguiAppendMetalShape(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                  CjguiInternalRendererComposableNode value, vector_float4 fill, vector_float4 border) {
    CGFloat x = value.x, y = value.y, width = value.width, height = value.height;
    // A linear gradient replaces the fill even when the flat fill color is
    // fully transparent, so it participates in the emptiness test. With
    // gradientPresent == 0 this reduces exactly to the legacy condition.
    BOOL hasGradient = value.gradientPresent != 0 && value.gradientStopCount >= 2;
    if (!batch || width <= 0.0 || height <= 0.0 ||
        (fill.w <= 0.0 && border.w <= 0.0 && !hasGradient)) return;
    float left = -1.0f + (float)(2.0 * x / pointWidth);
    float right = -1.0f + (float)(2.0 * (x + width) / pointWidth);
    float top = 1.0f - (float)(2.0 * y / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (y + height) / pointHeight);
    float radius = (float)MIN(MAX(0.0, value.cornerRadius), MIN(width, height) / 2.0);
    float stroke = (float)MIN(MAX(0.0, (CGFloat)value.borderWidth), MIN(width, height) / 2.0);
    vector_float2 gradientStart = { (float)value.gradientStartX, (float)value.gradientStartY };
    vector_float2 gradientEnd = { (float)value.gradientEndX, (float)value.gradientEndY };
    // Stop xyz is the sRGB color; a parallel vector carries the four alphas so
    // the payload stays vector-aligned with the Metal struct.
    vector_float4 gradientStop0 = { (float)value.gradientStop0Position, (float)value.gradientStop0Red,
        (float)value.gradientStop0Green, (float)value.gradientStop0Blue };
    vector_float4 gradientStop1 = { (float)value.gradientStop1Position, (float)value.gradientStop1Red,
        (float)value.gradientStop1Green, (float)value.gradientStop1Blue };
    vector_float4 gradientStop2 = { (float)value.gradientStop2Position, (float)value.gradientStop2Red,
        (float)value.gradientStop2Green, (float)value.gradientStop2Blue };
    vector_float4 gradientStop3 = { (float)value.gradientStop3Position, (float)value.gradientStop3Red,
        (float)value.gradientStop3Green, (float)value.gradientStop3Blue };
    vector_float4 gradientStopAlphas = { (float)value.gradientStop0Alpha, (float)value.gradientStop1Alpha,
        (float)value.gradientStop2Alpha, (float)value.gradientStop3Alpha };
    float gradientPresent = hasGradient ? 1.0f : 0.0f;
    float gradientStopCount = hasGradient ? (float)value.gradientStopCount : 0.0f;
    CJGuiInternalMetalVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    vector_float2 scenePoints[6] = { { (float)x, (float)y }, { (float)(x + width), (float)y }, { (float)x, (float)(y + height) }, { (float)(x + width), (float)y }, { (float)(x + width), (float)(y + height) }, { (float)x, (float)(y + height) } };
    vector_float2 localPoints[6] = { { 0, 0 }, { (float)width, 0 }, { 0, (float)height }, { (float)width, 0 }, { (float)width, (float)height }, { 0, (float)height } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].scenePoint = scenePoints[i]; vertices[i].localPoint = localPoints[i];
        vertices[i].size = (vector_float2){ (float)width, (float)height };
        CjguiPopulateMetalClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, value);
        vertices[i].cornerRadius = radius; vertices[i].borderWidth = stroke; vertices[i].fill = fill; vertices[i].border = border;
        vertices[i].passKind = 0.0f;
        vertices[i].gradientPresent = gradientPresent;
        vertices[i].gradientStopCount = gradientStopCount;
        vertices[i].gradientStart = gradientStart;
        vertices[i].gradientEnd = gradientEnd;
        vertices[i].gradientStop0 = gradientStop0;
        vertices[i].gradientStop1 = gradientStop1;
        vertices[i].gradientStop2 = gradientStop2;
        vertices[i].gradientStop3 = gradientStop3;
        vertices[i].gradientStopAlphas = gradientStopAlphas;
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

// Appends one outer-shadow quad for a node that requested `shadowPresent`.
// The quad spans the union of the node bounds and the offset/expanded shadow
// shape pushed out by three blur radii, so the soft falloff is never clipped
// by the node's own rectangle. Only the inherited ancestor clip chain is
// applied: the fragment evaluates the clip SDF against `scenePoint` exactly
// like an ordinary shape. The shadow shape itself is expressed in local SDF
// space (`localPoint` relative to the expanded shape origin, `size` its
// extent), which keeps the fragment free of an extra origin uniform.
static void CjguiAppendMetalShadow(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                   CjguiInternalRendererComposableNode value) {
    if (!batch || value.shadowPresent == 0 || !(value.shadowAlpha > 0.0)) return;
    CGFloat width = value.width, height = value.height;
    if (width <= 0.0 || height <= 0.0) return;
    CGFloat blur = MIN(MAX(0.0, (CGFloat)value.shadowBlurRadius), 256.0);
    CGFloat spread = MIN(MAX(0.0, (CGFloat)value.shadowSpread), 128.0);
    // Shadow shape = node bounds translated by the offset, expanded by spread.
    CGFloat shapeX = (CGFloat)value.x + (CGFloat)value.shadowOffsetX - spread;
    CGFloat shapeY = (CGFloat)value.y + (CGFloat)value.shadowOffsetY - spread;
    CGFloat shapeW = width + 2.0 * spread;
    CGFloat shapeH = height + 2.0 * spread;
    // Output range = shadow shape expanded by 3*blur, unioned with the node
    // bounds so the node's own pixels are always covered by the shadow quad
    // and the following fill can overwrite the shadow center.
    CGFloat expand = 3.0 * blur;
    CGFloat outX = MIN((CGFloat)value.x, shapeX - expand);
    CGFloat outY = MIN((CGFloat)value.y, shapeY - expand);
    CGFloat outRight = MAX((CGFloat)value.x + width, shapeX + shapeW + expand);
    CGFloat outBottom = MAX((CGFloat)value.y + height, shapeY + shapeH + expand);
    CGFloat outW = outRight - outX;
    CGFloat outH = outBottom - outY;
    if (outW <= 0.0 || outH <= 0.0) return;
    float radius = (float)MIN(MAX(0.0, value.cornerRadius), MIN(shapeW, shapeH) / 2.0);
    float left = -1.0f + (float)(2.0 * outX / pointWidth);
    float right = -1.0f + (float)(2.0 * (outX + outW) / pointWidth);
    float top = 1.0f - (float)(2.0 * outY / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (outY + outH) / pointHeight);
    vector_float4 shadowColor = { (float)value.shadowRed, (float)value.shadowGreen,
        (float)value.shadowBlue, (float)value.shadowAlpha };
    CJGuiInternalMetalVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    vector_float2 scenePoints[6] = { { (float)outX, (float)outY }, { (float)(outX + outW), (float)outY }, { (float)outX, (float)(outY + outH) },
        { (float)(outX + outW), (float)outY }, { (float)(outX + outW), (float)(outY + outH) }, { (float)outX, (float)(outY + outH) } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].scenePoint = scenePoints[i];
        // localPoint is relative to the shadow shape origin and size spans the
        // expanded shape, so the fragment SDF has no separate origin field.
        vertices[i].localPoint = (vector_float2){ scenePoints[i].x - (float)shapeX, scenePoints[i].y - (float)shapeY };
        vertices[i].size = (vector_float2){ (float)shapeW, (float)shapeH };
        CjguiPopulateMetalClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, value);
        vertices[i].cornerRadius = radius;
        vertices[i].borderWidth = 0.0f;
        vertices[i].passKind = 1.0f;
        vertices[i].shadowBlurRadius = (float)blur;
        vertices[i].shadowColor = shadowColor;
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

// Output range of one node's outer shadow in scene (flipped, top-left origin)
// coordinates: the node bounds unioned with the offset/spread shadow shape
// pushed out by three blur radii. This mirrors the quad extent built inside
// CjguiAppendMetalShadow so the paint gate below can never disagree with the
// geometry actually submitted. A shadow may extend past the node's own bounds;
// only the inherited ancestor clip chain limits it.
static NSRect CjguiComposableShadowOutputRect(CjguiInternalRendererComposableNode value) {
    CGFloat width = value.width, height = value.height;
    CGFloat blur = MIN(MAX(0.0, (CGFloat)value.shadowBlurRadius), 256.0);
    CGFloat spread = MIN(MAX(0.0, (CGFloat)value.shadowSpread), 128.0);
    CGFloat shapeX = (CGFloat)value.x + (CGFloat)value.shadowOffsetX - spread;
    CGFloat shapeY = (CGFloat)value.y + (CGFloat)value.shadowOffsetY - spread;
    CGFloat shapeW = width + 2.0 * spread;
    CGFloat shapeH = height + 2.0 * spread;
    CGFloat expand = 3.0 * blur;
    CGFloat outX = MIN((CGFloat)value.x, shapeX - expand);
    CGFloat outY = MIN((CGFloat)value.y, shapeY - expand);
    CGFloat outRight = MAX((CGFloat)value.x + width, shapeX + shapeW + expand);
    CGFloat outBottom = MAX((CGFloat)value.y + height, shapeY + shapeH + expand);
    return NSMakeRect(outX, outY, MAX(0.0, outRight - outX), MAX(0.0, outBottom - outY));
}

// Decides whether the shadow output range can survive the inherited ancestor
// clip chain. The chain INTERSECTS, so the visible region is the common
// intersection of every non-empty constraint and the shadow is submitted only
// when its range meets that common region. Requiring each constraint to meet
// the range individually is NOT equivalent: two disjoint clips can both meet a
// wide output while their common region does not, which would submit a quad the
// fragment then discards for every pixel. Rounded corners are ignored on
// purpose - this only decides whether to submit the quad, so a false positive
// merely adds a quad the fragment SDF discards, while a false negative would
// drop a genuinely visible shadow. The node's own bounds are never consulted,
// which is what lets a fully clipped-out body still paint its shadow.
static BOOL CjguiComposableShadowOutputIntersectsAncestorClip(CjguiInternalRendererComposableNode value,
                                                              NSRect shadowOutput) {
    if (NSIsEmptyRect(shadowOutput)) return NO;
    uint32_t clipCount = CjguiComposableClipConstraintCount(value);
    if (clipCount == 0) return NO;
    NSRect visibleRegion = NSMakeRect(0.0, 0.0, 0.0, 0.0);
    BOOL haveRegion = NO;
    for (uint32_t index = 0; index < clipCount; index++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableClipConstraintAt(value, index, &x, &y, &width, &height, &radius);
        NSRect clipRect = NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
        if (NSIsEmptyRect(clipRect)) return NO;
        visibleRegion = haveRegion ? NSIntersectionRect(visibleRegion, clipRect) : clipRect;
        haveRegion = YES;
        if (NSIsEmptyRect(visibleRegion)) return NO;
    }
    return NSIntersectsRect(visibleRegion, shadowOutput);
}

// Final drawable cull for the shadow-only path: map the logical output range
// into drawable pixels with the same scale used by the body path and require a
// non-empty intersection with the render target.
static BOOL CjguiComposableShadowOutputIntersectsDrawable(NSRect shadowOutput,
                                                          CGFloat scaleX, CGFloat scaleY,
                                                          CGSize drawableSize) {
    if (NSIsEmptyRect(shadowOutput) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    CGFloat left = MAX(0.0, NSMinX(shadowOutput) * scaleX);
    CGFloat top = MAX(0.0, NSMinY(shadowOutput) * scaleY);
    CGFloat right = MIN((CGFloat)drawableSize.width, NSMaxX(shadowOutput) * scaleX);
    CGFloat bottom = MIN((CGFloat)drawableSize.height, NSMaxY(shadowOutput) * scaleY);
    return right > left && bottom > top;
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorPoint(double x, double y) {
    return (CjguiInternalComposableVectorPoint){ x, y };
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorAdd(CjguiInternalComposableVectorPoint left,
                                                                    CjguiInternalComposableVectorPoint right) {
    return CjguiComposableVectorPoint(left.x + right.x, left.y + right.y);
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorSubtract(CjguiInternalComposableVectorPoint left,
                                                                         CjguiInternalComposableVectorPoint right) {
    return CjguiComposableVectorPoint(left.x - right.x, left.y - right.y);
}

static CjguiInternalComposableVectorPoint CjguiComposableVectorScale(CjguiInternalComposableVectorPoint point,
                                                                      double scalar) {
    return CjguiComposableVectorPoint(point.x * scalar, point.y * scalar);
}

static double CjguiComposableVectorLength(CjguiInternalComposableVectorPoint point) {
    return hypot(point.x, point.y);
}

static BOOL CjguiComposableVectorUnitDirection(CjguiInternalComposableVectorPoint start,
                                               CjguiInternalComposableVectorPoint end,
                                               CjguiInternalComposableVectorPoint *outDirection) {
    if (!outDirection) return NO;
    CjguiInternalComposableVectorPoint delta = CjguiComposableVectorSubtract(end, start);
    double length = CjguiComposableVectorLength(delta);
    if (!isfinite(length) || length <= CjguiComposableVectorEpsilon) return NO;
    *outDirection = CjguiComposableVectorScale(delta, 1.0 / length);
    return YES;
}

static void CjguiAppendMetalVectorTriangle(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                           CjguiInternalRendererComposableNode value,
                                           CjguiInternalComposableVectorGeometry geometry,
                                           CjguiInternalComposableVectorPoint first,
                                           CjguiInternalComposableVectorPoint second,
                                           CjguiInternalComposableVectorPoint third,
                                           vector_float4 fill) {
    if (!batch || fill.w <= 0.0 || geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0 ||
        pointWidth <= 0.0 || pointHeight <= 0.0) return;
    CjguiInternalComposableVectorPoint local[3] = { first, second, third };
    CJGuiInternalMetalVertex vertices[3] = {0};
    for (uint32_t index = 0; index < 3; index++) {
        double sceneX = (double)value.x + local[index].x * (double)value.width / geometry.viewBoxWidth;
        double sceneY = (double)value.y + local[index].y * (double)value.height / geometry.viewBoxHeight;
        vertices[index].position = (vector_float2){ -1.0f + (float)(2.0 * sceneX / pointWidth),
            1.0f - (float)(2.0 * sceneY / pointHeight) };
        vertices[index].scenePoint = (vector_float2){ (float)sceneX, (float)sceneY };
        vertices[index].localPoint = (vector_float2){ (float)(sceneX - (double)value.x),
            (float)(sceneY - (double)value.y) };
        vertices[index].size = (vector_float2){ (float)value.width, (float)value.height };
        CjguiPopulateMetalClipChain(vertices[index].clips, &vertices[index].clipRadii, &vertices[index].clipCount, value);
        vertices[index].cornerRadius = 0.0f;
        vertices[index].borderWidth = 0.0f;
        vertices[index].isVectorShape = 1.0f;
        vertices[index].vectorPadding = 0.0f;
        vertices[index].fill = fill;
        vertices[index].border = (vector_float4){ 0, 0, 0, 0 };
    }
    [batch appendBytes:vertices length:sizeof(vertices)];
}

static void CjguiAppendMetalVectorQuad(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                       CjguiInternalRendererComposableNode value,
                                       CjguiInternalComposableVectorGeometry geometry,
                                       CjguiInternalComposableVectorPoint first,
                                       CjguiInternalComposableVectorPoint second,
                                       CjguiInternalComposableVectorPoint third,
                                       CjguiInternalComposableVectorPoint fourth,
                                       vector_float4 fill) {
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, first, second, third, fill);
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, second, fourth, third, fill);
}

static void CjguiAppendMetalVectorStrokeSegment(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                                CjguiInternalRendererComposableNode value,
                                                CjguiInternalComposableVectorGeometry geometry,
                                                CjguiInternalComposableVectorPoint start,
                                                CjguiInternalComposableVectorPoint end,
                                                double halfWidth, vector_float4 stroke) {
    CjguiInternalComposableVectorPoint direction = {0};
    if (stroke.w <= 0.0 || halfWidth <= 0.0 ||
        !CjguiComposableVectorUnitDirection(start, end, &direction)) return;
    CjguiInternalComposableVectorPoint normal = CjguiComposableVectorPoint(-direction.y * halfWidth,
                                                                             direction.x * halfWidth);
    CjguiAppendMetalVectorQuad(batch, pointWidth, pointHeight, value, geometry,
        CjguiComposableVectorAdd(start, normal), CjguiComposableVectorSubtract(start, normal),
        CjguiComposableVectorAdd(end, normal), CjguiComposableVectorSubtract(end, normal), stroke);
}

static BOOL CjguiComposableVectorLineIntersection(CjguiInternalComposableVectorPoint point,
                                                  CjguiInternalComposableVectorPoint direction,
                                                  CjguiInternalComposableVectorPoint otherPoint,
                                                  CjguiInternalComposableVectorPoint otherDirection,
                                                  CjguiInternalComposableVectorPoint *outIntersection) {
    if (!outIntersection) return NO;
    double denominator = direction.x * otherDirection.y - direction.y * otherDirection.x;
    if (fabs(denominator) <= CjguiComposableVectorEpsilon) return NO;
    CjguiInternalComposableVectorPoint difference = CjguiComposableVectorSubtract(otherPoint, point);
    double ratio = (difference.x * otherDirection.y - difference.y * otherDirection.x) / denominator;
    *outIntersection = CjguiComposableVectorAdd(point, CjguiComposableVectorScale(direction, ratio));
    return isfinite(outIntersection->x) && isfinite(outIntersection->y);
}

static void CjguiAppendMetalVectorJoin(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                      CjguiInternalRendererComposableNode value,
                                      CjguiInternalComposableVectorGeometry geometry,
                                      CjguiInternalComposableVectorPoint previous,
                                      CjguiInternalComposableVectorPoint current,
                                      CjguiInternalComposableVectorPoint next,
                                      double halfWidth, vector_float4 stroke) {
    CjguiInternalComposableVectorPoint beforeDirection = {0};
    CjguiInternalComposableVectorPoint afterDirection = {0};
    if (stroke.w <= 0.0 || halfWidth <= 0.0 ||
        !CjguiComposableVectorUnitDirection(previous, current, &beforeDirection) ||
        !CjguiComposableVectorUnitDirection(current, next, &afterDirection)) return;
    double turn = beforeDirection.x * afterDirection.y - beforeDirection.y * afterDirection.x;
    if (fabs(turn) <= CjguiComposableVectorEpsilon) return;
    CjguiInternalComposableVectorPoint beforeNormal = CjguiComposableVectorPoint(-beforeDirection.y * halfWidth,
                                                                                   beforeDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint afterNormal = CjguiComposableVectorPoint(-afterDirection.y * halfWidth,
                                                                                  afterDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint outerBefore = turn > 0.0
        ? CjguiComposableVectorSubtract(current, beforeNormal) : CjguiComposableVectorAdd(current, beforeNormal);
    CjguiInternalComposableVectorPoint outerAfter = turn > 0.0
        ? CjguiComposableVectorSubtract(current, afterNormal) : CjguiComposableVectorAdd(current, afterNormal);
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_ROUND) {
        double startAngle = atan2(outerBefore.y - current.y, outerBefore.x - current.x);
        double endAngle = atan2(outerAfter.y - current.y, outerAfter.x - current.x);
        double delta = endAngle - startAngle;
        if (turn > 0.0) {
            while (delta < 0.0) delta += 2.0 * M_PI;
        } else {
            while (delta > 0.0) delta -= 2.0 * M_PI;
        }
        uint32_t segments = (uint32_t)MIN(8.0, MAX(1.0, ceil(fabs(delta) / (M_PI / 6.0))));
        CjguiInternalComposableVectorPoint previousArc = outerBefore;
        for (uint32_t index = 1; index <= segments; index++) {
            double angle = startAngle + delta * (double)index / (double)segments;
            CjguiInternalComposableVectorPoint currentArc = CjguiComposableVectorPoint(
                current.x + cos(angle) * halfWidth, current.y + sin(angle) * halfWidth);
            CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                            current, previousArc, currentArc, stroke);
            previousArc = currentArc;
        }
        return;
    }
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_MITER) {
        CjguiInternalComposableVectorPoint miter = {0};
        if (CjguiComposableVectorLineIntersection(outerBefore, beforeDirection, outerAfter, afterDirection, &miter) &&
            CjguiComposableVectorLength(CjguiComposableVectorSubtract(miter, current)) <=
                halfWidth * CjguiComposableVectorMiterLimit) {
            CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                            outerBefore, miter, outerAfter, stroke);
            return;
        }
    }
    CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry,
                                    current, outerBefore, outerAfter, stroke);
}

static void CjguiAppendMetalVectorCap(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                     CjguiInternalRendererComposableNode value,
                                     CjguiInternalComposableVectorGeometry geometry,
                                     CjguiInternalComposableVectorPoint center,
                                     CjguiInternalComposableVectorPoint direction,
                                     BOOL startCap, double halfWidth, vector_float4 stroke) {
    if (stroke.w <= 0.0 || halfWidth <= 0.0 || geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_BUTT) return;
    CjguiInternalComposableVectorPoint outward = startCap ? CjguiComposableVectorScale(direction, -1.0) : direction;
    if (geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            CjguiComposableVectorAdd(center, CjguiComposableVectorScale(outward, halfWidth)), center, halfWidth, stroke);
        return;
    }
    double base = atan2(outward.y, outward.x);
    CjguiInternalComposableVectorPoint prior = CjguiComposableVectorPoint(
        center.x + cos(base - M_PI / 2.0) * halfWidth, center.y + sin(base - M_PI / 2.0) * halfWidth);
    for (uint32_t index = 1; index <= 8; index++) {
        double angle = base - M_PI / 2.0 + M_PI * (double)index / 8.0;
        CjguiInternalComposableVectorPoint next = CjguiComposableVectorPoint(
            center.x + cos(angle) * halfWidth, center.y + sin(angle) * halfWidth);
        CjguiAppendMetalVectorTriangle(batch, pointWidth, pointHeight, value, geometry, center, prior, next, stroke);
        prior = next;
    }
}

static void CjguiAppendMetalVectorOpenStroke(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                             CjguiInternalRendererComposableNode value,
                                             CjguiInternalComposableVectorGeometry geometry,
                                             vector_float4 stroke) {
    if (geometry.pointCount < 2 || stroke.w <= 0.0 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++) {
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[index], geometry.points[index + 1], halfWidth, stroke);
    }
    for (uint32_t index = 1; index + 1 < geometry.pointCount; index++) {
        CjguiAppendMetalVectorJoin(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[index - 1], geometry.points[index], geometry.points[index + 1], halfWidth, stroke);
    }
    CjguiInternalComposableVectorPoint firstDirection = {0};
    CjguiInternalComposableVectorPoint lastDirection = {0};
    if (CjguiComposableVectorUnitDirection(geometry.points[0], geometry.points[1], &firstDirection)) {
        CjguiAppendMetalVectorCap(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[0], firstDirection, YES, halfWidth, stroke);
    }
    if (CjguiComposableVectorUnitDirection(geometry.points[geometry.pointCount - 2],
                                           geometry.points[geometry.pointCount - 1], &lastDirection)) {
        CjguiAppendMetalVectorCap(batch, pointWidth, pointHeight, value, geometry,
            geometry.points[geometry.pointCount - 1], lastDirection, NO, halfWidth, stroke);
    }
}

static void CjguiAppendMetalVectorClosedStroke(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                               CjguiInternalRendererComposableNode value,
                                               CjguiInternalComposableVectorGeometry geometry,
                                               const CjguiInternalComposableVectorPoint *points,
                                               uint32_t pointCount, vector_float4 stroke) {
    if (!points || pointCount < 3 || stroke.w <= 0.0 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendMetalVectorStrokeSegment(batch, pointWidth, pointHeight, value, geometry,
            points[index], points[next], halfWidth, stroke);
    }
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t previous = index == 0 ? pointCount - 1 : index - 1;
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendMetalVectorJoin(batch, pointWidth, pointHeight, value, geometry,
            points[previous], points[index], points[next], halfWidth, stroke);
    }
}

enum { CjguiPreparedVectorPaintFill = 1, CjguiPreparedVectorPaintStroke = 2 };

typedef struct CjguiInternalPreparedVectorTriangle {
    CjguiInternalComposableVectorPoint first;
    CjguiInternalComposableVectorPoint second;
    CjguiInternalComposableVectorPoint third;
    uint8_t paint;
} CjguiInternalPreparedVectorTriangle;

// Local vector topology is immutable between geometry changes. Store only a
// point and paint selector in the resident GPU buffer; layout, clip and paint
// values stay in a small per-draw uniform so a local paint/layout update does
// not rewrite every expanded triangle vertex.
typedef struct CJGuiInternalMetalVectorVertex {
    vector_float2 localPoint;
    uint32_t paint;
    uint32_t padding;
} CJGuiInternalMetalVectorVertex;

typedef struct CJGuiInternalMetalVectorUniform {
    vector_float4 nodeRect;
    // x/y are the declared vector viewBox; z/w are the current point extent.
    vector_float4 viewBoxAndPointExtent;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
    vector_float4 fill;
    vector_float4 stroke;
} CJGuiInternalMetalVectorUniform;

static void CjguiAppendPreparedVectorTriangle(NSMutableData *triangles,
                                              CjguiInternalComposableVectorPoint first,
                                              CjguiInternalComposableVectorPoint second,
                                              CjguiInternalComposableVectorPoint third,
                                              uint8_t paint) {
    if (!triangles) return;
    CjguiInternalPreparedVectorTriangle triangle = { first, second, third, paint };
    [triangles appendBytes:&triangle length:sizeof(triangle)];
}

static void CjguiAppendPreparedVectorQuad(NSMutableData *triangles,
                                          CjguiInternalComposableVectorPoint first,
                                          CjguiInternalComposableVectorPoint second,
                                          CjguiInternalComposableVectorPoint third,
                                          CjguiInternalComposableVectorPoint fourth,
                                          uint8_t paint) {
    CjguiAppendPreparedVectorTriangle(triangles, first, second, third, paint);
    CjguiAppendPreparedVectorTriangle(triangles, third, second, fourth, paint);
}

static void CjguiAppendPreparedVectorStrokeSegment(NSMutableData *triangles,
                                                    CjguiInternalComposableVectorPoint start,
                                                    CjguiInternalComposableVectorPoint end,
                                                    double halfWidth) {
    CjguiInternalComposableVectorPoint direction = {0};
    if (halfWidth <= 0.0 || !CjguiComposableVectorUnitDirection(start, end, &direction)) return;
    CjguiInternalComposableVectorPoint normal = CjguiComposableVectorPoint(-direction.y * halfWidth,
                                                                             direction.x * halfWidth);
    CjguiAppendPreparedVectorQuad(triangles, CjguiComposableVectorAdd(start, normal),
                                  CjguiComposableVectorSubtract(start, normal),
                                  CjguiComposableVectorAdd(end, normal),
                                  CjguiComposableVectorSubtract(end, normal), CjguiPreparedVectorPaintStroke);
}

static void CjguiAppendPreparedVectorJoin(NSMutableData *triangles,
                                          CjguiInternalComposableVectorGeometry geometry,
                                          CjguiInternalComposableVectorPoint previous,
                                          CjguiInternalComposableVectorPoint current,
                                          CjguiInternalComposableVectorPoint next,
                                          double halfWidth) {
    CjguiInternalComposableVectorPoint beforeDirection = {0}, afterDirection = {0};
    if (halfWidth <= 0.0 || !CjguiComposableVectorUnitDirection(previous, current, &beforeDirection) ||
        !CjguiComposableVectorUnitDirection(current, next, &afterDirection)) return;
    double turn = beforeDirection.x * afterDirection.y - beforeDirection.y * afterDirection.x;
    if (fabs(turn) <= CjguiComposableVectorEpsilon) return;
    CjguiInternalComposableVectorPoint beforeNormal = CjguiComposableVectorPoint(-beforeDirection.y * halfWidth,
                                                                                   beforeDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint afterNormal = CjguiComposableVectorPoint(-afterDirection.y * halfWidth,
                                                                                  afterDirection.x * halfWidth);
    CjguiInternalComposableVectorPoint outerBefore = turn > 0.0
        ? CjguiComposableVectorSubtract(current, beforeNormal) : CjguiComposableVectorAdd(current, beforeNormal);
    CjguiInternalComposableVectorPoint outerAfter = turn > 0.0
        ? CjguiComposableVectorSubtract(current, afterNormal) : CjguiComposableVectorAdd(current, afterNormal);
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_ROUND) {
        double startAngle = atan2(outerBefore.y - current.y, outerBefore.x - current.x);
        double endAngle = atan2(outerAfter.y - current.y, outerAfter.x - current.x);
        double delta = endAngle - startAngle;
        if (turn > 0.0) while (delta < 0.0) delta += 2.0 * M_PI;
        else while (delta > 0.0) delta -= 2.0 * M_PI;
        uint32_t segments = (uint32_t)MIN(8.0, MAX(1.0, ceil(fabs(delta) / (M_PI / 6.0))));
        CjguiInternalComposableVectorPoint previousArc = outerBefore;
        for (uint32_t index = 1; index <= segments; index++) {
            double angle = startAngle + delta * (double)index / (double)segments;
            CjguiInternalComposableVectorPoint currentArc = CjguiComposableVectorPoint(
                current.x + cos(angle) * halfWidth, current.y + sin(angle) * halfWidth);
            CjguiAppendPreparedVectorTriangle(triangles, current, previousArc, currentArc, CjguiPreparedVectorPaintStroke);
            previousArc = currentArc;
        }
        return;
    }
    if (geometry.join == CJGUI_INTERNAL_VECTOR_JOIN_MITER) {
        CjguiInternalComposableVectorPoint miter = {0};
        if (CjguiComposableVectorLineIntersection(outerBefore, beforeDirection, outerAfter, afterDirection, &miter) &&
            CjguiComposableVectorLength(CjguiComposableVectorSubtract(miter, current)) <= halfWidth * CjguiComposableVectorMiterLimit) {
            CjguiAppendPreparedVectorTriangle(triangles, outerBefore, miter, outerAfter, CjguiPreparedVectorPaintStroke);
            return;
        }
    }
    CjguiAppendPreparedVectorTriangle(triangles, current, outerBefore, outerAfter, CjguiPreparedVectorPaintStroke);
}

static void CjguiAppendPreparedVectorCap(NSMutableData *triangles,
                                         CjguiInternalComposableVectorGeometry geometry,
                                         CjguiInternalComposableVectorPoint center,
                                         CjguiInternalComposableVectorPoint direction,
                                         BOOL startCap, double halfWidth) {
    if (halfWidth <= 0.0 || geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_BUTT) return;
    CjguiInternalComposableVectorPoint outward = startCap ? CjguiComposableVectorScale(direction, -1.0) : direction;
    if (geometry.cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        CjguiAppendPreparedVectorStrokeSegment(triangles,
            CjguiComposableVectorAdd(center, CjguiComposableVectorScale(outward, halfWidth)), center, halfWidth);
        return;
    }
    double base = atan2(outward.y, outward.x);
    CjguiInternalComposableVectorPoint prior = CjguiComposableVectorPoint(
        center.x + cos(base - M_PI / 2.0) * halfWidth, center.y + sin(base - M_PI / 2.0) * halfWidth);
    for (uint32_t index = 1; index <= 8; index++) {
        double angle = base - M_PI / 2.0 + M_PI * (double)index / 8.0;
        CjguiInternalComposableVectorPoint next = CjguiComposableVectorPoint(
            center.x + cos(angle) * halfWidth, center.y + sin(angle) * halfWidth);
        CjguiAppendPreparedVectorTriangle(triangles, center, prior, next, CjguiPreparedVectorPaintStroke);
        prior = next;
    }
}

static void CjguiAppendPreparedVectorOpenStroke(NSMutableData *triangles,
                                                CjguiInternalComposableVectorGeometry geometry) {
    if (geometry.pointCount < 2 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++)
        CjguiAppendPreparedVectorStrokeSegment(triangles, geometry.points[index], geometry.points[index + 1], halfWidth);
    for (uint32_t index = 1; index + 1 < geometry.pointCount; index++)
        CjguiAppendPreparedVectorJoin(triangles, geometry, geometry.points[index - 1], geometry.points[index], geometry.points[index + 1], halfWidth);
    CjguiInternalComposableVectorPoint firstDirection = {0}, lastDirection = {0};
    if (CjguiComposableVectorUnitDirection(geometry.points[0], geometry.points[1], &firstDirection))
        CjguiAppendPreparedVectorCap(triangles, geometry, geometry.points[0], firstDirection, YES, halfWidth);
    if (CjguiComposableVectorUnitDirection(geometry.points[geometry.pointCount - 2], geometry.points[geometry.pointCount - 1], &lastDirection))
        CjguiAppendPreparedVectorCap(triangles, geometry, geometry.points[geometry.pointCount - 1], lastDirection, NO, halfWidth);
}

static void CjguiAppendPreparedVectorClosedStroke(NSMutableData *triangles,
                                                  CjguiInternalComposableVectorGeometry geometry,
                                                  const CjguiInternalComposableVectorPoint *points,
                                                  uint32_t pointCount) {
    if (!points || pointCount < 3 || geometry.strokeWidth <= 0.0) return;
    double halfWidth = geometry.strokeWidth / 2.0;
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendPreparedVectorStrokeSegment(triangles, points[index], points[next], halfWidth);
    }
    for (uint32_t index = 0; index < pointCount; index++) {
        uint32_t previous = index == 0 ? pointCount - 1 : index - 1;
        uint32_t next = index + 1 == pointCount ? 0 : index + 1;
        CjguiAppendPreparedVectorJoin(triangles, geometry, points[previous], points[index], points[next], halfWidth);
    }
}

static BOOL CjguiComposableVectorPreparationGeometryEquals(CjguiInternalComposableVectorGeometry first,
                                                            CjguiInternalComposableVectorGeometry second) {
    if (first.kind != second.kind || first.pointCount != second.pointCount || first.cap != second.cap || first.join != second.join ||
        first.viewBoxWidth != second.viewBoxWidth || first.viewBoxHeight != second.viewBoxHeight ||
        first.strokeWidth != second.strokeWidth || first.center.x != second.center.x || first.center.y != second.center.y ||
        first.radiusX != second.radiusX || first.radiusY != second.radiusY ||
        first.triangleIndexCount != second.triangleIndexCount) return NO;
    return memcmp(first.points, second.points, sizeof(CjguiInternalComposableVectorPoint) * first.pointCount) == 0 &&
        memcmp(first.triangleIndices, second.triangleIndices, first.triangleIndexCount) == 0;
}

static NSData *CjguiComposablePreparedVectorTrianglesForNode(CJGuiInternalMetalView *metalView,
                                                              CJGuiInternalComposableSceneNode *node) {
    if (!node || !node.hasVectorGeometry) return nil;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (node.vectorPreparedTriangles && node.hasVectorPreparedGeometry &&
        CjguiComposableVectorPreparationGeometryEquals(node.vectorPreparedGeometry, geometry)) return node.vectorPreparedTriangles;
    NSMutableData *triangles = [NSMutableData data];
    if (!triangles) return nil;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
        for (uint32_t index = 0; index + 2 < geometry.triangleIndexCount; index += 3) {
            uint8_t first = geometry.triangleIndices[index], second = geometry.triangleIndices[index + 1], third = geometry.triangleIndices[index + 2];
            if (first < geometry.pointCount && second < geometry.pointCount && third < geometry.pointCount)
                CjguiAppendPreparedVectorTriangle(triangles, geometry.points[first], geometry.points[second], geometry.points[third], CjguiPreparedVectorPaintFill);
        }
    } else if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        CjguiInternalComposableVectorPoint ring[CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS] = {0};
        for (uint32_t index = 0; index < CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS; index++) {
            double angle = 2.0 * M_PI * (double)index / (double)CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS;
            ring[index] = CjguiComposableVectorPoint(geometry.center.x + cos(angle) * geometry.radiusX,
                                                      geometry.center.y + sin(angle) * geometry.radiusY);
        }
        for (uint32_t index = 0; index < CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS; index++) {
            uint32_t next = index + 1 == CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS ? 0 : index + 1;
            CjguiAppendPreparedVectorTriangle(triangles, geometry.center, ring[index], ring[next], CjguiPreparedVectorPaintFill);
        }
        CjguiAppendPreparedVectorClosedStroke(triangles, geometry, ring, CJGUI_INTERNAL_COMPOSABLE_VECTOR_ELLIPSE_SEGMENTS);
    }
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_LINE || geometry.kind == CJGUI_INTERNAL_VECTOR_POLYLINE)
        CjguiAppendPreparedVectorOpenStroke(triangles, geometry);
    else if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON)
        CjguiAppendPreparedVectorClosedStroke(triangles, geometry, geometry.points, geometry.pointCount);
    node.vectorPreparedTriangles = triangles;
    // A new topology must never retain the prior topology's GPU allocation.
    // The old COW node is retained by an in-flight command buffer if needed.
    node.vectorPreparedVertexBuffer = nil;
    node.vectorPreparedVertexCount = 0;
    node.vectorPreparedVertexBytes = 0;
    node.vectorPreparedGeometry = geometry;
    node.hasVectorPreparedGeometry = YES;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView && metalView.testComposableVectorGeometryPreparationCount < UINT64_MAX)
        metalView.testComposableVectorGeometryPreparationCount += 1;
    if (metalView && triangles.length <= UINT64_MAX - metalView.testComposableVectorGeometryPreparedBytes)
        metalView.testComposableVectorGeometryPreparedBytes += triangles.length;
#endif
    return triangles;
}

static id<MTLBuffer> CjguiComposableVectorVertexBufferForNode(CJGuiInternalMetalView *metalView,
                                                               CJGuiInternalComposableSceneNode *node,
                                                               BOOL *outUploaded) {
    if (outUploaded) *outUploaded = NO;
    if (!metalView || !metalView.device || !node || !node.hasVectorGeometry) return nil;
    NSData *prepared = CjguiComposablePreparedVectorTrianglesForNode(metalView, node);
    if (!prepared || prepared.length % sizeof(CjguiInternalPreparedVectorTriangle) != 0) return nil;
    NSUInteger triangleCount = prepared.length / sizeof(CjguiInternalPreparedVectorTriangle);
    if (triangleCount == 0 || triangleCount > NSUIntegerMax / 3u) return nil;
    NSUInteger vertexCount = triangleCount * 3u;
    if (vertexCount > NSUIntegerMax / sizeof(CJGuiInternalMetalVectorVertex)) return nil;
    NSUInteger byteCount = vertexCount * sizeof(CJGuiInternalMetalVectorVertex);
    // Every currently supported geometry is bounded to twelve logical points
    // and 32 ellipse segments. Keep the native allocation cap explicit even
    // if future parser limits drift; the 1,024-node scene limit then bounds a
    // whole accepted scene to at most 16 MiB of resident vector buffers.
    if (byteCount == 0 || byteCount > 16u * 1024u) return nil;
    if (node.vectorPreparedVertexBuffer && node.vectorPreparedVertexCount == vertexCount &&
        node.vectorPreparedVertexBytes == byteCount) {
#ifdef CJGUI_INTERNAL_TESTING
        if (metalView.testComposableVectorBufferReuseCount < UINT32_MAX)
            metalView.testComposableVectorBufferReuseCount += 1;
#endif
        return node.vectorPreparedVertexBuffer;
    }
    NSMutableData *vertices = [NSMutableData dataWithLength:byteCount];
    if (!vertices) return nil;
    const CjguiInternalPreparedVectorTriangle *triangles = prepared.bytes;
    CJGuiInternalMetalVectorVertex *target = vertices.mutableBytes;
    for (NSUInteger index = 0; index < triangleCount; index++) {
        const CjguiInternalPreparedVectorTriangle triangle = triangles[index];
        const NSUInteger base = index * 3u;
        target[base] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.first.x, (float)triangle.first.y }, triangle.paint, 0 };
        target[base + 1u] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.second.x, (float)triangle.second.y }, triangle.paint, 0 };
        target[base + 2u] = (CJGuiInternalMetalVectorVertex){
            { (float)triangle.third.x, (float)triangle.third.y }, triangle.paint, 0 };
    }
    id<MTLBuffer> buffer = [metalView.device newBufferWithBytes:vertices.bytes length:byteCount
                                                         options:MTLResourceStorageModeShared];
    if (!buffer) return nil;
    node.vectorPreparedVertexBuffer = buffer;
    node.vectorPreparedVertexCount = vertexCount;
    node.vectorPreparedVertexBytes = byteCount;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposableVectorBufferUploadCount < UINT32_MAX)
        metalView.testComposableVectorBufferUploadCount += 1;
    metalView.testComposableVectorBufferUploadBytes = byteCount > UINT64_MAX - metalView.testComposableVectorBufferUploadBytes
        ? UINT64_MAX : metalView.testComposableVectorBufferUploadBytes + byteCount;
#endif
    if (outUploaded) *outUploaded = YES;
    return buffer;
}

// Decorations are regular scene rectangles with the text node's resolved
// clip chain. They deliberately do not become public nodes or textures:
// their sole owner is the active native input projection.
static void CjguiAppendMetalTextDecoration(NSMutableData *batch, CGFloat pointWidth, CGFloat pointHeight,
                                           CjguiInternalRendererComposableNode owner, NSRect rect,
                                           vector_float4 fill) {
    if (NSIsEmptyRect(rect) || fill.w <= 0.0) return;
    CjguiInternalRendererComposableNode decoration = owner;
    decoration.x = (int64_t)floor(NSMinX(rect));
    decoration.y = (int64_t)floor(NSMinY(rect));
    decoration.width = (int64_t)ceil(NSWidth(rect));
    decoration.height = (int64_t)ceil(NSHeight(rect));
    decoration.cornerRadius = 0.0;
    decoration.borderWidth = 0.0;
    // Text decorations (selection, caret, scrollbar) are flat overlays and
    // must never inherit the owner's shadow or gradient.
    decoration.shadowPresent = 0;
    decoration.gradientPresent = 0;
    decoration.fillAlpha = fill.w;
    decoration.borderAlpha = 0.0;
    CjguiAppendMetalShape(batch, pointWidth, pointHeight, decoration, fill, (vector_float4){ 0, 0, 0, 0 });
}

static vector_float4 CjguiMetalColorFromNSColor(NSColor *color) {
    NSColor *srgb = [color colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
    if (!srgb) return (vector_float4){ 0, 0, 0, 0 };
    return (vector_float4){ (float)srgb.redComponent, (float)srgb.greenComponent,
                             (float)srgb.blueComponent, (float)srgb.alphaComponent };
}

static BOOL CjguiEnsureComposableImagePipeline(CJGuiInternalMetalView *metalView) {
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> existing = usesMultisampling
        ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline;
    if (existing) return YES;
    NSError *error = nil;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct Vertex { float2 position; float2 texCoord; float2 scenePoint; float4 clips[4]; float4 clipRadii; float4 clipCount; float4 nodeRect; float nodeCornerRadius; float paintAlpha; };\n"
        "struct Out { float4 position [[position]]; float2 texCoord; float2 point; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float4 nodeRect; float nodeCornerRadius; float paintAlpha; };\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "vertex Out cjgui_image_vertex(uint i [[vertex_id]], const device Vertex *v [[buffer(0)]]) { Out o; o.position=float4(v[i].position,0,1); o.texCoord=v[i].texCoord; o.point=v[i].scenePoint; o.clip0=v[i].clips[0]; o.clip1=v[i].clips[1]; o.clip2=v[i].clips[2]; o.clip3=v[i].clips[3]; o.clipRadii=v[i].clipRadii; o.clipCount=v[i].clipCount; o.nodeRect=v[i].nodeRect; o.nodeCornerRadius=v[i].nodeCornerRadius; o.paintAlpha=v[i].paintAlpha; return o; }\n"
        // Normalized (non-premultiplied) texels: scale only alpha, never RGB, so
        // the blended colour is exactly the declared colour at the animated
        // opacity. Image quads pass paintAlpha=1 and are unchanged.
        "fragment float4 cjgui_image_fragment(Out in [[stage_in]], texture2d<float> image [[texture(0)]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.point,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } if (roundedDistance(in.point,in.nodeRect.xy,in.nodeRect.zw,in.nodeCornerRadius)>0.0) discard_fragment(); constexpr sampler s(coord::normalized, address::clamp_to_edge, filter::linear); float4 c=image.sample(s, in.texCoord); c.a*=in.paintAlpha; return c; }\n";
    id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: composable image metal library failed %@", error); return NO; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_image_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_image_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = usesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
    descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
    descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    id<MTLRenderPipelineState> pipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: composable image pipeline failed %@", error); return NO; }
    if (usesMultisampling) metalView.composableMultisampleImagePipeline = pipeline;
    else metalView.composableImagePipeline = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    return YES;
}

static BOOL CjguiEnsureComposableVectorPipeline(CJGuiInternalMetalView *metalView) {
    if (!metalView || !metalView.device) return NO;
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> existing = usesMultisampling
        ? metalView.composableMultisampleVectorPipeline : metalView.composableVectorPipeline;
    if (existing) return YES;
    NSError *error = nil;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct VectorVertex { float2 localPoint; uint paint; uint padding; };\n"
        "struct VectorUniform { float4 nodeRect; float4 viewBoxAndPointExtent; float4 clips[4]; float4 clipRadii; float4 clipCount; float4 fill; float4 stroke; };\n"
        "struct VectorOut { float4 position [[position]]; float2 point; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float4 color; };\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "vertex VectorOut cjgui_vector_vertex(uint i [[vertex_id]], const device VectorVertex *v [[buffer(0)]], constant VectorUniform &u [[buffer(1)]]) { VectorOut o; float2 point=u.nodeRect.xy+(v[i].localPoint/u.viewBoxAndPointExtent.xy)*u.nodeRect.zw; o.position=float4(-1.0+2.0*point.x/u.viewBoxAndPointExtent.z,1.0-2.0*point.y/u.viewBoxAndPointExtent.w,0,1); o.point=point; o.clip0=u.clips[0]; o.clip1=u.clips[1]; o.clip2=u.clips[2]; o.clip3=u.clips[3]; o.clipRadii=u.clipRadii; o.clipCount=u.clipCount; o.color=v[i].paint==1u?u.fill:u.stroke; return o; }\n"
        "fragment float4 cjgui_vector_fragment(VectorOut in [[stage_in]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.point,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } return in.color; }\n";
    id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: composable vector metal library failed %@", error); return NO; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_vector_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_vector_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = usesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
    descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
    descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    id<MTLRenderPipelineState> pipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: composable vector metal pipeline failed %@", error); return NO; }
    if (usesMultisampling) metalView.composableMultisampleVectorPipeline = pipeline;
    else metalView.composableVectorPipeline = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    return YES;
}

static BOOL CjguiEncodeMetalVectorShape(id<MTLRenderCommandEncoder> encoder,
                                        CGFloat pointWidth, CGFloat pointHeight,
                                        CJGuiInternalMetalView *metalView,
                                        CJGuiInternalComposableSceneNode *node) {
    if (!encoder || !metalView || !node || !node.hasVectorGeometry || pointWidth <= 0.0 || pointHeight <= 0.0) return NO;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0) return NO;
    if (geometry.fillAlpha <= 0.0 && geometry.strokeAlpha <= 0.0) return YES;
    if (!CjguiEnsureComposableVectorPipeline(metalView)) return NO;
    BOOL uploaded = NO;
    id<MTLBuffer> buffer = CjguiComposableVectorVertexBufferForNode(metalView, node, &uploaded);
    if (!buffer || node.vectorPreparedVertexCount == 0) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    CJGuiInternalMetalVectorUniform uniform = {0};
    uniform.nodeRect = (vector_float4){ (float)value.x, (float)value.y, (float)value.width, (float)value.height };
    uniform.viewBoxAndPointExtent = (vector_float4){ (float)geometry.viewBoxWidth, (float)geometry.viewBoxHeight,
                                                      (float)pointWidth, (float)pointHeight };
    CjguiPopulateMetalClipChain(uniform.clips, &uniform.clipRadii, &uniform.clipCount, value);
    uniform.fill = (vector_float4){ (float)geometry.fillRed, (float)geometry.fillGreen,
                                    (float)geometry.fillBlue, (float)geometry.fillAlpha };
    uniform.stroke = (vector_float4){ (float)geometry.strokeRed, (float)geometry.strokeGreen,
                                      (float)geometry.strokeBlue, (float)geometry.strokeAlpha };
    id<MTLRenderPipelineState> pipeline = metalView.composableUsesMultisampling
        ? metalView.composableMultisampleVectorPipeline : metalView.composableVectorPipeline;
    if (!pipeline) return NO;
    [encoder setRenderPipelineState:pipeline];
    [encoder setVertexBuffer:buffer offset:0 atIndex:0];
    [encoder setVertexBytes:&uniform length:sizeof(uniform) atIndex:1];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:node.vectorPreparedVertexCount];
#ifdef CJGUI_INTERNAL_TESTING
    if (metalView.testComposableVectorDrawCount < UINT32_MAX)
        metalView.testComposableVectorDrawCount += 1;
#endif
    (void)uploaded;
    return YES;
}

static void CjguiEncodeMetalTexture(id<MTLRenderCommandEncoder> encoder, CGFloat pointWidth, CGFloat pointHeight,
                                    CGFloat x, CGFloat y, CGFloat width, CGFloat height, id<MTLTexture> texture,
                                    CjguiInternalRendererComposableNode value, BOOL appKitBitmapRows,
                                    float paintAlpha) {
    if (!texture || width <= 0.0 || height <= 0.0) return;
    float left = -1.0f + (float)(2.0 * x / pointWidth);
    float right = -1.0f + (float)(2.0 * (x + width) / pointWidth);
    float top = 1.0f - (float)(2.0 * y / pointHeight);
    float bottom = 1.0f - (float)(2.0 * (y + height) / pointHeight);
    CJGuiInternalMetalTextureVertex vertices[6] = {0};
    vector_float2 positions[6] = { { left, top }, { right, top }, { left, bottom }, { right, top }, { right, bottom }, { left, bottom } };
    // CGBitmapContext's first byte row is the opposite vertical origin from
    // the normalized rows consumed by this Metal texture sampler. AppKit text
    // is rasterized into that raw BGRA memory, while decoded image resources
    // already use Metal's expected row orientation. Keep the distinction at
    // the sole texture-encoding boundary so neither TextKit nor image loading
    // gains a second coordinate model.
    float textureTop = appKitBitmapRows ? 1.0f : 0.0f;
    float textureBottom = appKitBitmapRows ? 0.0f : 1.0f;
    vector_float2 texCoords[6] = { { 0, textureTop }, { 1, textureTop }, { 0, textureBottom },
                                   { 1, textureTop }, { 1, textureBottom }, { 0, textureBottom } };
    vector_float2 scenePoints[6] = { { (float)x, (float)y }, { (float)(x + width), (float)y }, { (float)x, (float)(y + height) }, { (float)(x + width), (float)y }, { (float)(x + width), (float)(y + height) }, { (float)x, (float)(y + height) } };
    for (uint32_t i = 0; i < 6; i++) {
        vertices[i].position = positions[i]; vertices[i].texCoord = texCoords[i]; vertices[i].scenePoint = scenePoints[i];
        CjguiPopulateMetalClipChain(vertices[i].clips, &vertices[i].clipRadii, &vertices[i].clipCount, value);
        vertices[i].nodeRect = (vector_float4){ (float)value.x, (float)value.y, (float)value.width, (float)value.height };
        vertices[i].nodeCornerRadius = (float)MIN(MAX(0.0, value.cornerRadius), MIN((CGFloat)value.width, (CGFloat)value.height) / 2.0);
        vertices[i].paintAlpha = paintAlpha;
    }
    [encoder setVertexBytes:vertices length:sizeof(vertices) atIndex:0];
    [encoder setFragmentTexture:texture atIndex:0];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
}

static NSString *CjguiComposableGpuTextValueWithActiveValue(CJGuiInternalComposableSceneNode *node,
                                                             NSString *activeValue) {
    if (!node) return @"";
    NSString *value = activeValue ?: node.value ?: @"";
    uint32_t kind = node.node.nodeKind;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return value;
    // A tab page title is a LABEL. Its value carries the page key that Cangjie
    // resolves the activation against, so painting "label value" would put a
    // machine key on screen next to the human title.
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) return node.label ?: @"";
    // Buttons carry their visible action in both projection fields: label is
    // the semantic name and value remains the ordinary display value.  Paint
    // it once when those fields agree, without changing either the accessible
    // label/value pair or distinct form-control label/value rendering.
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON && node.label.length > 0 &&
        [node.label isEqualToString:value]) return value;
    return node.label.length > 0 ? [NSString stringWithFormat:@"%@ %@", node.label, value] : value;
}

static NSString *CjguiComposableGpuTextValue(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableGpuTextValueWithActiveValue(node, nil);
}

// The composable node kinds whose visible text is owned by the framework:
// admission, scene text-resource accounting, encoding, CPU-overlay exclusion and
// readback classification all ask THIS predicate. A tab page title belongs here
// with the buttons: it is an actionable control that carries a scoped identity
// and an accessible label, so leaving it out made the title reachable by
// pointer/AX/keyboard while never painting its own text.
//
// The active-TextKit paths (active-input refresh, decoration restore and
// focus-loss preparation) must NOT ask this predicate: those paths need a caret,
// selection and marked text, and a title has none. They ask
// `CjguiComposableNodeIsTextInput` instead, so a focused title cannot reach a
// focus-loss reraster that is charged outside the scene text-budget check.
static BOOL CjguiComposableNodeHasGpuText(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT;
}

// A plain text label and a tab page title draw their own single line inside the
// declared rect, so both use the tight label inset. Inputs and buttons keep the
// larger control-chrome inset. Measurement and both raster paths must agree.
static BOOL CjguiComposableNodeUsesLabelTextInset(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE;
}

// A text texture is only a projection of the pixels that can reach the
// drawable in this scene.  Keep its logical rectangle in scene coordinates:
// the encoder can then place the tile without changing TextKit/NSString
// layout coordinates, while the allocation is bounded by the resolved clip.
static NSRect CjguiComposableTextTextureRectForNodeWithText(CJGuiInternalComposableSceneNode *node,
                                                             NSString *displayText) {
    if (!node) return NSZeroRect;
    CjguiInternalRendererComposableNode value = node.node;
    NSRect nodeRect = NSMakeRect((CGFloat)value.x, (CGFloat)value.y,
                                 MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
    NSRect clipRect = NSMakeRect((CGFloat)value.clipX, (CGFloat)value.clipY,
                                 MAX(0.0, (CGFloat)value.clipWidth), MAX(0.0, (CGFloat)value.clipHeight));
    if (value.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        NSWidth(nodeRect) > 14.0 && NSHeight(nodeRect) > 4.0) {
        NSString *text = displayText ?: CjguiComposableGpuTextValue(node);
        if (text.length == 0) return NSZeroRect;
        CGFloat insetY = CjguiComposableNodeUsesLabelTextInset(value.nodeKind) ? 2.0 : 6.0;
        NSRect drawRect = NSInsetRect(nodeRect, 7.0, insetY);
        NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
        paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
        // Composable prose wraps by word on every path that produces pixels or
        // estimates their extent: character wrapping split English words across
        // lines ("tre" / "e"). Ideographs still break per character.
        paragraph.lineBreakMode = value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
            ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail;
        NSDictionary *attributes = @{NSFontAttributeName: CjguiComposableFont(node),
                                     NSParagraphStyleAttributeName: paragraph};
        NSRect measured = [text boundingRectWithSize:NSMakeSize(NSWidth(drawRect), CGFLOAT_MAX / 4.0)
                                             options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                                          attributes:attributes];
        // Glyph antialiasing and fallback font overhang need a small guard band.
        // The measurement uses precisely the same font, paragraph rule and
        // original draw width as the raster path; it never changes wrapping.
        CGFloat drawnWidth = MIN(NSWidth(drawRect), MAX(1.0, ceil(NSWidth(measured)) + 2.0));
        CGFloat drawnHeight = MIN(NSHeight(drawRect), MAX(1.0, ceil(NSHeight(measured)) + 2.0));
        nodeRect = NSIntersectionRect(nodeRect,
            NSMakeRect(NSMinX(drawRect) - 1.0, NSMinY(drawRect) - 1.0,
                       drawnWidth + 2.0, drawnHeight + 2.0));
    }
    return NSIntersectionRect(nodeRect, clipRect);
}

static NSRect CjguiComposableTextTextureRectForNode(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableTextTextureRectForNodeWithText(node, nil);
}

// The rectangular texture allocation is only a conservative intersection;
// its pixels are still rasterized through every rounded ancestor clip. Keep a
// canonical copy of that chain in each text-resource key so a radius-only
// projection update cannot reuse stale pixels from the same rectangle.
static NSString *CjguiComposableTextClipSignature(CJGuiInternalComposableSceneNode *node) {
    if (!node) return @"";
    CjguiInternalRendererComposableNode value = node.node;
    uint32_t count = CjguiComposableClipConstraintCount(value);
    NSMutableString *signature = [NSMutableString stringWithString:@"clip"];
    NSRect nodeRect = NSMakeRect((CGFloat)value.x, (CGFloat)value.y,
                                 MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
    for (uint32_t index = 0; index < count; index++) {
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableClipConstraintAt(value, index, &x, &y, &width, &height, &radius);
        NSRect constraint = NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
        // An ordinary ancestor rectangle containing the whole node cannot
        // change its raster pixels when the node moves inside that ancestor.
        if (radius == 0.0 && NSContainsRect(constraint, nodeRect)) continue;
        [signature appendFormat:@":%.3f:%.3f:%.3f:%.3f:%.3f",
            x - (CGFloat)value.x, y - (CGFloat)value.y, width, height, radius];
    }
    return signature;
}

// The key must cover EVERYTHING that changes the rasterized pixels. Style runs
// are part of that: a run-only change (an inline-code tint, a caret mark, a
// newly bold span) left the key identical and reused a stale texture, so the
// window kept painting the previous appearance.
static NSString *CjguiComposableTextTextureKey(CJGuiInternalComposableSceneNode *node, CGFloat scaleX, CGFloat scaleY,
                                               NSString *displayText, NSRect textureRect) {
    if (!node) return @"";
    CjguiInternalRendererComposableNode value = node.node;
    // The node's dynamic text alpha is deliberately NOT part of the key: it is
    // applied as a per-draw multiplier on the cached glyph texture, so an
    // opacity animation never re-prepares TextKit or re-rasterizes. The static
    // colour channels DO participate, so a real colour change still invalidates.
    NSString *key = [NSString stringWithFormat:@"%u:%lld:%lld:%0.3f:%0.3f:%0.3f:%u:%u:%0.4f:%0.4f:%0.4f:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%@:%@:%@",
            value.nodeKind, value.width, value.height,
            scaleX, scaleY, value.fontSize, value.fontWeight, value.fontFamily,
            value.textRed, value.textGreen, value.textBlue,
            NSMinX(textureRect) - (CGFloat)value.x, NSMinY(textureRect) - (CGFloat)value.y,
            NSWidth(textureRect), NSHeight(textureRect),
            NSMinX(textureRect) - (CGFloat)value.x, NSMinY(textureRect) - (CGFloat)value.y,
            displayText ?: @"", CjguiComposableTextClipSignature(node), node.styleRunsSignature ?: @""];
    return key;
}

static BOOL CjguiCheckedComposableTextTextureBytes(CGFloat logicalWidth, CGFloat logicalHeight,
                                                    CGFloat scaleX, CGFloat scaleY,
                                                    NSUInteger *outWidth, NSUInteger *outHeight,
                                                    NSUInteger *outBytesPerRow, uint64_t *outBytes) {
    if (!outWidth || !outHeight || !outBytesPerRow || !outBytes || logicalWidth <= 0.0 || logicalHeight <= 0.0 ||
        !isfinite(scaleX) || !isfinite(scaleY) || scaleX <= 0.0 || scaleY <= 0.0) return NO;
    CGFloat scaledWidth = ceil(logicalWidth * scaleX), scaledHeight = ceil(logicalHeight * scaleY);
    if (!isfinite(scaledWidth) || !isfinite(scaledHeight) || scaledWidth < 1.0 || scaledHeight < 1.0 ||
        scaledWidth > CjguiComposableTextTextureDimensionCapacity || scaledHeight > CjguiComposableTextTextureDimensionCapacity ||
        scaledWidth > (CGFloat)NSUIntegerMax || scaledHeight > (CGFloat)NSUIntegerMax) return NO;
    NSUInteger width = (NSUInteger)scaledWidth, height = (NSUInteger)scaledHeight;
    if (width > NSUIntegerMax / 4u) return NO;
    NSUInteger bytesPerRow = width * 4u;
    if (height > NSUIntegerMax / bytesPerRow) return NO;
    NSUInteger bytes = bytesPerRow * height;
    if (bytes > CjguiComposableTextTexturePerNodeByteCapacity) return NO;
    *outWidth = width; *outHeight = height; *outBytesPerRow = bytesPerRow; *outBytes = bytes;
    return YES;
}

// Work in integer logical points so adjacent tiles share an exact edge at
// both supported display scales. The last tile may be smaller. Each returned
// rect is independently admitted by the old 8 MiB allocation check; the sum
// is charged to the 24 MiB accepted scene before any texture is created.
static NSArray<NSValue *> *CjguiPlanComposableTextTiles(NSRect visibleRect, CGFloat scale,
                                                        uint64_t *outBytes) {
    if (outBytes) *outBytes = 0;
    if (NSIsEmptyRect(visibleRect) || !isfinite(scale) || scale <= 0.0) return nil;
    CGFloat maximumLogicalWidth = floor(CjguiComposableTextTextureDimensionCapacity / scale);
    if (maximumLogicalWidth < 1.0) return nil;
    NSMutableArray<NSValue *> *tiles = [NSMutableArray array];
    uint64_t total = 0;
    CGFloat right = NSMaxX(visibleRect), bottom = NSMaxY(visibleRect);
    for (CGFloat x = NSMinX(visibleRect); x < right;) {
        CGFloat width = MIN(right - x, maximumLogicalWidth);
        NSUInteger pixelWidth = (NSUInteger)ceil(width * scale);
        if (pixelWidth == 0 || pixelWidth > NSUIntegerMax / 4u) return nil;
        NSUInteger maximumPixelRows = MIN((NSUInteger)CjguiComposableTextTextureDimensionCapacity,
            (NSUInteger)(CjguiComposableTextTexturePerNodeByteCapacity / (pixelWidth * 4u)));
        CGFloat maximumLogicalHeight = floor((CGFloat)maximumPixelRows / scale);
        if (maximumLogicalHeight < 1.0) return nil;
        for (CGFloat y = NSMinY(visibleRect); y < bottom;) {
            CGFloat height = MIN(bottom - y, maximumLogicalHeight);
            NSUInteger checkedWidth = 0, checkedHeight = 0, rowBytes = 0;
            uint64_t bytes = 0;
            if (!CjguiCheckedComposableTextTextureBytes(width, height, scale, scale,
                                                        &checkedWidth, &checkedHeight, &rowBytes, &bytes) ||
                bytes > CjguiComposableTextTextureByteCapacity - total || tiles.count >= 64) return nil;
            [tiles addObject:[NSValue valueWithRect:NSMakeRect(x, y, width, height)]];
            total += bytes;
            y += height;
        }
        x += width;
    }
    if (outBytes) *outBytes = total;
    return tiles;
}

// One candidate-scoped AppKit TextKit stack for a text node. Prepared once
// before the tile loop, consumed by every tile's glyph-range draw, and
// released with the candidate — it is never retained past the prepare call,
// so ownership stays with the candidate transaction that created it.
@interface CjguiPreparedTextNodeLayout : NSObject
@property(nonatomic, strong) NSTextStorage *storage;
@property(nonatomic, strong) NSLayoutManager *layoutManager;
@property(nonatomic, strong) NSTextContainer *container;
@property(nonatomic, assign) NSRect textRect;
// Captured at prepare time because an empty value has no glyph to measure, and
// asking the storage for the attribute at index 0 throws on zero length.
@property(nonatomic, assign) CGFloat defaultLineHeight;
@end
@implementation CjguiPreparedTextNodeLayout
@end

// Forward declaration: the UTF-8 byte -> UTF-16 offset helper is defined below
// its first use in the accepted-caret query, so it must be declared before that
// caller (C99 forbids implicit function declarations).
static NSUInteger CjguiComposableUtf16OffsetForByte(const char *utf8, NSUInteger utf8Length, NSUInteger byteOffset);

// Prepares the shared layout for one text node with the exact attributes the
// per-tile `drawWithRect` path used (same font, color, paragraph break mode,
// and inset rect), so glyph-range tile drawing renders identical pixels.
// 2026-09-26(B2):**只读**查询 —— 由节点上**已持留**的 accepted 排版产物求 caret 矩形。
// 组合全程使用本文件既有 AppKit 用法(:6525 行矩形 / :6536 字形位置),**不新建临时布局**,
// 因而不会重排(契约 implementation order 2)。返回 NO 时调用方应给出具名 pending(不得静默零矩形)。

static BOOL CjguiComposableAcceptedTextCaretRect(CJGuiInternalComposableSceneNode *node,
                                                 NSUInteger displayByte, CGFloat caretWidthPt,
                                                 NSRect *outRect) {
    if (!node || !outRect) return NO;
    CjguiPreparedTextNodeLayout *prepared = node.preparedTextLayout;
    if (!prepared || !prepared.layoutManager || !prepared.container) return NO;
    NSLayoutManager *layoutManager = prepared.layoutManager;
    NSUInteger glyphCount = layoutManager.numberOfGlyphs;
    NSUInteger storageLength = prepared.storage.length;
    // displayByte is a UTF-8 BYTE offset; TextKit wants UTF-16 character indices.
    // Passing bytes as characters misplaces the caret on CJK text (3-byte chars
    // shift it ~2 chars late — measured on a 4-char CJK title).
    NSUInteger character = MIN(displayByte, storageLength);
    NSString *storageText = prepared.storage.string;
    const char *storageUtf8 = storageText.UTF8String;
    if (storageUtf8) {
        character = MIN((NSUInteger)CjguiComposableUtf16OffsetForByte(
            storageUtf8, strlen(storageUtf8), (uint32_t)displayByte), storageLength);
    }
    if (glyphCount == 0) {
        // An empty value still has a caret: the writer has to see where the first
        // character will land. Returning NO here made an empty paragraph look
        // unfocused, and a document whose first line is empty lost the caret on
        // click. There is no glyph to measure, so the position is the container's
        // own origin and the height is the line height captured at prepare time —
        // asking the storage for the attribute at index 0 throws on zero length.
        *outRect = NSMakeRect(prepared.textRect.origin.x, prepared.textRect.origin.y,
                              caretWidthPt, prepared.defaultLineHeight);
        return YES;
    }
    NSUInteger glyph = MIN([layoutManager glyphIndexForCharacterAtIndex:MIN(character, storageLength)],
                           glyphCount - 1);
    NSRange lineGlyphRange = NSMakeRange(0, 0);
    NSRect line = [layoutManager lineFragmentRectForGlyphAtIndex:glyph effectiveRange:&lineGlyphRange];
    if (NSIsEmptyRect(line)) {
        glyph = glyphCount - 1;
        line = [layoutManager lineFragmentRectForGlyphAtIndex:glyph effectiveRange:&lineGlyphRange];
    }
    CGFloat caretOriginX = prepared.textRect.origin.x +
        [layoutManager locationForGlyphAtIndex:glyph].x;
    // A position at or past the last character of its line fragment has no glyph
    // to stand on: it belongs at the END of the laid-out part of that line. Taking
    // the first unlabelled glyph's origin instead put the caret before the last
    // character the moment the value ended (and before the wrapped word at an
    // end-of-line caret).
    NSRange lineCharacterRange = [layoutManager characterRangeForGlyphRange:lineGlyphRange
                                                          actualGlyphRange:NULL];
    if (character >= NSMaxRange(lineCharacterRange)) {
        NSRect used = [layoutManager lineFragmentUsedRectForGlyphAtIndex:glyph effectiveRange:NULL];
        caretOriginX = prepared.textRect.origin.x + used.origin.x + used.size.width;
        // A value ending in a newline owns one more, empty line: TextKit reports it
        // as the extra fragment after that glyph, and the caret belongs at its start.
        // This applies only at the END of the value. `extraLineFragmentRect` is a
        // single layout-wide property, so a caret parked at the end of an interior
        // line ("abc|" before its '\n') would otherwise be dragged down to that
        // trailing empty line.
        NSRect extra = layoutManager.extraLineFragmentRect;
        if (character >= storageLength && !NSIsEmptyRect(extra)) {
            caretOriginX = prepared.textRect.origin.x + extra.origin.x;
            line = extra;
        }
    }
    *outRect = NSMakeRect(caretOriginX, prepared.textRect.origin.y + line.origin.y,
                          caretWidthPt, line.size.height);
    return YES;
}

// A presentation style run: display byte range plus the attributes to apply over
// it. The product composes nesting into one flat, non-overlapping list, so the
// renderer never applies overlapping layers. Byte offsets are UTF-8.
typedef struct CjguiInternalTextStyleRun {
    uint32_t start;
    uint32_t end;
    double fontSize;
    uint32_t fontWeight;      // 0/1 legacy boolean, or 100..1000 numeric weight
    uint32_t fontFamily;      // 0 system, 1 monospaced
    float red;
    float green;
    float blue;
    float alpha;
    // Optional run background (inline code, highlighted spans). hasBackground
    // distinguishes "no background" from a fully transparent one.
    uint32_t hasBackground;
    float backgroundRed;
    float backgroundGreen;
    float backgroundBlue;
    float backgroundAlpha;
} CjguiInternalTextStyleRun;

static NSAttributedString *CjguiComposableAttributedText(CJGuiInternalComposableSceneNode *node,
    NSString *displayText, NSDictionary *baseAttributes, const CjguiInternalTextStyleRun *runs,
    uint32_t runCount);
static CjguiPreparedTextNodeLayout *CjguiPrepareTextNodeLayout(
    CJGuiInternalComposableSceneNode *node, NSString *displayText, CGFloat scaleX,
    NSData *styleRunData) {
    NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
    if (NSIsEmptyRect(textRect) || textRect.size.width <= 0 || textRect.size.height <= 0) return nil;
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
        ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
            ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
    paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
    // Glyph textures are rasterized with an OPAQUE colour and the node's text
    // alpha is re-applied as a per-draw multiplier (CjguiEncodeMetalTexture).
    // This keeps the cached texture and the prepared layout valid across an
    // opacity animation instead of rebuilding TextKit and re-rasterizing every
    // frame; a static colour change still invalidates through the texture key.
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                               blue:node.node.textBlue alpha:1.0];
    NSFont *baseFont = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: baseFont,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    // B4(2026-09-26): the shared prepared layout must carry the node's style
// runs. Since B2 made EVERY text node draw through this prepared TextKit
// stack, run-based paint (selection background, caret tint, inline code)
// was silently dropped here while the non-prepared path still applied it.
// Apply the SAME decoded runs the drawWithRect path uses.
    NSAttributedString *preparedAttributed = nil;
    if (getenv("PHAROS_TRACE_RUNS")) {
        fprintf(stderr, "PHAROS_PREP_RUNS node=%llu rawDataLen=%lu\n",
                (unsigned long long)node.node.nodeId,
                (unsigned long)styleRunData.length);
    }
    if (styleRunData.length >= (NSUInteger)sizeof(CjguiInternalTextStyleRun)) {
        preparedAttributed = CjguiComposableAttributedText(node, displayText ?: @"", attributes,
            (const CjguiInternalTextStyleRun *)styleRunData.bytes,
            (uint32_t)(styleRunData.length / sizeof(CjguiInternalTextStyleRun)));
    }
    NSTextStorage *storage = preparedAttributed
        ? [[NSTextStorage alloc] initWithAttributedString:preparedAttributed]
        : [[NSTextStorage alloc] initWithString:displayText ?: @""
                                     attributes:attributes];
    NSLayoutManager *layoutManager = [NSLayoutManager new];
    [storage addLayoutManager:layoutManager];
    NSTextContainer *container = [[NSTextContainer alloc] initWithSize:textRect.size];
    container.widthTracksTextView = NO;
    // drawWithRect uses the complete inset rectangle for line breaking. The
    // default TextKit padding would narrow that width by 10pt and move glyphs
    // whenever the same node crosses the single/multiple tile boundary.
    container.lineFragmentPadding = 0.0;
    [layoutManager addTextContainer:container];
    CjguiPreparedTextNodeLayout *prepared = [CjguiPreparedTextNodeLayout new];
    prepared.storage = storage;
    prepared.layoutManager = layoutManager;
    prepared.container = container;
    prepared.textRect = textRect;
    prepared.defaultLineHeight = ceil([layoutManager defaultLineHeightForFont:baseFont]);
    return prepared;
}


// NOTE(P1 verify): the CjguiInternalTextStyleRun definition was moved above
// CjguiPrepareTextNodeLayout, which takes sizeof of the complete struct; a
// forward declaration alone left it incomplete at the use site.

// Build the attributed string for a node: base attributes plus every run. With
// runCount == 0 this yields exactly the base attributes the single-style path
// uses, which is what makes the "one run covering the whole text" comparison a
// real equivalence check rather than a tautology.
// The product speaks UTF-8 byte offsets (that is what the SourceMap is built
// on), but NSRange is measured in UTF-16 code units. Treating bytes as units
// shifted every run after the first non-ASCII character, so a link or an inline
// code span was coloured in the wrong place (or not visibly at all).
static NSUInteger CjguiComposableUtf16OffsetForByte(const char *utf8, NSUInteger utf8Length,
                                                    NSUInteger byteOffset) {
    if (!utf8) return 0;
    NSUInteger clamped = MIN(byteOffset, utf8Length);
    while (clamped > 0) {
        NSString *prefix = [[NSString alloc] initWithBytes:utf8 length:clamped encoding:NSUTF8StringEncoding];
        if (prefix) return prefix.length;
        // A mid-scalar offset cannot be honoured: walk back to a boundary.
        clamped--;
    }
    return 0;
}

static NSAttributedString *CjguiComposableAttributedText(CJGuiInternalComposableSceneNode *node,
                                                         NSString *displayText,
                                                         NSDictionary *baseAttributes,
                                                         const CjguiInternalTextStyleRun *runs,
                                                         uint32_t runCount) {
    NSMutableAttributedString *attributed = [[NSMutableAttributedString alloc]
        initWithString:displayText attributes:baseAttributes];
    if (!attributed || runCount == 0 || !runs) return attributed;
    NSUInteger length = attributed.length;
    const char *utf8 = displayText.UTF8String;
    NSUInteger utf8Length = utf8 ? strlen(utf8) : 0;
    for (uint32_t i = 0; i < runCount; i++) {
        const CjguiInternalTextStyleRun *run = &runs[i];
        NSUInteger start = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->start), length);
        NSUInteger end = MIN(CjguiComposableUtf16OffsetForByte(utf8, utf8Length, run->end), length);
        if (end <= start) continue;
        NSRange range = NSMakeRange(start, end - start);
        NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
        paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
            ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
                ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
        // CJK line-break prohibition: push trailing punctuation onto the previous
        // line instead of letting it start a line. Without this the layout
        // orphaned characters like "，" at the beginning of a line.
        paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
        NSFont *font = CjguiComposableFontForStyle(run->fontSize, run->fontWeight, run->fontFamily);
        NSColor *color = [NSColor colorWithSRGBRed:run->red green:run->green blue:run->blue alpha:run->alpha];
        [attributed addAttribute:NSFontAttributeName value:font ?: [NSFont systemFontOfSize:13.0] range:range];
        [attributed addAttribute:NSForegroundColorAttributeName value:color range:range];
        [attributed addAttribute:NSParagraphStyleAttributeName value:paragraph range:range];
        if (run->fontFamily == 2 || run->fontFamily == 3) {
            // Synthetic oblique. Asking NSFontManager for an italic face returns
            // the upright system font for San Francisco, so emphasis had no
            // visible slant; NSObliqueness always produces one.
            [attributed addAttribute:NSObliquenessAttributeName value:@0.20 range:range];
        }
        if (run->hasBackground) {
            NSColor *background = [NSColor colorWithSRGBRed:run->backgroundRed
                                                       green:run->backgroundGreen
                                                        blue:run->backgroundBlue
                                                       alpha:run->backgroundAlpha];
            if (background) {
                [attributed addAttribute:NSBackgroundColorAttributeName value:background range:range];
            }
        }
    }
    return attributed;
}

// Decode "start:end:fontSize:weight:family:r:g:b:a;..." into a C array. The
// caller owns the buffer via the returned NSData.
static NSData *CjguiComposableDecodeStyleRuns(NSString *encoded) {
    if (encoded.length == 0) return nil;
    NSMutableData *buffer = [NSMutableData data];
    for (NSString *item in [encoded componentsSeparatedByString:@";"]) {
        if (item.length == 0) continue;
        NSArray<NSString *> *fields = [item componentsSeparatedByString:@":"];
        if (fields.count < 9) continue;
        CjguiInternalTextStyleRun run = {0};
        run.start = (uint32_t)fields[0].intValue;
        run.end = (uint32_t)fields[1].intValue;
        run.fontSize = fields[2].doubleValue;
        run.fontWeight = (uint32_t)fields[3].intValue;
        run.fontFamily = (uint32_t)fields[4].intValue;
        run.red = fields[5].floatValue;
        run.green = fields[6].floatValue;
        run.blue = fields[7].floatValue;
        run.alpha = fields[8].floatValue;
        if (fields.count >= 13) {
            run.hasBackground = (uint32_t)fields[9].intValue;
            run.backgroundRed = fields[10].floatValue;
            run.backgroundGreen = fields[11].floatValue;
            run.backgroundBlue = fields[12].floatValue;
            run.backgroundAlpha = fields.count >= 14 ? fields[13].floatValue : 1.0f;
        }
        [buffer appendBytes:&run length:sizeof(run)];
    }
    return buffer.length > 0 ? buffer : nil;
}

static id<MTLTexture> CjguiRasterComposableTextTexture(CJGuiInternalMetalView *metalView,
                                                        CJGuiInternalComposableSceneNode *node,
                                                        CGFloat scaleX, CGFloat scaleY,
                                                        NSString *displayText,
                                                        NSRect textureRect,
                                                        uint64_t *outByteCount,
                                                        CjguiPreparedTextNodeLayout *prepared
#ifdef CJGUI_INTERNAL_TESTING
                                                        , CjguiInternalTextWorkReason reason
#endif
                                                        , const CjguiInternalTextStyleRun *styleRuns
                                                        , uint32_t styleRunCount
                                                        ) {
    if (outByteCount) *outByteCount = 0;
    uint64_t rasterStarted = CjguiMonotonicMicros();
    if (!metalView.device || !node || node.node.width <= 0 || node.node.height <= 0) return nil;
    NSString *text = displayText ?: @"";
    if (text.length == 0 || node.node.textAlpha <= 0.0) return nil;
    NSUInteger width = 0, height = 0, bytesPerRow = 0;
    uint64_t byteCount = 0;
    if (NSIsEmptyRect(textureRect)) return nil;
    if (!CjguiCheckedComposableTextTextureBytes(NSWidth(textureRect), NSHeight(textureRect),
                                                scaleX, scaleY, &width, &height, &bytesPerRow, &byteCount)) return nil;
    // The AppKit bitmap and Metal upload share one bounded BGRA allocation.
    // Normalize premultiplied components in place before upload instead of
    // retaining a second full-sized conversion buffer.
    NSMutableData *bgra = [NSMutableData dataWithLength:(NSUInteger)byteCount];
    CjguiAddTextCpuScratch(metalView, bgra ? byteCount : 0);
    CGColorSpaceRef colorSpace = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef bitmapContext = colorSpace ? CGBitmapContextCreate(bgra.mutableBytes, width, height, 8, bytesPerRow,
        colorSpace, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little) : NULL;
    if (colorSpace) CGColorSpaceRelease(colorSpace);
    NSGraphicsContext *context = bitmapContext ? [NSGraphicsContext graphicsContextWithCGContext:bitmapContext flipped:YES] : nil;
    if (!bgra || !bitmapContext || !context) {
        if (bitmapContext) CGContextRelease(bitmapContext);
        CjguiDropTextCpuScratch(metalView, byteCount);
        return nil;
    }
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT
        ? NSLineBreakByWordWrapping : (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
            ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
    paragraph.lineBreakStrategy = NSLineBreakStrategyPushOut;
    // Glyph textures are rasterized with an OPAQUE colour and the node's text
    // alpha is re-applied as a per-draw multiplier (CjguiEncodeMetalTexture).
    // This keeps the cached texture and the prepared layout valid across an
    // opacity animation instead of rebuilding TextKit and re-rasterizing every
    // frame; a static colour change still invalidates through the texture key.
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                               blue:node.node.textBlue alpha:1.0];
    NSFont *baseFont = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: baseFont,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    NSGraphicsContext *previousContext = NSGraphicsContext.currentContext;
    [NSGraphicsContext setCurrentContext:context];
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *transform = [NSAffineTransform transform];
    [transform scaleXBy:scaleX yBy:scaleY];
    // Keep the original node-local layout width.  Only the backing bitmap is
    // translated to the resolved visible tile, so line wrapping and selection
    // geometry do not reflow when an ancestor clip moves.
    [transform translateXBy:(NSMinX(textureRect) - (CGFloat)node.node.x) * -1.0
                       yBy:(NSMinY(textureRect) - (CGFloat)node.node.y) * -1.0];
    [transform concat];
    NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
#ifdef CJGUI_INTERNAL_TESTING
    // `drawWithRect` fuses layout and glyph drawing in one AppKit API, so this
    // interval is honest "draw-with-layout" work only. Splitting layout from
    // drawing requires the explicit TextKit path and is NOT claimed here.
    uint64_t drawStarted = CjguiMonotonicMicros();
#endif
    if (prepared) {
        // Shared-layout tile draw: the candidate prepared this node's TextKit
        // stack once, so this tile only draws the glyphs whose bounding rect
        // intersects it — no per-tile full-string layout.
        // textureRect is in scene coordinates; TextKit's container begins at
        // the node-local inset. Subtract both origins before selecting glyphs.
        NSRect tileInContainer = NSMakeRect(textureRect.origin.x - (CGFloat)node.node.x - prepared.textRect.origin.x,
                                            textureRect.origin.y - (CGFloat)node.node.y - prepared.textRect.origin.y,
                                            textureRect.size.width, textureRect.size.height);
        NSRange glyphRange = [prepared.layoutManager
            glyphRangeForBoundingRect:tileInContainer inTextContainer:prepared.container];
        // B4(2026-09-26, Sol consult): AppKit splits run backgrounds and glyphs into
        // TWO draw calls on NSLayoutManager. Drawing glyphs only silently dropped every
        // run-based paint on this shared-layout path -- selection background, caret tint,
        // inline-code background (pixel-identical screenshots even with an opaque red
        // selection run). Background first, then glyphs, same range and origin.
        [prepared.layoutManager drawBackgroundForGlyphRange:glyphRange
                                                    atPoint:prepared.textRect.origin];
        [prepared.layoutManager drawGlyphsForGlyphRange:glyphRange
                                                atPoint:prepared.textRect.origin];
    } else {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t drawStarted = CjguiMonotonicMicros();
#endif
    if (styleRunCount == 0) {
        // A scene node may carry its runs through the session table instead.
        CJGuiInternalSession *sessionContext = CjguiLookupSession(metalView.sessionToken);
        NSData *decoded = CjguiComposableDecodeStyleRuns(
            sessionContext.composableTextStyleRunsRaw[@(node.node.nodeId)]);
        if (getenv("PHAROS_TRACE_RUNS")) {
            fprintf(stderr, "PHAROS_RUNS_CONSUME node=%llu token=%llu bytes=%lu\n",
                    (unsigned long long)node.node.nodeId,
                    (unsigned long long)metalView.sessionToken, (unsigned long)decoded.length);
        }
        if (decoded.length > 0) {
            styleRuns = (const CjguiInternalTextStyleRun *)decoded.bytes;
            styleRunCount = (uint32_t)(decoded.length / sizeof(CjguiInternalTextStyleRun));
            // The runs are part of the texture key. Stamp them on the very node
            // being rasterized, so a run-only change (a caret mark, a tint, a new
            // bold span) invalidates the cached texture on the next frame.
            node.styleRunsSignature = sessionContext.composableTextStyleRunsRaw[@(node.node.nodeId)];
        }
    }
    if (styleRunCount > 0) {
        NSAttributedString *attributed = CjguiComposableAttributedText(node, text, attributes,
                                                                      styleRuns, styleRunCount);
        [attributed drawWithRect:textRect
                         options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading];
    } else {
        // Unchanged single-style path: no attributed string is built at all.
        [text drawWithRect:textRect
                   options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                attributes:attributes];
    }
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextStaticDrawWithLayoutMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextStaticDrawWithLayoutMicros, CjguiMonotonicMicros() - drawStarted);
#endif
    }
    [NSGraphicsContext restoreGraphicsState];
    [NSGraphicsContext setCurrentContext:previousContext];

    uint8_t *pixels = bgra.mutableBytes;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t normalizeStarted = CjguiMonotonicMicros();
#endif
    for (NSUInteger y = 0; y < height; y++) {
        uint8_t *row = pixels + y * bytesPerRow;
        for (NSUInteger x = 0; x < width; x++) {
            uint8_t *pixel = row + x * 4;
            uint8_t alpha = pixel[3];
            // AppKit's drawable bitmap is premultiplied RGBA. The shared
            // texture pipeline consumes ordinary RGBA texels, so normalize
            // it before channel-order conversion rather than blending twice.
            pixel[0] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[0] * 255 + alpha / 2) / alpha);
            pixel[1] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[1] * 255 + alpha / 2) / alpha);
            pixel[2] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[2] * 255 + alpha / 2) / alpha);
        }
    }
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextNormalizeMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextNormalizeMicros, CjguiMonotonicMicros() - normalizeStarted);
#endif
    CGContextRelease(bitmapContext);
    MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                                                                            width:width height:height mipmapped:NO];
    descriptor.usage = MTLTextureUsageShaderRead;
    descriptor.storageMode = MTLStorageModeShared;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t textureCreateStarted = CjguiMonotonicMicros();
#endif
    id<MTLTexture> texture = [metalView.device newTextureWithDescriptor:descriptor];
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableTextTextureCreateMicros = CjguiSaturatingAddU64(
        metalView.testComposableTextTextureCreateMicros, CjguiMonotonicMicros() - textureCreateStarted);
#endif
    if (!texture) {
        CjguiDropTextCpuScratch(metalView, byteCount);
        return nil;
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadStarted = CjguiMonotonicMicros();
    CjguiRecordTextWork(metalView, node.node.projectionVersion,
                        [displayText lengthOfBytesUsingEncoding:NSUTF8StringEncoding], reason);
    metalView.testComposableTextRasterCount = CjguiSaturatingAddU64(metalView.testComposableTextRasterCount, 1);
    metalView.testComposableTextRasterBytes = CjguiSaturatingAddU64(metalView.testComposableTextRasterBytes, byteCount);
    metalView.testComposableTextRasterMicros = CjguiSaturatingAddU64(metalView.testComposableTextRasterMicros,
                                                                       uploadStarted - rasterStarted);
#endif
    [texture replaceRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0 withBytes:bgra.bytes bytesPerRow:bytesPerRow];
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadEnded = CjguiMonotonicMicros();
    metalView.testComposableTextUploadCount = CjguiSaturatingAddU64(metalView.testComposableTextUploadCount, 1);
    metalView.testComposableTextUploadBytes = CjguiSaturatingAddU64(metalView.testComposableTextUploadBytes, byteCount);
    metalView.testComposableTextUploadMicros = CjguiSaturatingAddU64(metalView.testComposableTextUploadMicros,
                                                                       uploadEnded - uploadStarted);
#endif
    CjguiDropTextCpuScratch(metalView, byteCount);
    if (outByteCount) *outByteCount = byteCount;
    return texture;
}

static id<MTLTexture> CjguiComposableTextTexture(CJGuiInternalMetalView *metalView,
                                                  CJGuiInternalComposableSceneNode *node,
                                                  CGFloat scaleX, CGFloat scaleY,
                                                  NSString *displayText
#ifdef CJGUI_INTERNAL_TESTING
                                                  , CjguiInternalTextWorkReason reason
#endif
                                                  ) {
    NSRect textureRect = CjguiComposableTextTextureRectForNode(node);
    if (NSIsEmptyRect(textureRect)) return nil;
    NSString *key = CjguiComposableTextTextureKey(node, scaleX, scaleY, displayText, textureRect);
    if (key.length == 0) return nil;
    if ((node.textTexture || node.textTileTextures.count > 0) &&
        [node.textTextureCacheKey isEqualToString:key]) {
        if (!NSEqualRects(node.textTextureRect, textureRect)) {
            if (node.textTileTextures.count > 0) {
                uint64_t plannedBytes = 0;
                NSArray<NSValue *> *rects = CjguiPlanComposableTextTiles(textureRect, scaleX, &plannedBytes);
                if (rects.count != node.textTileTextures.count || plannedBytes != node.textTextureByteCount)
                    return nil;
                node.textTileRects = rects;
            }
            node.textTextureRect = textureRect;
        }
        return node.textTexture ?: node.textTileTextures.firstObject;
    }
    uint64_t plannedBytes = 0;
    NSArray<NSValue *> *tiles = CjguiPlanComposableTextTiles(textureRect, scaleX, &plannedBytes);
    if (tiles.count == 0 || plannedBytes == 0) return nil;
    NSMutableArray<id<MTLTexture>> *prepared = [NSMutableArray arrayWithCapacity:tiles.count];
    uint64_t actualBytes = 0;
    // Multiline text uses one candidate-scoped TextKit layout regardless of
    // tile count. Otherwise a narrow single tile takes drawWithRect's full
    // document layout while the same node split into two tiles stays bounded.
    // Small single-tile controls retain their fused drawWithRect path.
    // 2026-09-26(B2):**所有文本节点一律准备并持留排版产物** —— 契约要求几何查询
    // "取自绘制实际使用的 accepted 排版、且查询不重排",故每个文本节点都必须有可查索引;
    // 原先只覆盖多行 / 多 tile,导致单 tile 文本走 drawWithRect、查询恒得 GEOMETRY_EMPTY(实测 2 MiB 夹具)。
    BOOL needsSharedLayout = YES;
    CjguiPreparedTextNodeLayout *sharedLayout = needsSharedLayout ?
        CjguiPrepareTextNodeLayout(node, displayText, scaleX,
            CjguiComposableDecodeStyleRuns(
                [CjguiLookupSession(metalView.sessionToken) composableTextStyleRunsRaw][@(node.node.nodeId)])) : nil;
    node.preparedTextLayout = sharedLayout;   // B2:随本次准备持留(下次准备自然覆盖)
#ifdef CJGUI_INTERNAL_TESTING
    if (needsSharedLayout && metalView.testForceSharedTextLayoutNilOnce) {
        metalView.testForceSharedTextLayoutNilOnce = NO;
        sharedLayout = nil;
    }
#endif
    if (needsSharedLayout && !sharedLayout) {
        NSRect bounds = NSMakeRect(0.0, 0.0, (CGFloat)node.node.width, (CGFloat)node.node.height);
        CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
        NSRect textRect = NSInsetRect(bounds, 7.0, verticalInset);
        // An empty inset has no glyphs to prepare. For a drawable text area,
        // nil means preparation failed: reject the candidate instead of
        // silently switching the multiline node to per-tile drawWithRect.
        if (!NSIsEmptyRect(textRect) && textRect.size.width > 0 && textRect.size.height > 0)
            return nil;
    }
    for (NSValue *rectValue in tiles) {
        @autoreleasepool {
            uint64_t tileBytes = 0;
            id<MTLTexture> texture = CjguiRasterComposableTextTexture(metalView, node, scaleX, scaleY, displayText,
                                                               rectValue.rectValue, &tileBytes,
                                                               sharedLayout
#ifdef CJGUI_INTERNAL_TESTING
                                                               , reason
#endif
                                                               , NULL, 0);
            if (!texture || tileBytes == 0) return nil;
            [prepared addObject:texture];
            actualBytes += tileBytes;
        }
    }
    if (actualBytes != plannedBytes) return nil;
    node.textTexture = prepared.count == 1 ? prepared.firstObject : nil;
    node.textTileTextures = prepared.count > 1 ? [prepared copy] : nil;
    node.textTileRects = prepared.count > 1 ? tiles : nil;
    node.textTextureByteCount = actualBytes; node.textTextureCacheKey = key;
    node.textTextureRect = textureRect;
    return prepared.firstObject;
}

// An owner acknowledgement for the still-focused, same-identity input is not
// a new visual candidate.  The Cangjie bridge deliberately omits its value so
// setNodesFromProjection can retain the already accepted NSTextView value;
// replacing the retained active texture here would rasterize and upload that
// exact text/caret state again immediately afterwards.  Keep the existing
// scene-owned resource through this narrow hand-off. Any identity, kind,
// style, scale, tile, external-value, or retry difference still reaches
// refreshGpuTextForActiveInput and gets its normal body-cache-key check;
// selection, marked ranges and the caret are direct scene geometry.
static BOOL CjguiComposableTextResourceAcknowledgesActiveLocalInput(
    CJGuiInternalComposableSceneNode *node, CJGuiInternalComposableSceneNode *live) {
    if (!node || !live || node.node.preservesActiveLocalText == 0) return NO;
    // `preservesActiveLocalText` is the one-shot transport hint, while an
    // empty staged value is its concrete Cangjie-to-NSString hand-off form.
    // A non-empty value remains a visual candidate (including geometry or
    // tile changes in native scene probes) and must prepare normally.
    if (node.value.length != 0) return NO;
    uint32_t kind = node.node.nodeKind;
    if (kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return NO;
    return node.node.nodeId == live.node.nodeId &&
        node.node.resourceId == live.node.resourceId && kind == live.node.nodeKind;
}

// Clears ONE node's derived text resource fields. Semantic content (value,
// label, geometry, identity) is untouched, so the node can be re-prepared
// verbatim. ARC releases only this holder's strong references; a texture
// object shared with another node stays alive through that other holder.
static void CjguiReleaseComposableTextResource(CJGuiInternalComposableSceneNode *node) {
    if (!node) return;
    node.textTexture = nil;
    node.textTileTextures = nil;
    node.textTileRects = nil;
    node.textTextureCacheKey = @"";
    node.textTextureByteCount = 0;
    node.textTextureRect = NSZeroRect;
}

// A rejected scene transaction must not keep candidate-unique derived text
// resources alive until the next configure or close. Only staged entries that
// are NOT the committed node at the same index are cleared: a COW-shared
// entry IS the accepted scene's own holder and is never touched. Clearing
// derived fields only (never semantic content) keeps even a direct same-
// candidate retry correct, because empty derived state is simply re-prepared.
// When a staged clone still shares the accepted texture object, the committed
// node's own strong reference keeps that texture alive; this helper releases
// the candidate's hold, never the accepted scene's.
static void CjguiReleaseFailedCandidateTextResources(CJGuiInternalSession *ctx) {
    if (!ctx) return;
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
        if (!node || node == live) continue;
        CjguiReleaseComposableTextResource(node);
    }
}

// Defined after the overlay @interface (it reads the active-input identity
// properties); declared here because the prepare pass runs earlier in file.
static BOOL CjguiStagedNodeIsFocusedInput(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node);

// Defined later in the file but needed by the prepare pass, which converts a
// node-local declared caret into the view-space rect decorations are stored in.
static NSRect CjguiComposableRect(CJGuiInternalComposableSceneNode *node, NSView *view);

static CjguiInternalRendererStatus CjguiPrepareComposableTextResources(CJGuiInternalSession *ctx) {
    if (!ctx || !ctx.view) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalMetalView *metalView = ctx.view;
    CGFloat scale = [metalView currentBackingScale];
    scale = MAX(1.0, scale);
    uint64_t sceneBytes = 0;
    for (NSUInteger index = 0; index < ctx.stagedComposableNodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = ctx.stagedComposableNodes[index];
        CJGuiInternalComposableSceneNode *live = index < ctx.composableNodes.count ? ctx.composableNodes[index] : nil;
        if (CjguiComposableTextResourceAcknowledgesActiveLocalInput(node, live)) {
            // The staged COW node already retains the last active resource.
            // Count it like every other scene-owned texture so this reuse
            // cannot evade the accepted-scene resource cap.
            uint64_t retainedBytes = node.textTextureByteCount;
            if (retainedBytes > 0) {
                if (retainedBytes > CjguiComposableTextTextureByteCapacity ||
                    sceneBytes > CjguiComposableTextTextureByteCapacity - retainedBytes)
                    return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
                sceneBytes += retainedBytes;
            }
            continue;
        }
        // Decorations are meaningful only while the native TextKit proxy is
        // focused. A sparse staged candidate can still share an accepted
        // active-input node. Copy it before clearing presentation geometry so
        // a failed candidate cannot mutate the accepted selection/caret.
        BOOL hasDecorations = node.textSelectionRects.count > 0 ||
            node.textMarkedRects.count > 0 || !NSIsEmptyRect(node.textCaretRect);
        if (node == live && hasDecorations) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                  ctx.stagedComposableSceneVersion);
            if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            ctx.stagedComposableNodes[index] = node;
        }
        CjguiClearComposableTextDecorations(node);
        // The product's declared caret is PRESENTATION geometry, not pixel content: it lands
        // on the node's decoration rect and the Metal shape batch draws it after the body
        // texture, exactly like selection and marked ranges. Baking the bar into the body
        // texture made every caret move change the texture key and re-raster/re-upload the
        // whole paragraph.
        //
        // `declaredInputCaretRect` is in the node's OWN accepted-layout space (the prepared
        // layout is built from a (0,0,w,h) box), while decorations are stored in view space,
        // so the node rect is added here.
        // The overlay's concrete @interface appears later in this file, so its declared-caret
        // accessors are reached through the forward protocol (same route the input client uses).
        id<CjguiDeclaredInputCaretForward> caretOverlay =
            (id<CjguiDeclaredInputCaretForward>)ctx.composableSceneOverlay;
        if (caretOverlay.hasDeclaredInputCaret &&
            caretOverlay.declaredInputCaretNodeId == (int64_t)node.node.nodeId &&
            CjguiComposableNodeHasGpuText(node.node.nodeKind)) {
            if (node == live) {
                node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                      ctx.stagedComposableSceneVersion);
                if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                ctx.stagedComposableNodes[index] = node;
            }
            NSRect declared = caretOverlay.declaredInputCaretRect;
            NSRect nodeRect = CjguiComposableRect(node, metalView);
            node.textCaretRect = NSMakeRect(NSMinX(nodeRect) + NSMinX(declared),
                                            NSMinY(nodeRect) + NSMinY(declared),
                                            MAX(NSWidth(declared), 1.5), NSHeight(declared));
            node.textCaretIsDeclared = YES;
        }
        BOOL shouldClear = NO;
        if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) {
            shouldClear = YES;
        } else if (NSIsEmptyRect(CjguiComposableTextTextureRectForNode(node))) {
            // A fully clipped node cannot contribute pixels this turn. Its
            // immutable Cangjie value remains available for a later retry.
            shouldClear = YES;
        }
        NSString *text = shouldClear ? @"" : CjguiComposableGpuTextValue(node);
        if (text.length == 0 || node.node.textAlpha <= 0.0) shouldClear = YES;
        if (shouldClear) {
            if (node.textTexture || node.textTileTextures.count > 0 ||
                node.textTextureCacheKey.length > 0 || node.textTextureByteCount > 0) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
                    if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    ctx.stagedComposableNodes[index] = node;
                }
                node.textTexture = nil; node.textTileTextures = nil; node.textTileRects = nil;
                node.textTextureCacheKey = @""; node.textTextureByteCount = 0;
                node.textTextureRect = NSZeroRect;
            }
            // An EMPTY value that is still inside its clip owns a caret, and the B2
            // invariant says every text node keeps a queryable accepted layout. The
            // pixel path cannot supply one (no tiles, so it never prepares), which
            // left the first empty paragraph answering `pending` forever: no caret on
            // click. Retain the same prepared layout the raster path would have used —
            // zero glyphs, so no texture bytes and no raster work.
            if (text.length > 0) continue;
            if (node.preparedTextLayout && node.preparedTextLayout.storage.length == 0) continue;
            if (node == live) {
                node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
                if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                ctx.stagedComposableNodes[index] = node;
            }
            node.preparedTextLayout = CjguiPrepareTextNodeLayout(node, @"", scale, nil);
            continue;
        }
        NSRect textureRect = CjguiComposableTextTextureRectForNode(node);
        // Runs participate in the key, and the scene nodes are rebuilt every
        // frame, so the signature must be attached to THIS node before the key
        // is computed; stamping it later can never invalidate the cached texture.
        node.styleRunsSignature = ctx.composableTextStyleRunsRaw[@(node.node.nodeId)] ?: @"";
        // The declared caret deliberately does NOT participate in the key: caret arrival,
        // move and leave must not invalidate body pixels. It is drawn as a decoration after
        // the texture (see the shape batch), so only the caret's own rect changes.
        NSString *key = CjguiComposableTextTextureKey(node, scale, scale, text, textureRect);
        BOOL needsPreparation = !(node.textTexture || node.textTileTextures.count > 0) ||
            ![node.textTextureCacheKey isEqualToString:key];
        if (getenv("PHAROS_TRACE_RUNS") && node.node.nodeId == 200) {
            fprintf(stderr, "PHAROS_TEXTURE node=200 prep=%d sig=%s cached=%s keyLen=%lu\n",
                    (int)needsPreparation,
                    node.styleRunsSignature ? node.styleRunsSignature.UTF8String : "(nil)",
                    node.textTextureCacheKey ? node.textTextureCacheKey.UTF8String : "(nil)",
                    (unsigned long)key.length);
        }
        // The focused input's visible body comes from the active TextKit
        // refresh that the same commit triggers right after this loop; its
        // static candidate form is never drawn this turn. Keep the previous
        // resource (the safe fallback if focus moves first) and charge its
        // retained bytes like the acknowledge path instead of rasterizing the
        // same body twice per geometry or content turn. The active refresh
        // re-admits its own body against the scene budget afterwards.
        if (needsPreparation && CjguiStagedNodeIsFocusedInput(ctx, node)) {
            uint64_t retainedBytes = node.textTextureByteCount;
            if (retainedBytes > CjguiComposableTextTextureByteCapacity ||
                sceneBytes > CjguiComposableTextTextureByteCapacity - retainedBytes)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
            sceneBytes += retainedBytes;
            continue;
        }
        uint64_t nodeBytes = node.textTextureByteCount;
        if (needsPreparation) {
            if (CjguiPlanComposableTextTiles(textureRect, scale, &nodeBytes).count == 0)
                return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        }
        if (nodeBytes == 0 || sceneBytes > CjguiComposableTextTextureByteCapacity - nodeBytes) {
            fprintf(stderr, "PHAROS_BUDGET_REJECT node=%llu nodeBytes=%lu sceneBytes=%lu capacity=%lu "
                    "rectW=%.1f rectH=%.1f textUtf16=%lu kind=%u\n",
                    (unsigned long long)node.node.nodeId, (unsigned long)nodeBytes,
                    (unsigned long)sceneBytes, (unsigned long)CjguiComposableTextTextureByteCapacity,
                    (double)NSWidth(textureRect), (double)NSHeight(textureRect),
                    (unsigned long)(text ? text.length : 0), (unsigned)node.node.nodeKind);
            return CJGUI_INTERNAL_RENDERER_TEXT_RESOURCE_BUDGET_EXCEEDED;
        }
        sceneBytes += nodeBytes;
        if (!needsPreparation) {
            if (!NSEqualRects(node.textTextureRect, textureRect)) {
                if (node == live) {
                    node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index,
                                                          ctx.stagedComposableSceneVersion);
                    if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    ctx.stagedComposableNodes[index] = node;
                }
                // The texture is node-local pixel content. Moving the node
                // changes only the Metal destination rectangles, not bytes.
                if (node.textTileTextures.count > 0) {
                    uint64_t plannedBytes = 0;
                    NSArray<NSValue *> *rects = CjguiPlanComposableTextTiles(textureRect, scale, &plannedBytes);
                    if (rects.count != node.textTileTextures.count || plannedBytes != nodeBytes)
                        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                    node.textTileRects = rects;
                }
                node.textTextureRect = textureRect;
            }
            continue;
        }
        if (node == live) {
            node = CjguiCloneComposableSceneNode(ctx, live, (uint32_t)index, ctx.stagedComposableSceneVersion);
            if (!node) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            ctx.stagedComposableNodes[index] = node;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (ctx.forcedComposableTextPreparationFailures > 0) {
            ctx.forcedComposableTextPreparationFailures -= 1;
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
#endif
        if (!CjguiComposableTextTexture(metalView, node, scale, scale, text
#ifdef CJGUI_INTERNAL_TESTING
                                        , CjguiInternalTextWorkReasonStaticCandidate
#endif
                                        )) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

// Active TextKit updates bypass a Cangjie scene transaction, but they still
// replace a scene-owned derived texture. Apply the same accepted-scene budget
// before swapping it so a focused field cannot evade the admission limit.
static BOOL CjguiComposableTextTextureFitsSceneBudget(NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                                       CJGuiInternalComposableSceneNode *replacing,
                                                       uint64_t candidateBytes) {
    if (candidateBytes == 0 || candidateBytes > CjguiComposableTextTextureByteCapacity) return NO;
    uint64_t total = candidateBytes;
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node == replacing || !CjguiComposableNodeHasGpuText(node.node.nodeKind)) continue;
        uint64_t bytes = node.textTextureByteCount;
        if (bytes > CjguiComposableTextTextureByteCapacity - total) return NO;
        total += bytes;
    }
    return total <= CjguiComposableTextTextureByteCapacity;
}

static const uint32_t CjguiEffectGroupCapacity = 16;
enum { CjguiEffectGroupDepthCapacity = 4 };
static const uint32_t CjguiEffectTargetDimensionCapacity = 4096;
static const uint64_t CjguiEffectTargetPixelCapacity = 4u * 1024u * 1024u;
static const uint64_t CjguiEffectTargetByteCapacity = 96u * 1024u * 1024u;

static BOOL CjguiEffectFiniteUnit(double value) {
    return isfinite(value) && value >= 0.0 && value <= 1.0;
}

// No group span may cross a containing group's end. Relative subtree counts
// survive Cangjie layout COW replay without index relocation. Validate this
// before any text preparation or target allocation so malformed FFI values
// cannot publish a partially composited candidate.
static CjguiInternalRendererStatus CjguiValidateEffectGroupTopology(
    NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    NSUInteger ends[CjguiEffectGroupDepthCapacity] = {0};
    uint32_t depth = 0, groupCount = 0, backdropCount = 0;
    for (NSUInteger index = 0; index < nodes.count; index++) {
        while (depth > 0 && index >= ends[depth - 1]) depth--;
        CjguiInternalRendererComposableNode value = nodes[index].node;
        if (value.effectGroupPresent == 0) continue;
        if (value.effectGroupPresent != 1 || ++groupCount > CjguiEffectGroupCapacity ||
            depth >= CjguiEffectGroupDepthCapacity || value.effectGroupSubtreeCount == 0 ||
            value.effectGroupSubtreeCount > nodes.count - index ||
            (depth > 0 && value.effectGroupSubtreeCount > ends[depth - 1] - index) ||
            !CjguiEffectFiniteUnit(value.effectGroupOpacity) || value.effectGroupBlendMode > 1 ||
            value.effectMaskPresent > 1 || value.effectBackdropBlurRadiusPoints > 16 ||
            value.effectBackdropBlurFallback != 0) return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        // The first bounded backdrop slice has one root-level sampling group.
        // Nested/multiple backdrop readers need a separate dependency graph.
        if (value.effectBackdropBlurRadiusPoints > 0 && (depth > 0 || ++backdropCount > 1))
            return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        if (value.effectMaskPresent) {
            if (value.effectMaskStopCount < 2 || value.effectMaskStopCount > 4 ||
                !CjguiEffectFiniteUnit(value.effectMaskStartX) ||
                !CjguiEffectFiniteUnit(value.effectMaskStartY) ||
                !CjguiEffectFiniteUnit(value.effectMaskEndX) ||
                !CjguiEffectFiniteUnit(value.effectMaskEndY))
                return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            double dx = value.effectMaskEndX - value.effectMaskStartX;
            double dy = value.effectMaskEndY - value.effectMaskStartY;
            if (dx * dx + dy * dy <= 1.0e-12)
                return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            double positions[4] = {value.effectMaskStop0Position, value.effectMaskStop1Position,
                                   value.effectMaskStop2Position, value.effectMaskStop3Position};
            double alphas[4] = {value.effectMaskStop0Alpha, value.effectMaskStop1Alpha,
                                value.effectMaskStop2Alpha, value.effectMaskStop3Alpha};
            for (uint32_t stop = 0; stop < value.effectMaskStopCount; stop++) {
                if (!CjguiEffectFiniteUnit(positions[stop]) || !CjguiEffectFiniteUnit(alphas[stop]) ||
                    (stop > 0 && positions[stop] < positions[stop - 1]))
                    return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
            }
        } else if (value.effectMaskStopCount != 0) {
            return CJGUI_INTERNAL_RENDERER_EFFECT_DECLARATION_REJECTED;
        }
        ends[depth++] = index + value.effectGroupSubtreeCount;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

static NSRect CjguiEffectNodeOutputBounds(CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    NSRect output = NSZeroRect;
    if (value.width > 0 && value.height > 0 && value.clipWidth > 0 && value.clipHeight > 0) {
        output = NSIntersectionRect(NSMakeRect(value.x, value.y, value.width, value.height),
                                    NSMakeRect(value.clipX, value.clipY, value.clipWidth, value.clipHeight));
    }
    if (value.shadowPresent && value.shadowAlpha > 0.0) {
        NSRect shadow = CjguiComposableShadowOutputRect(value);
        uint32_t count = CjguiComposableClipConstraintCount(value);
        for (uint32_t clip = 0; clip < count && !NSIsEmptyRect(shadow); clip++) {
            CGFloat x, y, width, height, radius;
            CjguiComposableClipConstraintAt(value, clip, &x, &y, &width, &height, &radius);
            shadow = NSIntersectionRect(shadow, NSMakeRect(x, y, width, height));
        }
        if (!NSIsEmptyRect(shadow)) output = NSIsEmptyRect(output) ? shadow : NSUnionRect(output, shadow);
    }
    // Native input decorations are paint, not layout, but can extend a pixel
    // beyond the text body's clip before their own shader applies that clip.
    NSArray<NSValue *> *decorationRects = [(node.textSelectionRects ?: @[])
                                             arrayByAddingObjectsFromArray:(node.textMarkedRects ?: @[])];
    for (NSValue *rectValue in decorationRects) {
        NSRect rect = NSIntersectionRect(rectValue.rectValue,
            NSMakeRect(value.clipX, value.clipY, value.clipWidth, value.clipHeight));
        if (!NSIsEmptyRect(rect)) output = NSIsEmptyRect(output) ? rect : NSUnionRect(output, rect);
    }
    NSRect caret = NSIntersectionRect(node.textCaretRect,
        NSMakeRect(value.clipX, value.clipY, value.clipWidth, value.clipHeight));
    if (!NSIsEmptyRect(caret)) output = NSIsEmptyRect(output) ? caret : NSUnionRect(output, caret);
    NSRect scrollbar = NSIntersectionRect(node.textScrollbarRect,
        NSMakeRect(value.clipX, value.clipY, value.clipWidth, value.clipHeight));
    if (!NSIsEmptyRect(scrollbar)) output = NSIsEmptyRect(output) ? scrollbar : NSUnionRect(output, scrollbar);
    return output;
}

static NSRect CjguiEffectGroupOutputBounds(NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                          NSUInteger start, NSUInteger end) {
    NSRect output = NSZeroRect;
    for (NSUInteger index = start; index < end;) {
        CjguiInternalRendererComposableNode value = nodes[index].node;
        NSRect next = NSZeroRect;
        if (index != start && value.effectGroupPresent) {
            NSUInteger childEnd = index + value.effectGroupSubtreeCount;
            next = CjguiEffectGroupOutputBounds(nodes, index, childEnd);
            index = childEnd;
        } else {
            next = CjguiEffectNodeOutputBounds(nodes[index]);
            index++;
        }
        if (!NSIsEmptyRect(next)) output = NSIsEmptyRect(output) ? next : NSUnionRect(output, next);
    }
    CjguiInternalRendererComposableNode group = nodes[start].node;
    if (group.effectMaskPresent && !NSIsEmptyRect(output))
        output = NSIntersectionRect(output, NSMakeRect(group.x, group.y, group.width, group.height));
    return output;
}

static uint64_t CjguiEffectHashBytes(uint64_t hash, const void *bytes, NSUInteger length) {
    const uint8_t *cursor = (const uint8_t *)bytes;
    for (NSUInteger index = 0; index < length; index++) {
        hash ^= cursor[index];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static uint64_t CjguiEffectHashString(uint64_t hash, NSString *value) {
    NSData *data = [(value ?: @"") dataUsingEncoding:NSUTF8StringEncoding];
    uint64_t size = data.length;
    hash = CjguiEffectHashBytes(hash, &size, sizeof(size));
    return CjguiEffectHashBytes(hash, data.bytes, data.length);
}

static uint64_t CjguiEffectHashRectArray(uint64_t hash, NSArray<NSValue *> *rects) {
    uint64_t count = rects.count;
    hash = CjguiEffectHashBytes(hash, &count, sizeof(count));
    for (NSValue *value in rects) {
        NSRect rect = value.rectValue;
        hash = CjguiEffectHashBytes(hash, &rect, sizeof(rect));
    }
    return hash;
}

// Both foreground targets and sampled backdrops depend on these exact node
// paint inputs. Keep one list: native decorations, texture generations and
// their sampled rectangles cannot silently diverge between the two caches.
static uint64_t CjguiEffectHashPaintNode(uint64_t hash,
                                        CJGuiInternalComposableSceneNode *node,
                                        CjguiInternalRendererComposableNode value) {
    value.projectionVersion = 0;
    hash = CjguiEffectHashBytes(hash, &value, sizeof(value));
    hash = CjguiEffectHashString(hash, node.semanticId);
    hash = CjguiEffectHashString(hash, node.label);
    hash = CjguiEffectHashString(hash, node.value);
    hash = CjguiEffectHashString(hash, node.styleRunsSignature);
    hash = CjguiEffectHashString(hash, node.textTextureCacheKey);
    hash = CjguiEffectHashString(hash, node.imageTextureContentKey);
    uintptr_t resources[2] = {(uintptr_t)node.textTexture, (uintptr_t)node.imageTexture};
    hash = CjguiEffectHashBytes(hash, resources, sizeof(resources));
    uint64_t imageResourceVersion = node.imageResourceVersion;
    hash = CjguiEffectHashBytes(hash, &imageResourceVersion, sizeof(imageResourceVersion));
    uint64_t tileCount = node.textTileTextures.count;
    hash = CjguiEffectHashBytes(hash, &tileCount, sizeof(tileCount));
    for (id<MTLTexture> tile in node.textTileTextures) {
        uintptr_t pointer = (uintptr_t)tile;
        hash = CjguiEffectHashBytes(hash, &pointer, sizeof(pointer));
    }
    hash = CjguiEffectHashRectArray(hash, node.textSelectionRects);
    hash = CjguiEffectHashRectArray(hash, node.textMarkedRects);
    hash = CjguiEffectHashRectArray(hash, node.textTileRects);
    NSRect decorationRects[3] = {node.textTextureRect, node.textCaretRect, node.textScrollbarRect};
    hash = CjguiEffectHashBytes(hash, decorationRects, sizeof(decorationRects));
    BOOL caretIsDeclared = node.textCaretIsDeclared;
    hash = CjguiEffectHashBytes(hash, &caretIsDeclared, sizeof(caretIsDeclared));
    BOOL hasVector = node.hasVectorGeometry;
    hash = CjguiEffectHashBytes(hash, &hasVector, sizeof(hasVector));
    // The immutable copied vector value determines the lazily uploaded GPU
    // buffer. Do not hash the buffer pointer: first encoding may create it
    // after this signature is calculated, causing a false miss next frame.
    return hash;
}

static uint64_t CjguiEffectHashPaintEnvironment(uint64_t hash, NSSize viewSize,
                                                 CGSize drawableSize, BOOL multisample) {
    double scale[2] = {drawableSize.width / MAX(1.0, viewSize.width),
                       drawableSize.height / MAX(1.0, viewSize.height)};
    uint64_t drawable[3] = {(uint64_t)drawableSize.width, (uint64_t)drawableSize.height,
                            multisample ? 4u : 1u};
    hash = CjguiEffectHashBytes(hash, drawable, sizeof(drawable));
    hash = CjguiEffectHashBytes(hash, scale, sizeof(scale));
    vector_float4 selection = CjguiMetalColorFromNSColor(NSColor.selectedTextBackgroundColor);
    vector_float4 accent = CjguiMetalColorFromNSColor(NSColor.keyboardFocusIndicatorColor);
    hash = CjguiEffectHashBytes(hash, &selection, sizeof(selection));
    return CjguiEffectHashBytes(hash, &accent, sizeof(accent));
}

// A complete source key, not sceneVersion: the root's final group settings
// are deliberately excluded so an opacity/mask/blend-only update reuses its
// transparent content. Descendant group settings remain in the bytes and
// invalidate ancestors. Native text decorations and resource generations are
// included even when Cangjie's scene tree did not change.
static NSString *CjguiEffectContentSignature(NSArray<CJGuiInternalComposableSceneNode *> *nodes,
                                             NSUInteger start, NSUInteger end,
                                             uint32_t x, uint32_t y, uint32_t width, uint32_t height,
                                             BOOL multisample, NSSize viewSize, CGSize drawableSize) {
    uint64_t hash = UINT64_C(1469598103934665603);
    uint64_t geometry[5] = {x, y, width, height, multisample ? 4 : 1};
    hash = CjguiEffectHashBytes(hash, geometry, sizeof(geometry));
    hash = CjguiEffectHashPaintEnvironment(hash, viewSize, drawableSize, multisample);
    for (NSUInteger index = start; index < end; index++) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        value.projectionVersion = 0;
        if (index == start) {
            value.effectGroupOpacity = 1.0;
            value.effectGroupBlendMode = 0;
            value.effectMaskPresent = 0;
            value.effectMaskStopCount = 0;
            value.effectMaskStartX = value.effectMaskStartY = 0.0;
            value.effectMaskEndX = value.effectMaskEndY = 0.0;
            value.effectMaskStop0Position = value.effectMaskStop0Alpha = 0.0;
            value.effectMaskStop1Position = value.effectMaskStop1Alpha = 0.0;
            value.effectMaskStop2Position = value.effectMaskStop2Alpha = 0.0;
            value.effectMaskStop3Position = value.effectMaskStop3Alpha = 0.0;
            value.effectBackdropBlurRadiusPoints = 0;
            value.effectBackdropBlurFallback = 0;
        }
        hash = CjguiEffectHashPaintNode(hash, node, value);
    }
    return [NSString stringWithFormat:@"%016llx", (unsigned long long)hash];
}

static uint64_t CjguiEffectLiveTargetBytes(CJGuiInternalMetalView *view) {
    uint64_t bytes = 0;
    // Enumerate the weak ledger directly. allObjects creates an autoreleased
    // strong array, which would itself keep retired targets alive for the
    // enclosing run-loop pool and make the budget observation change lifetime.
    for (CJGuiInternalComposableEffectTarget *target in view.effectTargetLedger) {
        if (target.byteCount > UINT64_MAX - bytes) return UINT64_MAX;
        bytes += target.byteCount;
    }
#ifdef CJGUI_INTERNAL_TESTING
    view.testEffectTargetCurrentBytes = bytes;
    if (bytes > view.testEffectTargetPeakBytes) view.testEffectTargetPeakBytes = bytes;
#endif
    return bytes;
}

static BOOL CjguiEffectPixelBounds(NSRect bounds, NSSize viewSize, CGSize drawableSize,
                                   uint32_t *outX, uint32_t *outY, uint32_t *outWidth, uint32_t *outHeight) {
    *outX = *outY = *outWidth = *outHeight = 0;
    if (NSIsEmptyRect(bounds) || viewSize.width <= 0.0 || viewSize.height <= 0.0 ||
        drawableSize.width <= 0.0 || drawableSize.height <= 0.0) return YES;
    double scaleX = drawableSize.width / viewSize.width, scaleY = drawableSize.height / viewSize.height;
    double left = MAX(0.0, floor(NSMinX(bounds) * scaleX));
    double top = MAX(0.0, floor(NSMinY(bounds) * scaleY));
    double right = MIN(drawableSize.width, ceil(NSMaxX(bounds) * scaleX));
    double bottom = MIN(drawableSize.height, ceil(NSMaxY(bounds) * scaleY));
    if (right <= left || bottom <= top) return YES;
    if (!isfinite(left) || !isfinite(top) || !isfinite(right) || !isfinite(bottom) ||
        right - left > CjguiEffectTargetDimensionCapacity ||
        bottom - top > CjguiEffectTargetDimensionCapacity ||
        (right - left) * (bottom - top) > CjguiEffectTargetPixelCapacity ||
        right > UINT32_MAX || bottom > UINT32_MAX) return NO;
    *outX = (uint32_t)left;
    *outY = (uint32_t)top;
    *outWidth = (uint32_t)(right - left);
    *outHeight = (uint32_t)(bottom - top);
    return YES;
}

static CjguiInternalRendererStatus CjguiPrepareEffectTargets(CJGuiInternalMetalView *view,
                                                               CGSize drawableSize) {
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    NSMutableArray<NSNumber *> *newIndices = [NSMutableArray array];
    NSMutableArray<NSString *> *newSignatures = [NSMutableArray array];
    NSMutableArray<NSValue *> *newRects = [NSMutableArray array];
    uint64_t neededBytes = 0;
    uint64_t liveBytes = CjguiEffectLiveTargetBytes(view);
    BOOL msaa = view.composableUsesMultisampling;
    for (NSUInteger index = 0; index < nodes.count; index++) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        if (!value.effectGroupPresent) continue;
        NSRect bounds = CjguiEffectGroupOutputBounds(nodes, index, index + value.effectGroupSubtreeCount);
        uint32_t x, y, width, height;
        if (!CjguiEffectPixelBounds(bounds, view.bounds.size, drawableSize, &x, &y, &width, &height))
            return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        if (width == 0 || height == 0) { node.effectTarget = nil; continue; }
        NSString *signature = CjguiEffectContentSignature(nodes, index,
            index + value.effectGroupSubtreeCount, x, y, width, height, msaa,
            view.bounds.size, drawableSize);
        CJGuiInternalComposableEffectTarget *old = node.effectTarget;
        if (!old || ![old.contentSignature isEqualToString:signature] || old.invalidatedByGpuFailure)
            old = view.effectGroupCache[@(value.nodeId)];
        if (old && [old.contentSignature isEqualToString:signature] && !old.invalidatedByGpuFailure &&
            old.pixelX == x && old.pixelY == y && old.pixelWidth == width && old.pixelHeight == height) {
            node.effectTarget = old;
#ifdef CJGUI_INTERNAL_TESTING
            view.testEffectTargetReuseCount++;
#endif
            continue;
        }
        node.effectTarget = nil;
        uint64_t pixels = (uint64_t)width * height;
        uint64_t bytes = pixels * (msaa ? 20u : 4u);
        if (bytes > CjguiEffectTargetByteCapacity || neededBytes > CjguiEffectTargetByteCapacity - bytes)
            return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        neededBytes += bytes;
        [newIndices addObject:@(index)];
        [newSignatures addObject:signature];
        [newRects addObject:[NSValue valueWithRect:NSMakeRect(x, y, width, height)]];
    }
    if (liveBytes > CjguiEffectTargetByteCapacity ||
        neededBytes > CjguiEffectTargetByteCapacity - liveBytes)
        return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
    for (NSUInteger plan = 0; plan < newIndices.count; plan++) {
        NSRect rect = newRects[plan].rectValue;
        uint32_t width = (uint32_t)rect.size.width, height = (uint32_t)rect.size.height;
        MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
            width:width height:height mipmapped:NO];
        descriptor.storageMode = MTLStorageModePrivate;
        descriptor.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
        id<MTLTexture> resolved = [view.device newTextureWithDescriptor:descriptor];
        if (!resolved) return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        id<MTLTexture> multisample = nil;
        if (msaa) {
            descriptor.textureType = MTLTextureType2DMultisample;
            descriptor.sampleCount = 4;
            descriptor.usage = MTLTextureUsageRenderTarget;
            multisample = [view.device newTextureWithDescriptor:descriptor];
            if (!multisample) return CJGUI_INTERNAL_RENDERER_EFFECT_RESOURCE_BUDGET_EXCEEDED;
        }
        CJGuiInternalComposableEffectTarget *target = [[CJGuiInternalComposableEffectTarget alloc] init];
        target.resolvedTexture = resolved;
        target.multisampleTexture = multisample;
        target.contentSignature = newSignatures[plan];
        target.pixelX = (uint32_t)rect.origin.x;
        target.pixelY = (uint32_t)rect.origin.y;
        target.pixelWidth = width;
        target.pixelHeight = height;
        target.byteCount = (uint64_t)width * height * (msaa ? 20u : 4u);
        target.needsRedraw = YES;
        [view.effectTargetLedger addObject:target];
        nodes[newIndices[plan].unsignedIntegerValue].effectTarget = target;
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectTargetAllocationCount++;
#endif
    }
    (void)CjguiEffectLiveTargetBytes(view);
    return CJGUI_INTERNAL_RENDERER_OK;
}

static BOOL CjguiEncodeEffectGroupComposite(CJGuiInternalMetalView *view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, CJGuiInternalComposableSceneNode *node);

static BOOL CjguiEncodeComposableNodesRange(id view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, uint32_t targetX, uint32_t targetY,
                                            uint32_t targetWidth, uint32_t targetHeight,
                                            NSUInteger start, NSUInteger end, NSUInteger ownGroupIndex) {
    CJGuiInternalMetalView *metalView = (CJGuiInternalMetalView *)view;
    if (metalView.composableNodes.count == 0 || start >= end) return YES;
#ifdef CJGUI_INTERNAL_TESTING
    metalView.testComposableShapeNodeCount = 0;
    metalView.testComposableShapeBatchCount = 0;
    metalView.testComposableTextureDrawCount = 0;
    metalView.testComposableShapeVertexBytes = 0;
    metalView.testComposableMaxShapeBatchVertexBytes = 0;
    metalView.testComposableShapeVertexStride = (uint32_t)sizeof(CJGuiInternalMetalVertex);
    metalView.testComposableVectorDrawCount = 0;
    metalView.testComposableVectorBufferUploadCount = 0;
    metalView.testComposableVectorBufferReuseCount = 0;
    metalView.testComposableVectorBufferUploadBytes = 0;
#endif
    BOOL usesMultisampling = metalView.composableUsesMultisampling;
    id<MTLRenderPipelineState> scenePipeline = usesMultisampling
        ? metalView.composableMultisamplePipeline : metalView.composablePipeline;
    if (!scenePipeline) {
        NSError *error = nil;
        NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
            "struct Vertex { float2 position; float2 scenePoint; float2 localPoint; float2 size; float4 clips[4]; float4 clipRadii; float4 clipCount; float cornerRadius; float borderWidth; float isVectorShape; float vectorPadding; float4 fill; float4 border; float passKind; float shadowBlurRadius; float gradientPresent; float gradientStopCount; float2 gradientStart; float2 gradientEnd; float4 shadowColor; float4 gradientStop0; float4 gradientStop1; float4 gradientStop2; float4 gradientStop3; float4 gradientStopAlphas; };\n"
            "struct Out { float4 position [[position]]; float2 scenePoint; float2 localPoint; float2 size; float4 clip0; float4 clip1; float4 clip2; float4 clip3; float4 clipRadii; float4 clipCount; float cornerRadius; float borderWidth; float isVectorShape; float4 fill; float4 border; float passKind; float shadowBlurRadius; float gradientPresent; float gradientStopCount; float2 gradientStart; float2 gradientEnd; float4 shadowColor; float4 gradientStop0; float4 gradientStop1; float4 gradientStop2; float4 gradientStop3; float4 gradientStopAlphas; };\n"
            "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
            // Linear gradient in normalized node-local space: P in [0,1]^2,
            // t projected on the start->end axis, then piecewise sRGB lerp.
            "float4 cjgui_gradient_color(Out in) { float2 P=in.localPoint/max(in.size,float2(1e-6)); float2 dir=in.gradientEnd-in.gradientStart; float denom=max(dot(dir,dir),1e-6); float t=clamp(dot(P-in.gradientStart,dir)/denom,0.0,1.0); float4 c0=float4(in.gradientStop0.yzw,in.gradientStopAlphas.x); float4 c1=float4(in.gradientStop1.yzw,in.gradientStopAlphas.y); float4 c2=float4(in.gradientStop2.yzw,in.gradientStopAlphas.z); float4 c3=float4(in.gradientStop3.yzw,in.gradientStopAlphas.w); float4 r=mix(c0,c1,clamp((t-in.gradientStop0.x)/max(in.gradientStop1.x-in.gradientStop0.x,1e-6),0.0,1.0)); if (in.gradientStopCount>2.5 && t>=in.gradientStop1.x) r=mix(c1,c2,clamp((t-in.gradientStop1.x)/max(in.gradientStop2.x-in.gradientStop1.x,1e-6),0.0,1.0)); if (in.gradientStopCount>3.5 && t>=in.gradientStop2.x) r=mix(c2,c3,clamp((t-in.gradientStop2.x)/max(in.gradientStop3.x-in.gradientStop2.x,1e-6),0.0,1.0)); return r; }\n"
            "vertex Out cjgui_scene_vertex(uint i [[vertex_id]], const device Vertex *v [[buffer(0)]]) { Out o; o.position=float4(v[i].position,0,1); o.scenePoint=v[i].scenePoint; o.localPoint=v[i].localPoint; o.size=v[i].size; o.clip0=v[i].clips[0]; o.clip1=v[i].clips[1]; o.clip2=v[i].clips[2]; o.clip3=v[i].clips[3]; o.clipRadii=v[i].clipRadii; o.clipCount=v[i].clipCount; o.cornerRadius=v[i].cornerRadius; o.borderWidth=v[i].borderWidth; o.isVectorShape=v[i].isVectorShape; o.fill=v[i].fill; o.border=v[i].border; o.passKind=v[i].passKind; o.shadowBlurRadius=v[i].shadowBlurRadius; o.gradientPresent=v[i].gradientPresent; o.gradientStopCount=v[i].gradientStopCount; o.gradientStart=v[i].gradientStart; o.gradientEnd=v[i].gradientEnd; o.shadowColor=v[i].shadowColor; o.gradientStop0=v[i].gradientStop0; o.gradientStop1=v[i].gradientStop1; o.gradientStop2=v[i].gradientStop2; o.gradientStop3=v[i].gradientStop3; o.gradientStopAlphas=v[i].gradientStopAlphas; return o; }\n"
            // Clip chain first (shadows obey ancestor clips, never the node's own
            // rect). Shadow quads then evaluate a rounded-rect SDF in the expanded
            // shadow-shape space: the signed distance is clamped at zero so the
            // shadow shape interior (including any spread/offset area exposed
            // outside the node) stays at full shadow alpha, while the exterior
            // falls off with a Gaussian tail. Samples past 3*blur are discarded
            // early. Ordinary quads keep the legacy rounded fill/border path,
            // with the fill optionally replaced by a gradient.
            "fragment float4 cjgui_scene_fragment(Out in [[stage_in]]) { for(uint j=0;j<uint(in.clipCount.x);j++) { float4 clip=j==0?in.clip0:(j==1?in.clip1:(j==2?in.clip2:in.clip3)); if (roundedDistance(in.scenePoint,clip.xy,clip.zw,in.clipRadii[j])>0.0) discard_fragment(); } if (in.passKind>0.5) { float d=roundedDistance(in.localPoint,float2(0.0),in.size,in.cornerRadius); float blur=max(in.shadowBlurRadius,0.0); if (d>blur*3.0) discard_fragment(); float sigma=max(blur*0.5,0.5); float dd=max(d,0.0); return float4(in.shadowColor.rgb,in.shadowColor.a*exp(-(dd*dd)/(2.0*sigma*sigma))); } if (in.isVectorShape>0.5) return in.fill; float outer=roundedDistance(in.localPoint,float2(0.0),in.size,in.cornerRadius); if (outer>0.0) discard_fragment(); if (in.borderWidth>0.0 && in.border.a>0.0) { float2 innerSize=max(in.size-float2(in.borderWidth*2.0),float2(0.0)); float innerRadius=max(0.0,in.cornerRadius-in.borderWidth); float inner=roundedDistance(in.localPoint-float2(in.borderWidth),float2(0.0),innerSize,innerRadius); if (inner>0.0) return in.border; } if (in.gradientPresent>0.5 && in.gradientStopCount>1.5) return cjgui_gradient_color(in); return in.fill; }\n";
        id<MTLLibrary> library = [metalView.device newLibraryWithSource:source options:nil error:&error];
        if (!library) { NSLog(@"cjgui: composable metal library failed %@", error); return NO; }
        MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
        descriptor.vertexFunction = [library newFunctionWithName:@"cjgui_scene_vertex"];
        descriptor.fragmentFunction = [library newFunctionWithName:@"cjgui_scene_fragment"];
        descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
        descriptor.sampleCount = usesMultisampling ? 4 : 1;
        // Scene rectangles carry ordinary, non-premultiplied RGBA values from
        // the public Cangjie style.  They must compose in painter order just
        // like image texels, rather than overwriting the drawable with their
        // raw source alpha.
        descriptor.colorAttachments[0].blendingEnabled = YES;
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorSourceAlpha;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        scenePipeline = [metalView.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
        if (!scenePipeline) { NSLog(@"cjgui: composable metal pipeline failed %@", error); return NO; }
        if (usesMultisampling) metalView.composableMultisamplePipeline = scenePipeline;
        else metalView.composablePipeline = scenePipeline;
#ifdef CJGUI_INTERNAL_TESTING
        if (metalView.testComposablePipelineBuildCount < UINT64_MAX) metalView.testComposablePipelineBuildCount += 1;
#endif
    }
    CGFloat pointWidth = MAX(1.0, metalView.bounds.size.width);
    CGFloat pointHeight = MAX(1.0, metalView.bounds.size.height);
    CGFloat scaleX = drawableSize.width / pointWidth;
    CGFloat scaleY = drawableSize.height / pointHeight;
    [encoder setRenderPipelineState:scenePipeline];
    // Consecutive shape commands share one pipeline and vertex submission.
    // Texture nodes are explicit painter-order boundaries; we flush before
    // them rather than globally sorting by resource or alpha.
    NSMutableData *shapeBatch = [NSMutableData data];
    // Keep the historical six-vertex alignment: it preserves complete
    // rectangle submissions and is also a multiple of three, so vector
    // triangles never split across a `setVertexBytes` boundary.
    const NSUInteger maxShapeVerticesPerUpload =
        ((NSUInteger)CJGUI_INTERNAL_METAL_SET_VERTEX_BYTES_CAPACITY / sizeof(CJGuiInternalMetalVertex) / 6u) * 6u;
    if (maxShapeVerticesPerUpload < 6u) {
        NSLog(@"cjgui: composable shape vertex exceeds Metal setVertexBytes capacity");
        return NO;
    }
    BOOL (^flushShapeBatch)(void) = ^BOOL {
        if (shapeBatch.length == 0) return YES;
        const uint8_t *batchBytes = shapeBatch.bytes;
        NSUInteger remainingVertices = shapeBatch.length / sizeof(CJGuiInternalMetalVertex);
        NSUInteger vertexOffset = 0;
        while (remainingVertices > 0) {
            NSUInteger vertexCount = MIN(maxShapeVerticesPerUpload, remainingVertices);
            NSUInteger byteCount = vertexCount * sizeof(CJGuiInternalMetalVertex);
#ifdef CJGUI_INTERNAL_TESTING
            if (metalView.testComposableShapeBatchCount < UINT32_MAX) metalView.testComposableShapeBatchCount += 1;
            uint64_t bytes = byteCount;
            metalView.testComposableShapeVertexBytes = bytes > UINT64_MAX - metalView.testComposableShapeVertexBytes
                ? UINT64_MAX : metalView.testComposableShapeVertexBytes + bytes;
            metalView.testComposableMaxShapeBatchVertexBytes = MAX(metalView.testComposableMaxShapeBatchVertexBytes, bytes);
#endif
            [encoder setRenderPipelineState:scenePipeline];
            [encoder setVertexBytes:batchBytes + vertexOffset * sizeof(CJGuiInternalMetalVertex) length:byteCount atIndex:0];
            [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:vertexCount];
            vertexOffset += vertexCount;
            remainingVertices -= vertexCount;
        }
        [shapeBatch setLength:0];
        return YES;
    };
    [encoder setViewport:(MTLViewport){-(double)targetX, -(double)targetY,
                                      (double)drawableSize.width, (double)drawableSize.height, 0.0, 1.0}];
    [encoder setScissorRect:(MTLScissorRect){ 0, 0, targetWidth, targetHeight }];
    for (NSUInteger index = start; index < end; index++) {
        CJGuiInternalComposableSceneNode *node = metalView.composableNodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        if (index != ownGroupIndex && value.effectGroupPresent) {
            if (!flushShapeBatch()) return NO;
            if (node.effectTarget && !CjguiEncodeEffectGroupComposite(metalView, encoder, drawableSize, node)) return NO;
            [encoder setRenderPipelineState:scenePipeline];
            index += value.effectGroupSubtreeCount - 1;
            continue;
        }
        if (value.width <= 0 || value.height <= 0) continue;
        // An empty own clip (ancestor chain ∩ bounds) hides the node's body,
        // but an outer shadow can still paint outside those bounds and remain
        // visible in the viewport. Gate that case on the shadow's own output
        // range against the ancestor clip chain and the drawable, then submit
        // only the shadow pass; no body pixel can survive the ancestor clip,
        // so fill/border/vector/text/image passes are skipped below.
        if (value.clipWidth <= 0 || value.clipHeight <= 0) {
            if (value.shadowPresent == 0 || !(value.shadowAlpha > 0.0)) continue;
            NSRect shadowOutput = CjguiComposableShadowOutputRect(value);
            if (!CjguiComposableShadowOutputIntersectsAncestorClip(value, shadowOutput)) continue;
            if (!CjguiComposableShadowOutputIntersectsDrawable(shadowOutput, scaleX, scaleY, drawableSize)) continue;
            CjguiAppendMetalShadow(shapeBatch, pointWidth, pointHeight, value);
            continue;
        }
        uint64_t sx = (uint64_t)MAX(0, (int64_t)((CGFloat)value.clipX * scaleX));
        uint64_t sy = (uint64_t)MAX(0, (int64_t)((CGFloat)value.clipY * scaleY));
        uint64_t sw = (uint64_t)MAX(0, (int64_t)((CGFloat)value.clipWidth * scaleX));
        uint64_t sh = (uint64_t)MAX(0, (int64_t)((CGFloat)value.clipHeight * scaleY));
        if (sx >= drawableSize.width || sy >= drawableSize.height) continue;
        if (sx + sw > drawableSize.width) sw = drawableSize.width - sx;
        if (sy + sh > drawableSize.height) sh = drawableSize.height - sy;
        if (sw == 0 || sh == 0) continue;
        vector_float4 fill = { (float)value.fillRed, (float)value.fillGreen, (float)value.fillBlue, (float)value.fillAlpha };
        vector_float4 border = { (float)value.borderRed, (float)value.borderGreen, (float)value.borderBlue, (float)value.borderAlpha };
        NSUInteger shapeBytesBefore = shapeBatch.length;
        // Outer shadow paints before the node's own fill so the node covers the
        // shadow center, preserving painter order within the node. The shadow
        // quad only obeys the inherited ancestor clip chain.
        CjguiAppendMetalShadow(shapeBatch, pointWidth, pointHeight, value);
        CjguiAppendMetalShape(shapeBatch, pointWidth, pointHeight, value, fill, border);
        // A vector's immutable local topology lives in its own retained Metal
        // buffer. Flush preceding generic shapes at this exact painter-order
        // boundary, then bind only the compact topology plus one small node
        // uniform; never expand it into 176-byte generic vertices each frame.
        if (node.hasVectorGeometry) {
            if (!flushShapeBatch()) return NO;
            if (!CjguiEncodeMetalVectorShape(encoder, pointWidth, pointHeight, metalView, node)) return NO;
            [encoder setRenderPipelineState:scenePipeline];
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (shapeBatch.length > shapeBytesBefore && metalView.testComposableShapeNodeCount < UINT32_MAX) {
            metalView.testComposableShapeNodeCount += 1;
        }
        // The comparison path is still legal: every complete rectangle is
        // uploaded as six vertices, well below Metal's 4 KiB setVertexBytes
        // ceiling. It differs only in submission granularity; painter order,
        // vertex data and all resource boundaries stay identical.
        if (shapeBatch.length > shapeBytesBefore && metalView.testComposableShapeSubmissionMode == 1) {
            if (!flushShapeBatch()) return NO;
        }
#endif
        if (CjguiComposableNodeHasGpuText(value.nodeKind)) {
            // Selection backgrounds must paint after this node's fill but
            // before its immutable glyph texture. Foreground decorations are
            // appended after the texture and flushed before the next scene
            // node, preserving the same per-node painter order as a fully
            // rasterized active input.
            NSUInteger decorationsBefore = shapeBatch.length;
            vector_float4 selectionFill = CjguiMetalColorFromNSColor(NSColor.selectedTextBackgroundColor);
            for (NSValue *valueRect in node.textSelectionRects) {
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, value, valueRect.rectValue, selectionFill);
            }
            BOOL hasTextTexture = node.textTexture || node.textTileTextures.count > 0;
            if (hasTextTexture && !flushShapeBatch()) return NO;
            if (hasTextTexture && !CjguiEnsureComposableImagePipeline(metalView)) return NO;
            if (hasTextTexture) [encoder setRenderPipelineState:usesMultisampling
                ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline];
#ifdef CJGUI_INTERNAL_TESTING
            if (hasTextTexture && metalView.testComposableTextureDrawCount < UINT32_MAX)
                metalView.testComposableTextureDrawCount += 1;
#endif
            NSRect textureRect = node.textTextureRect;
            if (node.textTexture && !NSIsEmptyRect(textureRect)) {
                CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                        NSMinX(textureRect), NSMinY(textureRect),
                                        NSWidth(textureRect), NSHeight(textureRect), node.textTexture, value, YES,
                                        (float)value.textAlpha);
            }
            for (NSUInteger tileIndex = 0; tileIndex < node.textTileTextures.count; tileIndex++) {
                NSRect tileRect = node.textTileRects[tileIndex].rectValue;
                CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                        NSMinX(tileRect), NSMinY(tileRect),
                                        NSWidth(tileRect), NSHeight(tileRect),
                                        node.textTileTextures[tileIndex], value, YES, (float)value.textAlpha);
            }
            if (hasTextTexture) [encoder setRenderPipelineState:scenePipeline];
            vector_float4 foregroundFill = CjguiMetalColorFromNSColor(NSColor.keyboardFocusIndicatorColor);
            // An owner-declared caret keeps the colour it had while it was baked into the body
            // texture (the node's own text colour, opaque -- the texture is rasterized opaque
            // and re-multiplied by textAlpha at encode). The accent colour stays for composition
            // underlines and for the caret the hidden proxy derives for itself.
            vector_float4 caretFill = { (float)value.textRed, (float)value.textGreen, (float)value.textBlue, 1.0f };
            for (NSValue *valueRect in node.textMarkedRects) {
                CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, value, valueRect.rectValue, foregroundFill);
            }
            CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, value, node.textCaretRect,
                                           node.textCaretIsDeclared ? caretFill : foregroundFill);
            vector_float4 scrollbarFill = {0.75f, 0.75f, 0.75f, 0.48f};
            CjguiAppendMetalTextDecoration(shapeBatch, pointWidth, pointHeight, value, node.textScrollbarRect, scrollbarFill);
            if (shapeBatch.length > decorationsBefore && !flushShapeBatch()) return NO;
            [encoder setRenderPipelineState:scenePipeline];
        }
        if (value.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE && node.imageTexture) {
            if (!flushShapeBatch()) return NO;
            if (!CjguiEnsureComposableImagePipeline(metalView)) return NO;
            if (metalView.encodedImageTextures &&
                [metalView.encodedImageTextures indexOfObjectIdenticalTo:node.imageTexture] == NSNotFound) {
                [metalView.encodedImageTextures addObject:node.imageTexture];
            }
            CGFloat sourceWidth = MAX(1.0, (CGFloat)node.imageTexture.width);
            CGFloat sourceHeight = MAX(1.0, (CGFloat)node.imageTexture.height);
            CGFloat scale = value.imageContentMode == 2 ? MAX((CGFloat)value.width / sourceWidth, (CGFloat)value.height / sourceHeight)
                                                        : MIN((CGFloat)value.width / sourceWidth, (CGFloat)value.height / sourceHeight);
            CGFloat drawWidth = sourceWidth * scale;
            CGFloat drawHeight = sourceHeight * scale;
            [encoder setRenderPipelineState:usesMultisampling
                ? metalView.composableMultisampleImagePipeline : metalView.composableImagePipeline];
#ifdef CJGUI_INTERNAL_TESTING
            if (metalView.testComposableTextureDrawCount < UINT32_MAX) metalView.testComposableTextureDrawCount += 1;
#endif
            CjguiEncodeMetalTexture(encoder, pointWidth, pointHeight,
                                    value.x + ((CGFloat)value.width - drawWidth) / 2.0,
                                    value.y + ((CGFloat)value.height - drawHeight) / 2.0,
                                    drawWidth, drawHeight, node.imageTexture, value, NO, 1.0f);
            [encoder setRenderPipelineState:scenePipeline];
        }
    }
    return flushShapeBatch();
}

static BOOL CjguiEncodeComposableNodes(id view, id<MTLRenderCommandEncoder> encoder, CGSize drawableSize) {
    CJGuiInternalMetalView *metalView = (CJGuiInternalMetalView *)view;
    return CjguiEncodeComposableNodesRange(view, encoder, drawableSize, 0, 0,
        (uint32_t)drawableSize.width, (uint32_t)drawableSize.height,
        0, metalView.composableNodes.count, NSUIntegerMax);
}

typedef struct CjguiEffectCompositeVertex {
    vector_float2 position;
    vector_float2 scenePoint;
    vector_float2 texCoord;
} CjguiEffectCompositeVertex;

typedef struct CjguiEffectCompositeUniform {
    vector_float4 maskRect;
    vector_float4 endpoints;
    vector_float4 positions;
    vector_float4 alphas;
    float opacity;
    uint32_t maskPresent;
    uint32_t stopCount;
    uint32_t reserved;
    vector_float4 foregroundPixels;
    vector_float4 backdropPixels;
    vector_float4 scaleAndBackdrop;
    vector_float4 clips[CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY];
    vector_float4 clipRadii;
    vector_float4 clipCount;
} CjguiEffectCompositeUniform;

// Phase 0: normal premult source-over. Phases 1 and 2 are adjacent fixed
// blending draws for the exact premult multiply formula. They read the prior
// attachment only via Metal's defined blend unit, not by sampling the bound
// render target in a fragment shader.
static id<MTLRenderPipelineState> CjguiEffectPipeline(CJGuiInternalMetalView *view, uint32_t phase) {
    NSString *key = [NSString stringWithFormat:@"%u-%u", view.composableUsesMultisampling ? 4u : 1u, phase];
    id<MTLRenderPipelineState> pipeline = view.effectPipelines[key];
    if (pipeline) return pipeline;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "struct V { float2 position; float2 scenePoint; float2 uv; };\n"
        "struct U { float4 maskRect; float4 endpoints; float4 positions; float4 alphas; float opacity; uint maskPresent; uint stopCount; uint reserved; float4 foregroundPixels; float4 backdropPixels; float4 scaleAndBackdrop; float4 clips[4]; float4 clipRadii; float4 clipCount; };\n"
        "struct O { float4 position [[position]]; float2 point; float2 uv; };\n"
        "vertex O effect_vertex(uint i [[vertex_id]], const device V *v [[buffer(0)]]) { O o; o.position=float4(v[i].position,0,1); o.point=v[i].scenePoint; o.uv=v[i].uv; return o; }\n"
        "float roundedDistance(float2 point, float2 origin, float2 size, float radius) { float r=min(max(radius,0.0),min(size.x,size.y)*0.5); float2 q=abs((point-origin)-size*0.5)-(size*0.5-r); return length(max(q,float2(0.0)))+min(max(q.x,q.y),0.0)-r; }\n"
        "fragment float4 effect_fragment(O in [[stage_in]], constant U &u [[buffer(1)]], texture2d<float> image [[texture(0)]], texture2d<float> backdrop [[texture(1)]]) { constexpr sampler s(coord::normalized,address::clamp_to_edge,filter::nearest); float4 c; if(u.scaleAndBackdrop.z>0.5) { float2 px=in.point*u.scaleAndBackdrop.xy; float4 f=float4(0); if(px.x>=u.foregroundPixels.x&&px.y>=u.foregroundPixels.y&&px.x<u.foregroundPixels.x+u.foregroundPixels.z&&px.y<u.foregroundPixels.y+u.foregroundPixels.w) f=image.sample(s,(px-u.foregroundPixels.xy)/u.foregroundPixels.zw); float4 b=float4(0); if(in.point.x>=u.maskRect.x&&in.point.y>=u.maskRect.y&&in.point.x<u.maskRect.x+u.maskRect.z&&in.point.y<u.maskRect.y+u.maskRect.w&&px.x>=u.backdropPixels.x&&px.y>=u.backdropPixels.y&&px.x<u.backdropPixels.x+u.backdropPixels.z&&px.y<u.backdropPixels.y+u.backdropPixels.w) { bool inside=true; for(uint j=0;j<uint(u.clipCount.x);j++) { if(roundedDistance(in.point,u.clips[j].xy,u.clips[j].zw,u.clipRadii[j])>0.0) { inside=false; break; } } if(inside) b=backdrop.sample(s,(px-u.backdropPixels.xy)/u.backdropPixels.zw); } c=f+(1.0-f.a)*b; } else c=image.sample(s,in.uv); float q=u.opacity; if(u.maskPresent!=0u) { float2 p=in.point; float4 r=u.maskRect; if(p.x<r.x||p.y<r.y||p.x>=r.x+r.z||p.y>=r.y+r.w) q=0.0; else { float2 local=(p-r.xy)/max(r.zw,float2(1e-6)); float2 axis=u.endpoints.zw-u.endpoints.xy; float t=clamp(dot(local-u.endpoints.xy,axis)/dot(axis,axis),0.0,1.0); float a=u.alphas[0]; for(uint i=1u;i<u.stopCount;i++) { if(t<u.positions[i]) { float d=u.positions[i]-u.positions[i-1u]; if(d>0.0) a=mix(u.alphas[i-1u],u.alphas[i],clamp((t-u.positions[i-1u])/d,0.0,1.0)); break; } a=u.alphas[i]; } q*=a; } } return c*q; }\n";
    NSError *error = nil;
    id<MTLLibrary> library = [view.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: effect metal library failed %@", error); return nil; }
    MTLRenderPipelineDescriptor *descriptor = [[MTLRenderPipelineDescriptor alloc] init];
    descriptor.vertexFunction = [library newFunctionWithName:@"effect_vertex"];
    descriptor.fragmentFunction = [library newFunctionWithName:@"effect_fragment"];
    descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    descriptor.sampleCount = view.composableUsesMultisampling ? 4 : 1;
    descriptor.colorAttachments[0].blendingEnabled = YES;
    descriptor.colorAttachments[0].rgbBlendOperation = MTLBlendOperationAdd;
    descriptor.colorAttachments[0].alphaBlendOperation = MTLBlendOperationAdd;
    if (phase == 0) {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    } else if (phase == 1) {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorDestinationColor;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorZero;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOne;
    } else {
        descriptor.colorAttachments[0].sourceRGBBlendFactor = MTLBlendFactorOneMinusDestinationAlpha;
        descriptor.colorAttachments[0].destinationRGBBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = MTLBlendFactorOne;
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = MTLBlendFactorOneMinusSourceAlpha;
    }
    pipeline = [view.device newRenderPipelineStateWithDescriptor:descriptor error:&error];
    if (!pipeline) { NSLog(@"cjgui: effect pipeline failed %@", error); return nil; }
    view.effectPipelines[key] = pipeline;
#ifdef CJGUI_INTERNAL_TESTING
    view.testComposablePipelineBuildCount++;
#endif
    return pipeline;
}

static BOOL CjguiEncodeEffectGroupComposite(CJGuiInternalMetalView *view, id<MTLRenderCommandEncoder> encoder,
                                            CGSize drawableSize, CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    CJGuiInternalComposableEffectTarget *target = node.effectTarget;
    CJGuiInternalComposableEffectTarget *backdrop = value.effectBackdropBlurRadiusPoints > 0 ? node.backdropTarget : nil;
    BOOL hasForeground = target && target.resolvedTexture && target.pixelWidth > 0 && target.pixelHeight > 0;
    BOOL hasBackdrop = backdrop && backdrop.resolvedTexture && backdrop.pixelWidth > 0 && backdrop.pixelHeight > 0;
    if (!hasForeground && !hasBackdrop) return YES;
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    double left = hasForeground ? target.pixelX : backdrop.pixelX;
    double top = hasForeground ? target.pixelY : backdrop.pixelY;
    double right = left + (hasForeground ? target.pixelWidth : backdrop.pixelWidth);
    double bottom = top + (hasForeground ? target.pixelHeight : backdrop.pixelHeight);
    if (hasBackdrop) {
        left = MIN(left, backdrop.pixelX); top = MIN(top, backdrop.pixelY);
        right = MAX(right, backdrop.pixelX + backdrop.pixelWidth);
        bottom = MAX(bottom, backdrop.pixelY + backdrop.pixelHeight);
    }
    CjguiEffectCompositeVertex vertices[6] = {
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {left / scaleX, top / scaleY}, {0, 0}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {right / scaleX, top / scaleY}, {1, 0}},
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {left / scaleX, bottom / scaleY}, {0, 1}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * top / drawableSize.height},
         {right / scaleX, top / scaleY}, {1, 0}},
        {{-1.0f + 2.0f * right / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {right / scaleX, bottom / scaleY}, {1, 1}},
        {{-1.0f + 2.0f * left / drawableSize.width, 1.0f - 2.0f * bottom / drawableSize.height},
         {left / scaleX, bottom / scaleY}, {0, 1}},
    };
    CjguiEffectCompositeUniform uniform = {
        .maskRect = {(float)value.x, (float)value.y, (float)value.width, (float)value.height},
        .endpoints = {(float)value.effectMaskStartX, (float)value.effectMaskStartY,
                      (float)value.effectMaskEndX, (float)value.effectMaskEndY},
        .positions = {(float)value.effectMaskStop0Position, (float)value.effectMaskStop1Position,
                      (float)value.effectMaskStop2Position, (float)value.effectMaskStop3Position},
        .alphas = {(float)value.effectMaskStop0Alpha, (float)value.effectMaskStop1Alpha,
                   (float)value.effectMaskStop2Alpha, (float)value.effectMaskStop3Alpha},
        .opacity = (float)value.effectGroupOpacity,
        .maskPresent = value.effectMaskPresent,
        .stopCount = value.effectMaskStopCount,
        .foregroundPixels = hasForeground ? (vector_float4){target.pixelX, target.pixelY, target.pixelWidth, target.pixelHeight} : (vector_float4){0, 0, 0, 0},
        .backdropPixels = hasBackdrop ? (vector_float4){backdrop.pixelX, backdrop.pixelY, backdrop.pixelWidth, backdrop.pixelHeight} : (vector_float4){0, 0, 0, 0},
        .scaleAndBackdrop = {(float)scaleX, (float)scaleY, hasBackdrop ? 1.0f : 0.0f, 0.0f},
    };
    CjguiPopulateMetalClipChain(uniform.clips, &uniform.clipRadii, &uniform.clipCount, value);
    [encoder setVertexBytes:vertices length:sizeof(vertices) atIndex:0];
    [encoder setFragmentBytes:&uniform length:sizeof(uniform) atIndex:1];
    [encoder setFragmentTexture:hasForeground ? target.resolvedTexture : backdrop.resolvedTexture atIndex:0];
    [encoder setFragmentTexture:hasBackdrop ? backdrop.resolvedTexture : nil atIndex:1];
    uint32_t startPhase = value.effectGroupBlendMode == 1 ? 1 : 0;
    uint32_t endPhase = value.effectGroupBlendMode == 1 ? 2 : 0;
    for (uint32_t phase = startPhase; phase <= endPhase; phase++) {
        id<MTLRenderPipelineState> pipeline = CjguiEffectPipeline(view, phase);
        if (!pipeline) return NO;
        [encoder setRenderPipelineState:pipeline];
        [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectCompositeDrawCount++;
#endif
    }
    return YES;
}

static BOOL CjguiComposableSceneHasEffectGroups(NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.node.effectGroupPresent) return YES;
    }
    return NO;
}

// Bottom-up rendering makes every child target available before a parent's
// content pass. Encoding is only a preparation fact: a target stays dirty
// until the command buffer actually submits, and a changed content signature
// allocates a different generation.
static CjguiInternalRendererStatus CjguiEncodeEffectGroupContents(
    CJGuiInternalMetalView *view, id<MTLCommandBuffer> commandBuffer, CGSize drawableSize,
    NSMutableArray<CJGuiInternalComposableEffectTarget *> *redrawnTargets) {
    CjguiInternalRendererStatus prepared = CjguiPrepareEffectTargets(view, drawableSize);
    if (prepared != CJGUI_INTERNAL_RENDERER_OK) return prepared;
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    for (NSUInteger reverse = nodes.count; reverse > 0; reverse--) {
        NSUInteger index = reverse - 1;
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        CJGuiInternalComposableEffectTarget *target = node.effectTarget;
        if (!value.effectGroupPresent || !target || !target.needsRedraw) continue;
        MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
        pass.colorAttachments[0].texture = target.multisampleTexture ?: target.resolvedTexture;
        pass.colorAttachments[0].resolveTexture = target.multisampleTexture ? target.resolvedTexture : nil;
        pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        pass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 0);
        pass.colorAttachments[0].storeAction = target.multisampleTexture
            ? MTLStoreActionMultisampleResolve : MTLStoreActionStore;
        id<MTLRenderCommandEncoder> encoder = [commandBuffer renderCommandEncoderWithDescriptor:pass];
        if (!encoder) return CJGUI_INTERNAL_RENDERER_METAL_ENCODER_UNAVAILABLE;
        BOOL encoded = CjguiEncodeComposableNodesRange(view, encoder, drawableSize,
            target.pixelX, target.pixelY, target.pixelWidth, target.pixelHeight,
            index, index + value.effectGroupSubtreeCount, index);
        [encoder endEncoding];
        if (!encoded) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        [redrawnTargets addObject:target];
#ifdef CJGUI_INTERNAL_TESTING
        view.testEffectContentRedrawCount++;
        view.testEffectPassCount++;
#endif
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

// The in-app backdrop is the resolved root painter prefix immediately before
// the one admitted blur group. This key deliberately excludes later siblings
// and group foreground, while retaining every actual earlier contributor in
// the sampled halo. Rendering configuration and native decoration colours are
// part of the environment even when sceneVersion does not change.
static NSString *CjguiBackdropSignature(CJGuiInternalMetalView *view, NSUInteger groupIndex,
                                        uint32_t qx, uint32_t qy, uint32_t qw, uint32_t qh,
                                        uint32_t sy, uint32_t sh, uint32_t radius,
                                        float sigmaX, float sigmaY, uint32_t haloX, uint32_t haloY,
                                        CGSize drawableSize, MTLClearColor clearColor) {
    uint64_t hash = UINT64_C(1469598103934665603);
    uint64_t geometry[] = {qx, qy, qw, qh, sy, sh, radius,
                           (uint64_t)drawableSize.width, (uint64_t)drawableSize.height,
                           view.composableUsesMultisampling ? 4u : 1u};
    hash = CjguiEffectHashBytes(hash, geometry, sizeof(geometry));
    hash = CjguiEffectHashPaintEnvironment(hash, view.bounds.size, drawableSize,
                                           view.composableUsesMultisampling);
    float sigma[2] = {sigmaX, sigmaY};
    uint32_t support[2] = {haloX, haloY};
    hash = CjguiEffectHashBytes(hash, sigma, sizeof(sigma));
    hash = CjguiEffectHashBytes(hash, support, sizeof(support));
    double clear[] = {clearColor.red, clearColor.green, clearColor.blue, clearColor.alpha};
    hash = CjguiEffectHashBytes(hash, clear, sizeof(clear));
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    // Use the encoder's actual float kernel support for dependency filtering.
    // Re-deriving it with double rounding can miss a halo-only painter.
    double sampleLeft = MAX(0.0, (double)qx - haloX) / scaleX;
    double sampleRight = MIN(drawableSize.width, (double)qx + qw + haloX) / scaleX;
    NSRect sample = NSMakeRect(sampleLeft, sy / scaleY, sampleRight - sampleLeft, sh / scaleY);
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    for (NSUInteger index = 0; index < groupIndex;) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        BOOL group = value.effectGroupPresent != 0;
        NSRect output = group
            ? CjguiEffectGroupOutputBounds(nodes, index, index + value.effectGroupSubtreeCount)
            : CjguiEffectNodeOutputBounds(node);
        NSUInteger next = group ? index + value.effectGroupSubtreeCount : index + 1;
        if (!NSIsEmptyRect(NSIntersectionRect(output, sample))) {
            hash = CjguiEffectHashBytes(hash, &index, sizeof(index));
            hash = CjguiEffectHashPaintNode(hash, node, value);
            if (group) hash = CjguiEffectHashString(hash, node.effectTarget.contentSignature);
        }
        index = next;
    }
    return [NSString stringWithFormat:@"%016llx", (unsigned long long)hash];
}

static BOOL CjguiEnsureBackdropPipelines(CJGuiInternalMetalView *view) {
    if (view.backdropHorizontalPipeline && view.backdropVerticalPipeline) return YES;
    NSString *source = @"#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void backdrop_horizontal(texture2d<float,access::read> src [[texture(0)]], texture2d<float,access::write> dst [[texture(1)]], constant uint *p [[buffer(0)]], constant float *w [[buffer(1)]], uint2 id [[thread_position_in_grid]]) { if(id.x>=p[2]||id.y>=p[5]) return; int x=int(p[0]+id.x), y=int(p[4]+id.y); float4 c=float4(0); for(int k=-int(p[8]);k<=int(p[8]);k++) c+=src.read(uint2(uint(clamp(x+k,0,int(p[6])-1)),uint(y)))*w[k+int(p[8])]; dst.write(c,id); }\n"
        "kernel void backdrop_vertical(texture2d<float,access::read> src [[texture(0)]], texture2d<float,access::write> dst [[texture(1)]], constant uint *p [[buffer(0)]], constant float *w [[buffer(1)]], uint2 id [[thread_position_in_grid]]) { if(id.x>=p[2]||id.y>=p[3]) return; int y=int(p[1]+id.y); float4 c=float4(0); for(int k=-int(p[8]);k<=int(p[8]);k++) { int sourceY=clamp(y+k,0,int(p[7])-1)-int(p[4]); c+=src.read(uint2(id.x,uint(sourceY)))*w[k+int(p[8])]; } dst.write(c,id); }\n";
    NSError *error = nil;
    id<MTLLibrary> library = [view.device newLibraryWithSource:source options:nil error:&error];
    if (!library) { NSLog(@"cjgui: backdrop metal library failed %@", error); return NO; }
    id<MTLFunction> horizontal = [library newFunctionWithName:@"backdrop_horizontal"];
    id<MTLFunction> vertical = [library newFunctionWithName:@"backdrop_vertical"];
    if (!horizontal || !vertical) return NO;
    view.backdropHorizontalPipeline = [view.device newComputePipelineStateWithFunction:horizontal error:&error];
    view.backdropVerticalPipeline = [view.device newComputePipelineStateWithFunction:vertical error:&error];
    if (!view.backdropHorizontalPipeline || !view.backdropVerticalPipeline) {
        NSLog(@"cjgui: backdrop compute pipeline failed %@", error);
        return NO;
    }
    return YES;
}

static void CjguiBackdropWeights(uint32_t kernelRadius, float sigma, float weights[97]) {
    float sum = 0.0f;
    for (uint32_t index = 0; index <= 2 * kernelRadius; index++) {
        int distance = (int)index - (int)kernelRadius;
        weights[index] = expf(-0.5f * (float)(distance * distance) / (sigma * sigma));
        sum += weights[index];
    }
    for (uint32_t index = 0; index <= 2 * kernelRadius; index++) weights[index] /= sum;
}

typedef struct CjguiInternalBackdropOutcome {
    uint32_t requestedRadiusPoints;
    uint32_t mode;
    uint32_t reason;
} CjguiInternalBackdropOutcome;

// Returns YES only after both blur passes were encoded. On failure the caller
// abandons this command buffer and submits a fresh, unblurred accepted frame;
// a partial target is never published as a cache hit.
static BOOL CjguiEncodeBackdrop(CJGuiInternalMetalView *view, id<MTLCommandBuffer> commandBuffer,
                                CGSize drawableSize, MTLClearColor clearColor,
                                NSMutableArray<CJGuiInternalComposableEffectTarget *> *scratch,
                                NSMutableArray<CJGuiInternalComposableEffectTarget *> *written,
                                CjguiInternalBackdropOutcome *outcome) {
    *outcome = (CjguiInternalBackdropOutcome){0, CJGUI_INTERNAL_BACKDROP_NONE,
                                              CJGUI_INTERNAL_BACKDROP_REASON_NOT_REQUESTED};
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = view.composableNodes;
    NSUInteger groupIndex = NSNotFound;
    for (NSUInteger i = 0; i < nodes.count; i++) {
        if (nodes[i].node.effectBackdropBlurRadiusPoints > 0) groupIndex = i;
        else nodes[i].backdropTarget = nil;
    }
    if (groupIndex == NSNotFound) return YES;
    CJGuiInternalComposableSceneNode *node = nodes[groupIndex];
    CjguiInternalRendererComposableNode value = node.node;
    outcome->requestedRadiusPoints = value.effectBackdropBlurRadiusPoints;
    outcome->mode = CJGUI_INTERNAL_BACKDROP_BLURRED;
    outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_NONE;
    node.backdropTarget = nil;
    if (clearColor.alpha < 1.0) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_NON_OPAQUE_CLEAR;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    NSRect bounds = NSIntersectionRect(NSMakeRect(value.x, value.y, value.width, value.height),
                                      NSMakeRect(value.clipX, value.clipY, value.clipWidth, value.clipHeight));
    uint32_t qx, qy, qw, qh;
    if (!CjguiEffectPixelBounds(bounds, view.bounds.size, drawableSize, &qx, &qy, &qw, &qh) || !qw || !qh) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_NONE;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_EMPTY_ROI;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    double scaleX = drawableSize.width / MAX(1.0, view.bounds.size.width);
    double scaleY = drawableSize.height / MAX(1.0, view.bounds.size.height);
    float sigmaX = (float)(value.effectBackdropBlurRadiusPoints * scaleX / 2.0);
    float sigmaY = (float)(value.effectBackdropBlurRadiusPoints * scaleY / 2.0);
    uint32_t haloX = (uint32_t)ceilf(3.0f * sigmaX), haloY = (uint32_t)ceilf(3.0f * sigmaY);
    if (!isfinite(sigmaX) || !isfinite(sigmaY) || sigmaX <= 0 || sigmaY <= 0 ||
        haloX > 48 || haloY > 48 || drawableSize.width > CjguiEffectTargetDimensionCapacity ||
        drawableSize.height > CjguiEffectTargetDimensionCapacity ||
        drawableSize.width * drawableSize.height > CjguiEffectTargetPixelCapacity) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_KERNEL_LIMIT;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    uint32_t sy = qy > haloY ? qy - haloY : 0;
    uint32_t ey = MIN((uint32_t)drawableSize.height, qy + qh + haloY);
    uint32_t sh = ey - sy;
    NSString *signature = CjguiBackdropSignature(view, groupIndex, qx, qy, qw, qh, sy, sh,
                                                 value.effectBackdropBlurRadiusPoints,
                                                 sigmaX, sigmaY, haloX, haloY, drawableSize, clearColor);
    CJGuiInternalComposableEffectTarget *old = view.backdropCache[@(value.nodeId)];
    if (old && old.gpuCompleted && !old.invalidatedByGpuFailure && !old.needsRedraw &&
        [old.contentSignature isEqualToString:signature]) {
        node.backdropTarget = old;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropCacheHitCount++;
#endif
        return YES;
    }
    uint64_t pixels = (uint64_t)drawableSize.width * (uint64_t)drawableSize.height;
    uint64_t replayBytes = pixels * (view.composableUsesMultisampling ? 20u : 4u);
    uint64_t pingBytes = (uint64_t)qw * sh * 8u;
    uint64_t resultBytes = (uint64_t)qw * qh * 4u;
    uint64_t liveBytes = CjguiEffectLiveTargetBytes(view);
    if (liveBytes > CjguiEffectTargetByteCapacity ||
        replayBytes > CjguiEffectTargetByteCapacity - liveBytes ||
        pingBytes > CjguiEffectTargetByteCapacity - liveBytes - replayBytes ||
        resultBytes > CjguiEffectTargetByteCapacity - liveBytes - replayBytes - pingBytes) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_RESOURCE_BUDGET;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    if (!CjguiEnsureBackdropPipelines(view)) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_PIPELINE_UNAVAILABLE;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    MTLTextureDescriptor *desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
        width:(NSUInteger)drawableSize.width height:(NSUInteger)drawableSize.height mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
    id<MTLTexture> replay = [view.device newTextureWithDescriptor:desc];
    id<MTLTexture> replayMSAA = nil;
    if (replay && view.composableUsesMultisampling) {
        desc.textureType = MTLTextureType2DMultisample;
        desc.sampleCount = 4;
        desc.usage = MTLTextureUsageRenderTarget;
        replayMSAA = [view.device newTextureWithDescriptor:desc];
    }
    desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA16Float
        width:qw height:sh mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    id<MTLTexture> ping = [view.device newTextureWithDescriptor:desc];
    desc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
        width:qw height:qh mipmapped:NO];
    desc.storageMode = MTLStorageModePrivate;
    desc.usage = MTLTextureUsageShaderWrite | MTLTextureUsageShaderRead;
    id<MTLTexture> blurred = [view.device newTextureWithDescriptor:desc];
    if (!replay || (view.composableUsesMultisampling && !replayMSAA) || !ping || !blurred) {
        outcome->mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
        outcome->reason = CJGUI_INTERNAL_BACKDROP_REASON_ALLOCATION_FAILED;
#ifdef CJGUI_INTERNAL_TESTING
        view.testBackdropFallbackCount++;
#endif
        return YES;
    }
    CJGuiInternalComposableEffectTarget *replayOwner = [[CJGuiInternalComposableEffectTarget alloc] init];
    replayOwner.resolvedTexture = replay; replayOwner.multisampleTexture = replayMSAA;
    replayOwner.byteCount = replayBytes;
    CJGuiInternalComposableEffectTarget *pingOwner = [[CJGuiInternalComposableEffectTarget alloc] init];
    pingOwner.resolvedTexture = ping; pingOwner.byteCount = pingBytes;
    CJGuiInternalComposableEffectTarget *result = [[CJGuiInternalComposableEffectTarget alloc] init];
    result.resolvedTexture = blurred; result.byteCount = resultBytes;
    result.pixelX = qx; result.pixelY = qy; result.pixelWidth = qw; result.pixelHeight = qh;
    result.samplePixelX = qx > haloX ? qx - haloX : 0;
    result.samplePixelY = sy;
    result.samplePixelWidth = MIN((uint32_t)drawableSize.width, qx + qw + haloX) - result.samplePixelX;
    result.samplePixelHeight = sh;
    result.contentSignature = signature; result.needsRedraw = YES;
    [view.effectTargetLedger addObject:replayOwner];
    [view.effectTargetLedger addObject:pingOwner];
    [view.effectTargetLedger addObject:result];
    [scratch addObject:replayOwner]; [scratch addObject:pingOwner];
    MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
    pass.colorAttachments[0].texture = replayMSAA ?: replay;
    pass.colorAttachments[0].resolveTexture = replayMSAA ? replay : nil;
    pass.colorAttachments[0].loadAction = MTLLoadActionClear;
    pass.colorAttachments[0].storeAction = replayMSAA ? MTLStoreActionMultisampleResolve : MTLStoreActionStore;
    pass.colorAttachments[0].clearColor = clearColor;
    id<MTLRenderCommandEncoder> prefix = [commandBuffer renderCommandEncoderWithDescriptor:pass];
    if (!prefix) return NO;
    BOOL prefixEncoded = CjguiEncodeComposableNodesRange(view, prefix, drawableSize, 0, 0,
        (uint32_t)drawableSize.width, (uint32_t)drawableSize.height, 0, groupIndex, NSUIntegerMax);
    [prefix endEncoding];
    if (!prefixEncoded) return NO;
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropPrefixPassCount++;
#endif
    uint32_t params[9] = {qx, qy, qw, qh, sy, sh, (uint32_t)drawableSize.width,
                          (uint32_t)drawableSize.height, haloX};
    float weights[97] = {0};
    CjguiBackdropWeights(haloX, sigmaX, weights);
    id<MTLComputeCommandEncoder> compute = [commandBuffer computeCommandEncoder];
    if (!compute) return NO;
    [compute setComputePipelineState:view.backdropHorizontalPipeline];
    [compute setTexture:replay atIndex:0]; [compute setTexture:ping atIndex:1];
    [compute setBytes:params length:sizeof(params) atIndex:0];
    [compute setBytes:weights length:(2 * haloX + 1) * sizeof(float) atIndex:1];
    [compute dispatchThreads:MTLSizeMake(qw, sh, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)];
    [compute endEncoding];
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropHorizontalPassCount++;
#endif
    params[8] = haloY;
    CjguiBackdropWeights(haloY, sigmaY, weights);
    compute = [commandBuffer computeCommandEncoder];
    if (!compute) return NO;
    [compute setComputePipelineState:view.backdropVerticalPipeline];
    [compute setTexture:ping atIndex:0]; [compute setTexture:blurred atIndex:1];
    [compute setBytes:params length:sizeof(params) atIndex:0];
    [compute setBytes:weights length:(2 * haloY + 1) * sizeof(float) atIndex:1];
    [compute dispatchThreads:MTLSizeMake(qw, qh, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)];
    [compute endEncoding];
#ifdef CJGUI_INTERNAL_TESTING
    view.testBackdropVerticalPassCount++;
#endif
    node.backdropTarget = result;
    [written addObject:result];
    (void)CjguiEffectLiveTargetBytes(view);
    return YES;
}

static void CjguiPublishAcceptedEffectCache(CJGuiInternalMetalView *view) {
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *accepted = [NSMutableDictionary dictionary];
    NSMutableDictionary<NSNumber *, CJGuiInternalComposableEffectTarget *> *backdrops = [NSMutableDictionary dictionary];
    for (CJGuiInternalComposableSceneNode *node in view.composableNodes) {
        if (node.node.effectGroupPresent && node.effectTarget)
            accepted[@(node.node.nodeId)] = node.effectTarget;
        if (node.node.effectBackdropBlurRadiusPoints > 0 && node.backdropTarget)
            backdrops[@(node.node.nodeId)] = node.backdropTarget;
    }
    view.effectGroupCache = accepted;
    view.backdropCache = backdrops;
    (void)CjguiEffectLiveTargetBytes(view);
}

static void CjguiReleaseFailedCandidateEffectTargets(CJGuiInternalSession *ctx) {
    if (!ctx) return;
    NSSet<CJGuiInternalComposableSceneNode *> *accepted = [NSSet setWithArray:ctx.composableNodes ?: @[]];
    for (CJGuiInternalComposableSceneNode *node in ctx.stagedComposableNodes) {
        // COW may have reused the exact accepted node object. Clearing its
        // target would mutate the old scene, so release only candidate copies.
        if (![accepted containsObject:node]) {
            node.effectTarget = nil;
            node.backdropTarget = nil;
        }
    }
    (void)CjguiEffectLiveTargetBytes(ctx.view);
}

static NSRect CjguiComposableRect(CJGuiInternalComposableSceneNode *node, NSView *view) {
    CjguiInternalRendererComposableNode value = node.node;
    // The composable overlay is flipped, as is the Cangjie layout space: both
    // start at the window's top-left.  Do not invert here; doing so made text,
    // hit testing and AX frames disagree with the Metal scene.
    return NSMakeRect((CGFloat)value.x, (CGFloat)value.y,
                      MAX(0.0, (CGFloat)value.width), MAX(0.0, (CGFloat)value.height));
}

static NSRect CjguiComposableClipConstraintRect(CJGuiInternalComposableSceneNode *node, uint32_t index) {
    CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
    CjguiComposableClipConstraintAt(node.node, index, &x, &y, &width, &height, &radius);
    return NSMakeRect(x, y, MAX(0.0, width), MAX(0.0, height));
}

// The layout projection also supplies this rectangle intersection for cheap
// culling and AX bounds.  It is never used as the final rounded clip: every
// draw and hit test below evaluates the complete ancestor chain.
static NSRect CjguiComposableClipBounds(CJGuiInternalComposableSceneNode *node) {
    CjguiInternalRendererComposableNode value = node.node;
    return NSMakeRect((CGFloat)value.clipX, (CGFloat)value.clipY,
                      MAX(0.0, (CGFloat)value.clipWidth), MAX(0.0, (CGFloat)value.clipHeight));
}

// Scene geometry is expressed in the overlay's flipped coordinate space.  A
// rounded inherited clip must therefore have the same meaning for Metal,
// TextKit's remaining multiline path, and pointer routing.  A decoration
// radius alone is not consulted here: only the resolved clip radius controls
// whether children may draw or receive an event.
static BOOL CjguiPointInRoundedRect(NSPoint point, NSRect rect, CGFloat requestedRadius) {
    if (!NSPointInRect(point, rect)) return NO;
    CGFloat radius = MIN(MAX(0.0, requestedRadius), MIN(NSWidth(rect), NSHeight(rect)) / 2.0);
    if (radius <= 0.0) return YES;
    CGFloat minX = NSMinX(rect), maxX = NSMaxX(rect);
    CGFloat minY = NSMinY(rect), maxY = NSMaxY(rect);
    CGFloat centreX = point.x < minX + radius ? minX + radius :
                      (point.x > maxX - radius ? maxX - radius : point.x);
    CGFloat centreY = point.y < minY + radius ? minY + radius :
                      (point.y > maxY - radius ? maxY - radius : point.y);
    CGFloat dx = point.x - centreX, dy = point.y - centreY;
    return dx * dx + dy * dy <= radius * radius;
}

static BOOL CjguiPointInComposableNodeClip(NSPoint point, CJGuiInternalComposableSceneNode *node, NSView *view) {
    (void)view;
    return node && CjguiComposablePointInClipChain(point.x, point.y, node.node);
}

static BOOL CjguiComposableVectorPointInSimplePolygon(CjguiInternalComposableVectorPoint point,
                                                      const CjguiInternalComposableVectorPoint *points,
                                                      uint32_t pointCount) {
    if (!points || pointCount < 3) return NO;
    BOOL inside = NO;
    for (uint32_t index = 0, previous = pointCount - 1; index < pointCount; previous = index++) {
        CjguiInternalComposableVectorPoint start = points[previous];
        CjguiInternalComposableVectorPoint end = points[index];
        if (fabs(CjguiComposableVectorCross(start, end, point)) <= CjguiComposableVectorEpsilon &&
            CjguiComposableVectorBetween(point.x, start.x, end.x) &&
            CjguiComposableVectorBetween(point.y, start.y, end.y)) return YES;
        BOOL crosses = ((start.y > point.y) != (end.y > point.y));
        if (crosses && point.x < (end.x - start.x) * (point.y - start.y) / (end.y - start.y) + start.x) {
            inside = !inside;
        }
    }
    return inside;
}

static BOOL CjguiComposableVectorPointNearSegment(CjguiInternalComposableVectorPoint point,
                                                  CjguiInternalComposableVectorPoint start,
                                                  CjguiInternalComposableVectorPoint end,
                                                  double halfWidth, uint32_t cap,
                                                  BOOL startCap, BOOL endCap) {
    if (halfWidth <= 0.0) return NO;
    CjguiInternalComposableVectorPoint direction = {0};
    if (!CjguiComposableVectorUnitDirection(start, end, &direction)) return NO;
    CjguiInternalComposableVectorPoint delta = CjguiComposableVectorSubtract(point, start);
    double length = CjguiComposableVectorLength(CjguiComposableVectorSubtract(end, start));
    double along = delta.x * direction.x + delta.y * direction.y;
    double across = fabs(delta.x * -direction.y + delta.y * direction.x);
    if (along >= 0.0 && along <= length && across <= halfWidth) return YES;
    if (cap == CJGUI_INTERNAL_VECTOR_CAP_SQUARE) {
        if (startCap && along >= -halfWidth && along < 0.0 && across <= halfWidth) return YES;
        if (endCap && along > length && along <= length + halfWidth && across <= halfWidth) return YES;
    }
    if (cap == CJGUI_INTERNAL_VECTOR_CAP_ROUND) {
        if (startCap && along < 0.0 && CjguiComposableVectorLength(delta) <= halfWidth) return YES;
        CjguiInternalComposableVectorPoint endDelta = CjguiComposableVectorSubtract(point, end);
        if (endCap && along > length && CjguiComposableVectorLength(endDelta) <= halfWidth) return YES;
    }
    return NO;
}

static BOOL CjguiComposableVectorContainsPoint(CJGuiInternalComposableSceneNode *node, NSPoint point) {
    if (!node || !node.hasVectorGeometry) return NO;
    CjguiInternalRendererComposableNode value = node.node;
    CjguiInternalComposableVectorGeometry geometry = node.vectorGeometry;
    if (value.width <= 0 || value.height <= 0 || geometry.viewBoxWidth <= 0.0 || geometry.viewBoxHeight <= 0.0) return NO;
    CjguiInternalComposableVectorPoint local = CjguiComposableVectorPoint(
        ((double)point.x - (double)value.x) * geometry.viewBoxWidth / (double)value.width,
        ((double)point.y - (double)value.y) * geometry.viewBoxHeight / (double)value.height);
    BOOL fillVisible = geometry.fillAlpha > 0.0;
    BOOL strokeVisible = geometry.strokeAlpha > 0.0 && geometry.strokeWidth > 0.0;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_ELLIPSE) {
        double normalizedX = (local.x - geometry.center.x) / geometry.radiusX;
        double normalizedY = (local.y - geometry.center.y) / geometry.radiusY;
        double normalizedDistance = normalizedX * normalizedX + normalizedY * normalizedY;
        if (fillVisible && normalizedDistance <= 1.0) return YES;
        if (strokeVisible) {
            double radial = sqrt(MAX(0.0, normalizedDistance));
            return fabs(radial - 1.0) * MIN(geometry.radiusX, geometry.radiusY) <= geometry.strokeWidth / 2.0;
        }
        return NO;
    }
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON && fillVisible &&
        CjguiComposableVectorPointInSimplePolygon(local, geometry.points, geometry.pointCount)) return YES;
    if (!strokeVisible || geometry.pointCount < 2) return NO;
    double halfWidth = geometry.strokeWidth / 2.0;
    if (geometry.kind == CJGUI_INTERNAL_VECTOR_SIMPLE_POLYGON) {
        for (uint32_t index = 0; index < geometry.pointCount; index++) {
            uint32_t next = index + 1 == geometry.pointCount ? 0 : index + 1;
            if (CjguiComposableVectorPointNearSegment(local, geometry.points[index], geometry.points[next],
                                                       halfWidth, CJGUI_INTERNAL_VECTOR_CAP_BUTT, NO, NO)) return YES;
        }
        return NO;
    }
    for (uint32_t index = 0; index + 1 < geometry.pointCount; index++) {
        if (CjguiComposableVectorPointNearSegment(local, geometry.points[index], geometry.points[index + 1], halfWidth,
                                                   geometry.cap, index == 0, index + 2 == geometry.pointCount)) return YES;
    }
    return NO;
}

static BOOL CjguiComposableNodeContainsPoint(CJGuiInternalComposableSceneNode *node, NSPoint point, NSView *view) {
    if (!node || !NSPointInRect(point, CjguiComposableRect(node, view))) return NO;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC) {
        return CjguiComposableVectorContainsPoint(node, point);
    }
    return YES;
}

static void CjguiClipComposableNode(CJGuiInternalComposableSceneNode *node, NSView *view) {
    if (!node) return;
    (void)view;
    uint32_t count = CjguiComposableClipConstraintCount(node.node);
    for (uint32_t i = 0; i < count; i++) {
        NSRect rect = CjguiComposableClipConstraintRect(node, i);
        CGFloat x = 0, y = 0, width = 0, height = 0, radius = 0;
        CjguiComposableClipConstraintAt(node.node, i, &x, &y, &width, &height, &radius);
        radius = MIN(MAX(0.0, radius), MIN(NSWidth(rect), NSHeight(rect)) / 2.0);
        if (radius <= 0.0) {
            NSRectClip(rect);
        } else {
            [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:radius yRadius:radius] addClip];
        }
    }
}

// Font weight accepts both the legacy boolean form and the numeric scale:
// 0 = regular and any small non-zero value (1..99) still means bold, so existing
// callers are unchanged. From 100 up the value is a CSS-like weight, so 400 is
// regular, 500/600 semibold and 700+ bold. Before this, passing 400 made body
// text render bold because every non-zero value was treated as bold.
static NSFontWeight CjguiComposableWeightForCode(uint32_t fontWeight) {
    if (fontWeight == 0) {
        return NSFontWeightRegular;
    }
    if (fontWeight < 100) {
        return NSFontWeightBold;
    }
    if (fontWeight < 500) {
        return NSFontWeightRegular;
    }
    if (fontWeight < 600) {
        return NSFontWeightMedium;
    }
    if (fontWeight < 700) {
        return NSFontWeightSemibold;
    }
    return NSFontWeightBold;
}

// Font family codes: 0 system, 1 monospaced, 2 system italic, 3 monospaced
// italic. Italic rides the family field so no native node field has to change.
static NSFont *CjguiComposableFontForStyle(double requested, uint32_t fontWeight, uint32_t fontFamily) {
    CGFloat size = MIN(144.0, MAX(6.0, requested));
    NSFontWeight weight = CjguiComposableWeightForCode(fontWeight);
    BOOL italic = (fontFamily == 2 || fontFamily == 3);
    NSFont *base = (fontFamily == 1 || fontFamily == 3)
        ? [NSFont monospacedSystemFontOfSize:size weight:weight]
        : [NSFont systemFontOfSize:size weight:weight];
    if (!italic) {
        return base;
    }
    NSFont *slanted = [[NSFontManager sharedFontManager] convertFont:base toHaveTrait:NSItalicFontMask];
    return slanted ?: base;
}

static NSFont *CjguiComposableFont(CJGuiInternalComposableSceneNode *node) {
    return CjguiComposableFontForStyle(
        node ? node.node.fontSize : 13.0,
        node ? node.node.fontWeight : 0,
        node ? node.node.fontFamily : 0
    );
}

#ifdef CJGUI_INTERNAL_TESTING
static CGRect CjguiMapMultilineDiagnosticRect(CGRect rect, CGAffineTransform transform) {
    CGPoint corners[4] = {
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMinX(rect), CGRectGetMinY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMaxX(rect), CGRectGetMinY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMinX(rect), CGRectGetMaxY(rect)), transform),
        CGPointApplyAffineTransform(CGPointMake(CGRectGetMaxX(rect), CGRectGetMaxY(rect)), transform),
    };
    CGFloat minX = corners[0].x, maxX = corners[0].x, minY = corners[0].y, maxY = corners[0].y;
    for (NSUInteger index = 1; index < 4; index++) {
        minX = MIN(minX, corners[index].x); maxX = MAX(maxX, corners[index].x);
        minY = MIN(minY, corners[index].y); maxY = MAX(maxY, corners[index].y);
    }
    return CGRectMake(minX, minY, maxX - minX, maxY - minY);
}

static void CjguiLogMultilineGlyphDrawingState(uint64_t nodeId, NSLayoutManager *layoutManager,
                                                NSTextContainer *container, NSRange visibleGlyphs,
                                                NSPoint origin, NSString *value) {
    // All diagnostics below include whole-document UTF-16 formatting, font
    // enumeration and CoreText fallback lookup. The opt-in must guard the
    // work itself, not just the final NSLog, or TESTING builds distort raster
    // latency by tens of milliseconds per tile.
    if (!CjguiTestVerboseGlyphDiagnosticsEnabled()) return;
    CGContextRef context = NSGraphicsContext.currentContext.CGContext;
    if (!context || !layoutManager || !container || visibleGlyphs.location == NSNotFound || visibleGlyphs.length == 0) return;
    CGAffineTransform ctm = CGContextGetCTM(context);
    CGAffineTransform textMatrix = CGContextGetTextMatrix(context);
    CGPoint textPosition = CGContextGetTextPosition(context);
    NSRange containerGlyphs = [layoutManager glyphRangeForTextContainer:container];
    NSGlyph glyph = [layoutManager glyphAtIndex:visibleGlyphs.location];
    NSGlyphProperty property = [layoutManager propertyForGlyphAtIndex:visibleGlyphs.location];
    NSRect line = [layoutManager lineFragmentRectForGlyphAtIndex:visibleGlyphs.location effectiveRange:NULL];
    NSRect used = [layoutManager lineFragmentUsedRectForGlyphAtIndex:visibleGlyphs.location effectiveRange:NULL];
    NSPoint glyphLocation = [layoutManager locationForGlyphAtIndex:visibleGlyphs.location];
    NSRect glyphBounds = [layoutManager boundingRectForGlyphRange:NSMakeRange(visibleGlyphs.location, 1)
                                                   inTextContainer:container];
    NSRect glyphUserBounds = NSOffsetRect(glyphBounds, origin.x, origin.y);
    CGRect glyphDeviceBounds = CjguiMapMultilineDiagnosticRect(NSRectToCGRect(glyphUserBounds), ctm);
    CGRect clipUserBounds = CGContextGetClipBoundingBox(context);
    NSMutableString *utf16 = [NSMutableString string];
    for (NSUInteger index = 0; index < value.length; index++) [utf16 appendFormat:@"%04X", [value characterAtIndex:index]];
    NSDictionary *attributes = value.length > 0 ? [layoutManager.textStorage attributesAtIndex:0 effectiveRange:NULL] : @{};
    NSMutableString *fontRuns = [NSMutableString string];
    [layoutManager.textStorage enumerateAttributesInRange:NSMakeRange(0, value.length) options:0
                                               usingBlock:^(NSDictionary<NSAttributedStringKey, id> *runAttributes,
                                                            NSRange range, BOOL *stop) {
        (void)stop;
        NSFont *runFont = runAttributes[NSFontAttributeName];
        [fontRuns appendFormat:@"%lu:%lu=%@;", (unsigned long)range.location, (unsigned long)range.length,
         runFont.fontName ?: @"(none)"];
    }];
    NSMutableString *glyphs = [NSMutableString string];
    NSUInteger glyphEnd = MIN(NSMaxRange(visibleGlyphs), visibleGlyphs.location + 8);
    for (NSUInteger index = visibleGlyphs.location; index < glyphEnd; index++) {
        [glyphs appendFormat:@"%lu:%u/%lu;", (unsigned long)index, [layoutManager glyphAtIndex:index],
         (unsigned long)[layoutManager propertyForGlyphAtIndex:index]];
    }
    NSFont *font = attributes[NSFontAttributeName];
    CGGlyph directGlyph = 0;
    BOOL hasDirectGlyph = NO;
    CTFontRef fallback = NULL;
    if (font && value.length > 0) {
        CTFontRef baseFont = (__bridge CTFontRef)font;
        UniChar firstCharacter = [value characterAtIndex:0];
        hasDirectGlyph = CTFontGetGlyphsForCharacters(baseFont, &firstCharacter, &directGlyph, 1);
        fallback = CTFontCreateForString(baseFont, (__bridge CFStringRef)value, CFRangeMake(0, value.length));
    }
    NSString *fallbackName = fallback ? CFBridgingRelease(CTFontCopyPostScriptName(fallback)) : @"(none)";
    if (fallback) CFRelease(fallback);
    if (CjguiTestVerboseGlyphDiagnosticsEnabled()) NSLog(@"cjgui: multiline glyph-draw node=%llu context=%p flipped=%d ctm=(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f) textMatrix=(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f) textPosition=(%.3f,%.3f) clipUser=%@ origin=%@ value=%@ utf16=%@ font=%@ fontRuns=%@ directGlyph=%u direct=%d cascadeCandidate=%@ containerGlyphs=%lu:%lu visible=%lu:%lu glyphs=%@ glyph0=%u property=%lu line=%@ used=%@ location=%@ glyphBounds=%@ glyphUser=%@ glyphDevice=%@",
          nodeId, context, NSGraphicsContext.currentContext.isFlipped,
          ctm.a, ctm.b, ctm.c, ctm.d, ctm.tx, ctm.ty,
          textMatrix.a, textMatrix.b, textMatrix.c, textMatrix.d, textMatrix.tx, textMatrix.ty,
          textPosition.x, textPosition.y, NSStringFromRect(NSRectFromCGRect(clipUserBounds)), NSStringFromPoint(origin),
          value ?: @"", utf16, font, fontRuns, directGlyph, hasDirectGlyph, fallbackName,
          (unsigned long)containerGlyphs.location, (unsigned long)containerGlyphs.length,
          (unsigned long)visibleGlyphs.location, (unsigned long)visibleGlyphs.length, glyphs,
          glyph, (unsigned long)property, NSStringFromRect(line), NSStringFromRect(used),
          NSStringFromPoint(glyphLocation), NSStringFromRect(glyphBounds), NSStringFromRect(glyphUserBounds),
          NSStringFromRect(NSRectFromCGRect(glyphDeviceBounds)));
}
#endif

@class CJGuiInternalComposableSceneOverlay;

// A self-drawn multiline node needs TextKit for exactly the same glyph and
// line-fragment geometry used by input hit testing.  Keep that layout bounded
// and projection-owned rather than allocating a second TextKit graph on every
// display pass.  The current projection version is part of the cache key, so
// a changed projection cannot reuse an older semantic snapshot.
@interface CJGuiInternalComposableMultilineLayoutCacheEntry : NSObject
@property(nonatomic, strong) NSTextStorage *storage;
@property(nonatomic, strong) NSLayoutManager *layoutManager;
@property(nonatomic, strong) NSTextContainer *container;
@property(nonatomic, strong) NSString *value;
@property(nonatomic, assign) CGFloat contentWidth;
@property(nonatomic, assign) CGFloat maximumScroll;
@end

@implementation CJGuiInternalComposableMultilineLayoutCacheEntry
@end

static BOOL CjguiComposableNodeIsTextInput(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
}

static BOOL CjguiComposableNodeAcceptsPointerCapture(uint32_t kind) {
    // 2026-09-26: TEXT 必须能开始指针捕获。此前白名单只有分隔条/滑块,文本节点在
    // beginPointerCaptureForNode 的第三条件被拒 ⇒ 从不产出 POINTER_* ⇒ 点击不落光标、
    // 无法拖选(用户实机反馈 + tools/check-hit-routing.sh FAIL:caretNode=-1)。
    // 文本输入类(MULTILINE/INTEGER)已有各自的输入处理,不在此纳入,避免双重捕获。
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SPLIT_DIVIDER ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SLIDER ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT;
}

static BOOL CjguiComposableNodeIsPressable(uint32_t kind) {
    return kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC;
}

static BOOL CjguiComposableNodeIsAccessibilityElement(CJGuiInternalComposableSceneNode *node) {
    if (!node) return NO;
    // Disabled controls remain discoverable so an assistive client can tell
    // why the visible action cannot run. Static text is likewise a first
    // class semantic object even though it never receives pointer input.
    uint32_t kind = node.node.nodeKind;
    return node.node.isInteractive != 0 || kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        CjguiComposableNodeIsTextInput(kind) || kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA ||
        node.node.semanticRole == 4 || node.node.semanticRole == 5;
}

@interface CJGuiInternalComposableAccessibilityAction : NSAccessibilityElement
@property(nonatomic, weak) CJGuiInternalComposableSceneOverlay *overlay;
@property(nonatomic, strong) CJGuiInternalComposableSceneNode *node;
@property(nonatomic, copy) NSString *identityKey;
@property(nonatomic, weak) CJGuiInternalComposableAccessibilityAction *semanticParent;
@property(nonatomic, strong) NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *semanticChildren;
- (instancetype)initWithOverlay:(CJGuiInternalComposableSceneOverlay *)overlay node:(CJGuiInternalComposableSceneNode *)node;
@end

#ifdef CJGUI_INTERNAL_TESTING
// This test-only accumulator keeps scalar timings on the existing TextKit
// graph. It never becomes a text-system delegate or content owner.
@interface CJGuiInternalComposableActiveLayoutTrace : NSObject
@property(nonatomic, assign) uint64_t characterEnsureCount;
@property(nonatomic, assign) uint64_t characterEnsureMicros;
@property(nonatomic, assign) uint64_t boundingEnsureCount;
@property(nonatomic, assign) uint64_t boundingEnsureMicros;
@property(nonatomic, assign) uint64_t glyphIndexCount;
@property(nonatomic, assign) uint64_t glyphIndexMicros;
@property(nonatomic, assign) uint64_t lineFragmentCount;
@property(nonatomic, assign) uint64_t lineFragmentMicros;
@property(nonatomic, assign) uint64_t glyphLocationCount;
@property(nonatomic, assign) uint64_t glyphLocationMicros;
@property(nonatomic, assign) uint64_t positionProxyMicros;
@property(nonatomic, assign) uint64_t positionNoopWrites;
@property(nonatomic, assign) uint64_t positionChangedWrites;
@property(nonatomic, assign) uint64_t firstUnlaidBefore;
@property(nonatomic, assign) uint64_t firstUnlaidAfter;
@property(nonatomic, assign) uint64_t invalidatedLocation;
@property(nonatomic, assign) uint64_t invalidatedLength;
@property(nonatomic, assign) uint64_t revealMicros;
@property(nonatomic, assign) uint64_t candidateMicros;
@property(nonatomic, assign) uint64_t positionFirstUnlaidBefore;
@property(nonatomic, assign) uint64_t positionFirstUnlaidAfter;
@property(nonatomic, assign) uint64_t positionChangedMask;
- (void)reset;
@end

@implementation CJGuiInternalComposableActiveLayoutTrace
- (instancetype)init {
    self = [super init];
    if (self) [self reset];
    return self;
}
- (void)reset {
    self.characterEnsureCount = 0; self.characterEnsureMicros = 0;
    self.boundingEnsureCount = 0; self.boundingEnsureMicros = 0;
    self.glyphIndexCount = 0; self.glyphIndexMicros = 0;
    self.lineFragmentCount = 0; self.lineFragmentMicros = 0;
    self.glyphLocationCount = 0; self.glyphLocationMicros = 0;
    self.positionProxyMicros = 0; self.positionNoopWrites = 0; self.positionChangedWrites = 0;
    self.firstUnlaidBefore = UINT64_MAX; self.firstUnlaidAfter = UINT64_MAX;
    self.invalidatedLocation = UINT64_MAX; self.invalidatedLength = 0;
    self.revealMicros = 0; self.candidateMicros = 0;
    self.positionFirstUnlaidBefore = UINT64_MAX; self.positionFirstUnlaidAfter = UINT64_MAX;
    self.positionChangedMask = 0;
}
@end

// This trace is intentionally scoped to one test-driven normal insertion.
// It records nested timing separately from the enclosing NSTextView call, so
// consumers do not add the fields together as an E2E duration.
@interface CJGuiInternalComposableInputCallbackTrace : NSObject
@property(nonatomic, assign) uint64_t superInsertMicros;
@property(nonatomic, assign) uint64_t modeChangeCount;
@property(nonatomic, assign) uint64_t modeChangeMicros;
@property(nonatomic, assign) uint64_t textCallbackCount;
@property(nonatomic, assign) uint64_t textCallbackMicros;
@property(nonatomic, assign) uint64_t selectionCallbackCount;
@property(nonatomic, assign) uint64_t pendingEditSelectionCount;
@property(nonatomic, assign) uint64_t selectionCallbackMicros;
@property(nonatomic, assign) uint64_t selectionRevealMicros;
@property(nonatomic, assign) uint64_t selectionQueueMicros;
@property(nonatomic, assign) uint64_t selectionAccessibilityMicros;
@property(nonatomic, assign) uint64_t refreshMicros;
@property(nonatomic, assign) uint64_t preparationMicros;
@property(nonatomic, assign) uint64_t wholeAttributeWriteCount;
@property(nonatomic, assign) uint64_t wholeAttributeCharacters;
@property(nonatomic, assign) uint64_t fallbackApplyCount;
@property(nonatomic, assign) uint64_t fallbackCharacters;
@property(nonatomic, assign) uint64_t fallbackMicros;
@property(nonatomic, assign) uint64_t decorationsMicros;
@property(nonatomic, assign) uint64_t keyConstructionMicros;
- (void)reset;
@end

@implementation CJGuiInternalComposableInputCallbackTrace
- (instancetype)init {
    self = [super init];
    if (self) [self reset];
    return self;
}
- (void)reset {
    self.superInsertMicros = 0; self.modeChangeCount = 0; self.modeChangeMicros = 0;
    self.textCallbackCount = 0; self.textCallbackMicros = 0;
    self.selectionCallbackCount = 0; self.pendingEditSelectionCount = 0;
    self.selectionCallbackMicros = 0; self.selectionRevealMicros = 0;
    self.selectionQueueMicros = 0; self.selectionAccessibilityMicros = 0;
    self.refreshMicros = 0; self.preparationMicros = 0;
    self.wholeAttributeWriteCount = 0; self.wholeAttributeCharacters = 0;
    self.fallbackApplyCount = 0; self.fallbackCharacters = 0; self.fallbackMicros = 0;
    self.decorationsMicros = 0; self.keyConstructionMicros = 0;
}
@end
#endif

@interface CJGuiInternalComposableSceneOverlay : NSView <NSTextViewDelegate, NSDraggingSource, NSDraggingDestination>
// B4(2026-09-26, Sol consult): YES when the ACTIVE composable target is a
// read-only interactive presentation TEXT node (the visual body). The hidden
// input proxy forwards navigation keys to the overlay only in that state, so
// arrow/delete keys move the PRODUCT caret instead of the proxy's invisible
// selection; the source editor's own proxy navigation is unchanged.
- (BOOL)composableActiveNodeIsPresentationText;
// The point of the mouse-down currently being routed, so a queued interaction
// that reports a pointer position can be stamped with it.
@property(nonatomic, assign) NSPoint lastPointerDownPoint;
@property(nonatomic, weak) CJGuiInternalSession *session;
@property(nonatomic, strong) NSArray<CJGuiInternalComposableSceneNode *> *nodes;
// M8/IME: the caret the PRODUCT drew, declared explicitly (never inferred from a run style).
// The input client answers IME geometry from this rect instead of falling back to the hidden
// proxy, which is the only fallback a self-drawn editor would otherwise have.
@property(nonatomic) int64_t declaredInputCaretNodeId;
@property(nonatomic) NSRect declaredInputCaretRect;
@property(nonatomic) BOOL hasDeclaredInputCaret;
@property(nonatomic, strong) NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *accessibilityActions;
@property(nonatomic, strong) NSMutableDictionary<NSString *, CJGuiInternalComposableAccessibilityAction *> *accessibilityActionsByIdentity;
@property(nonatomic, strong) NSArray<CJGuiInternalComposableAccessibilityAction *> *accessibilityRoots;
// Owns the mouse-moved tracking area. A tracking area delivers `mouseMoved:`
// directly to its owner, independent of hitTest/first-responder state, which
// the window-level `acceptsMouseMovedEvents` opt-in alone did not achieve for
// this self-drawn overlay (hover was only ever observed on the mouseDown path).
@property(nonatomic, strong) NSTrackingArea *hoverTrackingArea;
@property(nonatomic, strong) NSTextView *inputProxy;
@property(nonatomic, strong) NSScrollView *inputScrollProxy;
@property(nonatomic, assign) NSInteger activeNodeIndex;
@property(nonatomic, assign) uint64_t activeNodeId;
@property(nonatomic, assign) uint64_t activeProjectionVersion;
@property(nonatomic, assign) int64_t activeNodeResourceId;
@property(nonatomic, assign) uint32_t activeNodeKind;
@property(nonatomic, assign) BOOL applyingProjection;
// True only while a kind-52 TERMINAL phase (commit/cancel) is inside its
// synchronous `super` call. The platform's own text callbacks fire with
// `hasMarkedText` already false at that point, so without this flag the commit
// would ALSO enqueue an ordinary TEXT_CHANGED/RANGE_CHANGED pair and the
// session-owned node would have a second, out-of-session writer.
@property(nonatomic, assign) BOOL compositionTerminalInFlight;
// The ACTIVE node is the node the window declared through
// `set_composable_owned_text_session`, so its composition belongs to the
// window-owned session.
- (BOOL)activeNodeOwnsCompositionSession;
#ifdef CJGUI_INTERNAL_TESTING
// Test-only receipt counter. It establishes whether an NSEvent dispatched by
// NSApplication reached this production responder; it is never projected or
// exposed through the framework API.
@property(nonatomic, assign) uint64_t testKeyDownReceiptCount;
// This is set only around the production source-drag handoff so the native
// trace can distinguish an actual AppKit session from a press cancellation.
@property(nonatomic, assign) BOOL testDataTransferDragSessionBegan;
#endif
// The platform text service remains the input/IME adapter. Its visible
// viewport is never the document surface; this offset belongs to the
// self-drawn composable multiline viewport.
@property(nonatomic, assign) CGFloat multilineScrollOffset;
@property(nonatomic, strong) NSMutableDictionary<NSString *, NSNumber *> *multilineScrollOffsets;
@property(nonatomic, strong) NSMutableDictionary<NSString *, CJGuiInternalComposableMultilineLayoutCacheEntry *> *multilineLayoutCache;
@property(nonatomic, strong) NSMutableArray<NSString *> *multilineLayoutCacheOrder;
@property(nonatomic, assign) uint32_t multilineLayoutCacheHighWater;
@property(nonatomic, copy) NSString *activeTextLayoutSignature;
// Attribute-affecting fields only (font/color). A width-only change must not
// rewrite attributes over the whole document.
@property(nonatomic, copy) NSString *activeTextAttributeSignature;
// Projection-phase wall times (setNodesFromProjection), cumulative. Callers
// take deltas around a declared sample; they never merge with stage/commit.
@property(nonatomic, assign) uint64_t testProjectionAccessibilityMicros;
@property(nonatomic, assign) uint64_t testProjectionInputMicros;
@property(nonatomic, assign) uint64_t testProjectionRefreshMicros;
// Fallback fonts are a derived presentation property of the one active
// TextKit graph. They are prepared after an edit transaction, never by a
// second text owner or during the synchronous text-change callback.
@property(nonatomic, assign) BOOL activeTextFallbackRunsDirty;
@property(nonatomic, assign) BOOL activeTextFallbackNeedsFullRefresh;
@property(nonatomic, assign) BOOL activeTextFallbackHasDirtyRange;
@property(nonatomic, assign) NSRange activeTextFallbackDirtyRange;
@property(nonatomic, assign) BOOL activeTextFallbackHasPendingEdit;
@property(nonatomic, assign) NSRange activeTextFallbackPendingEditRange;
// Last NSTextView range mutation observed for the active proxy. It is the
// framework's own edit delta: `shouldChangeTextInRange` fills it and
// `textDidChange` forwards it as a range event. It is cleared as soon as it is
// consumed and whenever the projection or focus changes.
@property(nonatomic, copy) NSString *activeTextRangeEditReplacement;
@property(nonatomic, assign) NSRange activeTextRangeEditRange;
@property(nonatomic, assign) BOOL activeTextRangeEditPending;
// The projection the unacknowledged edit was made against. The edit only outranks
// the owner's text while that projection is still current; once a newer projection
// arrives the owner's value already carries (or deliberately drops) the edit.
@property(nonatomic, assign) uint64_t activeTextRangeEditProjectionVersion;
// The same outranking rule, but durable across the delta's single use. The delta
// above is consumed by `textDidChange` whether or not it can be delivered, so it
// cannot also guard the proxy text: a query path (scroll, candidate rect, hit
// test) that runs after the enqueue and before the owner republishes still sees
// the stale committed value and writes it over the edit the human just made.
// Measured: `editWithAppKit(LONG_MULTILINE_TEXT)` left 319 units in the proxy,
// then the multiline-scroll test repositioned the same node at the same
// projection and reverted it to the 37-unit baseline, so the visible glyph range
// came from two lines instead of sixteen and the scroll assertion failed.
@property(nonatomic, assign) BOOL activeLocalEditAwaitingOwner;
@property(nonatomic, assign) uint64_t activeLocalEditProjectionVersion;
// This is the style-owned base, never a font inferred from the currently
// selected fallback run in NSTextStorage.
@property(nonatomic, strong) NSFont *activeTextBaseFont;
// The last base font deliberately assigned through NSTextView.font.  It is
// distinct from `activeTextBaseFont`: preparation may already have adopted a
// new node style before positioning decides whether the global setter is
// required.  Never derive this from NSTextView.font, whose getter can expose
// a character's fallback run.
@property(nonatomic, strong) NSFont *inputProxyAssignedBaseFont;
@property(nonatomic, assign) BOOL activeTextResourcePreparationScheduled;
@property(nonatomic, copy) NSString *activeTextTextureRetryKey;
@property(nonatomic, assign) uint32_t activeTextTextureRetryCount;
@property(nonatomic, assign) BOOL activeTextTexturePreparationFailed;
// Test-only cause supplied by the production event boundary immediately
// before an active refresh. It is consumed only when a key change causes real
// raster/upload; otherwise the bucket stays explicit unknown.
#ifdef CJGUI_INTERNAL_TESTING
@property(nonatomic, assign) uint32_t testActiveTextWorkReason;
#endif
// These values intentionally describe separate facts.  A text mutation can
// need visible glyphs while the total document height is unknown; neither
// fact authorizes a full-container layout on the next selection callback.
@property(nonatomic, assign) BOOL activeTextLayoutNeedsVisibleGlyphs;
@property(nonatomic, assign) BOOL activeTextHasExactContentHeight;
@property(nonatomic, assign) CGFloat activeTextKnownContentHeight;
@property(nonatomic, assign) BOOL activeTextHasScrollAnchor;
@property(nonatomic, assign) NSUInteger activeTextScrollAnchorCharacter;
@property(nonatomic, assign) CGFloat activeTextScrollAnchorViewportOffset;
// Increment only when the visible body may have changed. A local edit beyond
