// The focused input's staged static candidate is never drawn this turn: the
// active TextKit refresh that the same commit triggers owns the visible body.
// Only a real text input is continued by that refresh. A focused tab title or
// button has no caret, selection or marked text, so its static candidate must
// still rasterize here — skipping it left a same-commit label or textColor
// change rendering the previous texture.
static BOOL CjguiStagedNodeIsFocusedInput(CJGuiInternalSession *ctx,
    CJGuiInternalComposableSceneNode *node) {
    if (!ctx || !node) return NO;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    if (!overlay || !CjguiComposableNodeIsTextInput(overlay.activeNodeKind)) return NO;
    return node.node.nodeId == overlay.activeNodeId &&
        node.node.resourceId == overlay.activeNodeResourceId &&
        node.node.nodeKind == overlay.activeNodeKind;
}

@implementation CJGuiInternalComposableAccessibilityAction
- (instancetype)initWithOverlay:(CJGuiInternalComposableSceneOverlay *)overlay node:(CJGuiInternalComposableSceneNode *)node {
    self = [super init]; if (!self) return nil; self.overlay = overlay; self.node = node;
    self.semanticChildren = [NSMutableArray array];
    return self;
}
- (CJGuiInternalComposableSceneNode *)currentNode {
    // Once published, a retired wrapper may never acquire a later node that
    // happens to reuse its numeric id or projection version.
    if (self.identityKey.length > 0 && self.overlay.accessibilityActionsByIdentity[self.identityKey] != self) return nil;
    return [self.overlay accessibilityLiveNodeForNode:self.node];
}
- (id)accessibilityParent { return [self currentNode] ? (self.semanticParent ?: self.overlay) : nil; }
- (NSArray<id> *)accessibilityChildren { return [self currentNode] ? [self.semanticChildren copy] : @[]; }
- (id)accessibilityWindow { return [self currentNode] ? self.overlay.window : nil; }
- (id)accessibilityTopLevelUIElement { return [self currentNode] ? self.overlay.window : nil; }
- (BOOL)isAccessibilityElement { return [self currentNode] != nil; }
- (NSAccessibilityRole)accessibilityRole {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    uint32_t kind = node ? node.node.nodeKind : 0;
    uint32_t semanticRole = node ? node.node.semanticRole : 0;
    if (semanticRole == 1) return NSAccessibilityTabGroupRole;
    if (semanticRole == 2) return NSAccessibilityRadioButtonRole;
    if (semanticRole == 3) return NSAccessibilityScrollAreaRole;
    if (semanticRole == 4) return NSAccessibilityOutlineRole;
    if (semanticRole == 5) return NSAccessibilityRowRole;
    if (semanticRole == 6) return NSAccessibilityButtonRole;
    if (semanticRole == 7) return NSAccessibilityCheckBoxRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT) return NSAccessibilityStaticTextRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC) return NSAccessibilityButtonRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return NSAccessibilityCheckBoxRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS) return NSAccessibilityTabGroupRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) return NSAccessibilityRadioButtonRole;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA) return NSAccessibilityScrollAreaRole;
    if (CjguiComposableNodeIsTextInput(kind)) return NSAccessibilityTextFieldRole;
    return NSAccessibilityGroupRole;
}
- (NSString *)accessibilityLabel {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node ? (node.semanticLabel.length > 0 ? node.semanticLabel :
        (node.label.length > 0 ? node.label : node.value)) : @"";
}
- (NSString *)accessibilityTitle {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.label.length > 0 ? node.label : nil;
}
- (NSString *)accessibilityIdentifier {
    // The accepted public semantic identity is the exact address of this
    // instance. A driver or assistant targets one node by its stable id instead
    // of guessing from the rendered caption, which two rows may share.
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node.semanticId.length > 0 ? node.semanticId : nil;
}
- (id)accessibilityValue {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return nil;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        return @([node.value isEqualToString:@"true"]);
    }
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) {
        return @(node.node.tabSelected != 0);
    }
    return CjguiComposableNodeIsTextInput(node.node.nodeKind) ? [self.overlay accessibilityCurrentTextForNode:node] : node.value;
}
- (BOOL)isAccessibilitySelected {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    if (node.node.semanticRole == 5) return (node.node.semanticState & 1u) != 0;
    return node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE && node.node.tabSelected != 0;
}
- (BOOL)isAccessibilityDisclosed {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.node.semanticRole == 5 && (node.node.semanticState & 4u) != 0;
}
- (BOOL)isAccessibilityExpanded { return [self isAccessibilityDisclosed]; }
- (NSInteger)accessibilityDisclosureLevel {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && node.node.semanticRole == 5 ? (NSInteger)node.node.semanticLevel : 0;
}
- (BOOL)accessibilityIsAttributeSettable:(NSAccessibilityAttributeName)attribute {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    uint32_t kind = node.node.nodeKind;
    if ([attribute isEqualToString:NSAccessibilitySelectedTextRangeAttribute]) {
        return CjguiComposableNodeIsTextInput(kind) && node.node.isInteractive != 0;
    }
    if (![attribute isEqualToString:NSAccessibilityValueAttribute]) return NO;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return [self.overlay accessibilityNodeIsActionable:node];
    return CjguiComposableNodeIsTextInput(kind) && [self.overlay accessibilityNodeIsActionable:node];
}

- (BOOL)accessibilityIsEnabled {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NO;
    if (node.node.semanticRole == 5) return (node.node.semanticState & 8u) == 0;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) return node.node.isInteractive != 0;
    return (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TABS ||
        node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA ||
        node.node.semanticRole == 4 || node.node.isInteractive != 0);
}
- (BOOL)isAccessibilityEnabled {
    // AppKit accessibility clients query this legacy selector when deciding
    // whether an exposed self-drawn element can receive an action.
    return [self accessibilityIsEnabled];
}
- (BOOL)accessibilityIsEditable {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node && CjguiComposableNodeIsTextInput(node.node.nodeKind) && [self.overlay accessibilityNodeIsActionable:node];
}
- (NSArray<NSAccessibilityActionName> *)accessibilityActionNames {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node || ![self.overlay accessibilityNodeIsActionable:node]) return @[];
    uint32_t kind = node.node.nodeKind;
    // A tab TITLE and a vector graphic are pressable exactly like a button: the
    // press enqueues the generic ACTIVATE interaction and Cangjie resolves it
    // against the accepted state. An action that can be performed but is never
    // ADVERTISED is invisible to an accessibility client, so this list and
    // accessibilityPerformPressForNode must agree.
    return (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC ||
            kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE)
        ? @[ NSAccessibilityPressAction ] : @[];
}
- (NSRect)accessibilityFrame {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    return node ? NSAccessibilityFrameInView(self.overlay,
        NSIntersectionRect(CjguiComposableRect(node, self.overlay), CjguiComposableClipBounds(node))) : NSZeroRect;
}
- (NSPoint)accessibilityPosition { return [self accessibilityFrame].origin; }
- (NSSize)accessibilitySize { return [self accessibilityFrame].size; }
- (NSRect)accessibilityFrameInParentSpace {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node) return NSZeroRect;
    NSRect rect = NSIntersectionRect(CjguiComposableRect(node, self.overlay), CjguiComposableClipBounds(node));
    CJGuiInternalComposableSceneNode *parent = [self.semanticParent currentNode];
    if (parent) {
        NSRect parentRect = CjguiComposableRect(parent, self.overlay);
        rect.origin.x -= parentRect.origin.x;
        rect.origin.y -= parentRect.origin.y;
    }
    return rect;
}
- (BOOL)accessibilityFocused { return [self.overlay accessibilityNodeIsFocused:[self currentNode]]; }
- (void)accessibilitySetFocused:(BOOL)focused {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!focused || !node) return;
    if (CjguiComposableNodeIsTextInput(node.node.nodeKind) && node.node.isInteractive != 0) {
        [self.overlay focusNode:node enqueue:YES];
    } else if ([self.overlay accessibilityNodeIsActionable:node]) {
        [self.overlay focusNode:node enqueue:YES];
    }
}
- (NSRange)accessibilitySelectedTextRange {
    CJGuiInternalComposableSceneNode *node = [self currentNode];
    if (!node || !CjguiComposableNodeIsTextInput(node.node.nodeKind) || ![self.overlay accessibilityNodeIsFocused:node]) {
        return NSMakeRange(NSNotFound, 0);
    }
    return self.overlay.inputProxy.selectedRange;
}
- (void)accessibilitySetSelectedTextRange:(NSValue *)value {
    if (![value respondsToSelector:@selector(rangeValue)]) return;
    [self.overlay accessibilitySetSelectedTextRange:value.rangeValue forNode:[self currentNode]];
}
- (NSString *)accessibilitySelectedText {
    NSString *text = [self accessibilityValue];
    NSRange selection = [self accessibilitySelectedTextRange];
    if (!text || selection.location == NSNotFound || NSMaxRange(selection) > text.length) return @"";
    return [text substringWithRange:selection];
}
- (NSRange)accessibilityVisibleCharacterRange {
    NSString *text = [self accessibilityValue];
    return NSMakeRange(0, text.length);
}
- (NSInteger)accessibilityNumberOfCharacters { return [[self accessibilityValue] length]; }
- (BOOL)accessibilityPerformPress { return [self.overlay accessibilityPerformPressForNode:[self currentNode]]; }
- (void)accessibilityPerformAction:(NSAccessibilityActionName)action {
    if ([action isEqualToString:NSAccessibilityPressAction]) [self accessibilityPerformPress];
}
- (void)accessibilitySetValue:(id)value {
    [self.overlay accessibilitySetValue:value forNode:[self currentNode]];
}
@end

// Resolve the CURRENT scene index of one node identity. The composition
// snapshot stores identity, never an index: a reconfigured scene may reorder
// nodes, and a stale index would silently address a different control.
static NSInteger CjguiIndexOfComposableNodeIdentity(CJGuiInternalComposableSceneOverlay *overlay,
                                                    uint64_t nodeId, int64_t resourceId,
                                                    uint32_t nodeKind) {
    if (!overlay || nodeId == 0) return NSNotFound;
    for (CJGuiInternalComposableSceneNode *node in overlay.nodes) {
        if (node.node.nodeId == nodeId && node.node.resourceId == resourceId &&
            node.node.nodeKind == nodeKind) {
            return node.index;
        }
    }
    return NSNotFound;
}

// Emit one phase of the composition this proxy currently tracks. Ranges are
// forwarded in the proxy's own UTF-16 coordinates; NSNotFound is converted
// explicitly (never through NSUInteger overflow). A missing node identity means
// the intent has no target left and must not be re-addressed by index.
static BOOL CjguiEmitProxyCompositionPhase(CJGuiInternalComposableInputProxy *proxy, uint32_t phase,
                                           NSString *text, NSRange inner, NSRange replacement,
                                           NSRange marked) {
    CJGuiInternalComposableSceneOverlay *overlay = proxy.composableOverlay;
    CJGuiInternalSession *session = overlay.session;
    if (!session) return NO;
    NSInteger nodeIndex = CjguiIndexOfComposableNodeIdentity(overlay, proxy.compositionSessionNodeId,
                                                             proxy.compositionSessionResourceId,
                                                             proxy.compositionSessionNodeKind);
    if (nodeIndex == NSNotFound || nodeIndex < 0) return NO;
    return CjguiEnqueueCompositionPhase(session, phase, (uint32_t)nodeIndex, text, inner,
        replacement.location == NSNotFound ? -1 : (int64_t)replacement.location,
        replacement.location == NSNotFound ? 0 : (int64_t)replacement.length,
        marked.location == NSNotFound ? -1 : (int64_t)marked.location,
        marked.location == NSNotFound ? 0 : (int64_t)marked.length,
        proxy.compositionSessionId, proxy.compositionSessionEpoch);
}

static BOOL CjguiAccessibilitySameText(NSString *left, NSString *right) {
    return left == right || (left != nil && right != nil && [left isEqualToString:right]);
}

@implementation CJGuiInternalComposableSceneOverlay
- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session {
    self = [super initWithFrame:frame]; if (!self) return nil;
    self.session = session; self.nodes = @[]; self.accessibilityActions = [NSMutableArray array];
    self.accessibilityActionsByIdentity = [NSMutableDictionary dictionary];
    self.accessibilityRoots = @[];
    self.activeNodeIndex = NSNotFound; self.activeNodeId = 0; self.activeProjectionVersion = 0;
    self.activeNodeResourceId = -1; self.activeNodeKind = 0; self.wantsLayer = NO;
    self.multilineScrollOffset = 0.0;
    self.multilineScrollOffsets = [NSMutableDictionary dictionary];
    self.multilineLayoutCache = [NSMutableDictionary dictionary];
    self.multilineLayoutCacheOrder = [NSMutableArray array];
    self.multilineLayoutCacheHighWater = 0;
    self.activeTextLayoutSignature = nil;
    self.activeTextLayoutNeedsVisibleGlyphs = NO;
    self.activeTextHasExactContentHeight = NO;
    self.activeTextKnownContentHeight = 0.0;
    self.activeTextHasScrollAnchor = NO;
    self.activeTextScrollAnchorCharacter = 0;
    self.activeTextScrollAnchorViewportOffset = 0.0;
    self.activeTextBodyGeneration = 0;
    self.activeTextAttributedGeneration = 0;
    self.activeTextRunsSignature = nil;
    self.activeTextVisibleParagraphEnd = 0;
    self.activeTextRangeLayoutCount = 0;
    self.activeTextFullLayoutCount = 0;
    self.multilineLayoutBuildCount = 0;
    self.multilineLayoutFullLayoutCount = 0;
    self.draggingNodeId = 0; self.draggingNodeResourceId = -1;
    self.draggingProjectionVersion = 0; self.draggingAnchor = 0;
    self.dataTransferHoverNodeId = 0; self.dataTransferHoverResourceId = -1;
    self.dataTransferHoverNodeKind = 0;
    self.lastDrawnProjectionVersion = 0;
    self.inputScrollProxy = [[NSScrollView alloc] initWithFrame:NSMakeRect(-2, -2, 1, 1)];
    self.inputScrollProxy.drawsBackground = NO;
    self.inputScrollProxy.borderType = NSNoBorder;
    self.inputScrollProxy.hasVerticalScroller = YES;
    self.inputScrollProxy.autohidesScrollers = YES;
    self.inputScrollProxy.alphaValue = 0.01;
    self.inputProxy = [[CJGuiInternalComposableInputProxy alloc] initWithFrame:NSMakeRect(0, 0, 1, 1)];
    ((CJGuiInternalComposableInputProxy *)self.inputProxy).composableOverlay = self;
    self.inputProxy.delegate = self; self.inputProxy.drawsBackground = NO; self.inputProxy.alphaValue = 0.01;
    self.inputProxy.editable = YES; self.inputProxy.selectable = YES; self.inputProxy.richText = NO; self.inputProxy.usesRuler = NO;
    // This is a plain-text IME adapter, not a document editor surface. The
    // system's whole-document spelling/grammar/substitution passes add work
    // to every insert without contributing to the rendered projection or its
    // owner. Keep NSTextInputClient itself intact for marked text and
    // candidates, but disable those independent analysis features.
    self.inputProxy.continuousSpellCheckingEnabled = NO;
    self.inputProxy.grammarCheckingEnabled = NO;
    // Undo/redo belongs to the Cangjie document owner. Retaining an AppKit
    // undo snapshot as well duplicates a long plain-text document for every
    // keystroke and creates a second, non-authoritative history.
    self.inputProxy.allowsUndo = NO;
    self.inputProxy.automaticSpellingCorrectionEnabled = NO;
    self.inputProxy.automaticTextReplacementEnabled = NO;
    self.inputProxy.automaticQuoteSubstitutionEnabled = NO;
    self.inputProxy.automaticDashSubstitutionEnabled = NO;
    self.inputProxy.textContainer.widthTracksTextView = YES;
    self.inputProxy.textContainer.lineFragmentPadding = 0.0;
    self.inputProxy.textContainer.maximumNumberOfLines = 1;
    self.inputProxy.textContainer.lineBreakMode = NSLineBreakByTruncatingTail;
    self.inputProxy.layoutManager.allowsNonContiguousLayout = YES;
    // The hidden input adapter has no pixels of its own to keep warm. Its
    // layout is requested explicitly by the composable viewport, candidate
    // and scroll paths; background realization here only competes with the
    // next input transaction.
    self.inputProxy.layoutManager.backgroundLayoutEnabled = NO;
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace = [[CJGuiInternalComposableActiveLayoutTrace alloc] init];
    self.testInputCallbackTrace = [[CJGuiInternalComposableInputCallbackTrace alloc] init];
    self.testUsesBoundedInputLayout = NO;
#endif
    self.inputScrollProxy.documentView = self.inputProxy;
    [self addSubview:self.inputScrollProxy];
    // `setNodesFromProjection` replaces this conservative initial type set
    // with the formats declared by the accepted Cangjie scene.
    [self registerForDraggedTypes:@[NSPasteboardTypeString]];
    return self;
}
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }
- (NSAccessibilityRole)accessibilityRole { return NSAccessibilityGroupRole; }
- (NSString *)accessibilityLabel { return @"CJGUI composable scene"; }
- (NSArray<id> *)accessibilityChildren { return self.accessibilityRoots; }
- (void)reconcileAccessibilityActions {
    // One accepted projection owns one bounded AX graph. The map is per
    // window/overlay, so a wrapper cannot cross windows. Its binding key
    // includes the Cangjie operation target; a rebind retires the old object
    // even if nodeId/resourceId/kind happen to remain equal.
    NSMutableDictionary<NSString *, CJGuiInternalComposableAccessibilityAction *> *nextByKey =
        [NSMutableDictionary dictionary];
    NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *next = [NSMutableArray array];
    NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *roots = [NSMutableArray array];
    NSMutableArray<NSNumber *> *ends = [NSMutableArray array];
    NSMutableArray<id> *ancestors = [NSMutableArray array];
    NSMutableDictionary<NSString *, CJGuiInternalComposableAccessibilityAction *> *rows = [NSMutableDictionary dictionary];
    NSMutableArray<CJGuiInternalComposableAccessibilityAction *> *valueChanges = [NSMutableArray array];
    BOOL structureChanged = self.accessibilityActions.count == 0 && self.nodes.count > 0;
    NSUInteger index = 0;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        while (ends.count > 0 && index >= ends.lastObject.unsignedIntegerValue) {
            [ends removeLastObject]; [ancestors removeLastObject];
        }
        CJGuiInternalComposableAccessibilityAction *parent = nil;
        if (ancestors.count > 0 && ancestors.lastObject != [NSNull null]) parent = ancestors.lastObject;
        BOOL visible = node.node.width > 0 && node.node.height > 0 &&
            node.node.clipWidth > 0 && node.node.clipHeight > 0;
        if (visible && CjguiComposableNodeIsAccessibilityElement(node)) {
            NSString *binding = node.semanticBindingKey.length > 0 ? node.semanticBindingKey : (node.semanticId ?: @"");
            NSString *key = [NSString stringWithFormat:@"%llu/%lld/%u/%lld/%lu:%@",
                (unsigned long long)node.node.nodeId, (long long)node.node.resourceId,
                node.node.nodeKind, (long long)node.node.semanticIncarnation,
                (unsigned long)binding.length, binding];
            // Duplicate identities in one malformed projection must not alias
            // one mutable AX object. The second remains a separate ephemeral
            // element and cannot retarget an earlier reference.
            if (nextByKey[key]) key = [key stringByAppendingFormat:@"#%lu", (unsigned long)index];
            CJGuiInternalComposableAccessibilityAction *action = self.accessibilityActionsByIdentity[key];
            if (!action) {
                action = [[CJGuiInternalComposableAccessibilityAction alloc] initWithOverlay:self node:node];
                structureChanged = YES;
            } else {
                CjguiInternalRendererComposableNode prior = action.node.node;
                CjguiInternalRendererComposableNode current = node.node;
                if (prior.x != current.x || prior.y != current.y || prior.width != current.width ||
                    prior.height != current.height || prior.clipX != current.clipX || prior.clipY != current.clipY ||
                    prior.clipWidth != current.clipWidth || prior.clipHeight != current.clipHeight ||
                    !CjguiAccessibilitySameText(action.node.semanticRowKey, node.semanticRowKey) ||
                    !CjguiAccessibilitySameText(action.node.semanticParentRowKey, node.semanticParentRowKey)) {
                    structureChanged = YES;
                }
                if (!CjguiAccessibilitySameText(action.node.value, node.value) ||
                    !CjguiAccessibilitySameText(action.node.label, node.label) ||
                    !CjguiAccessibilitySameText(action.node.semanticLabel, node.semanticLabel) ||
                    prior.semanticState != current.semanticState || prior.semanticLevel != current.semanticLevel ||
                    prior.tabSelected != current.tabSelected || prior.isReadOnly != current.isReadOnly ||
                    prior.isInteractive != current.isInteractive) {
                    [valueChanges addObject:action];
                }
            }
            action.identityKey = key;
            action.node = node;
            [action.semanticChildren removeAllObjects];
            // Tree row parent keys are logical, not layout indices. Missing
            // virtual ancestors remain under the outline until revealed.
            if (node.node.semanticRole == 5 && node.semanticParentRowKey.length > 0) {
                CJGuiInternalComposableAccessibilityAction *outline = nil;
                for (NSInteger depth = (NSInteger)ancestors.count - 1; depth >= 0; depth--) {
                    id candidate = ancestors[(NSUInteger)depth];
                    if (candidate != [NSNull null] &&
                        ((CJGuiInternalComposableAccessibilityAction *)candidate).node.node.semanticRole == 4) {
                        outline = candidate; break;
                    }
                }
                if (outline) {
                    NSString *parentKey = [NSString stringWithFormat:@"%@/%@", outline.identityKey, node.semanticParentRowKey];
                    parent = rows[parentKey] ?: outline;
                }
            }
            if (node.node.semanticRole == 5 && node.semanticRowKey.length > 0) {
                CJGuiInternalComposableAccessibilityAction *outline = nil;
                for (NSInteger depth = (NSInteger)ancestors.count - 1; depth >= 0; depth--) {
                    id candidate = ancestors[(NSUInteger)depth];
                    if (candidate != [NSNull null] &&
                        ((CJGuiInternalComposableAccessibilityAction *)candidate).node.node.semanticRole == 4) {
                        outline = candidate; break;
                    }
                }
                if (outline) rows[[NSString stringWithFormat:@"%@/%@", outline.identityKey, node.semanticRowKey]] = action;
            }
            if (action.semanticParent != parent) structureChanged = YES;
            action.semanticParent = parent;
            if (parent) [parent.semanticChildren addObject:action]; else [roots addObject:action];
            nextByKey[key] = action;
            [next addObject:action];
        }
        NSUInteger subtree = node.node.effectGroupSubtreeCount;
        if (subtree > 1 && subtree <= self.nodes.count - index) {
            [ends addObject:@(index + subtree)];
            [ancestors addObject:next.count > 0 && next.lastObject.node == node ? next.lastObject :
                (parent ?: (id)[NSNull null])];
        }
        index++;
    }
    if (next.count != self.accessibilityActions.count) structureChanged = YES;
    if (!structureChanged) {
        for (NSUInteger i = 0; i < next.count; i++) {
            if (next[i] != self.accessibilityActions[i]) { structureChanged = YES; break; }
        }
    }
    for (CJGuiInternalComposableAccessibilityAction *old in self.accessibilityActions) {
        if (nextByKey[old.identityKey] != old) {
            old.node = nil;
            old.semanticParent = nil;
            [old.semanticChildren removeAllObjects];
        }
    }
    self.accessibilityActionsByIdentity = nextByKey;
    self.accessibilityActions = next;
    self.accessibilityRoots = roots;
    if (structureChanged) {
        NSAccessibilityPostNotification(self, NSAccessibilityLayoutChangedNotification);
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableAccessibilityNotificationCount += 1;
#endif
    }
    for (CJGuiInternalComposableAccessibilityAction *action in valueChanges) {
        NSAccessibilityPostNotification(action, NSAccessibilityValueChangedNotification);
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableAccessibilityNotificationCount += 1;
#endif
    }
}
- (CJGuiInternalComposableSceneNode *)accessibilityLiveNodeForNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node) return nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == node.node.nodeId && candidate.node.resourceId == node.node.resourceId &&
            candidate.node.nodeKind == node.node.nodeKind &&
            candidate.node.projectionVersion == node.node.projectionVersion &&
            CjguiComposableNodeIsAccessibilityElement(candidate)) {
            return candidate;
        }
    }
    return nil;
}
- (BOOL)accessibilityNodeIsActionable:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live || live.node.isInteractive == 0 || live.node.isReadOnly != 0) return NO;
    uint32_t kind = live.node.nodeKind;
    // A tab TITLE is actionable exactly like a button: AXPress enqueues the same
    // generic ACTIVATE interaction, and Cangjie decides whether it selects a page.
    // Leaving it out here made the action invisible to an accessibility client
    // even though accessibilityPerformPressForNode already accepted the kind.
    if (kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE &&
        !CjguiComposableNodeIsTextInput(kind)) return NO;
    // Modal focus is established by the Cangjie layer owner when its scene is
    // committed. An AX action may not bypass that visible input boundary to
    // operate a covered base-layer control.
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (active && active.node.inputScope != 0 && live.node.inputScope != active.node.inputScope) return NO;
    return YES;
}
- (BOOL)accessibilityNodeIsFocused:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live) return NO;
    BOOL isActive = live.node.nodeId == self.activeNodeId && live.node.resourceId == self.activeNodeResourceId &&
        live.node.nodeKind == self.activeNodeKind && live.node.projectionVersion == self.activeProjectionVersion;
    if (!isActive) return NO;
    if (CjguiComposableNodeIsTextInput(live.node.nodeKind)) return self.window.firstResponder == self.inputProxy;
    return self.window.firstResponder == self;
}
- (NSString *)accessibilityCurrentTextForNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live) return @"";
    if ([self accessibilityNodeIsFocused:live]) return self.inputProxy.string ?: @"";
    return live.value ?: @"";
}
- (BOOL)accessibilityPerformPressForNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live || ![self accessibilityNodeIsActionable:live]) return NO;
    uint32_t kind = live.node.nodeKind;
    // A tab TITLE is actionable exactly like a button: the press enqueues the
    // generic ACTIVATE interaction and Cangjie decides whether it selects a page.
    if (kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT &&
        kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) return NO;
    [self focusNode:live enqueue:YES];
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        NSString *next = [live.value isEqualToString:@"true"] ? @"false" : @"true";
        return CjguiEnqueueComposableInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED, live.index, next, NSMakeRange(0, 0));
    }
    return CjguiEnqueueComposableInteraction(self.session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, live.index, @"", NSMakeRange(0, 0));
}
- (void)accessibilitySetValue:(id)value forNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live || ![self accessibilityNodeIsActionable:live]) return;
    if (live.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        BOOL enabled = [value respondsToSelector:@selector(boolValue)] ? [value boolValue] : [value isEqual:@"true"];
        (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED,
                                                live.index, enabled ? @"true" : @"false", NSMakeRange(0, 0));
    } else if (CjguiComposableNodeIsTextInput(live.node.nodeKind) && [value isKindOfClass:[NSString class]]) {
        [self setText:(NSString *)value forNode:live];
        [self postAccessibilityValueChangedForNode:live];
        [self postAccessibilitySelectionChangedForNode:live];
    }
}
- (void)accessibilitySetSelectedTextRange:(NSRange)range forNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableSceneNode *live = [self accessibilityLiveNodeForNode:node];
    if (!live || !CjguiComposableNodeIsTextInput(live.node.nodeKind) || live.node.isInteractive == 0) return;
    [self focusNode:live enqueue:NO];
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, range.location, NSMaxRange(range));
    [self refreshGpuTextForActiveInput];
    (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
                                            live.index, @"", self.inputProxy.selectedRange);
    [self postAccessibilitySelectionChangedForNode:live];
}
- (CJGuiInternalComposableAccessibilityAction *)accessibilityActionForNode:(CJGuiInternalComposableSceneNode *)node {
    for (CJGuiInternalComposableAccessibilityAction *action in self.accessibilityActions) {
        if ([self accessibilityLiveNodeForNode:action.node] == node) return action;
    }
    return nil;
}
- (void)postAccessibilityValueChangedForNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableAccessibilityAction *action = [self accessibilityActionForNode:node];
    if (action) {
        NSAccessibilityPostNotification(action, NSAccessibilityValueChangedNotification);
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableAccessibilityNotificationCount += 1;
#endif
    }
}
- (void)postAccessibilitySelectionChangedForNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableAccessibilityAction *action = [self accessibilityActionForNode:node];
    if (action) {
        NSAccessibilityPostNotification(action, NSAccessibilitySelectedTextChangedNotification);
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableAccessibilityNotificationCount += 1;
#endif
    }
}
- (void)postAccessibilityFocusChangedForNode:(CJGuiInternalComposableSceneNode *)node {
    CJGuiInternalComposableAccessibilityAction *action = [self accessibilityActionForNode:node];
    if (action) NSAccessibilityPostNotification(action, NSAccessibilityFocusedUIElementChangedNotification);
    else NSAccessibilityPostNotification(self, NSAccessibilityFocusedUIElementChangedNotification);
#ifdef CJGUI_INTERNAL_TESTING
    self.session.testComposableAccessibilityNotificationCount += 1;
#endif
}
- (NSString *)multilineLayoutIdentityForNode:(CJGuiInternalComposableSceneNode *)node {
    return [NSString stringWithFormat:@"%llu:%lld:%u",
            node.node.nodeId, node.node.resourceId, node.node.nodeKind];
}
- (NSString *)multilineLayoutCacheKeyForNode:(CJGuiInternalComposableSceneNode *)node
                                        value:(NSString *)value
                                 contentWidth:(CGFloat)contentWidth {
    CjguiInternalRendererComposableNode style = node.node;
    (void)value;
    // Cache ownership follows the stable component identity and layout
    // inputs, not a complete text snapshot. A new projection value is
    // applied to the retained NSTextStorage below; including the full value
    // here used to retain a history of whole documents and rebuild TextKit on
    // every sparse external replacement.
    //
    // `textAlpha` is deliberately absent: it is the DYNAMIC paint multiplier
    // applied once at encode time (CjguiEncodeMetalTexture), never a glyph or
    // style-owned colour. Baking it into this key used to rebuild the retained
    // TextKit graph on every opacity frame even though no glyph pixel changes.
    return [NSString stringWithFormat:@"%@:%.3f:%.3f:%u:%u:%.3f:%.3f:%.3f",
            [self multilineLayoutIdentityForNode:node],
            contentWidth, style.fontSize, style.fontWeight, style.fontFamily,
            style.textRed, style.textGreen, style.textBlue];
}
- (NSString *)activeTextLayoutSignatureForNode:(CJGuiInternalComposableSceneNode *)node contentWidth:(CGFloat)contentWidth {
    CjguiInternalRendererComposableNode value = node.node;
    // Glyph layout depends on the static colour channels (a real colour change
    // is a different glyph appearance) but NOT on `textAlpha`. The dynamic
    // alpha is a per-draw multiplier on the cached texture, so including it
    // here forced a full re-layout/re-raster/re-upload for a pure opacity
    // animation and, worse, baked the multiplier into the glyph pixels once
    // more (double multiplication at encode time).
    return [NSString stringWithFormat:@"%llu:%lld:%u:%.3f:%.3f:%u:%u:%.3f:%.3f:%.3f",
            value.nodeId, value.resourceId, value.nodeKind, contentWidth, value.fontSize,
            value.fontWeight, value.fontFamily, value.textRed, value.textGreen, value.textBlue];
}
- (NSString *)activeTextAttributeSignatureForNode:(CJGuiInternalComposableSceneNode *)node {
    CjguiInternalRendererComposableNode value = node.node;
    // Attribute-affecting fields only (font and static colour). The dynamic
    // `textAlpha` never enters this signature, so a pure opacity change cannot
    // trigger a whole-document `setAttributes:` rewrite. Style runs keep their
    // own style-owned colour/alpha and are tracked by their runs signature.
    return [NSString stringWithFormat:@"%llu:%lld:%u:%.3f:%u:%u:%.3f:%.3f:%.3f",
            value.nodeId, value.resourceId, value.nodeKind, value.fontSize,
            value.fontWeight, value.fontFamily, value.textRed, value.textGreen, value.textBlue];
}
- (void)touchMultilineLayoutCacheKey:(NSString *)key {
    [self.multilineLayoutCacheOrder removeObject:key];
    [self.multilineLayoutCacheOrder addObject:key];
}
- (CJGuiInternalComposableMultilineLayoutCacheEntry *)cachedMultilineLayoutForNode:(CJGuiInternalComposableSceneNode *)node
                                                                               value:(NSString *)value
                                                                          attributes:(NSDictionary *)attributes
                                                                        contentWidth:(CGFloat)contentWidth {
    NSString *key = [self multilineLayoutCacheKeyForNode:node value:value contentWidth:contentWidth];
    CJGuiInternalComposableMultilineLayoutCacheEntry *entry = self.multilineLayoutCache[key];
    if (entry && fabs(entry.contentWidth - contentWidth) < 0.01) {
        if (![entry.value isEqualToString:value]) {
            // The node is inactive, so it has no native text-service state
            // to reconcile. Preserve its TextKit object graph and invalidate
            // only its storage content; visible glyphs are realized lazily by
            // draw, while an explicit focus/scroll query establishes an exact
            // document extent through the active path.
            [entry.storage beginEditing];
            [entry.storage replaceCharactersInRange:NSMakeRange(0, entry.storage.length) withString:value];
            if (value.length > 0) [entry.storage setAttributes:attributes range:NSMakeRange(0, value.length)];
            [entry.storage endEditing];
            entry.value = value;
        }
        [self touchMultilineLayoutCacheKey:key];
        return entry;
    }
    if (entry) {
        [self.multilineLayoutCache removeObjectForKey:key];
        [self.multilineLayoutCacheOrder removeObject:key];
    }
    while (self.multilineLayoutCacheOrder.count >= 16) {
        NSString *oldest = self.multilineLayoutCacheOrder.firstObject;
        [self.multilineLayoutCacheOrder removeObjectAtIndex:0];
        [self.multilineLayoutCache removeObjectForKey:oldest];
    }
    entry = [[CJGuiInternalComposableMultilineLayoutCacheEntry alloc] init];
    entry.value = value;
    entry.contentWidth = contentWidth;
    entry.storage = [[NSTextStorage alloc] initWithString:value attributes:attributes];
    entry.layoutManager = [[NSLayoutManager alloc] init];
    entry.layoutManager.allowsNonContiguousLayout = YES;
    entry.container = [[NSTextContainer alloc] initWithContainerSize:NSMakeSize(contentWidth, CGFLOAT_MAX)];
    entry.container.lineFragmentPadding = 0.0;
    [entry.layoutManager addTextContainer:entry.container];
    [entry.storage addLayoutManager:entry.layoutManager];
    [entry.layoutManager ensureLayoutForTextContainer:entry.container];
    entry.maximumScroll = MAX(0.0, [entry.layoutManager usedRectForTextContainer:entry.container].size.height);
    self.multilineLayoutBuildCount += 1;
    self.multilineLayoutFullLayoutCount += 1;
    self.multilineLayoutCache[key] = entry;
    [self touchMultilineLayoutCacheKey:key];
    self.multilineLayoutCacheHighWater = (uint32_t)MIN(MAX((NSUInteger)self.multilineLayoutCacheHighWater,
                                                            self.multilineLayoutCache.count), UINT32_MAX);
    return entry;
}
// Computes the single contiguous UTF-16 replacement span turning `baseline`
// into `replacement`, with both spans expanded to composed-sequence (grapheme)
// boundaries in their own string. Returns NO when the edit replaces the whole
// body (nothing to preserve) — the caller then keeps the full-replace path.
static BOOL CjguiExternalReplacementRange(NSString *baseline, NSString *replacement,
                                          NSRange *outRemoved, NSRange *outInserted) {
    NSUInteger oldLen = baseline.length, newLen = replacement.length;
    if (oldLen == 0 || newLen == 0) return NO;
    NSUInteger prefix = 0;
    NSUInteger maxPrefix = MIN(oldLen, newLen);
    while (prefix < maxPrefix &&
           [baseline characterAtIndex:prefix] == [replacement characterAtIndex:prefix]) prefix += 1;
    NSUInteger suffix = 0;
    NSUInteger maxSuffix = maxPrefix - prefix;
    while (suffix < maxSuffix &&
           [baseline characterAtIndex:oldLen - 1 - suffix] == [replacement characterAtIndex:newLen - 1 - suffix]) {
        suffix += 1;
    }
    NSUInteger removedStart = prefix, removedEnd = oldLen - suffix;
    // Expand the removed span to composed-sequence boundaries in the baseline:
    // a change inside one emoji/ZWJ cluster invalidates the whole cluster.
    if (removedStart < removedEnd && removedStart > 0) {
        removedStart = [baseline rangeOfComposedCharacterSequenceAtIndex:removedStart].location;
    }
    if (removedEnd > removedStart && removedEnd < oldLen) {
        removedEnd = NSMaxRange([baseline rangeOfComposedCharacterSequenceAtIndex:removedEnd - 1]);
    }
    // The prefix and suffix spans are identical in both strings, so the
    // expanded boundaries map 1:1 onto the replacement.
    NSUInteger insertedEnd = newLen - (oldLen - removedEnd);
    // Pure insertions (removed span empty) and pure deletions (inserted span
    // empty) are legitimate local edits; only a change of the WHOLE body has
    // nothing to preserve.
    if (removedEnd < removedStart || insertedEnd < removedStart) return NO;
    // A span touching more than half the old body gains nothing from a local
    // replace; the full-replace path stays the legal fallback.
    if (removedEnd - removedStart > oldLen / 2) return NO;
    if (outRemoved) *outRemoved = NSMakeRange(removedStart, removedEnd - removedStart);
    if (outInserted) *outInserted = NSMakeRange(removedStart, insertedEnd - removedStart);
    return YES;
}
// Map an old UTF-16 endpoint into the replacement. A pure insertion retains
// the existing before-insertion affinity at its boundary; a removed endpoint
// lands at the new tail, while the old tail and later positions shift by the
// edit delta. The caller clamps and snaps the resulting selection to clusters.
static NSUInteger CjguiMapCharacterAfterReplacement(NSUInteger position, NSRange removed,
                                                      NSUInteger insertedLength) {
    NSUInteger oldEnd = NSMaxRange(removed);
    NSUInteger newEnd = removed.location + insertedLength;
    if (position < removed.location || (removed.length == 0 && position == removed.location)) return position;
    if (position < oldEnd) return newEnd;
    if (insertedLength >= removed.length) return position + insertedLength - removed.length;
    return position - MIN(position, removed.length - insertedLength);
}
static BOOL CjguiPlainAsciiEditSpan(NSString *value, NSRange range) {
    if (!value || NSMaxRange(range) > value.length) return NO;
    for (NSUInteger index = range.location; index < NSMaxRange(range); index++) {
        unichar character = [value characterAtIndex:index];
        if (character < 0x20 || character > 0x7e) return NO;
    }
    return YES;
}
static BOOL CjguiPlainAsciiParagraph(NSString *value, NSRange range) {
    if (!value || NSMaxRange(range) > value.length || range.length == 0) return NO;
    NSRange content = range;
    if ([value characterAtIndex:NSMaxRange(range) - 1] == '\n') content.length -= 1;
    return CjguiPlainAsciiEditSpan(value, content);
}
- (void)setNodesFromProjection:(NSArray<CJGuiInternalComposableSceneNode *> *)nodes {
    self.activeTextDirtyVisibleRectValid = NO;
    BOOL permitsLocalReplacement = YES;
#ifdef CJGUI_INTERNAL_TESTING
    permitsLocalReplacement = !self.testForceFullProjectionReplacementOnce;
    self.testForceFullProjectionReplacementOnce = NO;
#endif
#ifdef CJGUI_INTERNAL_TESTING
    // Honest attribution for the active refresh this projection triggers: a
    // geometry/clip change or an external value replacement names the reason
    // instead of letting the work fall into Unknown.
    BOOL projectionExternalContentChanged = NO;
    BOOL projectionGeometryChanged = NO;
#endif
    CJGuiInternalComposableSceneNode *previousActive = nil;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == self.activeNodeId && node.node.resourceId == self.activeNodeResourceId &&
            node.node.nodeKind == self.activeNodeKind) {
            previousActive = node; break;
        }
    }
    NSArray<CJGuiInternalComposableSceneNode *> *nextNodes = [nodes copy] ?: @[];
    self.nodes = nextNodes;
    // AppKit needs the concrete type list up front, while Cangjie owns which
    // stable node may accept it. Replacing this list at the same committed
    // scene boundary prevents a retired target from accepting a later drop.
    [self unregisterDraggedTypes];
    NSMutableArray<NSPasteboardType> *dragTypes = [NSMutableArray array];
    for (CJGuiInternalComposableDataTransferItem *item in self.session.composableDataTransferItems) {
        if (item.item.role != CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET) continue;
        NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
        if (type && ![dragTypes containsObject:type]) [dragTypes addObject:type];
    }
    if (dragTypes.count == 0) [dragTypes addObject:NSPasteboardTypeString];
    [self registerForDraggedTypes:dragTypes];
    if (CjguiDataTransferTraceEnabled()) {
        NSRect frame = self.window ? self.window.frame : NSZeroRect;
        NSLog(@"cjgui: transfer target registration window=%ld frame=%.1f,%.1f,%.1f,%.1f types=%@ scene=%llu",
              (long)(self.window ? self.window.windowNumber : 0), frame.origin.x, frame.origin.y, frame.size.width,
              frame.size.height, dragTypes, (unsigned long long)self.session.composableSceneVersion);
    }
    // A replacement projection may delete, disable or rebind the captured
    // target. Native then releases platform routing immediately; Cangjie
    // reconciles and emits the owner-visible cancel from its retained stable
    // capture record, so no raw native object crosses that boundary.
    if (self.pointerCaptureActive && ![self capturedPointerNode]) {
        [self cancelPointerCapture];
    }
    if (self.hoveredNodeId != 0 && ![self hoveredPressableNode]) {
        self.hoveredNodeId = 0; self.hoveredResourceId = -1; self.hoveredNodeKind = 0;
    }
    if (self.pressedNodeId != 0 && ![self pressedPressableNode]) {
        [self clearPressRouting];
    }
    if (self.dataTransferHoverNodeId != 0) {
        CJGuiInternalComposableSceneNode *hover = nil;
        for (CJGuiInternalComposableSceneNode *node in self.nodes) {
            if (node.node.nodeId == self.dataTransferHoverNodeId &&
                node.node.resourceId == self.dataTransferHoverResourceId &&
                node.node.nodeKind == self.dataTransferHoverNodeKind) {
                hover = node;
                break;
            }
        }
        if (!hover || ![self dataTransferItemForNode:hover role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET]) {
            [self clearDataTransferHoverAtPoint:NSZeroPoint];
        }
    }
    // Scroll offsets are local interaction state. Once a multiline identity
    // leaves the projection it must not keep a stale entry alive, nor be
    // available to a later component that merely reuses its node id.
    NSMutableSet<NSString *> *liveViewportKeys = [NSMutableSet set];
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            [liveViewportKeys addObject:[self multilineViewportKeyForNode:node]];
        }
    }
    for (NSString *key in [self.multilineScrollOffsets.allKeys copy]) {
        if (![liveViewportKeys containsObject:key]) [self.multilineScrollOffsets removeObjectForKey:key];
    }
    NSMutableSet<NSString *> *liveLayoutIdentities = [NSMutableSet set];
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            [liveLayoutIdentities addObject:[self multilineLayoutIdentityForNode:node]];
        }
    }
    for (NSString *key in [self.multilineLayoutCache.allKeys copy]) {
        BOOL hasLiveIdentity = NO;
        for (NSString *identity in liveLayoutIdentities) {
            if ([key hasPrefix:[NSString stringWithFormat:@"%@:", identity]]) {
                hasLiveIdentity = YES;
                break;
            }
        }
        if (!hasLiveIdentity) {
            [self.multilineLayoutCache removeObjectForKey:key];
            [self.multilineLayoutCacheOrder removeObject:key];
        }
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t axStarted = CjguiMonotonicMicros();
#endif
    [self reconcileAccessibilityActions];
#ifdef CJGUI_INTERNAL_TESTING
    self.testProjectionAccessibilityMicros += CjguiMonotonicMicros() - axStarted;
#endif
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t inputStarted = CjguiMonotonicMicros();
#endif
    if (self.activeNodeId != 0) {
        CJGuiInternalComposableSceneNode *replacement = nil;
        for (CJGuiInternalComposableSceneNode *node in self.nodes) {
            if (node.node.nodeId == self.activeNodeId && node.node.resourceId == self.activeNodeResourceId &&
                node.node.nodeKind == self.activeNodeKind) { replacement = node; break; }
        }
        // A disabled projection may retain its identity for layout purposes,
        // but it is no longer a valid TextKit target. Treat it as a focus
        // removal so pending marked text cannot later commit into a disabled
        // owner.
        if (replacement && replacement.node.isInteractive == 0) replacement = nil;
#ifdef CJGUI_INTERNAL_TESTING
        if (CjguiTestVerboseGlyphDiagnosticsEnabled()) {
            NSLog(@"cjgui: projection focus block activeNodeId=%llu replacement=%d kind=%u interactive=%d",
                  self.activeNodeId, replacement != nil,
                  replacement ? replacement.node.nodeKind : 0,
                  replacement ? replacement.node.isInteractive : 0);
        }
#endif
        if (replacement) {
            self.activeNodeIndex = replacement.index;
            self.activeProjectionVersion = replacement.node.projectionVersion;
            self.activeNodeResourceId = replacement.node.resourceId;
            self.activeNodeKind = replacement.node.nodeKind;
            // Resolve the "preserve the local text" transport hint BEFORE the proxy is
            // positioned. The hint travels as an in-band empty value (the window omits a
            // string it believes native already holds), so positioning first made the
            // proxy adopt "" and erase the edit the owner had just acknowledged; the
            // baseline recorded here was then read back from the emptied proxy, so
            // `hasLocalText` and `externalValueChanged` were computed from destroyed state.
            NSString *replacementValue = replacement.value ?: @"";
            BOOL preservesActiveLocalText = replacement.node.preservesActiveLocalText != 0 && previousActive &&
                previousActive.node.nodeId == replacement.node.nodeId &&
                previousActive.node.resourceId == replacement.node.resourceId &&
                previousActive.node.nodeKind == replacement.node.nodeKind &&
                replacement.node.nodeId == self.activeNodeId &&
                replacement.node.resourceId == self.activeNodeResourceId &&
                replacement.node.nodeKind == self.activeNodeKind &&
                CjguiComposableNodeIsTextInput(replacement.node.nodeKind);
            if (preservesActiveLocalText) {
                // Record the current proxy value as the new projection
                // baseline. The Cangjie owner already checked that its
                // accepted value matches this local event, so a later
                // external replacement still compares against this text.
                replacement.value = self.inputProxy.string ?: @"";
                replacementValue = replacement.value;
            }
            [self positionInputProxyForNode:replacement];
            if (CjguiComposableNodeIsTextInput(replacement.node.nodeKind)) {
                self.inputProxy.editable = replacement.node.isReadOnly == 0;
                self.inputProxy.selectable = YES;
                // A RETAINED active text node keeps its Cangjie identity across a
                // scene commit, so the library-side focus restore correctly treats
                // it as unchanged and does not re-hand the native responder. If
                // the projection pass handed firstResponder back to the view (or
                // to another control), a keyboard event after the commit would
                // reach nothing even though the owner still declares this node
                // active. Re-install the SAME input proxy for the node the owner
                // already focused; this adds no new focus state and only runs
                // while this window is key.
                if (self.window.isKeyWindow && self.window.firstResponder != self.inputProxy) {
                    (void)[self.window makeFirstResponder:self.inputProxy];
                }
            }
            self.multilineScrollOffset = [self multilineScrollOffsetForNode:replacement];
            BOOL hasLocalText = previousActive && ![self.inputProxy.string isEqualToString:previousActive.value ?: @""];
            BOOL externalValueChanged = !preservesActiveLocalText && previousActive &&
                ![replacementValue isEqualToString:previousActive.value ?: @""];
#ifdef CJGUI_INTERNAL_TESTING
            projectionExternalContentChanged = externalValueChanged;
            if (previousActive && (previousActive.node.width != replacement.node.width ||
                previousActive.node.height != replacement.node.height ||
                previousActive.node.x != replacement.node.x || previousActive.node.y != replacement.node.y ||
                previousActive.node.clipWidth != replacement.node.clipWidth ||
                previousActive.node.clipHeight != replacement.node.clipHeight)) {
                projectionGeometryChanged = YES;
            }
#endif
            BOOL compositionMustCancel = self.inputProxy.hasMarkedText &&
                (externalValueChanged || replacement.node.isReadOnly != 0 || replacement.node.isInteractive == 0);
            if (compositionMustCancel) {
                // Marked text belongs to the platform composition, not the
                // Cangjie domain. A newer value for this same identity is an
                // external replacement, so retaining the preedit would let
                // a later commit overwrite truth that the proxy no longer
                // represents. Cancel it under projection suppression, then
                // adopt the owner's value without enqueuing a human edit.
                self.applyingProjection = YES;
                [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
                self.inputProxy.string = replacementValue;
                NSUInteger start = MIN(self.inputProxy.selectedRange.location, self.inputProxy.string.length);
                NSUInteger end = MIN(NSMaxRange(self.inputProxy.selectedRange), self.inputProxy.string.length);
                self.inputProxy.selectedRange = NSMakeRange(start, end - start);
                self.applyingProjection = NO;
                self.activeTextLayoutSignature = nil;
                self.activeTextBodyGeneration += 1;
                self.activeTextVisibleParagraphEnd = 0;
                if (replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                    self.activeTextFallbackHasPendingEdit = NO;
                    [self markActiveTextFallbackRunsDirtyForWholeValue];
                }
                self.activeTextLayoutNeedsVisibleGlyphs = YES;
                self.activeTextHasExactContentHeight = NO;
                self.activeTextKnownContentHeight = 0.0;
                [self postAccessibilityValueChangedForNode:replacement];
                [self postAccessibilitySelectionChangedForNode:replacement];
            // A newer owner projection wins even when the proxy has an
            // unpumped local edit. That edit still carries the old rendered
            // version and will be rejected by Cangjie; retaining it here
            // would leave the platform adapter detached from authoritative
            // text until another edit happens.
            } else if ((externalValueChanged || !hasLocalText) && !self.inputProxy.hasMarkedText) {
#ifdef CJGUI_INTERNAL_TESTING
                if (CjguiTestVerboseGlyphDiagnosticsEnabled()) {
                    NSLog(@"cjgui: projection external branch prev=%d extChanged=%d hasLocal=%d marked=%d",
                          previousActive != nil, externalValueChanged, hasLocalText,
                          self.inputProxy.hasMarkedText);
                }
#endif
                BOOL textChanged = ![self.inputProxy.string isEqualToString:replacementValue];
                // A local modification keeps the unchanged span's attributes
                // and incremental layout: only a contiguous, cluster-aligned
                // minority span of the confirmed baseline is replaced. Same
                // identity is guaranteed by this branch; font style must not
                // have changed, or the whole body legitimately re-derives.
                BOOL styleCompatible = previousActive &&
                    previousActive.node.fontSize == replacement.node.fontSize &&
                    previousActive.node.fontWeight == replacement.node.fontWeight &&
                    previousActive.node.fontFamily == replacement.node.fontFamily;
                if (styleCompatible && replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                    NSString *attributes = [self activeTextAttributeSignatureForNode:replacement];
                    styleCompatible = [attributes isEqualToString:self.activeTextAttributeSignature];
                }
                NSRange removed = NSMakeRange(0, 0), inserted = NSMakeRange(0, 0);
                BOOL localApplied = NO;
                if (textChanged && styleCompatible && permitsLocalReplacement &&
                    CjguiExternalReplacementRange(self.inputProxy.string, replacementValue,
                                                  &removed, &inserted)) {
                    BOOL preservesVisibleBody = replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
                        self.activeTextVisibleParagraphEnd > 0 &&
                        self.activeTextVisibleParagraphEnd < self.inputProxy.string.length &&
                        removed.location >= self.activeTextVisibleParagraphEnd &&
                        (!self.activeTextHasScrollAnchor || self.activeTextScrollAnchorCharacter < removed.location);
                    if (preservesVisibleBody) {
                        NSRect content = NSInsetRect(CjguiComposableRect(replacement, self), 7.0, 6.0);
                        NSString *signature = [self activeTextLayoutSignatureForNode:replacement contentWidth:NSWidth(content)];
                        preservesVisibleBody = [signature isEqualToString:self.activeTextLayoutSignature];
                    }
                    NSTextStorage *storage = self.inputProxy.textStorage;
                    NSString *oldValue = self.inputProxy.string ?: @"";
                    NSString *insertedText = [replacementValue substringWithRange:inserted];
                    BOOL mayReuseUnaffectedTiles = !preservesVisibleBody &&
                        replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
                        !self.activeTextTexturePreparationFailed &&
                        previousActive.textTileTextures.count > 1 &&
                        previousActive.node.x == replacement.node.x && previousActive.node.y == replacement.node.y &&
                        previousActive.node.width == replacement.node.width &&
                        previousActive.node.height == replacement.node.height &&
                        previousActive.node.clipX == replacement.node.clipX &&
                        previousActive.node.clipY == replacement.node.clipY &&
                        previousActive.node.clipWidth == replacement.node.clipWidth &&
                        previousActive.node.clipHeight == replacement.node.clipHeight &&
                        removed.location < self.activeTextVisibleParagraphEnd &&
                        CjguiPlainAsciiEditSpan(oldValue, removed) &&
                        CjguiPlainAsciiEditSpan(replacementValue, inserted);
                    NSRange oldParagraph = NSMakeRange(0, 0);
                    NSRect oldParagraphRect = NSZeroRect;
                    if (mayReuseUnaffectedTiles && oldValue.length > 0) {
                        oldParagraph = [oldValue paragraphRangeForRange:NSMakeRange(MIN(removed.location, oldValue.length - 1), 0)];
                        mayReuseUnaffectedTiles = oldParagraph.length > 0 && oldParagraph.length <= 1024 &&
                            CjguiPlainAsciiParagraph(oldValue, oldParagraph);
                        if (mayReuseUnaffectedTiles) {
                            NSLayoutManager *layout = self.inputProxy.layoutManager;
                            [self ensureActiveLayoutForCharacterRange:oldParagraph layoutManager:layout];
                            NSRange glyphs = [layout glyphRangeForCharacterRange:oldParagraph actualCharacterRange:NULL];
                            oldParagraphRect = [layout boundingRectForGlyphRange:glyphs
                                                               inTextContainer:self.inputProxy.textContainer];
                            mayReuseUnaffectedTiles = !NSIsEmptyRect(oldParagraphRect);
                        }
                    }
                    NSRange oldSelection = self.inputProxy.selectedRange;
                    self.applyingProjection = YES;
                    [storage replaceCharactersInRange:removed withString:insertedText];
                    // NSTextStorage can inherit the adjacent fallback font at
                    // the splice. Seed only newly inserted text from the
                    // style-owned base; fallback resolution below handles the
                    // composed boundary and preserves all untouched runs.
                    if (inserted.length > 0 && replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                        [storage setAttributes:self.inputProxy.typingAttributes range:inserted];
                    }
                    NSUInteger newLocation = CjguiMapCharacterAfterReplacement(oldSelection.location, removed, inserted.length);
                    NSUInteger newEnd = CjguiMapCharacterAfterReplacement(NSMaxRange(oldSelection), removed, inserted.length);
                    NSUInteger limit = replacementValue.length;
                    newLocation = MIN(newLocation, limit);
                    newEnd = MIN(MAX(newEnd, newLocation), limit);
                    self.inputProxy.selectedRange = CjguiComposedSelection(replacementValue, newLocation, newEnd);
                    self.applyingProjection = NO;
                    if (mayReuseUnaffectedTiles && replacementValue.length > 0) {
                        NSRange newParagraph = [replacementValue paragraphRangeForRange:
                            NSMakeRange(MIN(inserted.location, replacementValue.length - 1), 0)];
                        if (newParagraph.length > 0 && newParagraph.length <= 1024 &&
                            CjguiPlainAsciiParagraph(replacementValue, newParagraph)) {
                            NSLayoutManager *layout = self.inputProxy.layoutManager;
                            [self ensureActiveLayoutForCharacterRange:newParagraph layoutManager:layout];
                            NSRange glyphs = [layout glyphRangeForCharacterRange:newParagraph actualCharacterRange:NULL];
                            NSRect newParagraphRect = [layout boundingRectForGlyphRange:glyphs
                                                                      inTextContainer:self.inputProxy.textContainer];
                            if (!NSIsEmptyRect(newParagraphRect) &&
                                fabs(NSMinY(oldParagraphRect) - NSMinY(newParagraphRect)) < 0.25 &&
                                fabs(NSHeight(oldParagraphRect) - NSHeight(newParagraphRect)) < 0.25) {
                                NSRect content = NSInsetRect(CjguiComposableRect(replacement, self), 7.0, 6.0);
                                CGFloat scroll = [self multilineScrollOffsetForNode:replacement];
                                NSRect affected = NSUnionRect(oldParagraphRect, newParagraphRect);
                                affected = NSInsetRect(affected, -4.0, -2.0);
                                self.activeTextDirtyVisibleRect = NSOffsetRect(affected, NSMinX(content),
                                                                             NSMinY(content) - scroll);
                                self.activeTextDirtyVisibleRectValid = YES;
                            }
                        }
                    }
                    if (!preservesVisibleBody) self.activeTextBodyGeneration += 1;
                    if (replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                        self.activeTextFallbackHasPendingEdit = NO;
                        [self remapActiveTextFallbackDirtyRangeForEditRange:removed replacementLength:inserted.length];
                        // Scoped invalidation: only the composed-aligned span
                        // the edit actually touched re-runs font fallback.
                        NSRange affected = [self fallbackAffectedRangeAfterEditAt:removed.location
                                                                replacementLength:inserted.length
                                                                            value:replacementValue];
                        [self markActiveTextFallbackRunsDirtyForRange:affected];
                        if (self.activeTextHasScrollAnchor) {
                            self.activeTextScrollAnchorCharacter = MIN(limit,
                                CjguiMapCharacterAfterReplacement(self.activeTextScrollAnchorCharacter, removed, inserted.length));
                        }
                    } else {
                        self.activeTextLayoutSignature = nil;
                    }
                    self.activeTextLayoutNeedsVisibleGlyphs = YES;
                    self.activeTextHasExactContentHeight = NO;
                    self.activeTextKnownContentHeight = 0.0;
                    localApplied = YES;
#ifdef CJGUI_INTERNAL_TESTING
                    if (CjguiTestVerboseGlyphDiagnosticsEnabled()) {
                        NSLog(@"cjgui: projection local replace removed=%@ inserted_len=%lu affected=[%@]",
                              NSStringFromRange(removed), (unsigned long)inserted.length,
                              NSStringFromRange(NSMakeRange(removed.location, inserted.length)));
                    }
#endif
                }
                if (!localApplied) {
                    self.applyingProjection = YES;
                    if (textChanged) self.inputProxy.string = replacementValue;
                    NSUInteger start = MIN(self.inputProxy.selectedRange.location, self.inputProxy.string.length);
                    NSUInteger end = MIN(NSMaxRange(self.inputProxy.selectedRange), self.inputProxy.string.length);
                    self.inputProxy.selectedRange = NSMakeRange(start, end - start);
                    self.applyingProjection = NO;
                    if (textChanged) {
                        self.activeTextLayoutSignature = nil;
                        self.activeTextBodyGeneration += 1;
                        self.activeTextVisibleParagraphEnd = 0;
                        if (replacement.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
                            self.activeTextFallbackHasPendingEdit = NO;
                            [self markActiveTextFallbackRunsDirtyForWholeValue];
                        }
                        self.activeTextLayoutNeedsVisibleGlyphs = YES;
                        self.activeTextHasExactContentHeight = NO;
                        self.activeTextKnownContentHeight = 0.0;
                    }
                }
                if (textChanged) {
                    [self postAccessibilityValueChangedForNode:replacement];
                    [self postAccessibilitySelectionChangedForNode:replacement];
                }
            }
        } else if (previousActive && !CjguiComposableNodeIsTextInput(previousActive.node.nodeKind) &&
                   [self survivingScrollScopeForRemovedNode:previousActive]) {
            // The focused non-text control (a tree/list row) left the projection
            // - for example a keyboard collapse removed exactly the focused row.
            // Re-anchor the native focus to the surviving list/scroll scope that
            // contained it instead of dropping every later key: the owner keeps
            // its own model focus, and without a native focus the very next
            // arrow key would be discarded before it reached that model.
            CJGuiInternalComposableSceneNode *scope = [self survivingScrollScopeForRemovedNode:previousActive];
            self.activeNodeIndex = scope.index;
            self.activeNodeId = scope.node.nodeId;
            self.activeNodeResourceId = scope.node.resourceId;
            self.activeNodeKind = scope.node.nodeKind;
            self.activeProjectionVersion = scope.node.projectionVersion;
            self.applyingProjection = YES;
            if (self.inputProxy.hasMarkedText) [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
            self.inputProxy.editable = NO;
            self.inputProxy.string = @""; self.inputProxy.selectedRange = NSMakeRange(0, 0);
            self.applyingProjection = NO;
            self.activeTextLayoutSignature = nil;
            self.activeTextFallbackRunsDirty = NO;
            self.activeTextFallbackNeedsFullRefresh = NO;
            self.activeTextFallbackHasDirtyRange = NO;
            self.activeTextFallbackHasPendingEdit = NO;
            self.activeTextBaseFont = nil;
            self.inputProxyAssignedBaseFont = nil;
            self.activeTextTextureRetryKey = nil;
            self.activeTextTextureRetryCount = 0;
            self.activeTextTexturePreparationFailed = NO;
            self.activeTextLayoutNeedsVisibleGlyphs = NO;
            self.activeTextHasExactContentHeight = NO;
            self.activeTextKnownContentHeight = 0.0;
        } else {
            self.activeNodeIndex = NSNotFound; self.activeNodeId = 0; self.activeProjectionVersion = 0;
            self.activeNodeResourceId = -1; self.activeNodeKind = 0;
            [self clearDraggingSelection];
            self.applyingProjection = YES;
            if (self.inputProxy.hasMarkedText) [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
            self.inputProxy.string = @""; self.inputProxy.selectedRange = NSMakeRange(0, 0);
            self.applyingProjection = NO;
            self.activeTextLayoutSignature = nil;
            self.activeTextFallbackRunsDirty = NO;
            self.activeTextFallbackNeedsFullRefresh = NO;
            self.activeTextFallbackHasDirtyRange = NO;
            self.activeTextFallbackHasPendingEdit = NO;
            self.activeTextBaseFont = nil;
            self.inputProxyAssignedBaseFont = nil;
            self.activeTextTextureRetryKey = nil;
            self.activeTextTextureRetryCount = 0;
            self.activeTextTexturePreparationFailed = NO;
            self.activeTextLayoutNeedsVisibleGlyphs = NO;
            self.activeTextHasExactContentHeight = NO;
            self.activeTextKnownContentHeight = 0.0;
            [self.window makeFirstResponder:nil];
            [self postAccessibilityFocusChangedForNode:nil];
        }
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.testProjectionInputMicros += CjguiMonotonicMicros() - inputStarted;
    // The projection reason must be set BEFORE the refresh consumes it: the
    // refresh's rasters call CjguiRecordTextWork with this reason, so setting
    // it only afterwards meant a projection-driven refresh was always
    // recorded as Unknown.
    if (self.testActiveTextWorkReason == CjguiInternalTextWorkReasonUnknown) {
        if (projectionGeometryChanged) {
            self.testActiveTextWorkReason = CjguiInternalTextWorkReasonProjectionGeometry;
        } else if (projectionExternalContentChanged) {
            self.testActiveTextWorkReason = CjguiInternalTextWorkReasonExternalProjectionContent;
        }
    }
    uint64_t refreshStarted = CjguiMonotonicMicros();
#endif
    [self refreshGpuTextForActiveInput];
#ifdef CJGUI_INTERNAL_TESTING
    self.testProjectionRefreshMicros += CjguiMonotonicMicros() - refreshStarted;
    // Scoped to the work interval: once the refresh consumed the reason, a
    // leftover projection reason must not attach to unrelated work later.
    if (self.testActiveTextWorkReason == CjguiInternalTextWorkReasonProjectionGeometry ||
        self.testActiveTextWorkReason == CjguiInternalTextWorkReasonExternalProjectionContent) {
        self.testActiveTextWorkReason = CjguiInternalTextWorkReasonUnknown;
    }
#endif
    [self setNeedsDisplay:YES];
}
// The surviving list/scroll scope that contained a node of the previous
// projection, or nil when nothing of that scope remains. Used to keep keyboard
// navigation alive when the focused row itself was removed by the same update.

- (CJGuiInternalComposableSceneNode *)survivingScrollScopeForRemovedNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node) return nil;
    NSRect rect = CjguiComposableRect(node, self);
    if (NSIsEmptyRect(rect)) return nil;
    return [self scrollNodeContainingPoint:NSMakePoint(NSMidX(rect), NSMidY(rect))];
}

- (CJGuiInternalComposableSceneNode *)nodeAtPoint:(NSPoint)point {
    // Prefer the INNERMOST interactive node under the point instead of the last one in node order. A
    // scroll area that CONTAINS interactive text is itself interactive and used to win this loop, so a
    // click on body text was routed to the container (measured 2026-09-25: the app received the event
    // with node 311 -- the visual scroll area -- and the caret never moved even though the text node was
    // interactive). The smallest containing rect is the innermost target; ties keep the previous
    // topmost preference, so existing single-node behaviour is unchanged.
    CJGuiInternalComposableSceneNode *best = nil;
    CGFloat bestArea = 0.0;
    for (CJGuiInternalComposableSceneNode *node in [self.nodes reverseObjectEnumerator]) {
        if (node.node.isInteractive && CjguiComposableNodeContainsPoint(node, point, self) &&
            CjguiPointInComposableNodeClip(point, node, self)) {
            NSRect nodeRect = CjguiComposableRect(node, self);
            // Topmost wins; a later (lower) node may take over ONLY when it lies strictly inside the current
            // best. Comparing AREA alone let a small sibling in a LOWER layer beat a large upper layer that
            // also contained the point, while containment still keeps the 2026-09-25 fix: the interactive text
            // node inside the scroll area still wins over the container.
            BOOL insideBest = NO;
            if (best != nil) {
                // A modal backdrop is an input shield for all lower layers.
                // The inner-node preference must not let a smaller base
                // control underneath it win a later iteration.
                if (best.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_LAYER_BACKDROP) continue;
                NSRect bestRect = CjguiComposableRect(best, self);
                insideBest = nodeRect.origin.x >= bestRect.origin.x && nodeRect.origin.y >= bestRect.origin.y &&
                    NSMaxX(nodeRect) <= NSMaxX(bestRect) && NSMaxY(nodeRect) <= NSMaxY(bestRect);
            }
            if (best == nil || insideBest) {
                best = node;
                bestArea = nodeRect.size.width * nodeRect.size.height;
            }
        }
    }
    return best;
}
- (BOOL)focusCommittedNodeId:(uint64_t)nodeId {
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == nodeId && node.node.isInteractive != 0 &&
            node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA) {
            [self focusNode:node enqueue:NO];
            return YES;
        }
    }
    return NO;
}
- (CJGuiInternalComposableSceneNode *)scrollNodeContainingPoint:(NSPoint)point {
    // A list row is normally painted above its scroll container.  Mouse
    // target lookup may therefore find the row, while scroll ownership still
    // belongs to the containing scroll region from the same scene snapshot.
    for (CJGuiInternalComposableSceneNode *node in [self.nodes reverseObjectEnumerator]) {
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SCROLL_AREA &&
            NSPointInRect(point, CjguiComposableRect(node, self)) &&
            CjguiPointInComposableNodeClip(point, node, self)) return node;
    }
    return nil;
}
- (void)routeScrollAtPoint:(NSPoint)point deltaY:(CGFloat)deltaY {
    if (deltaY == 0.0) return;
    CJGuiInternalComposableSceneNode *scrollNode = [self scrollNodeContainingPoint:point];
    if (scrollNode) {
        (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SCROLL,
                                                scrollNode.index, deltaY < 0.0 ? @"next" : @"previous", NSMakeRange(0, 0));
    }
}
- (void)prepareInactiveTextResourceForFocusChange:(CJGuiInternalComposableSceneNode *)node {
    if (!node || !CjguiComposableNodeIsTextInput(node.node.nodeKind)) return;
    CjguiClearComposableTextDecorations(node);
    NSString *displayText = CjguiComposableGpuTextValue(node);
    if (displayText.length == 0 || node.node.textAlpha <= 0.0) {
        node.textTexture = nil;
        node.textTileTextures = nil;
        node.textTileRects = nil;
        node.textTextureCacheKey = @"";
        node.textTextureByteCount = 0;
        node.textTextureRect = NSZeroRect;
        return;
    }
    CJGuiInternalMetalView *metalView = self.session.view;
    if (!metalView) return;
    CGFloat scale = [metalView currentBackingScale];
    scale = MAX(1.0, scale);
    // Focus is a visible-state boundary. Convert the old active resource to
    // its caret-free static form now, rather than charging that work to a
    // later owner acknowledgement for a different input.
    //
    // That conversion still REPLACES a scene-owned derived resource, so it
    // takes the same pre-raster admission the focused multiline path uses:
    // plan first, admit against the accepted-scene budget, reuse on a key
    // match, and keep the previous resource when admission or preparation
    // fails. The old texture remains a safe caret-free-enough fallback (the
    // decorations were cleared above and are separate geometry); it converges
    // to the exact static form on the next legal commit or retry instead of
    // ever pushing the scene past its resource cap.
    NSRect textureRect = CjguiComposableTextTextureRectForNode(node);
    if (NSIsEmptyRect(textureRect)) {
        // A fully clipped node cannot contribute pixels; drop the resource.
        CjguiReleaseComposableTextResource(node);
        return;
    }
    uint64_t plannedBytes = 0;
    NSArray<NSValue *> *tiles = CjguiPlanComposableTextTiles(textureRect, scale, &plannedBytes);
    if (tiles.count == 0 || plannedBytes == 0) {
        CjguiReleaseComposableTextResource(node);
        return;
    }
    NSString *key = CjguiComposableTextTextureKey(node, scale, scale, displayText, textureRect);
    if (key.length == 0) return;
    if ((node.textTexture || node.textTileTextures.count > 0) &&
        [node.textTextureCacheKey isEqualToString:key] &&
        node.textTextureByteCount == plannedBytes) {
        // The active resource already matches the exact static form.
        return;
    }
    if (!CjguiComposableTextTextureFitsSceneBudget(self.nodes, node, plannedBytes)) {
        // Over the accepted-scene cap: keep the previous resource and its
        // bytes. Refusing the conversion is the same bounded recovery the
        // focused paths use; it never installs a half state silently.
        return;
    }
    (void)CjguiComposableTextTexture(metalView, node, scale, scale, displayText
#ifdef CJGUI_INTERNAL_TESTING
                                      , CjguiInternalTextWorkReasonStaticCandidate
#endif
                                      );
}
- (void)focusNode:(CJGuiInternalComposableSceneNode *)node enqueue:(BOOL)enqueue {
    // A pending delta belongs to the previous focused editor only.
    self.activeTextRangeEditPending = NO;
    BOOL isSameNode = self.activeNodeId == node.node.nodeId && self.activeNodeResourceId == node.node.resourceId &&
        self.activeNodeKind == node.node.nodeKind;
    CJGuiInternalComposableSceneNode *previousActive = nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == self.activeNodeId && candidate.node.resourceId == self.activeNodeResourceId &&
            candidate.node.nodeKind == self.activeNodeKind) {
            previousActive = candidate;
            break;
        }
    }
    BOOL focusScopeChanged = !previousActive || previousActive.node.inputScope != node.node.inputScope;
    if (!isSameNode) {
        [self prepareInactiveTextResourceForFocusChange:previousActive];
    }
    uint32_t kind = node.node.nodeKind;
    // A PRESENTATION text node is also an input target. The product renders its document body as
    // presentation TEXT nodes, and those are exactly where the user types; excluding them meant a
    // click focused only the scene overlay, so the selected input method had no NSTextInputClient
    // to compose into (measured: firstResponder=CJGuiInternalComposableSceneOverlay while real
    // Pinyin key events arrived at the process and no composition ever started).
    BOOL isTextInput = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT;
    BOOL isMultiline = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT;
    self.activeNodeIndex = node.index; self.activeNodeId = node.node.nodeId; self.activeProjectionVersion = node.node.projectionVersion;
    self.activeNodeResourceId = node.node.resourceId; self.activeNodeKind = kind;
    // The AppKit menu is process-global but scope-dependent. A Cangjie layer
    // can move focus only after its scene commits, so refresh the projection
    // at that actual input-boundary transition; background windows never own
    // the current key menu.
    // Cmd-C/V reservation depends on whether the newly focused node is a
    // non-text transfer source/target, not only on its scope.  Rebuild on a
    // real node transition so AppKit never leaves a stale Edit equivalent
    // installed while focus moves between a button and a text proxy.
    if ((focusScopeChanged || !isSameNode) && self.session.window == NSApp.keyWindow) {
        CjguiRebuildComposableCommandMenuForKeyWindow();
    }
    if (!isTextInput) {
        if (self.inputProxy.hasMarkedText) {
            self.applyingProjection = YES;
            [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
            self.applyingProjection = NO;
        }
        [self clearDraggingSelection];
        [self.window makeFirstResponder:self];
        if (enqueue) (void)CjguiEnqueueComposableInteraction(self.session,
                                                              CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS,
                                                              node.index, @"", NSMakeRange(0, 0));
        [self postAccessibilityFocusChangedForNode:node];
        [self setNeedsDisplay:YES];
        return;
    }
    self.applyingProjection = YES;
    self.inputProxy.textContainer.maximumNumberOfLines = isMultiline ? 0 : 1;
    self.inputProxy.textContainer.lineBreakMode = isMultiline ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail;
    self.inputProxy.verticallyResizable = NO;
    self.inputProxy.horizontallyResizable = NO;
    self.inputProxy.editable = node.node.isReadOnly == 0;
    self.inputProxy.selectable = YES;
    // Never let AppKit's text/scroll controls become an independent visual
    // surface. They remain first-responder/IME adapters only; drawRect owns
    // both inactive and active document rows from the composable snapshot.
    self.inputScrollProxy.alphaValue = 0.01;
    self.inputProxy.alphaValue = 0.01;
    // The platform text view is a hidden first-responder/IME adapter whose
    // storage supplies glyph pixels for the derived textures. Its base colour
    // stays OPAQUE; `node.textAlpha` is the dynamic paint multiplier applied
    // once at encode time and must not be baked into the storage here.
    self.inputProxy.textColor = [NSColor colorWithSRGBRed:node.node.textRed
                                                    green:node.node.textGreen
                                                    blue:node.node.textBlue
                                                    alpha:1.0];
    if (!isSameNode) {
        if (self.inputProxy.hasMarkedText) [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
        self.inputProxy.string = node.value ?: @""; self.inputProxy.selectedRange = NSMakeRange(self.inputProxy.string.length, 0);
        // The awaited edit belonged to the editor being left; this node's own value is now
        // installed above, so the new focus starts from the projection's truth.
        self.activeLocalEditAwaitingOwner = NO;
        self.activeLocalEditProjectionVersion = 0;
        self.activeTextLayoutSignature = nil;
        self.activeTextRunsSignature = nil;
        self.activeTextBodyGeneration += 1;
        self.activeTextVisibleParagraphEnd = 0;
        self.activeTextFallbackHasPendingEdit = NO;
        self.activeTextBaseFont = nil;
        self.inputProxyAssignedBaseFont = nil;
        self.activeTextTextureRetryKey = nil;
        self.activeTextTextureRetryCount = 0;
        self.activeTextTexturePreparationFailed = NO;
        [self markActiveTextFallbackRunsDirtyForWholeValue];
        self.activeTextLayoutNeedsVisibleGlyphs = YES;
        self.activeTextHasExactContentHeight = NO;
        self.activeTextKnownContentHeight = 0.0;
    }
    self.multilineScrollOffset = [self multilineScrollOffsetForNode:node];
    [self positionInputProxyForNode:node];
    [self.window makeFirstResponder:self.inputProxy]; self.applyingProjection = NO;
    if (enqueue) (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_FOCUS, node.index, self.inputProxy.string, self.inputProxy.selectedRange);
    [self postAccessibilityFocusChangedForNode:node];
#ifdef CJGUI_INTERNAL_TESTING
    // A focus hand-off can change only caret/selection pixels. It is neither
    // content admission nor an unknown background refresh.
    self.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
#endif
    [self refreshGpuTextForActiveInput];
    [self setNeedsDisplay:YES];
}
- (NSString *)multilineViewportKeyForNode:(CJGuiInternalComposableSceneNode *)node {
    return [NSString stringWithFormat:@"%llu:%lld", node.node.nodeId, node.node.resourceId];
}
- (CGFloat)multilineScrollOffsetForNode:(CJGuiInternalComposableSceneNode *)node {
    NSNumber *value = self.multilineScrollOffsets[[self multilineViewportKeyForNode:node]];
    return value ? value.doubleValue : 0.0;
}
- (void)setMultilineScrollOffset:(CGFloat)offset forNode:(CJGuiInternalComposableSceneNode *)node {
    self.multilineScrollOffsets[[self multilineViewportKeyForNode:node]] = @(MAX(0.0, offset));
    if (node.node.nodeId == self.activeNodeId && node.node.resourceId == self.activeNodeResourceId &&
        node.node.nodeKind == self.activeNodeKind) {
        self.multilineScrollOffset = MAX(0.0, offset);
    }
}
- (void)ensureActiveLayoutForCharacterRange:(NSRange)range layoutManager:(NSLayoutManager *)layoutManager {
    if (!layoutManager || range.location == NSNotFound) return;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
    self.activeTextLayoutTrace.firstUnlaidBefore = (uint64_t)layoutManager.firstUnlaidCharacterIndex;
#endif
    [layoutManager ensureLayoutForCharacterRange:range];
    self.activeTextRangeLayoutCount += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.characterEnsureCount += 1;
    self.activeTextLayoutTrace.characterEnsureMicros += CjguiMonotonicMicros() - started;
    self.activeTextLayoutTrace.firstUnlaidAfter = (uint64_t)layoutManager.firstUnlaidCharacterIndex;
#endif
}
- (void)ensureActiveLayoutForBoundingRect:(NSRect)rect container:(NSTextContainer *)container layoutManager:(NSLayoutManager *)layoutManager {
    if (!layoutManager || !container || NSIsEmptyRect(rect)) return;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    [layoutManager ensureLayoutForBoundingRect:rect inTextContainer:container];
    self.activeTextRangeLayoutCount += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.boundingEnsureCount += 1;
    self.activeTextLayoutTrace.boundingEnsureMicros += CjguiMonotonicMicros() - started;
#endif
}
- (void)ensureActiveFullLayoutForContainer:(NSTextContainer *)container layoutManager:(NSLayoutManager *)layoutManager {
    if (!layoutManager || !container) return;
    [layoutManager ensureLayoutForTextContainer:container];
    self.activeTextFullLayoutCount += 1;
}
- (NSUInteger)activeGlyphIndexForCharacter:(NSUInteger)character layoutManager:(NSLayoutManager *)layoutManager {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    NSUInteger glyph = [layoutManager glyphIndexForCharacterAtIndex:character];
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.glyphIndexCount += 1;
    self.activeTextLayoutTrace.glyphIndexMicros += CjguiMonotonicMicros() - started;
#endif
    return glyph;
}
- (NSRect)activeLineFragmentForGlyph:(NSUInteger)glyph layoutManager:(NSLayoutManager *)layoutManager {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    NSRect line = [layoutManager lineFragmentRectForGlyphAtIndex:glyph effectiveRange:NULL];
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.lineFragmentCount += 1;
    self.activeTextLayoutTrace.lineFragmentMicros += CjguiMonotonicMicros() - started;
#endif
    return line;
}
- (NSPoint)activeGlyphLocation:(NSUInteger)glyph layoutManager:(NSLayoutManager *)layoutManager {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    NSPoint location = [layoutManager locationForGlyphAtIndex:glyph];
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.glyphLocationCount += 1;
    self.activeTextLayoutTrace.glyphLocationMicros += CjguiMonotonicMicros() - started;
#endif
    return location;
}
- (void)positionInputProxyForNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node) return;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    NSRect textRect = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    CGFloat width = MAX(1.0, NSWidth(textRect));
    CGFloat height = MAX(1.0, NSHeight(textRect));
    BOOL isMultiline = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
    NSRect proxyFrame = NSMakeRect(0, 0, width, height);
    NSSize containerSize = NSMakeSize(width, isMultiline ? CGFLOAT_MAX : height);
    NSFont *font = CjguiComposableFont(node);
    NSRect parkedProxyFrame = NSMakeRect(-2.0, -2.0, 1.0, 1.0);
    BOOL sameScrollFrame = NSEqualRects(self.inputScrollProxy.frame, parkedProxyFrame);
    BOOL sameMaximumLines = self.inputProxy.textContainer.maximumNumberOfLines == (isMultiline ? 0 : 1);
    BOOL sameLineBreak = self.inputProxy.textContainer.lineBreakMode == (isMultiline ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
    BOOL sameContainerSize = NSEqualSizes(self.inputProxy.textContainer.containerSize, containerSize);
    BOOL sameHeightTracks = self.inputProxy.textContainer.heightTracksTextView == !isMultiline;
    BOOL sameMinSize = NSEqualSizes(self.inputProxy.minSize, NSMakeSize(width, height));
    BOOL sameMaxSize = NSEqualSizes(self.inputProxy.maxSize, NSMakeSize(width, height));
    BOOL sameProxyFrame = NSEqualRects(self.inputProxy.frame, proxyFrame);
    BOOL sameFont = [self.inputProxy.font isEqual:font];
    // NSTextView's font getter can report the first character's resolved
    // fallback (for example PingFang) rather than the style base (system
    // font).  Once the active multiline document has established that base,
    // treating that expected getter difference as a reason to assign `font`
    // again replaces every per-character fallback run just after a local
    // owner acknowledgement.  Preserve those runs only when both the active
    // layout base and the last deliberately assigned proxy base match.  The
    // second condition keeps a real style change visible even if preparation
    // has already adopted its new active base; initial focus, a rebind, an
    // empty field, and a style change still take the normal assignment path.
    BOOL proxyBaseMatches = self.inputProxyAssignedBaseFont && [self.inputProxyAssignedBaseFont isEqual:font];
    BOOL preservesActiveMultilineFontRuns = isMultiline && self.inputProxy.textStorage.length > 0 &&
        self.activeTextBaseFont && [self.activeTextBaseFont isEqual:font] && proxyBaseMatches;
    BOOL needsFontAssignment = !sameFont && !preservesActiveMultilineFontRuns;
    if (isMultiline && !proxyBaseMatches) needsFontAssignment = YES;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t sameWrites = (sameScrollFrame ? 1 : 0) + (sameMaximumLines ? 1 : 0) +
        (sameLineBreak ? 1 : 0) + (sameContainerSize ? 1 : 0) + (sameHeightTracks ? 1 : 0) +
        (sameMinSize ? 1 : 0) + (sameMaxSize ? 1 : 0) + (sameProxyFrame ? 1 : 0) + (needsFontAssignment ? 0 : 1);
    uint64_t changedMask = (sameScrollFrame ? 0 : 1) | (sameMaximumLines ? 0 : 2) |
        (sameLineBreak ? 0 : 4) | (sameContainerSize ? 0 : 8) | (sameHeightTracks ? 0 : 16) |
        (sameMinSize ? 0 : 32) | (sameMaxSize ? 0 : 64) | (sameProxyFrame ? 0 : 128) | (needsFontAssignment ? 256 : 0);
    self.activeTextLayoutTrace.positionFirstUnlaidBefore = (uint64_t)self.inputProxy.layoutManager.firstUnlaidCharacterIndex;
#endif
    // Keep the input view attached (and therefore eligible for the macOS
    // text service) without laying it out as a second, visible editor.
    if (!sameScrollFrame) self.inputScrollProxy.frame = parkedProxyFrame;
    if (!sameMaximumLines) self.inputProxy.textContainer.maximumNumberOfLines = isMultiline ? 0 : 1;
    if (!sameLineBreak) self.inputProxy.textContainer.lineBreakMode = isMultiline ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail;
    if (!sameContainerSize) self.inputProxy.textContainer.containerSize = containerSize;
    if (!sameHeightTracks) self.inputProxy.textContainer.heightTracksTextView = !isMultiline;
    if (!sameMinSize) self.inputProxy.minSize = NSMakeSize(width, height);
    if (!sameMaxSize) self.inputProxy.maxSize = NSMakeSize(width, height);
    if (!sameProxyFrame) self.inputProxy.frame = proxyFrame;
    // Keep the client's TEXT in sync with the active node.
    //
    // Measured: in source mode the active client (the hidden proxy) reported proxyLen=0 and
    // selected=0+0 while the editor node held the document, so every IME offset the client
    // handed the product was meaningless and the resulting edit was (correctly) rejected as
    // `not_utf8_boundary`. Geometry alone is not an input context: the text and the selection
    // must be there too.
    //
    // An in-progress composition is NEVER overwritten: the marked text belongs to the IME
    // until it commits or cancels.
    //
    // Neither is an unacknowledged human keystroke. `shouldChangeTextInRange:` has already
    // replaced the proxy text by the time the selection notification reaches this method, so
    // writing `node.value` here erases the edit that the queued delta describes: the delta
    // then carries the caret of the *pre-edit* value and a second keystroke before the next
    // projection is captured in coordinates the owner never saw (measured: owner text `abYX`
    // for `ab` + X + Y).
    //
    // The skip is scoped to the projection the edit was made against, not to the flag alone:
    // a newer projection means the owner has already judged that keystroke, so its value is
    // the truth and must reach the proxy. Skipping whenever the flag was set stranded an empty
    // proxy forever when the only fill attempt happened inside the pending window (measured:
    // hidden text storage empty right after an acknowledged insert).
    //
    // `activeTextRangeEditPending` alone is not enough: it is single-use and already consumed by
    // the time a later query path repositions the same node, so the durable companion flag below
    // carries the same version-scoped rule until the owner republishes or focus moves.
    BOOL editOutranksProjection = (self.activeTextRangeEditPending &&
            node.node.projectionVersion == self.activeTextRangeEditProjectionVersion) ||
        (self.activeLocalEditAwaitingOwner &&
            node.node.projectionVersion == self.activeLocalEditProjectionVersion);
#ifdef CJGUI_INTERNAL_TESTING
    if (getenv("PHAROS_TRACE_PROXY_SYNC")) {
        fprintf(stderr, "PHAROS_PROXY_SYNC node=%llu marked=%d pending=%d capVer=%llu nodeVer=%llu "
                "skip=%d preserve=%d awaitOwner=%d ownerLen=%lu proxyLen=%lu\n",
                (unsigned long long)node.node.nodeId, (int)self.inputProxy.hasMarkedText,
                (int)self.activeTextRangeEditPending,
                (unsigned long long)self.activeTextRangeEditProjectionVersion,
                (unsigned long long)node.node.projectionVersion, (int)editOutranksProjection,
                (int)(node.node.preservesActiveLocalText != 0),
                (int)self.activeLocalEditAwaitingOwner,
                (unsigned long)(node.value ?: @"").length, (unsigned long)self.inputProxy.string.length);
    }
#endif
    if (!self.inputProxy.hasMarkedText && !editOutranksProjection) {
        NSString *nodeValue = node.value ?: @"";
        if (![self.inputProxy.string isEqualToString:nodeValue]) {
            self.inputProxy.string = nodeValue;
        }
        NSUInteger length = self.inputProxy.string ? self.inputProxy.string.length : 0;
        NSRange selection = self.inputProxy.selectedRange;
        if (selection.location == NSNotFound || selection.location > length) {
            self.inputProxy.selectedRange = NSMakeRange(length, 0);
        }
    }
    if (needsFontAssignment) {
        self.inputProxy.font = font;
        if (isMultiline) self.inputProxyAssignedBaseFont = font;
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.positionProxyMicros += CjguiMonotonicMicros() - started;
    self.activeTextLayoutTrace.positionNoopWrites += sameWrites;
    self.activeTextLayoutTrace.positionChangedWrites += 9 - sameWrites;
    self.activeTextLayoutTrace.positionFirstUnlaidAfter = (uint64_t)self.inputProxy.layoutManager.firstUnlaidCharacterIndex;
    self.activeTextLayoutTrace.positionChangedMask |= changedMask;
#endif
}
- (NSRect)candidateRectForCharacterRange:(NSRange)range actualRange:(NSRangePointer)actualRange {
    return [self candidateRectForCharacterRange:range actualRange:actualRange answered:NULL];
}

- (NSRect)candidateRectForCharacterRange:(NSRange)range actualRange:(NSRangePointer)actualRange answered:(BOOL *)answered {
    if (answered) *answered = NO;
    // The product declared a drawn caret: answer from it. This is the case a self-drawn
    // visual editor is in, where the focused node is a presentation TEXT node rather than a
    // text-input node.
    if (self.hasDeclaredInputCaret) {
        if (actualRange) *actualRange = NSMakeRange(0, 0);
        if (answered) *answered = YES;
        // `declaredInputCaretRect` is in the declaring node's own accepted-layout space, while
        // this method's contract is overlay scene space; add the node rect exactly as the
        // decoration pass does so both answers live in one coordinate system.
        NSRect declared = self.declaredInputCaretRect;
        for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
            if ((int64_t)candidate.node.nodeId != self.declaredInputCaretNodeId) continue;
            NSRect nodeRect = CjguiComposableRect(candidate, self);
            declared = NSMakeRect(NSMinX(nodeRect) + NSMinX(declared), NSMinY(nodeRect) + NSMinY(declared),
                                  MAX(NSWidth(declared), 1.5), NSHeight(declared));
            break;
        }
#ifdef CJGUI_INTERNAL_TESTING
        if (getenv("PHAROS_TRACE_CANDIDATE_RECT")) {
            fprintf(stderr, "PHAROS_CANDIDATE_RECT_DECLARED scene=%.1f,%.1f,%.1f,%.1f\n",
                    NSMinX(declared), NSMinY(declared), NSWidth(declared), NSHeight(declared));
        }
#endif
        return declared;
    }
    CJGuiInternalComposableSceneNode *node = [self activeFocusableNode];
    uint32_t kind = node ? node.node.nodeKind : 0;
    // A PRESENTATION text node is also an input target. The product renders its document body as
    // presentation TEXT nodes, and those are exactly where the user types; excluding them meant a
    // click focused only the scene overlay, so the selected input method had no NSTextInputClient
    // to compose into (measured: firstResponder=CJGuiInternalComposableSceneOverlay while real
    // Pinyin key events arrived at the process and no composition ever started).
    BOOL isTextInput = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT;
    if (!node || !isTextInput || !self.window) {
#ifdef CJGUI_INTERNAL_TESTING
        if (getenv("PHAROS_TRACE_CANDIDATE_RECT")) {
            fprintf(stderr, "PHAROS_CANDIDATE_RECT_UNANSWERED node=%p kind=%u window=%p declaredCaret=%d\n",
                    (__bridge void *)node, kind, (__bridge void *)self.window, (int)self.hasDeclaredInputCaret);
        }
#endif
        return NSZeroRect;
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    [self positionInputProxyForNode:node];
    NSLayoutManager *layoutManager = self.inputProxy.layoutManager;
    NSTextContainer *container = self.inputProxy.textContainer;
    NSString *text = self.inputProxy.string ?: @"";
    NSUInteger length = text.length;
    NSUInteger location = MIN(range.location, length);
    NSUInteger requestedEnd = MIN(NSMaxRange(range), length);
    if (actualRange) *actualRange = NSMakeRange(location, requestedEnd - location);
    if (answered) *answered = YES;
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        // An IME asks for the composition/caret rectangle, which must share
        // the viewport policy with selection reveal rather than returning an
        // off-screen proxy coordinate after a remote selection.
        [self revealActiveMultilineCharacterAtLocation:location forNode:node];
    }
    NSRect content = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    CGFloat scroll = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
        ? [self multilineScrollOffsetForNode:node] : 0.0;
    CGFloat lineHeight = MAX(1.0, [layoutManager defaultLineHeightForFont:self.inputProxy.font]);
    NSRect line = NSMakeRect(0.0, 0.0, 1.0, lineHeight);
    CGFloat caretX = 0.0;
    if (length > 0) {
        NSUInteger character = location >= length ? length - 1 : location;
        [self ensureActiveLayoutForCharacterRange:NSMakeRange(character, 1) layoutManager:layoutManager];
        if (location == length && layoutManager.extraLineFragmentTextContainer == container &&
            !NSIsEmptyRect(layoutManager.extraLineFragmentRect)) {
            line = layoutManager.extraLineFragmentRect;
            caretX = NSMinX(layoutManager.extraLineFragmentUsedRect);
        } else {
            NSUInteger glyph = [self activeGlyphIndexForCharacter:character layoutManager:layoutManager];
            line = [self activeLineFragmentForGlyph:glyph layoutManager:layoutManager];
            caretX = location >= length ? NSMaxX(line) : [self activeGlyphLocation:glyph layoutManager:layoutManager].x;
        }
    }
    NSRect overlayRect = NSMakeRect(NSMinX(content) + caretX, NSMinY(content) + NSMinY(line) - scroll,
                                    1.0, MAX(1.0, NSHeight(line)));
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.candidateMicros += CjguiMonotonicMicros() - started;
#endif
    // Scene space, per the declared contract: the caller owns the conversion to screen.
    return overlayRect;
}
- (NSUInteger)characterIndexAtPoint:(NSPoint)point forNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node) return 0;
    [self positionInputProxyForNode:node];
    NSLayoutManager *layoutManager = self.inputProxy.layoutManager;
    NSTextContainer *container = self.inputProxy.textContainer;
    NSRect content = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    CGFloat scroll = node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT
        ? [self multilineScrollOffsetForNode:node] : 0.0;
    NSPoint layoutPoint = NSMakePoint(point.x - NSMinX(content), point.y - NSMinY(content) + scroll);
    [self ensureActiveLayoutForBoundingRect:NSMakeRect(0.0, MAX(0.0, layoutPoint.y - 1.0),
                                                        NSWidth(content), 2.0)
                                      container:container layoutManager:layoutManager];
    CGFloat fraction = 0.0;
    NSUInteger character = [layoutManager characterIndexForPoint:layoutPoint
                                                  inTextContainer:container
                           fractionOfDistanceBetweenInsertionPoints:&fraction];
    NSUInteger length = self.inputProxy.string.length;
    if (character < length && fraction > 0.5) character += 1;
    return MIN(character, length);
}
- (void)clearDraggingSelection {
    self.draggingNodeId = 0; self.draggingNodeResourceId = -1;
    self.draggingProjectionVersion = 0; self.draggingAnchor = 0;
}
- (void)cancelPointerCapture {
    self.pointerCaptureActive = NO;
    self.pointerCaptureNodeId = 0;
    self.pointerCaptureResourceId = -1;
    self.pointerCaptureNodeKind = 0;
    self.pointerCaptureX = 0.0;
    self.pointerCaptureY = 0.0;
}

- (void)cancelPointerCaptureForPlatformLoss {
    if (self.pointerCaptureActive) {
        [self endPointerCaptureAtPoint:NSMakePoint(self.pointerCaptureX, self.pointerCaptureY) cancelled:YES];
    }
    [self cancelPressForPlatformLoss];
}

- (CJGuiInternalComposableSceneNode *)capturedPointerNode {
    if (!self.pointerCaptureActive || self.pointerCaptureNodeId == 0) return nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == self.pointerCaptureNodeId &&
            candidate.node.resourceId == self.pointerCaptureResourceId &&
            candidate.node.nodeKind == self.pointerCaptureNodeKind &&
            candidate.node.isInteractive != 0 && candidate.node.isReadOnly == 0 &&
            CjguiComposableNodeAcceptsPointerCapture(candidate.node.nodeKind)) {
            return candidate;
        }
    }
    return nil;
}
- (CJGuiInternalComposableSceneNode *)hoveredPressableNode {
    if (self.hoveredNodeId == 0) return nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == self.hoveredNodeId &&
            candidate.node.resourceId == self.hoveredResourceId &&
            candidate.node.nodeKind == self.hoveredNodeKind && candidate.node.isInteractive != 0 &&
            candidate.node.isReadOnly == 0 && CjguiComposableNodeIsPressable(candidate.node.nodeKind)) return candidate;
    }
    return nil;
}
- (CJGuiInternalComposableSceneNode *)pressedPressableNode {
    if (self.pressedNodeId == 0) return nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == self.pressedNodeId &&
            candidate.node.resourceId == self.pressedResourceId &&
            candidate.node.nodeKind == self.pressedNodeKind && candidate.node.isInteractive != 0 &&
            candidate.node.isReadOnly == 0 && CjguiComposableNodeIsPressable(candidate.node.nodeKind)) return candidate;
    }
    return nil;
}
- (void)clearPressRouting {
    self.pressedNodeId = 0; self.pressedResourceId = -1; self.pressedNodeKind = 0;
    self.pressedCancelled = NO; self.pressedX = 0.0; self.pressedY = 0.0;
}
- (void)clearHoverAtPoint:(NSPoint)point {
    CJGuiInternalComposableSceneNode *previous = [self hoveredPressableNode];
    self.hoveredNodeId = 0; self.hoveredResourceId = -1; self.hoveredNodeKind = 0;
    if (previous) (void)CjguiEnqueueComposablePointerInteraction(
        self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_LEAVE, previous, point);
}
- (void)updateHoverAtPoint:(NSPoint)point {
    CJGuiInternalComposableSceneNode *next = [self nodeAtPoint:point];
    if (!next || !CjguiComposableNodeIsPressable(next.node.nodeKind) || next.node.isInteractive == 0 ||
        next.node.isReadOnly != 0) next = nil;
    CJGuiInternalComposableSceneNode *previous = [self hoveredPressableNode];
    if (previous && next && previous.node.nodeId == next.node.nodeId &&
        previous.node.resourceId == next.node.resourceId && previous.node.nodeKind == next.node.nodeKind) return;
    [self clearHoverAtPoint:point];
    if (next) {
        self.hoveredNodeId = next.node.nodeId; self.hoveredResourceId = next.node.resourceId;
        self.hoveredNodeKind = next.node.nodeKind;
        (void)CjguiEnqueueComposablePointerInteraction(
            self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_ENTER, next, point);
    }
}
- (void)beginPressForNode:(CJGuiInternalComposableSceneNode *)node atPoint:(NSPoint)point {
    if (!node || node.node.isInteractive == 0 || node.node.isReadOnly != 0 ||
        !CjguiComposableNodeIsPressable(node.node.nodeKind)) return;
    [self clearPressRouting];
    [self focusNode:node enqueue:YES];
    self.pressedNodeId = node.node.nodeId; self.pressedResourceId = node.node.resourceId;
    self.pressedNodeKind = node.node.nodeKind; self.pressedX = point.x; self.pressedY = point.y;
    if (!CjguiEnqueueComposablePointerInteraction(
        self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_BEGIN, node, point)) {
        [self clearPressRouting];
    }
}
- (void)cancelPressAtPoint:(NSPoint)point {
    CJGuiInternalComposableSceneNode *node = [self pressedPressableNode];
    if (!node) { [self clearPressRouting]; return; }
    self.pressedCancelled = YES; self.pressedX = point.x; self.pressedY = point.y;
    (void)CjguiEnqueueComposablePointerInteraction(
        self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL, node, point);
}
- (void)completePressAtPoint:(NSPoint)point {
    CJGuiInternalComposableSceneNode *pressed = [self pressedPressableNode];
    if (!pressed) { [self clearPressRouting]; return; }
    CJGuiInternalComposableSceneNode *hit = [self nodeAtPoint:point];
    BOOL activates = !self.pressedCancelled && hit && hit.node.nodeId == pressed.node.nodeId &&
        hit.node.resourceId == pressed.node.resourceId && hit.node.nodeKind == pressed.node.nodeKind;
    self.pressedX = point.x; self.pressedY = point.y;
    (void)CjguiEnqueueComposablePointerInteraction(
        self.session, activates ? CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_END :
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_PRESS_CANCEL, pressed, point);
    [self clearPressRouting];
    if (!activates) return;
    if (pressed.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        NSString *next = [pressed.value isEqualToString:@"true"] ? @"false" : @"true";
        (void)CjguiEnqueueComposableInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED, pressed.index, next, NSMakeRange(0, 0));
        CjguiStampPointerModifiersOnQueuedInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED, pressed.index);
    } else {
        (void)CjguiEnqueueComposableInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, pressed.index, @"", NSMakeRange(0, 0));
        CjguiStampPointerModifiersOnQueuedInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, pressed.index);
    }
}
- (void)cancelPressForPlatformLoss {
    if (self.pressedNodeId != 0) [self cancelPressAtPoint:NSMakePoint(self.pressedX, self.pressedY)];
    [self clearPressRouting];
}
- (CJGuiInternalComposableDataTransferItem *)dataTransferItemForNode:(CJGuiInternalComposableSceneNode *)node
                                                                 role:(uint32_t)role {
    if (!node) return nil;
    return CjguiComposableDataTransferItemForNode(self.session, node.node.nodeId,
        node.node.resourceId, node.node.nodeKind, role);
}
- (CJGuiInternalComposableSceneNode *)dataTransferTargetAtPoint:(NSPoint)point
                                                       pasteboard:(NSPasteboard *)pasteboard {
    CJGuiInternalComposableSceneNode *node = [self nodeAtPoint:point];
    CJGuiInternalComposableDataTransferItem *item = [self dataTransferItemForNode:node
        role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET];
    if (!item || !pasteboard) return nil;
    return [pasteboard availableTypeFromArray:@[CjguiPasteboardTypeForDataTransferFormat(item.format)]] ? node : nil;
}
- (void)clearDataTransferHoverAtPoint:(NSPoint)point {
    if (self.dataTransferHoverNodeId == 0) return;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == self.dataTransferHoverNodeId &&
            node.node.resourceId == self.dataTransferHoverResourceId &&
            node.node.nodeKind == self.dataTransferHoverNodeKind) {
            (void)CjguiEnqueueComposablePointerInteraction(self.session,
                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_LEAVE, node, point);
            break;
        }
    }
    self.dataTransferHoverNodeId = 0; self.dataTransferHoverResourceId = -1;
    self.dataTransferHoverNodeKind = 0;
}
- (void)setDataTransferHoverTarget:(CJGuiInternalComposableSceneNode *)node atPoint:(NSPoint)point {
    if (node && self.dataTransferHoverNodeId == node.node.nodeId &&
        self.dataTransferHoverResourceId == node.node.resourceId &&
        self.dataTransferHoverNodeKind == node.node.nodeKind) return;
    [self clearDataTransferHoverAtPoint:point];
    if (!node) return;
    self.dataTransferHoverNodeId = node.node.nodeId;
    self.dataTransferHoverResourceId = node.node.resourceId;
    self.dataTransferHoverNodeKind = node.node.nodeKind;
    (void)CjguiEnqueueComposablePointerInteraction(self.session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_HOVER_ENTER, node, point);
}
- (BOOL)beginDataTransferDragForNode:(CJGuiInternalComposableSceneNode *)node event:(NSEvent *)event {
#ifdef CJGUI_INTERNAL_TESTING
    self.testDataTransferDragSessionBegan = NO;
#endif
    CJGuiInternalComposableDataTransferItem *item = [self dataTransferItemForNode:node
        role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE];
    if (!item || !event) return NO;
    NSData *payload = [item.format isEqualToString:@"image/png"]
        ? item.binaryPayload : [item.payload dataUsingEncoding:NSUTF8StringEncoding];
    NSPasteboardType type = CjguiPasteboardTypeForDataTransferFormat(item.format);
    if (!payload || payload.length > item.item.maximumPayloadBytes || !type) return NO;
    if (CjguiDataTransferTraceEnabled()) {
        NSPoint local = [self convertPoint:event.locationInWindow fromView:nil];
        NSPoint screen = NSEvent.mouseLocation;
        NSLog(@"cjgui: transfer source begin window=%ld node=%llu local=%.1f,%.1f event_window=%.1f,%.1f screen=%.1f,%.1f type=%@ bytes=%lu",
              (long)(self.window ? self.window.windowNumber : 0), (unsigned long long)node.node.nodeId,
              local.x, local.y, event.locationInWindow.x, event.locationInWindow.y, screen.x, screen.y, type,
              (unsigned long)payload.length);
    }
    NSPasteboardItem *pasteboardItem = [[NSPasteboardItem alloc] init];
    if (!pasteboardItem) return NO;
    [pasteboardItem setData:payload forType:type];
    NSData *metadata = CjguiDataTransferSourceMetadata(item);
    if (metadata) [pasteboardItem setData:metadata forType:kCjguiDataTransferSourceMetadataType];
    NSDraggingItem *draggingItem = [[NSDraggingItem alloc] initWithPasteboardWriter:pasteboardItem];
    NSRect frame = CjguiComposableRect(node, self);
    NSImage *preview = [[NSImage alloc] initWithSize:frame.size];
    [preview lockFocus];
    [[NSColor colorWithCalibratedWhite:0.82 alpha:0.82] setFill];
    NSRectFill(NSMakeRect(0, 0, frame.size.width, frame.size.height));
    [preview unlockFocus];
    [draggingItem setDraggingFrame:frame contents:preview];
    [self cancelPressAtPoint:NSMakePoint(self.pressedX, self.pressedY)];
    [self clearPressRouting];
    BOOL began = [self beginDraggingSessionWithItems:@[draggingItem] event:event source:self] != nil;
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer source session window=%ld began=%@", (long)(self.window ? self.window.windowNumber : 0),
              began ? @"true" : @"false");
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.testDataTransferDragSessionBegan = began;
#endif
    return began;
}
- (NSDragOperation)draggingSession:(NSDraggingSession *)session
    sourceOperationMaskForDraggingContext:(NSDraggingContext)context {
    (void)session; (void)context;
    return NSDragOperationCopy;
}
- (void)draggingSession:(NSDraggingSession *)session endedAtPoint:(NSPoint)screenPoint
               operation:(NSDragOperation)operation {
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer source ended window=%ld screen=%.1f,%.1f operation=%lu session=%@",
              (long)(self.window ? self.window.windowNumber : 0), screenPoint.x, screenPoint.y,
              (unsigned long)operation, session);
    }
}
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)sender {
    NSPoint point = [self convertPoint:sender.draggingLocation fromView:nil];
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target entered window=%ld drag_window=%.1f,%.1f local=%.1f,%.1f types=%@",
              (long)(self.window ? self.window.windowNumber : 0), sender.draggingLocation.x, sender.draggingLocation.y,
              point.x, point.y, sender.draggingPasteboard.types);
    }
    CJGuiInternalComposableSceneNode *target = [self dataTransferTargetAtPoint:point
        pasteboard:sender.draggingPasteboard];
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target entered-result window=%ld node=%@", (long)(self.window ? self.window.windowNumber : 0),
              target ? @(target.node.nodeId) : @"none");
    }
    [self setDataTransferHoverTarget:target atPoint:point];
    return target ? NSDragOperationCopy : NSDragOperationNone;
}
- (NSDragOperation)draggingUpdated:(id<NSDraggingInfo>)sender {
    return [self draggingEntered:sender];
}
- (void)draggingExited:(nullable id<NSDraggingInfo>)sender {
    NSPoint point = sender ? [self convertPoint:sender.draggingLocation fromView:nil] : NSZeroPoint;
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target exited window=%ld local=%.1f,%.1f sender=%@",
              (long)(self.window ? self.window.windowNumber : 0), point.x, point.y, sender ? @"present" : @"nil");
    }
    [self clearDataTransferHoverAtPoint:point];
}
- (BOOL)prepareForDragOperation:(id<NSDraggingInfo>)sender {
    NSPoint point = [self convertPoint:sender.draggingLocation fromView:nil];
    CJGuiInternalComposableSceneNode *target = [self dataTransferTargetAtPoint:point pasteboard:sender.draggingPasteboard];
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target prepare window=%ld local=%.1f,%.1f node=%@",
              (long)(self.window ? self.window.windowNumber : 0), point.x, point.y,
              target ? @(target.node.nodeId) : @"none");
    }
    return target != nil;
}
- (BOOL)performDragOperation:(id<NSDraggingInfo>)sender {
    NSPoint point = [self convertPoint:sender.draggingLocation fromView:nil];
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target perform window=%ld drag_window=%.1f,%.1f local=%.1f,%.1f types=%@",
              (long)(self.window ? self.window.windowNumber : 0), sender.draggingLocation.x, sender.draggingLocation.y,
              point.x, point.y, sender.draggingPasteboard.types);
    }
    CJGuiInternalComposableSceneNode *target = [self dataTransferTargetAtPoint:point
        pasteboard:sender.draggingPasteboard];
    CJGuiInternalComposableDataTransferItem *item = [self dataTransferItemForNode:target
        role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET];
    CjguiInternalRendererStatus status = CjguiReadComposableDataTransferItem(self.session, item,
        sender.draggingPasteboard, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_DROP);
    if (CjguiDataTransferTraceEnabled()) {
        NSLog(@"cjgui: transfer target perform-result window=%ld node=%@ status=%d",
              (long)(self.window ? self.window.windowNumber : 0), target ? @(target.node.nodeId) : @"none", status);
    }
    [self clearDataTransferHoverAtPoint:point];
    return status == CJGUI_INTERNAL_RENDERER_OK;
}
- (BOOL)beginPointerCaptureForNode:(CJGuiInternalComposableSceneNode *)node atPoint:(NSPoint)point {
    if (!node || node.node.isInteractive == 0 || node.node.isReadOnly != 0 ||
        !CjguiComposableNodeAcceptsPointerCapture(node.node.nodeKind)) return NO;
    [self cancelPointerCapture];
    // A pointer control is also a keyboard control.  Keep native focus on
    // the exact captured node so the following Arrow key follows the same
    // Cangjie-owned control route as a physical drag.
    [self focusNode:node enqueue:YES];
    self.pointerCaptureActive = YES;
    self.pointerCaptureNodeId = node.node.nodeId;
    self.pointerCaptureResourceId = node.node.resourceId;
    self.pointerCaptureNodeKind = node.node.nodeKind;
    self.pointerCaptureX = point.x;
    self.pointerCaptureY = point.y;
    if (!CjguiEnqueueComposablePointerInteraction(self.session,
                                                   CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_BEGIN,
                                                   node, point)) {
        [self cancelPointerCapture];
        return NO;
    }
    return YES;
}
- (BOOL)updatePointerCaptureAtPoint:(NSPoint)point {
    CJGuiInternalComposableSceneNode *node = [self capturedPointerNode];
    if (!node) {
        [self cancelPointerCapture];
        return NO;
    }
    self.pointerCaptureX = point.x;
    self.pointerCaptureY = point.y;
    return CjguiEnqueueComposablePointerInteraction(self.session,
                                                     CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_UPDATE,
                                                     node, point);
}
- (void)endPointerCaptureAtPoint:(NSPoint)point cancelled:(BOOL)cancelled {
    CJGuiInternalComposableSceneNode *node = [self capturedPointerNode];
    if (!node) {
        [self cancelPointerCapture];
        return;
    }
    self.pointerCaptureX = point.x;
    self.pointerCaptureY = point.y;
    (void)CjguiEnqueueComposablePointerInteraction(
        self.session,
        cancelled ? CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_CANCEL :
                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_POINTER_END,
        node,
        point
    );
    [self cancelPointerCapture];
}
- (void)beginTextSelectionForNode:(CJGuiInternalComposableSceneNode *)node atPoint:(NSPoint)point {
    [self focusNode:node enqueue:YES];
    NSUInteger character = [self characterIndexAtPoint:point forNode:node];
    self.draggingNodeId = node.node.nodeId;
    self.draggingNodeResourceId = node.node.resourceId;
    self.draggingProjectionVersion = node.node.projectionVersion;
    self.draggingAnchor = character;
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, character, character);
    (void)CjguiEnqueueComposableInteraction(self.session,
                                            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
                                            node.index, @"", self.inputProxy.selectedRange);
    [self setNeedsDisplay:YES];
}
- (void)mouseDownForNode:(CJGuiInternalComposableSceneNode *)node atPoint:(NSPoint)point {
    uint32_t kind = node.node.nodeKind;
    if (node.node.isInteractive == 0) return;
    if (CjguiComposableNodeAcceptsPointerCapture(kind)) {
        (void)[self beginPointerCaptureForNode:node atPoint:point];
        return;
    }
    if (CjguiComposableNodeIsTextInput(kind)) {
        [self beginTextSelectionForNode:node atPoint:point];
        return;
    }
    if (node.node.isReadOnly != 0) return;
    if (CjguiComposableNodeIsPressable(kind)) {
        [self beginPressForNode:node atPoint:point];
        return;
    }
    self.lastPointerDownPoint = point;
    [self mouseDownForNode:node];
}
- (void)mouseDownForNode:(CJGuiInternalComposableSceneNode *)node {
    uint32_t kind = node.node.nodeKind;
    if (node.node.isInteractive == 0) return;
    if (CjguiComposableNodeIsTextInput(kind)) { [self focusNode:node enqueue:YES]; return; }
    if (node.node.isReadOnly != 0) return;
    [self focusNode:node enqueue:YES];
    if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        NSString *next = [node.value isEqualToString:@"true"] ? @"false" : @"true";
        (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED, node.index, next, NSMakeRange(0, 0));
        CjguiStampPointerModifiersOnQueuedInteraction(self.session,
            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED, node.index);
        return;
    }
    (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, node.index, @"", NSMakeRange(0, 0));
    CjguiStampPointerModifiersOnQueuedInteraction(self.session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, node.index);
    CjguiStampPointerPositionOnQueuedInteraction(self.session,
        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE, node.index, self.lastPointerDownPoint);
}
- (void)setText:(NSString *)text forNode:(CJGuiInternalComposableSceneNode *)node {
    self.activeTextRangeEditPending = NO;
    [self focusNode:node enqueue:NO]; self.applyingProjection = YES; self.inputProxy.string = text ?: @"";
    self.inputProxy.selectedRange = NSMakeRange(self.inputProxy.string.length, 0); self.applyingProjection = NO;
    // Same rule as a human keystroke: the proxy now holds text the committed projection does
    // not, and the value change queued below has not been judged yet.
    self.activeLocalEditAwaitingOwner = YES;
    self.activeLocalEditProjectionVersion = self.activeProjectionVersion;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        self.activeTextFallbackHasPendingEdit = NO;
        [self markActiveTextFallbackRunsDirtyForWholeValue];
#ifdef CJGUI_INTERNAL_TESTING
        self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
        [self refreshGpuTextForActiveInput];
    }
    (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED, node.index, self.inputProxy.string, self.inputProxy.selectedRange);
}
- (void)mouseDown:(NSEvent *)event {
    self.session.pointerModifierFlags = (int64_t)event.modifierFlags;
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    [self updateHoverAtPoint:point];
    CJGuiInternalComposableSceneNode *node = [self nodeAtPoint:point];
    if (node) [self mouseDownForNode:node atPoint:point];
    else [self clearDraggingSelection];
}
- (void)mouseDragged:(NSEvent *)event {
    self.session.pointerModifierFlags = (int64_t)event.modifierFlags;
    if (self.pointerCaptureActive) {
        NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
        (void)[self updatePointerCaptureAtPoint:point];
        return;
    }
    if (self.pressedNodeId != 0) {
        NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
        [self updateHoverAtPoint:point];
        CJGuiInternalComposableSceneNode *pressed = [self pressedPressableNode];
        if (pressed && [self dataTransferItemForNode:pressed role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE] &&
            hypot(point.x - self.pressedX, point.y - self.pressedY) >= 3.0 &&
            [self beginDataTransferDragForNode:pressed event:event]) {
            return;
        }
        CJGuiInternalComposableSceneNode *hit = [self nodeAtPoint:point];
        if (pressed && (!hit || hit.node.nodeId != pressed.node.nodeId || hit.node.resourceId != pressed.node.resourceId ||
            hit.node.nodeKind != pressed.node.nodeKind)) [self cancelPressAtPoint:point];
        return;
    }
    if (self.draggingNodeId == 0 || self.activeNodeIndex == NSNotFound) return;
    CJGuiInternalComposableSceneNode *node = nil;
    for (CJGuiInternalComposableSceneNode *candidate in self.nodes) {
        if (candidate.node.nodeId == self.draggingNodeId &&
            candidate.node.resourceId == self.draggingNodeResourceId &&
            candidate.node.projectionVersion == self.draggingProjectionVersion) {
            node = candidate; break;
        }
    }
    if (!node || node.node.nodeId != self.activeNodeId || node.node.resourceId != self.activeNodeResourceId ||
        node.node.nodeKind != self.activeNodeKind) {
        [self clearDraggingSelection]; return;
    }
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    NSUInteger character = [self characterIndexAtPoint:point forNode:node];
    NSUInteger start = MIN(self.draggingAnchor, character);
    NSUInteger end = MAX(self.draggingAnchor, character);
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, start, end);
#ifdef CJGUI_INTERNAL_TESTING
    self.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
#endif
    [self refreshGpuTextForActiveInput];
    (void)CjguiEnqueueComposableInteraction(self.session,
                                            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
                                            node.index, @"", self.inputProxy.selectedRange);
    [self setNeedsDisplay:YES];
}
- (void)mouseUp:(NSEvent *)event {
    self.session.pointerModifierFlags = (int64_t)event.modifierFlags;
    if (self.pointerCaptureActive) {
        NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
        [self endPointerCaptureAtPoint:point cancelled:NO];
        return;
    }
    if (self.pressedNodeId != 0) {
        NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
        [self updateHoverAtPoint:point];
        [self completePressAtPoint:point];
        return;
    }
    [self clearDraggingSelection];
}
- (void)updateTrackingAreas {
    [super updateTrackingAreas];
    if (self.hoverTrackingArea) {
        [self removeTrackingArea:self.hoverTrackingArea];
        self.hoverTrackingArea = nil;
    }
    // NSTrackingMouseMoved delivers mouse-moved events to THIS owner directly,
    // and NSTrackingInVisibleRect keeps the area in step with the bounds. This
    // is what makes hover enter/leave observable without a press.
    NSTrackingAreaOptions options = NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited |
        NSTrackingActiveInKeyWindow | NSTrackingInVisibleRect;
    NSTrackingArea *area = [[NSTrackingArea alloc] initWithRect:NSZeroRect options:options owner:self userInfo:nil];
    [self addTrackingArea:area];
    self.hoverTrackingArea = area;
    if (self.window) {
        self.window.acceptsMouseMovedEvents = YES;
    }
}
- (void)mouseMoved:(NSEvent *)event {
    [self updateHoverAtPoint:[self convertPoint:event.locationInWindow fromView:nil]];
}
- (void)mouseEntered:(NSEvent *)event {
    [self updateHoverAtPoint:[self convertPoint:event.locationInWindow fromView:nil]];
}
- (void)mouseExited:(NSEvent *)event {
    // Leaving the visible area must retire hover without a press, so a UI-only
    // consumer observes HOVER_LEAVE, not only HOVER_ENTER.
    [self clearHoverAtPoint:[self convertPoint:event.locationInWindow fromView:nil]];
}
- (void)scrollWheel:(NSEvent *)event {
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == self.activeNodeId && node.index == self.activeNodeIndex &&
            node.node.resourceId == self.activeNodeResourceId && node.node.nodeKind == self.activeNodeKind &&
            node.node.projectionVersion == self.activeProjectionVersion) { active = node; break; }
    }
    CJGuiInternalComposableSceneNode *hit = [self nodeAtPoint:point];
    if (hit && hit.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        (!active || active.node.nodeId != hit.node.nodeId || active.node.resourceId != hit.node.resourceId)) {
        [self focusNode:hit enqueue:YES];
        active = hit;
    }
    if (active && active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        NSPointInRect(point, CjguiComposableRect(active, self)) &&
        CjguiPointInComposableNodeClip(point, active, self)) {
        [self scrollActiveMultiline:active deltaY:event.scrollingDeltaY];
        return;
    }
    [self routeScrollAtPoint:point deltaY:event.scrollingDeltaY];
}
- (BOOL)textView:(NSTextView *)textView shouldChangeTextInRange:(NSRange)affectedCharRange
 replacementString:(NSString *)replacementString {
    if (textView == self.inputProxy && !self.applyingProjection) {
        // Record the exact human edit (replaced range + inserted string) so the
        // same callback that produced the new value can also publish a delta.
        self.activeTextRangeEditRange = affectedCharRange;
        self.activeTextRangeEditReplacement = replacementString ?: @"";
        self.activeTextRangeEditProjectionVersion = self.activeProjectionVersion;
        self.activeTextRangeEditPending = YES;
    }
    if (textView == self.inputProxy && !self.applyingProjection &&
        self.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        // Preserve an already-pending local range across consecutive edits.
        // The range is stored in document coordinates, so an insertion before
        // it must shift it; blindly unioning ranges from different revisions
        // can skip an emoji/combining sequence after a deletion.
        [self remapActiveTextFallbackDirtyRangeForEditRange:affectedCharRange
                                          replacementLength:replacementString.length];
        // Selection notifications can precede textDidChange for a key event.
        // Capture the *new* UTF-16 replacement span; textDidChange expands it
        // to composed-character boundaries once NSTextStorage is current.
        self.activeTextFallbackPendingEditRange = NSMakeRange(affectedCharRange.location, replacementString.length);
        self.activeTextFallbackHasPendingEdit = YES;
    }
    return YES;
}
- (void)textDidChange:(NSNotification *)notification {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
    self.testInputCallbackTrace.textCallbackCount += 1;
#endif
    (void)notification;
    // Do not request glyphs from NSTextView in its synchronous edit callback.
    // On a long paragraph that query can expand layout all the way to the
    // changed character and turn one keystroke into a document-wide stall.
    // The self-drawn viewport establishes only the needed visible glyphs on
    // its next draw; an explicit scroll/candidate query still asks TextKit
    // for exact geometry when that is actually required.
    self.activeTextLayoutNeedsVisibleGlyphs = YES;
    self.activeTextHasExactContentHeight = NO;
    if (self.activeNodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        if (!self.applyingProjection) {
            self.activeTextBodyGeneration += 1;
            self.activeTextVisibleParagraphEnd = 0;
            if (self.activeTextFallbackHasPendingEdit) {
                NSRange affected = [self fallbackAffectedRangeAfterEditAt:self.activeTextFallbackPendingEditRange.location
                                                         replacementLength:self.activeTextFallbackPendingEditRange.length
                                                                      value:self.inputProxy.textStorage.string ?: @""];
                [self markActiveTextFallbackRunsDirtyForRange:affected];
                self.activeTextFallbackHasPendingEdit = NO;
            } else {
                [self markActiveTextFallbackRunsDirtyForWholeValue];
            }
#ifdef CJGUI_INTERNAL_TESTING
            self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
            [self scheduleActiveTextResourcePreparation];
        }
    } else {
#ifdef CJGUI_INTERNAL_TESTING
        self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
        [self refreshGpuTextForActiveInput];
    }
    [self setNeedsDisplay:YES];
    // The captured range edit is SINGLE-USE: the next text-did-change consumes it whether or
    // not it can be delivered. Under marked text the change describes an in-progress
    // composition (its commit captures a fresh one), and a projection write is the owner's own
    // text. A flag that survived either case would block the owner→proxy sync for every later
    // projection, leaving the hidden proxy showing a value the owner had already replaced.
    BOOL hasRangeEdit = self.activeTextRangeEditPending;
    self.activeTextRangeEditPending = NO;
    if (self.applyingProjection || self.inputProxy.hasMarkedText) hasRangeEdit = NO;
    // A kind-52 terminal is inside its synchronous platform call right now: the
    // proxy text it just changed belongs to that composition, and an ordinary
    // TEXT_CHANGED/RANGE_CHANGED pair from here would make the session-owned
    // node look edited by someone else. The terminal event alone carries it.
    if (self.compositionTerminalInFlight) hasRangeEdit = NO;
    if (!self.applyingProjection && !self.compositionTerminalInFlight &&
        self.activeNodeIndex != NSNotFound && self.activeNodeId != 0 && !self.inputProxy.hasMarkedText) {
        // Consume the captured delta exactly once, whether or not the node
        // identity still resolves: a stale delta must never be re-sent.
        NSRange rangeEdit = self.activeTextRangeEditRange;
        NSString *rangeEditText = self.activeTextRangeEditReplacement ?: @"";
        CJGuiInternalComposableSceneNode *active = nil;
        for (CJGuiInternalComposableSceneNode *node in self.nodes) {
            if (node.node.nodeId == self.activeNodeId && node.index == self.activeNodeIndex &&
                node.node.resourceId == self.activeNodeResourceId && node.node.nodeKind == self.activeNodeKind &&
                node.node.projectionVersion == self.activeProjectionVersion) { active = node; break; }
        }
        if (active) {
            // The proxy now holds text the committed projection does not. Record it against the
            // projection the human edited so query paths (scroll, candidate rect, hit test) that
            // reposition this node before the owner republishes cannot revert it.
            self.activeLocalEditAwaitingOwner = YES;
            self.activeLocalEditProjectionVersion = self.activeProjectionVersion;
#ifdef CJGUI_INTERNAL_TESTING
            uint64_t enqueueStarted = CjguiMonotonicMicros();
#endif
            (void)CjguiEnqueueComposableInteraction(self.session, CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_CHANGED, active.index,
                                                    self.inputProxy.string, self.inputProxy.selectedRange);
            if (hasRangeEdit && self.session.rangeTextEditDeltaDeliveryEnabled) {
                // Same edit, delivered as a bounded delta on the existing FIFO, in
                // the proxy's own UTF-16 coordinates.
                //
                // This must NOT be clamped to `active.value`. The projected value is
                // the last thing the owner published, not what the platform surface
                // holds: two keystrokes before one projection legitimately address
                // the first keystroke's text, and clamping the second range onto the
                // stale length silently rewrote it into an earlier offset (owner text
                // `abYX` for `ab` + X + Y). A range the consumer cannot honor is a
                // named refusal at the session seam, which then locks the binding and
                // restores the proxy from the owner; a range repaired here is an
                // unrecoverable silent corruption.
                (void)CjguiEnqueueComposableInteraction(self.session,
                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_TEXT_RANGE_CHANGED, active.index,
                    rangeEditText, rangeEdit);
            }
#ifdef CJGUI_INTERNAL_TESTING
            self.session.testComposableEventEnqueueMicros = CjguiMonotonicMicros() - enqueueStarted;
            uint64_t accessibilityStarted = CjguiMonotonicMicros();
#endif
            [self postAccessibilityValueChangedForNode:active];
            [self postAccessibilitySelectionChangedForNode:active];
#ifdef CJGUI_INTERNAL_TESTING
            self.session.testComposableAccessibilityMicros = CjguiMonotonicMicros() - accessibilityStarted;
#endif
        }
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.session.testComposableTextDelegateMicros = CjguiMonotonicMicros() - started;
    self.testInputCallbackTrace.textCallbackMicros += self.session.testComposableTextDelegateMicros;
#endif
}
- (void)textViewDidChangeSelection:(NSNotification *)notification {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
    self.testInputCallbackTrace.selectionCallbackCount += 1;
    if (self.activeTextFallbackHasPendingEdit) self.testInputCallbackTrace.pendingEditSelectionCount += 1;
#endif
    (void)notification;
    // Selection is owned by the platform text service. Keep it separate from
    // a text edit: Cangjie records it only as window query state, never as a
    // domain write or a reason to rebuild the scene.
    if (self.applyingProjection || self.activeNodeIndex == NSNotFound || self.activeNodeId == 0 || self.inputProxy.hasMarkedText) {
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableSelectionDelegateMicros = CjguiMonotonicMicros() - started;
#endif
        return;
    }
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == self.activeNodeId && node.index == self.activeNodeIndex &&
            node.node.resourceId == self.activeNodeResourceId && node.node.nodeKind == self.activeNodeKind &&
            node.node.projectionVersion == self.activeProjectionVersion) {
            active = node; break;
        }
    }
    if (!active) {
#ifdef CJGUI_INTERNAL_TESTING
        self.session.testComposableSelectionDelegateMicros = CjguiMonotonicMicros() - started;
#endif
        return;
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t revealStarted = CjguiMonotonicMicros();
#endif
    [self revealActiveMultilineCaret:active];
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.selectionRevealMicros += CjguiMonotonicMicros() - revealStarted;
    uint64_t enqueueStarted = CjguiMonotonicMicros();
#endif
    (void)CjguiEnqueueComposableInteraction(self.session,
                                            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_SELECTION_CHANGED,
                                            active.index, @"", self.inputProxy.selectedRange);
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.selectionQueueMicros += CjguiMonotonicMicros() - enqueueStarted;
    uint64_t accessibilityStarted = CjguiMonotonicMicros();
#endif
    [self postAccessibilitySelectionChangedForNode:active];
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.selectionAccessibilityMicros += CjguiMonotonicMicros() - accessibilityStarted;
#endif
    if (active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        (self.activeTextFallbackRunsDirty || self.activeTextFallbackHasPendingEdit)) {
#ifdef CJGUI_INTERNAL_TESTING
        self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
        [self scheduleActiveTextResourcePreparation];
    } else {
#ifdef CJGUI_INTERNAL_TESTING
        self.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
        if (self.testForceFullBodyPreparationOnSelection) {
            self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
        }
#endif
        [self refreshGpuTextForActiveInput];
    }
    [self setNeedsDisplay:YES];
#ifdef CJGUI_INTERNAL_TESTING
    self.session.testComposableSelectionDelegateMicros = CjguiMonotonicMicros() - started;
    self.testInputCallbackTrace.selectionCallbackMicros += self.session.testComposableSelectionDelegateMicros;
#endif
}
- (CJGuiInternalComposableSceneNode *)nextFocusableNodeFrom:(NSInteger)index backwards:(BOOL)backwards {
    NSInteger cursor = index;
    NSInteger step = backwards ? -1 : 1;
    uint64_t activeScope = 0;
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (active) activeScope = active.node.inputScope;
    uint64_t activeTabGroup = active && active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE
        ? active.node.tabGroupId : 0;
    NSUInteger attempts = 0;
    while (attempts < self.nodes.count) {
        if (cursor < 0) cursor = (NSInteger)self.nodes.count - 1;
        if (cursor >= (NSInteger)self.nodes.count) cursor = 0;
        CJGuiInternalComposableSceneNode *candidate = self.nodes[(NSUInteger)cursor];
        uint32_t kind = candidate.node.nodeKind;
        BOOL tabStop = YES;
        if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE && candidate.node.tabGroupId != 0) {
            uint64_t group = candidate.node.tabGroupId;
            if (group == activeTabGroup) {
                tabStop = NO; // Tab exits the group even after an arrow moved title focus.
            } else {
                CJGuiInternalComposableSceneNode *firstEnabled = nil, *selected = nil;
                for (CJGuiInternalComposableSceneNode *peer in self.nodes) {
                    if (peer.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
                        peer.node.tabGroupId != group || peer.node.inputScope != activeScope ||
                        peer.node.isInteractive == 0 || peer.node.width <= 0 || peer.node.height <= 0 ||
                        peer.node.clipWidth <= 0 || peer.node.clipHeight <= 0) continue;
                    if (!firstEnabled) firstEnabled = peer;
                    if (peer.node.tabSelected != 0) selected = peer;
                }
                tabStop = candidate == (selected ?: firstEnabled);
            }
        }
        if (tabStop && candidate.node.inputScope == activeScope && candidate.node.isInteractive != 0 &&
            candidate.node.width > 0 && candidate.node.height > 0 &&
            // A scroll-clipped control still owns a real layout rect. Tab must
            // reach it so the window can reveal it; hidden tab pages have no
            // accepted positive layout rect in the active scene.
            (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SPLIT_DIVIDER ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_SLIDER)) return candidate;
        cursor += step;
        attempts += 1;
    }
    return nil;
}

// This bridge deliberately transports only a normalized physical shortcut.
// It has no application command table: Cangjie decides whether the chord is
// declared, enabled, and inside the current focus scope after it enters the
// existing bounded FIFO.
static NSString *CjguiComposableShortcutForEvent(NSEvent *event) {
    if (!event || (event.modifierFlags & NSEventModifierFlagCommand) == 0) return nil;
    NSString *key = event.charactersIgnoringModifiers.lowercaseString;
    if (key.length != 1) return nil;
    unichar scalar = [key characterAtIndex:0];
    if (scalar < 0x21 || scalar > 0x7e) return nil;
    NSMutableString *result = [NSMutableString stringWithString:@"shortcut:"];
    if ((event.modifierFlags & NSEventModifierFlagControl) != 0) [result appendString:@"control+"];
    if ((event.modifierFlags & NSEventModifierFlagOption) != 0) [result appendString:@"option+"];
    if ((event.modifierFlags & NSEventModifierFlagShift) != 0) [result appendString:@"shift+"];
    [result appendFormat:@"command+%@", key];
    return result;
}

// Copy/paste are framework transfer gestures only for an unmodified Command
// chord on a non-text control.  Shift/Option/Control variants remain distinct
// declared shortcuts (or ordinary AppKit input); they must not be silently
// folded into the generic transfer route.
static BOOL CjguiEventIsExactCommandCharacter(NSEvent *event, NSString *expected) {
    if (!event || expected.length != 1) return NO;
    NSEventModifierFlags relevant = NSEventModifierFlagCommand | NSEventModifierFlagControl |
        NSEventModifierFlagOption | NSEventModifierFlagShift;
    if ((event.modifierFlags & relevant) != NSEventModifierFlagCommand) return NO;
    return [event.charactersIgnoringModifiers.lowercaseString isEqualToString:expected];
}

static BOOL CjguiEnqueueComposableShortcut(CJGuiInternalSession *session, NSString *shortcut) {
    if (!session || shortcut.length == 0) return NO;
    return CjguiEnqueueComposableInteraction(session,
                                             CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_WINDOW_COMMAND,
                                             0, shortcut, NSMakeRange(0, 0));
}

- (BOOL)textView:(NSTextView *)textView doCommandBySelector:(SEL)selector {
    (void)textView;
    if (selector == @selector(saveDocument:) || selector == @selector(saveDocumentAs:)) {
        return CjguiEnqueueComposableShortcut(self.session, @"shortcut:command+s");
    }
    if (selector == @selector(undo:)) {
        return CjguiEnqueueComposableShortcut(self.session, @"shortcut:command+z");
    }
    if (selector == @selector(redo:)) {
        return CjguiEnqueueComposableShortcut(self.session, @"shortcut:shift+command+z");
    }
    BOOL backwards = selector == @selector(insertBacktab:);
    BOOL forwards = selector == @selector(insertTab:);
    if (!backwards && !forwards) return NO;
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (forwards && active && active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        active.node.tabInsertsText != 0) return NO;
    CJGuiInternalComposableSceneNode *next = [self nextFocusableNodeFrom:self.activeNodeIndex + (backwards ? -1 : 1) backwards:backwards];
    if (next) [self focusNode:next enqueue:YES];
    return next != nil;
}
- (BOOL)composableActiveNodeIsPresentationText {
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (!active) return NO;
    return active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
        active.node.isInteractive != 0 && active.node.isReadOnly == 0;
}
- (BOOL)activeNodeOwnsCompositionSession {
    CJGuiInternalSession *session = self.session;
    if (!session || !session.ownedTextSessionEnabled || self.activeNodeId == 0) return NO;
    return self.activeNodeId == session.ownedTextSessionNodeId &&
        self.activeNodeResourceId == session.ownedTextSessionResourceId &&
        self.activeNodeKind == session.ownedTextSessionNodeKind;
}
- (CJGuiInternalComposableSceneNode *)activeFocusableNode {
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.index == self.activeNodeIndex && node.node.nodeId == self.activeNodeId &&
            node.node.resourceId == self.activeNodeResourceId && node.node.nodeKind == self.activeNodeKind &&
            node.node.projectionVersion == self.activeProjectionVersion) return node;
    }
    return nil;
}
- (void)activateFocusedNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node || node.node.isInteractive == 0 || node.node.isReadOnly != 0) return;
    if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) {
        NSString *next = [node.value isEqualToString:@"true"] ? @"false" : @"true";
        (void)CjguiEnqueueComposableInteraction(self.session,
                                                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_BOOLEAN_CHANGED,
                                                node.index, next, NSMakeRange(0, 0));
    } else if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON ||
               node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC ||
               node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE) {
        (void)CjguiEnqueueComposableInteraction(self.session,
                                                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_ACTIVATE,
                                                node.index, @"", NSMakeRange(0, 0));
    }
}
- (BOOL)handleWindowCommandKeyDown:(NSEvent *)event {
    NSString *shortcut = CjguiComposableShortcutForEvent(event);
    // Native has no command executor.  It may forward only a declaration
    // that is currently visible in the focused scope; Cangjie then performs
    // the authoritative identity/enabled check after FIFO delivery.  An
    // undeclared Cmd-C/V must fall through to the generic transfer route.
    if (!CjguiComposableActiveScopeDeclaresShortcut(self.session, shortcut)) return NO;
    return CjguiEnqueueComposableShortcut(self.session, shortcut);
}
- (void)keyDown:(NSEvent *)event {
#ifdef CJGUI_INTERNAL_TESTING
    self.testKeyDownReceiptCount += 1;
#endif
    if (CjguiDataTransferTraceEnabled() &&
        (CjguiEventIsExactCommandCharacter(event, @"c") ||
         CjguiEventIsExactCommandCharacter(event, @"v"))) {
        CJGuiInternalComposableSceneNode *focusedTransferNode = [self activeFocusableNode];
        NSLog(@"cjgui: transfer shortcut window=%ld key=%@ active=%@ first_responder=%@",
              (long)(self.window ? self.window.windowNumber : 0), event.charactersIgnoringModifiers,
              focusedTransferNode ? @(focusedTransferNode.node.nodeId) : @"none",
              NSStringFromClass(self.window.firstResponder.class));
    }
    if (event.keyCode == 53 && self.pointerCaptureActive) {
        [self endPointerCaptureAtPoint:NSMakePoint(self.pointerCaptureX, self.pointerCaptureY) cancelled:YES];
        return;
    }
    if ([self handleWindowCommandKeyDown:event]) {
        return;
    }
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    uint32_t activeKind = active ? active.node.nodeKind : 0;
    BOOL activeIsText = activeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        activeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        activeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
    // Text controls retain NSTextView's standard Cmd-C/X/V ownership through
    // the input proxy. Only a declared non-text transfer node reaches this
    // bounded generic route, and only after an explicit human shortcut.
    if (!activeIsText && active) {
        if (CjguiEventIsExactCommandCharacter(event, @"c")) {
            CJGuiInternalComposableDataTransferItem *source = [self dataTransferItemForNode:active
                role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE];
            CjguiInternalRendererStatus status = source ?
                CjguiCopyComposableDataTransferItem(self.session, source) : CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
            if (status == CJGUI_INTERNAL_RENDERER_OK) {
                return;
            }
        } else if (CjguiEventIsExactCommandCharacter(event, @"v")) {
            CJGuiInternalComposableDataTransferItem *target = [self dataTransferItemForNode:active
                role:CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET];
            CjguiInternalRendererStatus transferStatus = target ?
                CjguiReadComposableDataTransferItem(self.session, target,
                NSPasteboard.generalPasteboard,
                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DATA_TRANSFER_PASTE) :
                CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
            if (CjguiDataTransferTraceEnabled()) {
                NSLog(@"cjgui: transfer paste window=%ld target=%@ status=%d types=%@",
                      (long)(self.window ? self.window.windowNumber : 0),
                      target ? @(target.item.nodeId) : @"none", transferStatus,
                      NSPasteboard.generalPasteboard.types);
            }
            if (transferStatus == CJGUI_INTERNAL_RENDERER_OK) {
                return;
            }
        } else if (CjguiEventIsExactCommandCharacter(event, @"a")) {
            // Command-A over a non-text composable control is a scope-local
            // "select all" for the list/tree that contains the focused node.
            // Text controls keep NSTextView's own select-all through the
            // input proxy (they never reach this branch), and a scope with
            // no containing list falls back to the focused node itself.
            NSRect activeRect = CjguiComposableRect(active, self);
            CJGuiInternalComposableSceneNode *scopeNode = [self scrollNodeContainingPoint:
                NSMakePoint(NSMidX(activeRect), NSMidY(activeRect))];
            if (!scopeNode) scopeNode = active;
            (void)CjguiEnqueueComposableInteraction(self.session,
                                                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                    scopeNode.index, @"select_all", NSMakeRange(0, 0));
            CjguiStampKeyboardModifiersOnQueuedInteraction(self.session,
                                                           CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                           scopeNode.index, event.modifierFlags);
            return;
        }
    }
    if (event.keyCode == 53 && self.inputProxy.hasMarkedText) {
        // A composition is in progress: the FIRST Escape may only close the candidate list,
        // so it belongs to the input method. Treating it as "dismiss the layer" here would
        // throw away a conversion the user is still choosing from.
        if (getenv("PHAROS_TRACE_FIRST_RECT") != NULL) {
            fprintf(stderr, "PHAROS_ESCAPE_TO_IME marked=1\n");
        }
        return;
    }
    if (event.keyCode == 53 && active && active.node.inputScope != 0) {
        (void)CjguiEnqueueComposableInteraction(self.session,
                                                CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_DISMISS_LAYER,
                                                active.index, @"escape", NSMakeRange(0, 0));
        return;
    }
    if (!activeIsText && active) {
        // A focused tab TITLE owns its own Left/Right rule: the interaction is
        // enqueued against the TITLE, and Cangjie moves focus to the next enabled
        // title in the SAME accepted tab group. It must not be turned into a
        // list/scroll navigation by the generic branch below, which would scroll
        // the containing container instead of moving within the title row.
        if (activeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TAB_TITLE &&
            (event.keyCode == 123 || event.keyCode == 124)) {
            NSString *navigation = event.keyCode == 123 ? @"left" : @"right";
            (void)CjguiEnqueueComposableInteraction(self.session,
                                                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                    active.index, navigation, NSMakeRange(0, 0));
            CjguiStampKeyboardModifiersOnQueuedInteraction(self.session,
                                                           CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                           active.index, event.modifierFlags);
            return;
        }
        // A pointer-reporting, non-input presentation node has no text proxy, so
        // keys would otherwise be dropped entirely. Map the caret intents it can
        // act on into the existing NAVIGATE channel; the product resolves what
        // each intent means against its own SourceMap.
        if (activeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
            active.node.isInteractive != 0 && active.node.isReadOnly == 0) {
            NSString *caretIntent = nil;
            if (event.keyCode == 51) caretIntent = @"deleteBackward";
            else if (event.keyCode == 117) caretIntent = @"deleteForward";
            else if (event.keyCode == 123) caretIntent = @"left";
            else if (event.keyCode == 124) caretIntent = @"right";
            // Scrolling intents for a bounded presentation surface: without a text
            // proxy these keys would otherwise be dropped entirely.
            else if (event.keyCode == 116) caretIntent = @"pageUp";
            else if (event.keyCode == 121) caretIntent = @"pageDown";
            else if (event.keyCode == 125) caretIntent = @"down";
            else if (event.keyCode == 126) caretIntent = @"up";
            // Tab in a table: the same NAVIGATE channel carries it, so the product can
            // move between cells without a private key path.
            // Unmodified Tab only: Shift-Tab and every modifier combination keep their
            // ordinary meaning (focus traversal), so this cannot hijack them.
            else if (event.keyCode == 48 &&
                     (event.modifierFlags & (NSEventModifierFlagShift | NSEventModifierFlagCommand |
                                             NSEventModifierFlagOption | NSEventModifierFlagControl)) == 0)
                caretIntent = @"nextCell";
            if (caretIntent) {
                (void)CjguiEnqueueComposableInteraction(self.session,
                                                        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                        active.index, caretIntent, NSMakeRange(0, 0));
                CjguiStampKeyboardModifiersOnQueuedInteraction(self.session,
                                                               CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                               active.index, event.modifierFlags);
                return;
            }
        }
        BOOL activeIsPointerControl = CjguiComposableNodeAcceptsPointerCapture(activeKind);
        if (activeIsPointerControl && (event.keyCode == 123 || event.keyCode == 124 ||
                                       event.keyCode == 126 || event.keyCode == 125)) {
            NSString *navigation = event.keyCode == 123 ? @"left" :
                (event.keyCode == 124 ? @"right" : (event.keyCode == 126 ? @"up" : @"down"));
            (void)CjguiEnqueueComposableInteraction(self.session,
                                                    CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                    active.index, navigation, NSMakeRange(0, 0));
            CjguiStampKeyboardModifiersOnQueuedInteraction(self.session,
                                                           CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                           active.index, event.modifierFlags);
            return;
        }
        if (active.node.inputScope != 0 && (event.keyCode == 123 || event.keyCode == 124 ||
                                            event.keyCode == 126 || event.keyCode == 125)) {
            BOOL backwards = event.keyCode == 123 || event.keyCode == 126;
            CJGuiInternalComposableSceneNode *next = [self nextFocusableNodeFrom:self.activeNodeIndex + (backwards ? -1 : 1)
                                                                         backwards:backwards];
            if (next) [self focusNode:next enqueue:YES];
            return;
        }
        NSString *navigation = nil;
        if (event.keyCode == 126) navigation = @"up";
        else if (event.keyCode == 125) navigation = @"down";
        // Left/Right belong to the same scroll/list navigation vocabulary as
        // up/down/home/end: a tree uses them to collapse/ascend and
        // expand/descend. Pointer-capture nodes (split handles, sliders) and
        // input-scope focus traversal keep their own earlier branches, so this
        // only reaches an ordinary list/tree scope.
        else if (event.keyCode == 123) navigation = @"left";
        else if (event.keyCode == 124) navigation = @"right";
        else if (event.keyCode == 116) navigation = @"page_up";
        else if (event.keyCode == 121) navigation = @"page_down";
        else if (event.keyCode == 115) navigation = @"home";
        else if (event.keyCode == 119) navigation = @"end";
        if (navigation) {
            NSRect activeRect = CjguiComposableRect(active, self);
            CJGuiInternalComposableSceneNode *scrollNode = [self scrollNodeContainingPoint:NSMakePoint(NSMidX(activeRect), NSMidY(activeRect))];
            if (scrollNode) {
                (void)CjguiEnqueueComposableInteraction(self.session,
                                                        CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                        scrollNode.index, navigation, NSMakeRange(0, 0));
                CjguiStampKeyboardModifiersOnQueuedInteraction(self.session,
                                                               CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                                               scrollNode.index, event.modifierFlags);
                return;
            }
        }
    }
    // Tab inside a pointer-interactive TEXT node is a PRODUCT intent (e.g. moving to the
    // next table cell), not focus traversal. It must be decided here: the caret-intent
    // branch above only runs for non-text nodes, so a text node's Tab fell through to
    // the focus-move below and the product never saw it.
    if (event.keyCode == 48) {
        BOOL backwards = (event.modifierFlags & NSEventModifierFlagShift) != 0;
        CJGuiInternalComposableSceneNode *next = [self nextFocusableNodeFrom:self.activeNodeIndex + (backwards ? -1 : 1)
                                                                     backwards:backwards];
        if (next) [self focusNode:next enqueue:YES];
        return;
    }
    if (event.keyCode == 49 || event.keyCode == 36 || event.keyCode == 76) {
        [self activateFocusedNode:[self activeFocusableNode]];
        return;
    }
    [super keyDown:event];
}

// The Edit menu's "Select All" (Command-A) is offered to the menu before any
// keyDown, so the Command-A branch in keyDown is unreachable for a non-text
// composable control while this view is first responder. Routing the standard
// action here makes the menu item and the raw chord land on the same scope:
// a focused non-text control selects its containing list/tree through the
// ordinary NAVIGATE interaction. A text control keeps NSTextView's own
// select-all, because the input proxy is the first responder in that case and
// handles the command itself.
- (void)selectAll:(id)sender {
    (void)sender;
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (!active) return;
    uint32_t kind = active.node.nodeKind;
    BOOL activeIsText = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
        kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT;
    if (activeIsText) return;
    NSRect activeRect = CjguiComposableRect(active, self);
    CJGuiInternalComposableSceneNode *scopeNode = [self scrollNodeContainingPoint:
        NSMakePoint(NSMidX(activeRect), NSMidY(activeRect))];
    if (!scopeNode) scopeNode = active;
    (void)CjguiEnqueueComposableInteraction(self.session,
                                            CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_NAVIGATE,
                                            scopeNode.index, @"select_all", NSMakeRange(0, 0));
}
- (void)cancelActiveComposition {
    if (!self.inputProxy.hasMarkedText) return;
    // Keep cancellation in the adapter layer. The Cangjie owner receives no
    // edit event for a discarded preedit and therefore cannot accidentally
    // create an undo entry for text the user never committed.
    self.applyingProjection = YES;
    [(CJGuiInternalComposableInputProxy *)self.inputProxy cancelMarkedText];
    self.applyingProjection = NO;
    self.activeTextLayoutSignature = nil;
    self.activeTextLayoutNeedsVisibleGlyphs = YES;
    self.activeTextHasExactContentHeight = NO;
    CJGuiInternalComposableSceneNode *active = [self activeFocusableNode];
    if (active) {
        [self postAccessibilityValueChangedForNode:active];
        [self postAccessibilitySelectionChangedForNode:active];
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
    [self refreshGpuTextForActiveInput];
    [self setNeedsDisplay:YES];
}
- (void)scrollActiveMultiline:(CJGuiInternalComposableSceneNode *)node deltaY:(CGFloat)deltaY {
    if (!node || deltaY == 0.0) return;
    [self positionInputProxyForNode:node];
    NSLayoutManager *layoutManager = self.inputProxy.layoutManager;
    NSTextContainer *container = self.inputProxy.textContainer;
    NSRect rect = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    CGFloat next = MAX(0.0, [self multilineScrollOffsetForNode:node] - deltaY);
    if (self.activeTextHasExactContentHeight) {
        CGFloat maximum = MAX(0.0, self.activeTextKnownContentHeight - NSHeight(rect));
        next = MIN(maximum, next);
    }
    // Request only the viewport the wheel is moving into. With non-contiguous
    // layout TextKit may expand this range, but it is not a request for the
    // whole text container. An empty result is the explicit "past known end"
    // case where exact extent is required to clamp correctly.
    [self ensureActiveLayoutForBoundingRect:NSMakeRect(0.0, next, NSWidth(rect), NSHeight(rect))
                                  container:container layoutManager:layoutManager];
    NSRange visible = [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:
                       NSMakeRect(0.0, next, NSWidth(rect), NSHeight(rect)) inTextContainer:container];
    if (visible.location == NSNotFound || visible.length == 0) {
        [self ensureActiveFullLayoutForContainer:container layoutManager:layoutManager];
        self.activeTextKnownContentHeight = [layoutManager usedRectForTextContainer:container].size.height;
        self.activeTextHasExactContentHeight = YES;
        CGFloat maximum = MAX(0.0, self.activeTextKnownContentHeight - NSHeight(rect));
        next = MIN(maximum, next);
        visible = [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:
                   NSMakeRect(0.0, next, NSWidth(rect), NSHeight(rect)) inTextContainer:container];
    }
    [self setMultilineScrollOffset:next forNode:node];
    if (visible.location != NSNotFound && visible.length > 0) {
        NSUInteger character = [layoutManager characterIndexForGlyphAtIndex:visible.location];
        NSRect line = [self activeLineFragmentForGlyph:visible.location layoutManager:layoutManager];
        self.activeTextHasScrollAnchor = YES;
        self.activeTextScrollAnchorCharacter = character;
        self.activeTextScrollAnchorViewportOffset = NSMinY(line) - next;
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.testActiveTextWorkReason = CjguiInternalTextWorkReasonVisibleTileScroll;
#endif
    [self refreshGpuTextForActiveInput];
    [self setNeedsDisplay:YES];
    if (!self.activeTextTexturePreparationFailed) [self scheduleAcceptedScenePresent];
}
- (void)revealActiveMultilineCaret:(CJGuiInternalComposableSceneNode *)node {
    NSUInteger length = self.inputProxy.string.length;
    [self revealActiveMultilineCharacterAtLocation:MIN(self.inputProxy.selectedRange.location, length) forNode:node];
}
- (void)revealActiveMultilineCharacterAtLocation:(NSUInteger)requestedLocation forNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node || node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    [self positionInputProxyForNode:node];
    NSLayoutManager *layoutManager = self.inputProxy.layoutManager;
    NSTextContainer *container = self.inputProxy.textContainer;
    NSUInteger length = self.inputProxy.string.length;
    NSUInteger location = MIN(requestedLocation, length);
    if (length == 0) {
        [self setMultilineScrollOffset:0.0 forNode:node];
        self.activeTextHasScrollAnchor = YES;
        self.activeTextScrollAnchorCharacter = 0;
        self.activeTextScrollAnchorViewportOffset = 0.0;
#ifdef CJGUI_INTERNAL_TESTING
        self.activeTextLayoutTrace.revealMicros += CjguiMonotonicMicros() - started;
#endif
        return;
    }
    NSUInteger character = location >= length ? length - 1 : location;
    [self ensureActiveLayoutForCharacterRange:NSMakeRange(character, 1) layoutManager:layoutManager];
    NSUInteger glyph = [self activeGlyphIndexForCharacter:character layoutManager:layoutManager];
    NSRect glyphRect = location == length && layoutManager.extraLineFragmentTextContainer == container &&
        !NSIsEmptyRect(layoutManager.extraLineFragmentRect) ? layoutManager.extraLineFragmentRect :
        [self activeLineFragmentForGlyph:glyph layoutManager:layoutManager];
    NSRect textRect = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    CGFloat scroll = [self multilineScrollOffsetForNode:node];
    if (NSMinY(glyphRect) < scroll) scroll = NSMinY(glyphRect);
    if (NSMaxY(glyphRect) > scroll + NSHeight(textRect)) {
        scroll = NSMaxY(glyphRect) - NSHeight(textRect);
    }
    if (self.activeTextHasExactContentHeight) {
        CGFloat maximum = MAX(0.0, self.activeTextKnownContentHeight - NSHeight(textRect));
        scroll = MIN(maximum, scroll);
    }
    scroll = MAX(0.0, scroll);
    [self setMultilineScrollOffset:scroll forNode:node];
    self.activeTextHasScrollAnchor = YES;
    self.activeTextScrollAnchorCharacter = character;
    self.activeTextScrollAnchorViewportOffset = NSMinY(glyphRect) - scroll;
#ifdef CJGUI_INTERNAL_TESTING
    self.activeTextLayoutTrace.revealMicros += CjguiMonotonicMicros() - started;
#endif
}
- (void)updateActiveSingleLineTextDecorationsForNode:(CJGuiInternalComposableSceneNode *)node
                                           displayText:(NSString *)displayText
                                             selection:(NSRange)selection
                                           markedRange:(NSRange)markedRange
                                            drawsCaret:(BOOL)drawsCaret {
    CjguiClearComposableTextDecorations(node);
    if (!node || displayText.length == 0) return;
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = NSLineBreakByTruncatingTail;
    NSDictionary *attributes = @{ NSFontAttributeName: CjguiComposableFont(node),
                                  NSParagraphStyleAttributeName: paragraph };
    NSRect bounds = CjguiComposableRect(node, self);
    NSRect textRect = NSInsetRect(bounds, 7.0, 6.0);
    NSMutableArray<NSValue *> *selectionRects = [NSMutableArray array];
    if (selection.location != NSNotFound) {
        NSUInteger start = MIN(selection.location, displayText.length);
        NSUInteger end = MIN(NSMaxRange(selection), displayText.length);
        CGFloat before = [[displayText substringToIndex:start] sizeWithAttributes:attributes].width;
        if (end > start) {
            CGFloat selected = [[displayText substringWithRange:NSMakeRange(start, end - start)] sizeWithAttributes:attributes].width;
            [selectionRects addObject:[NSValue valueWithRect:NSMakeRect(NSMinX(textRect) + before, NSMinY(textRect),
                                                                  MAX(1.0, selected), NSHeight(textRect))]];
        } else if (drawsCaret) {
            node.textCaretRect = NSMakeRect(NSMinX(textRect) + before, NSMinY(textRect) + 2.0, 1.0,
                                             MAX(1.0, NSHeight(textRect) - 4.0));
        }
    }
    node.textSelectionRects = selectionRects;
    if (markedRange.location == NSNotFound || markedRange.length == 0) return;
    NSUInteger markedStart = MIN(markedRange.location, displayText.length);
    NSUInteger markedEnd = MIN(NSMaxRange(markedRange), displayText.length);
    if (markedEnd <= markedStart) return;
    CGFloat before = [[displayText substringToIndex:markedStart] sizeWithAttributes:attributes].width;
    CGFloat marked = [[displayText substringWithRange:NSMakeRange(markedStart, markedEnd - markedStart)] sizeWithAttributes:attributes].width;
    node.textMarkedRects = @[ [NSValue valueWithRect:NSMakeRect(NSMinX(textRect) + before, NSMaxY(textRect) - 1.0,
                                                               MAX(1.0, marked), 1.0)] ];
}
- (void)applyDeclaredInputCaretToNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node || !self.hasDeclaredInputCaret) return;
    if (self.declaredInputCaretNodeId != (int64_t)node.node.nodeId) return;
    if (!CjguiComposableNodeHasGpuText(node.node.nodeKind)) return;
    NSRect rect = CjguiComposableRect(node, self);
    NSRect clip = NSIntersectionRect(rect, CjguiComposableClipBounds(node));
    CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(node.node.nodeKind) ? 2.0 : 6.0;
    NSRect visibleTextRect = NSIntersectionRect(NSInsetRect(rect, 7.0, verticalInset), clip);
    if (NSIsEmptyRect(visibleTextRect)) return;
    // The declaration is in the node's own accepted-layout space (the prepared layout is
    // built from a (0,0,w,h) box inset by 7/verticalInset); decorations are view space.
    NSRect declared = self.declaredInputCaretRect;
    NSRect caret = NSMakeRect(NSMinX(rect) + NSMinX(declared), NSMinY(rect) + NSMinY(declared),
                              MAX(NSWidth(declared), 1.5), NSHeight(declared));
    caret = NSIntersectionRect(caret, visibleTextRect);
    if (NSIsEmptyRect(caret)) return;
    node.textCaretRect = caret;
    node.textCaretIsDeclared = YES;
}

- (void)updateActiveMultilineTextDecorationsForNode:(CJGuiInternalComposableSceneNode *)node {
    CjguiClearComposableTextDecorations(node);
    if (!node || node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return;
    NSRect rect = CjguiComposableRect(node, self);
    NSRect clip = NSIntersectionRect(rect, CjguiComposableClipBounds(node));
    NSRect contentRect = NSInsetRect(rect, 7.0, 6.0);
    NSRect visibleTextRect = NSIntersectionRect(contentRect, clip);
    if (NSIsEmptyRect(visibleTextRect)) return;
    NSString *value = self.inputProxy.string ?: @"";
    self.inputProxy.textContainer.maximumNumberOfLines = 0;
    self.inputProxy.textContainer.lineBreakMode = NSLineBreakByWordWrapping;
    NSLayoutManager *layoutManager = self.inputProxy.layoutManager;
    NSTextContainer *container = self.inputProxy.textContainer;
    container.containerSize = NSMakeSize(NSWidth(contentRect), CGFLOAT_MAX);
    container.widthTracksTextView = NO;
    if (self.activeTextLayoutNeedsVisibleGlyphs && value.length > 0) {
        NSUInteger location = MIN(self.inputProxy.selectedRange.location, value.length);
        NSUInteger character = location >= value.length ? value.length - 1 : location;
        [layoutManager ensureGlyphsForCharacterRange:NSMakeRange(character, 1)];
        self.activeTextLayoutNeedsVisibleGlyphs = NO;
    }
    if (self.activeTextHasScrollAnchor && value.length > 0) {
        NSUInteger anchor = MIN(self.activeTextScrollAnchorCharacter, value.length - 1);
        [self ensureActiveLayoutForCharacterRange:NSMakeRange(anchor, 1) layoutManager:layoutManager];
        NSUInteger anchorGlyph = [self activeGlyphIndexForCharacter:anchor layoutManager:layoutManager];
        NSRect anchorLine = [self activeLineFragmentForGlyph:anchorGlyph layoutManager:layoutManager];
        [self setMultilineScrollOffset:MAX(0.0, NSMinY(anchorLine) - self.activeTextScrollAnchorViewportOffset)
                              forNode:node];
    }
    CGFloat maximumScroll = self.activeTextHasExactContentHeight
        ? MAX(0.0, self.activeTextKnownContentHeight - NSHeight(contentRect)) : CGFLOAT_MAX;
    CGFloat scroll = MAX(0.0, [self multilineScrollOffsetForNode:node]);
    if (maximumScroll != CGFLOAT_MAX) scroll = MIN(maximumScroll, scroll);
    [self setMultilineScrollOffset:scroll forNode:node];
    NSRect visibleLayoutRect = NSMakeRect(0.0, scroll, NSWidth(contentRect), NSHeight(contentRect));
    [self ensureActiveLayoutForBoundingRect:visibleLayoutRect container:container layoutManager:layoutManager];
    NSRange visibleGlyphs = [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:visibleLayoutRect
                                                                      inTextContainer:container];
    if (visibleGlyphs.location == NSNotFound) visibleGlyphs = NSMakeRange(0, 0);
    self.activeTextVisibleParagraphEnd = 0;
    if (visibleGlyphs.length > 0 && value.length > 0) {
        NSRange visibleCharacters = [layoutManager characterRangeForGlyphRange:visibleGlyphs actualGlyphRange:NULL];
        if (visibleCharacters.length > 0) {
            NSUInteger lastCharacter = MIN(value.length - 1, NSMaxRange(visibleCharacters) - 1);
            self.activeTextVisibleParagraphEnd = NSMaxRange([value paragraphRangeForRange:NSMakeRange(lastCharacter, 0)]);
        }
    }
    if (maximumScroll != CGFLOAT_MAX && maximumScroll > 0.0) {
        CGFloat trackHeight = MAX(12.0, NSHeight(contentRect) - 4.0);
        CGFloat thumbHeight = MAX(14.0, trackHeight * NSHeight(contentRect) / (maximumScroll + NSHeight(contentRect)));
        CGFloat thumbY = NSMinY(contentRect) + 2.0 + (trackHeight - thumbHeight) * scroll / maximumScroll;
        node.textScrollbarRect = NSIntersectionRect(NSMakeRect(NSMaxX(contentRect) - 3.0, thumbY, 2.0, thumbHeight), visibleTextRect);
    }
    NSPoint origin = NSMakePoint(NSMinX(contentRect), NSMinY(contentRect) - scroll);
    NSRange selection = self.inputProxy.selectedRange;
    selection.location = MIN(selection.location, value.length);
    selection.length = MIN(selection.length, value.length - selection.location);
    if (selection.length > 0 && visibleGlyphs.length > 0) {
        NSRange visibleCharacters = [layoutManager characterRangeForGlyphRange:visibleGlyphs actualGlyphRange:NULL];
        NSRange selectedCharacters = NSIntersectionRange(selection, visibleCharacters);
        if (selectedCharacters.length > 0) {
            NSRange selectionGlyphs = [layoutManager glyphRangeForCharacterRange:selectedCharacters actualCharacterRange:NULL];
            NSMutableArray<NSValue *> *selectionRects = [NSMutableArray array];
            [layoutManager enumerateLineFragmentsForGlyphRange:selectionGlyphs usingBlock:^(NSRect lineRect, NSRect usedRect,
                                                                                              NSTextContainer *lineContainer,
                                                                                              NSRange lineGlyphRange, BOOL *stop) {
                (void)lineRect; (void)usedRect; (void)lineContainer; (void)stop;
                NSRange intersection = NSIntersectionRange(lineGlyphRange, selectionGlyphs);
                if (intersection.length == 0) return;
                NSRect selected = [layoutManager boundingRectForGlyphRange:intersection inTextContainer:container];
                selected.origin.x += origin.x; selected.origin.y += origin.y;
                selected = NSIntersectionRect(selected, visibleTextRect);
                if (!NSIsEmptyRect(selected)) [selectionRects addObject:[NSValue valueWithRect:selected]];
            }];
            node.textSelectionRects = selectionRects;
        }
    }
    // Marked text is system composition state, not a second text resource.
    // Its underline follows the same visible TextKit fragments as selection
    // geometry, preserving preedit feedback without another body texture.
    NSRange markedRange = self.inputProxy.markedRange;
    if (markedRange.location != NSNotFound && markedRange.length > 0 && visibleGlyphs.length > 0) {
        markedRange.location = MIN(markedRange.location, value.length);
        markedRange.length = MIN(markedRange.length, value.length - markedRange.location);
        NSRange visibleCharacters = [layoutManager characterRangeForGlyphRange:visibleGlyphs actualGlyphRange:NULL];
        NSRange markedCharacters = NSIntersectionRange(markedRange, visibleCharacters);
        if (markedCharacters.length > 0) {
            NSRange markedGlyphs = [layoutManager glyphRangeForCharacterRange:markedCharacters actualCharacterRange:NULL];
            NSMutableArray<NSValue *> *markedRects = [NSMutableArray array];
            [layoutManager enumerateLineFragmentsForGlyphRange:markedGlyphs usingBlock:^(NSRect lineRect, NSRect usedRect,
                                                                                           NSTextContainer *lineContainer,
                                                                                           NSRange lineGlyphRange, BOOL *stop) {
                (void)lineRect; (void)usedRect; (void)lineContainer; (void)stop;
                NSRange intersection = NSIntersectionRange(lineGlyphRange, markedGlyphs);
                if (intersection.length == 0) return;
                NSRect marked = [layoutManager boundingRectForGlyphRange:intersection inTextContainer:container];
                marked.origin.x += origin.x; marked.origin.y += origin.y;
                marked = NSIntersectionRect(marked, visibleTextRect);
                if (NSIsEmptyRect(marked)) return;
                marked.origin.y = NSMaxY(marked) - 1.0;
                marked.size.height = 1.0;
                [markedRects addObject:[NSValue valueWithRect:marked]];
            }];
            node.textMarkedRects = markedRects;
        }
    }
    if (selection.length != 0 || self.window.firstResponder != self.inputProxy || value.length == 0) return;
    NSUInteger location = MIN(selection.location, value.length);
    NSUInteger character = location >= value.length ? value.length - 1 : location;
    [self ensureActiveLayoutForCharacterRange:NSMakeRange(character, 1) layoutManager:layoutManager];
    NSUInteger glyph = [self activeGlyphIndexForCharacter:character layoutManager:layoutManager];
    BOOL usesExtraLine = location == value.length && layoutManager.extraLineFragmentTextContainer == container &&
        !NSIsEmptyRect(layoutManager.extraLineFragmentRect);
    NSRect line = usesExtraLine ? layoutManager.extraLineFragmentRect :
        [self activeLineFragmentForGlyph:glyph layoutManager:layoutManager];
    NSPoint glyphPoint = usesExtraLine ? layoutManager.extraLineFragmentUsedRect.origin :
        [self activeGlyphLocation:glyph layoutManager:layoutManager];
    CGFloat caretX = usesExtraLine ? glyphPoint.x : (location >= value.length ? NSMaxX(line) : glyphPoint.x);
    NSRect caret = NSMakeRect(origin.x + caretX, origin.y + NSMinY(line) + 2.0, 1.0, MAX(1.0, NSHeight(line) - 4.0));
    caret = NSIntersectionRect(caret, visibleTextRect);
    if (!NSIsEmptyRect(caret)) node.textCaretRect = caret;
}
- (void)drawMultilineNode:(CJGuiInternalComposableSceneNode *)node active:(BOOL)active
          outLayoutMicros:(uint64_t *)outLayoutMicros outDrawMicros:(uint64_t *)outDrawMicros
           outSaveMicros:(uint64_t *)outSaveMicros outClipMicros:(uint64_t *)outClipMicros
        outRestoreMicros:(uint64_t *)outRestoreMicros outGlyphs:(NSUInteger *)outGlyphs {
    if (outLayoutMicros) *outLayoutMicros = 0;
    if (outDrawMicros) *outDrawMicros = 0;
    if (outSaveMicros) *outSaveMicros = 0;
    if (outClipMicros) *outClipMicros = 0;
    if (outRestoreMicros) *outRestoreMicros = 0;
    if (outGlyphs) *outGlyphs = 0;
    uint64_t layoutStarted = CjguiMonotonicMicros();
    NSRect rect = CjguiComposableRect(node, self);
    NSRect clip = NSIntersectionRect(rect, CjguiComposableClipBounds(node));
    NSRect contentRect = NSInsetRect(rect, 7.0, 6.0);
    NSRect visibleTextRect = NSIntersectionRect(contentRect, clip);
    if (NSIsEmptyRect(visibleTextRect)) return;
    NSString *value = active ? self.inputProxy.string : node.value;
    if (!value) value = @"";
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                              blue:node.node.textBlue alpha:1.0];
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = NSLineBreakByWordWrapping;
    NSFont *font = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: font,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    NSLayoutManager *layoutManager = nil;
    NSTextContainer *container = nil;
    CGFloat maximumScroll = 0.0;
    if (active) {
        self.inputProxy.textContainer.maximumNumberOfLines = 0;
        self.inputProxy.textContainer.lineBreakMode = NSLineBreakByWordWrapping;
        layoutManager = self.inputProxy.layoutManager;
        container = self.inputProxy.textContainer;
        container.containerSize = NSMakeSize(NSWidth(contentRect), CGFLOAT_MAX);
        container.widthTracksTextView = NO;
        if (self.activeTextLayoutNeedsVisibleGlyphs) {
            NSUInteger length = value.length;
            if (length > 0) {
                NSUInteger location = MIN(self.inputProxy.selectedRange.location, length);
                NSUInteger character = location >= length ? length - 1 : location;
                [layoutManager ensureGlyphsForCharacterRange:NSMakeRange(character, 1)];
            }
            self.activeTextLayoutNeedsVisibleGlyphs = NO;
        }
        // A width/style invalidation must not clamp the viewport to zero just
        // because total height has not yet been requested. Re-establish an
        // existing character anchor with a range layout query instead.
        if (self.activeTextHasScrollAnchor && value.length > 0) {
            NSUInteger anchor = MIN(self.activeTextScrollAnchorCharacter, value.length - 1);
            [self ensureActiveLayoutForCharacterRange:NSMakeRange(anchor, 1) layoutManager:layoutManager];
            NSUInteger anchorGlyph = [self activeGlyphIndexForCharacter:anchor layoutManager:layoutManager];
            NSRect anchorLine = [self activeLineFragmentForGlyph:anchorGlyph layoutManager:layoutManager];
            [self setMultilineScrollOffset:MAX(0.0, NSMinY(anchorLine) - self.activeTextScrollAnchorViewportOffset)
                                  forNode:node];
        }
        maximumScroll = self.activeTextHasExactContentHeight
            ? MAX(0.0, self.activeTextKnownContentHeight - NSHeight(contentRect)) : CGFLOAT_MAX;
    } else {
        CJGuiInternalComposableMultilineLayoutCacheEntry *entry = [self cachedMultilineLayoutForNode:node
                                                                                                  value:value
                                                                                             attributes:attributes
                                                                                           contentWidth:NSWidth(contentRect)];
        layoutManager = entry.layoutManager;
        container = entry.container;
        maximumScroll = MAX(0.0, entry.maximumScroll - NSHeight(contentRect));
    }
    CGFloat scroll = MAX(0.0, [self multilineScrollOffsetForNode:node]);
    if (maximumScroll != CGFLOAT_MAX) scroll = MIN(maximumScroll, scroll);
    [self setMultilineScrollOffset:scroll forNode:node];
    NSRect visibleLayoutRect = NSMakeRect(0.0, scroll, NSWidth(contentRect), NSHeight(contentRect));
    if (active) [self ensureActiveLayoutForBoundingRect:visibleLayoutRect container:container layoutManager:layoutManager];
    NSRange visibleGlyphs = active ? [layoutManager glyphRangeForBoundingRectWithoutAdditionalLayout:visibleLayoutRect
                                                                                   inTextContainer:container] :
        [layoutManager glyphRangeForBoundingRect:visibleLayoutRect inTextContainer:container];
    if (visibleGlyphs.location == NSNotFound) visibleGlyphs = NSMakeRange(0, 0);
    if (outLayoutMicros) *outLayoutMicros = CjguiMonotonicMicros() - layoutStarted;
    if (outGlyphs) *outGlyphs = visibleGlyphs.length;
#ifdef CJGUI_INTERNAL_TESTING
    if (active && CjguiTestVerboseGlyphDiagnosticsEnabled()) {
        NSDictionary *firstAttributes = value.length > 0 ? [self.inputProxy.textStorage attributesAtIndex:0 effectiveRange:NULL] : @{};
        NSLog(@"cjgui: multiline raster geometry node=%llu value=%lu glyphs=%lu:%lu scroll=%.2f content=%@ visible=%@ container=%@ used=%@",
              node.node.nodeId, (unsigned long)value.length, (unsigned long)visibleGlyphs.location,
              (unsigned long)visibleGlyphs.length, scroll, NSStringFromRect(contentRect),
              NSStringFromRect(visibleTextRect), NSStringFromSize(container.containerSize),
              NSStringFromRect([layoutManager usedRectForTextContainer:container]));
        NSLog(@"cjgui: multiline raster attributes font=%@ color=%@", firstAttributes[NSFontAttributeName], firstAttributes[NSForegroundColorAttributeName]);
    }
#endif
    uint64_t graphicsStarted = CjguiMonotonicMicros();
    [NSGraphicsContext saveGraphicsState];
    if (outSaveMicros) *outSaveMicros = CjguiMonotonicMicros() - graphicsStarted;
    uint64_t clipStarted = CjguiMonotonicMicros();
    CjguiClipComposableNode(node, self);
    NSRectClip(visibleTextRect);
    if (outClipMicros) *outClipMicros = CjguiMonotonicMicros() - clipStarted;
    NSPoint origin = NSMakePoint(NSMinX(contentRect), NSMinY(contentRect) - scroll);
#ifdef CJGUI_INTERNAL_TESTING
    if (active) CjguiLogMultilineGlyphDrawingState(node.node.nodeId, layoutManager, container, visibleGlyphs, origin, value);
#endif
    uint64_t drawStarted = CjguiMonotonicMicros();
    // TextKit paints run backgrounds separately from glyphs. Use the exact
    // visible glyph range and scrolled origin shared by the focused body.
    [layoutManager drawBackgroundForGlyphRange:visibleGlyphs atPoint:origin];
    [layoutManager drawGlyphsForGlyphRange:visibleGlyphs atPoint:origin];
    if (outDrawMicros) *outDrawMicros = CjguiMonotonicMicros() - drawStarted;
    uint64_t restoreStarted = CjguiMonotonicMicros();
    [NSGraphicsContext restoreGraphicsState];
    if (outRestoreMicros) *outRestoreMicros = CjguiMonotonicMicros() - restoreStarted;
}
- (id<MTLTexture>)rasterizeMultilineNode:(CJGuiInternalComposableSceneNode *)node
                                   active:(BOOL)active
                                    scale:(CGFloat)scale
                                 tileRect:(NSRect)textureRect
                             outByteCount:(uint64_t *)outByteCount
                           outTextureRect:(NSRect *)outTextureRect
#ifdef CJGUI_INTERNAL_TESTING
                                   reason:(CjguiInternalTextWorkReason)reason
#endif
                                   {
    if (outByteCount) *outByteCount = 0;
    if (outTextureRect) *outTextureRect = NSZeroRect;
    uint64_t rasterStarted = CjguiMonotonicMicros();
    CJGuiInternalMetalView *metalView = self.session.view;
    if (!metalView || !node || node.node.width <= 0 || node.node.height <= 0) return nil;
    if (NSIsEmptyRect(textureRect)) return nil;
    NSUInteger width = 0, height = 0, bytesPerRow = 0;
    uint64_t byteCount = 0;
    if (!CjguiCheckedComposableTextTextureBytes(NSWidth(textureRect), NSHeight(textureRect),
                                                scale, scale, &width, &height, &bytesPerRow, &byteCount)) return nil;
    NSMutableData *bgra = [NSMutableData dataWithLength:(NSUInteger)byteCount];
    CjguiAddTextCpuScratch(metalView, bgra ? byteCount : 0);
    CGColorSpaceRef colorSpace = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef bitmap = colorSpace ? CGBitmapContextCreate(bgra.mutableBytes, width, height, 8, bytesPerRow,
        colorSpace, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little) : NULL;
    if (colorSpace) CGColorSpaceRelease(colorSpace);
    NSGraphicsContext *context = bitmap ? [NSGraphicsContext graphicsContextWithCGContext:bitmap flipped:YES] : nil;
    if (!bgra || !bitmap || !context) { if (bitmap) CGContextRelease(bitmap); CjguiDropTextCpuScratch(metalView, byteCount); return nil; }
    uint64_t allocationMicros = CjguiMonotonicMicros() - rasterStarted;
    NSGraphicsContext *previousContext = NSGraphicsContext.currentContext;
    [NSGraphicsContext setCurrentContext:context];
#ifdef CJGUI_INTERNAL_TESTING
    if (CjguiTestVerboseGlyphDiagnosticsEnabled()) NSLog(@"cjgui: multiline offscreen target node=%llu bitmap=%p current=%p flipped=%d size=%lux%lu scale=%.3f",
          node.node.nodeId, bitmap, NSGraphicsContext.currentContext.CGContext,
          NSGraphicsContext.currentContext.isFlipped, (unsigned long)width, (unsigned long)height, scale);
#endif
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *transform = [NSAffineTransform transform];
    [transform scaleXBy:scale yBy:scale];
    [transform translateXBy:(NSMinX(textureRect) - (CGFloat)node.node.x) * -1.0
                       yBy:(NSMinY(textureRect) - (CGFloat)node.node.y) * -1.0];
    [transform concat];
    CJGuiInternalComposableSceneNode *localNode = [[CJGuiInternalComposableSceneNode alloc] init];
    CjguiInternalRendererComposableNode localValue = node.node;
    localValue.x = 0; localValue.y = 0;
    localValue.clipX -= node.node.x; localValue.clipY -= node.node.y;
    if (localValue.clipConstraintCount > 0 &&
        localValue.clipConstraintCount <= CJGUI_INTERNAL_COMPOSABLE_CLIP_CONSTRAINT_CAPACITY) {
        localValue.clip0X -= node.node.x; localValue.clip0Y -= node.node.y;
        localValue.clip1X -= node.node.x; localValue.clip1Y -= node.node.y;
        localValue.clip2X -= node.node.x; localValue.clip2Y -= node.node.y;
        localValue.clip3X -= node.node.x; localValue.clip3Y -= node.node.y;
    }
    localNode.node = localValue; localNode.label = node.label; localNode.value = node.value;
    // This calls the same active TextKit graph/cache used for input, scroll,
    // selection and candidate geometry.  No second editable body or layout
    // owner is created for the Metal projection.
    uint64_t contextPrepareMicros = CjguiMonotonicMicros() - rasterStarted - allocationMicros;
    uint64_t drawMethodStarted = CjguiMonotonicMicros();
    uint64_t layoutMicros = 0, drawMicros = 0, saveMicros = 0, clipMicros = 0, restoreMicros = 0;
    NSUInteger drawnGlyphs = 0;
    [self drawMultilineNode:localNode active:active outLayoutMicros:&layoutMicros
            outDrawMicros:&drawMicros outSaveMicros:&saveMicros outClipMicros:&clipMicros
            outRestoreMicros:&restoreMicros outGlyphs:&drawnGlyphs];
    uint64_t drawMethodMicros = CjguiMonotonicMicros() - drawMethodStarted;
    uint64_t contextRestoreStarted = CjguiMonotonicMicros();
    [NSGraphicsContext restoreGraphicsState];
    [NSGraphicsContext setCurrentContext:previousContext];
    uint64_t contextRestoreMicros = CjguiMonotonicMicros() - contextRestoreStarted;
    uint8_t *pixels = bgra.mutableBytes;
    uint64_t normalizeStarted = CjguiMonotonicMicros();
#ifdef CJGUI_INTERNAL_TESTING
    NSUInteger firstX = width, firstY = height, lastX = 0, lastY = 0;
    BOOL hasPixels = NO;
#endif
    for (NSUInteger y = 0; y < height; y++) {
        uint8_t *row = pixels + y * bytesPerRow;
        for (NSUInteger x = 0; x < width; x++) {
            uint8_t *pixel = row + x * 4;
            uint8_t alpha = pixel[3];
            pixel[0] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[0] * 255 + alpha / 2) / alpha);
            pixel[1] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[1] * 255 + alpha / 2) / alpha);
            pixel[2] = alpha == 0 ? 0 : (uint8_t)MIN(255, (pixel[2] * 255 + alpha / 2) / alpha);
        }
    }
    uint64_t normalizeMicros = CjguiMonotonicMicros() - normalizeStarted;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t alphaScanStarted = CjguiMonotonicMicros();
    if (CjguiTestVerboseGlyphDiagnosticsEnabled() || CjguiTestTileCostDiagnosticsEnabled()) {
        for (NSUInteger y = 0; y < height; y++) {
            uint8_t *row = pixels + y * bytesPerRow;
            for (NSUInteger x = 0; x < width; x++) {
                if (row[x * 4 + 3] == 0) continue;
                hasPixels = YES; firstX = MIN(firstX, x); firstY = MIN(firstY, y);
                lastX = MAX(lastX, x); lastY = MAX(lastY, y);
            }
        }
    }
    uint64_t alphaScanMicros = CjguiMonotonicMicros() - alphaScanStarted;
    if (active && CjguiTestVerboseGlyphDiagnosticsEnabled()) NSLog(@"cjgui: multiline raster bitmap node=%llu hasPixels=%d bounds=%lu,%lu-%lu,%lu size=%lux%lu",
                      node.node.nodeId, hasPixels, (unsigned long)firstX, (unsigned long)firstY,
                      (unsigned long)lastX, (unsigned long)lastY, (unsigned long)width, (unsigned long)height);
#endif
    uint64_t bitmapReleaseStarted = CjguiMonotonicMicros();
    CGContextRelease(bitmap);
    uint64_t bitmapReleaseMicros = CjguiMonotonicMicros() - bitmapReleaseStarted;
    uint64_t textureCreateStarted = CjguiMonotonicMicros();
    MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                                                                            width:width height:height mipmapped:NO];
    descriptor.usage = MTLTextureUsageShaderRead;
    descriptor.storageMode = MTLStorageModeShared;
    id<MTLTexture> texture = [metalView.device newTextureWithDescriptor:descriptor];
    if (!texture) { CjguiDropTextCpuScratch(metalView, byteCount); return nil; }
    uint64_t textureCreateMicros = CjguiMonotonicMicros() - textureCreateStarted;
 #ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadStarted = CjguiMonotonicMicros();
    uint64_t recordStarted = uploadStarted;
    NSString *recordedText = active ? self.inputProxy.string : node.value;
    CjguiRecordTextWork(metalView, node.node.projectionVersion,
                        [recordedText lengthOfBytesUsingEncoding:NSUTF8StringEncoding], reason);
    uint64_t recordMicros = CjguiMonotonicMicros() - recordStarted;
    metalView.testComposableTextRasterCount = CjguiSaturatingAddU64(metalView.testComposableTextRasterCount, 1);
    metalView.testComposableTextRasterBytes = CjguiSaturatingAddU64(metalView.testComposableTextRasterBytes, byteCount);
    metalView.testComposableTextRasterMicros = CjguiSaturatingAddU64(metalView.testComposableTextRasterMicros,
                                                                       uploadStarted - rasterStarted);
#endif
    [texture replaceRegion:MTLRegionMake2D(0, 0, width, height) mipmapLevel:0 withBytes:bgra.bytes bytesPerRow:bytesPerRow];
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t uploadEnded = CjguiMonotonicMicros();
    if (active && CjguiTestTileCostDiagnosticsEnabled()) {
        NSLog(@"CJGUI_ACTIVE_TILE_COST node=%llu rect=%@ pixels=%llu glyphs=%lu allocation_us=%llu context_prepare_us=%llu draw_method_us=%llu layout_us=%llu save_us=%llu clip_us=%llu draw_us=%llu restore_us=%llu context_restore_us=%llu normalize_us=%llu alpha_scan_us=%llu bitmap_release_us=%llu texture_create_us=%llu record_us=%llu upload_us=%llu total_us=%llu",
              (unsigned long long)node.node.nodeId, NSStringFromRect(textureRect),
              (unsigned long long)(width * height), (unsigned long)drawnGlyphs,
              (unsigned long long)allocationMicros, (unsigned long long)contextPrepareMicros,
              (unsigned long long)drawMethodMicros, (unsigned long long)layoutMicros,
              (unsigned long long)saveMicros, (unsigned long long)clipMicros,
              (unsigned long long)drawMicros, (unsigned long long)restoreMicros,
              (unsigned long long)contextRestoreMicros,
              (unsigned long long)normalizeMicros, (unsigned long long)alphaScanMicros,
              (unsigned long long)bitmapReleaseMicros, (unsigned long long)textureCreateMicros,
              (unsigned long long)recordMicros,
              (unsigned long long)(uploadEnded - uploadStarted),
              (unsigned long long)(uploadEnded - rasterStarted));
    }
    metalView.testComposableTextUploadCount = CjguiSaturatingAddU64(metalView.testComposableTextUploadCount, 1);
    metalView.testComposableTextUploadBytes = CjguiSaturatingAddU64(metalView.testComposableTextUploadBytes, byteCount);
    metalView.testComposableTextUploadMicros = CjguiSaturatingAddU64(metalView.testComposableTextUploadMicros,
                                                                       uploadEnded - uploadStarted);
#endif
    if (outByteCount) *outByteCount = byteCount;
    if (outTextureRect) *outTextureRect = textureRect;
    CjguiDropTextCpuScratch(metalView, byteCount);
    return texture;
}
- (void)refreshGpuTextForActiveInput {
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t refreshStarted = CjguiMonotonicMicros();
#endif
    CJGuiInternalMetalView *metalView = self.session.view;
    if (!metalView || self.activeNodeId == 0 || !CjguiComposableNodeIsTextInput(self.activeNodeKind)) return;
    CJGuiInternalComposableSceneNode *active = nil;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        if (node.node.nodeId == self.activeNodeId && node.index == self.activeNodeIndex &&
            node.node.resourceId == self.activeNodeResourceId && node.node.nodeKind == self.activeNodeKind &&
            node.node.projectionVersion == self.activeProjectionVersion) {
            active = node;
            break;
        }
    }
    if (!active || active.node.clipWidth <= 0 || active.node.clipHeight <= 0) return;
#ifdef CJGUI_INTERNAL_TESTING
    if (self.session.testMidworkArmed &&
        active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        CJGuiInternalSession *source = self.session;
        source.testMidworkArmed = NO;
        uint64_t sourceToken = source.rendererSessionToken;
        uint64_t epoch = source.testMidworkEpoch;
        uint64_t targetToken = source.testMidworkTargetSession;
        uint32_t targetIndex = source.testMidworkTargetIndex;
        uint32_t eventKind = source.testMidworkEventKind;
        NSString *payload = [source.testMidworkText copy] ?: @"";
        uint32_t delayMicros = source.testMidworkDelayMicros;
        source.testMidworkAStartMicros = CjguiMonotonicMicros();
        source.testMidworkProducerReadyMicros = source.testMidworkAStartMicros;
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)delayMicros * NSEC_PER_USEC),
                       dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            uint64_t posted = CjguiMonotonicMicros();
            dispatch_async(dispatch_get_main_queue(), ^{
                CJGuiInternalSession *liveSource = CjguiLookupSession(sourceToken);
                if (!liveSource || liveSource.testMidworkEpoch != epoch) return;
                liveSource.testMidworkProducerPostMicros = posted;
                CJGuiInternalSession *target = CjguiLookupSession(targetToken);
                liveSource.testMidworkEnqueueStatus = target &&
                    CjguiEnqueueComposableInteraction(target, eventKind, targetIndex,
                                                      payload, NSMakeRange(0, 0))
                    ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
                liveSource.testMidworkNativeEnqueueMicros = CjguiMonotonicMicros();
            });
        });
    }
#endif
    NSString *activeValue = self.inputProxy.string ?: @"";
    CGFloat scale = [metalView currentBackingScale];
    scale = MAX(1.0, scale);
    if (active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        [self prepareActiveMultilineFallbackRunsForNode:active];
        NSArray<NSValue *> *previousSelectionRects = active.textSelectionRects;
        NSArray<NSValue *> *previousMarkedRects = active.textMarkedRects;
        NSRect previousCaretRect = active.textCaretRect;
        NSRect previousScrollbarRect = active.textScrollbarRect;
#ifdef CJGUI_INTERNAL_TESTING
        uint64_t decorationsStarted = CjguiMonotonicMicros();
#endif
        [self updateActiveMultilineTextDecorationsForNode:active];
        [self applyDeclaredInputCaretToNode:active];
#ifdef CJGUI_INTERNAL_TESTING
        self.testInputCallbackTrace.decorationsMicros += CjguiMonotonicMicros() - decorationsStarted;
        uint64_t keyStarted = CjguiMonotonicMicros();
#endif
        NSRect textureRect = CjguiComposableTextTextureRectForNode(active);
        // The key must cover every input that changes the derived pixels:
        // body generation (content), attributed generation (framework/runs/
        // composition attribute content), layout signature, the caller-owned
        // runs, scroll/scale/viewport and clip. The DYNAMIC text alpha is
        // deliberately absent — it is applied once at encode and must never
        // invalidate this cached texture.
        NSString *runsSignature = [self activeTextRunsSignatureForNode:active];
        NSString *key = [NSString stringWithFormat:@"multiline:%llu:%llu:%@:%@:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%0.3f:%@",
            (unsigned long long)self.activeTextBodyGeneration,
            (unsigned long long)self.activeTextAttributedGeneration,
            self.activeTextLayoutSignature ?: @"",
            runsSignature ?: @"",
            [self multilineScrollOffsetForNode:active], scale,
            NSMinX(textureRect), NSMinY(textureRect), NSWidth(textureRect), NSHeight(textureRect),
            NSMinX(textureRect) - (CGFloat)active.node.x, NSMinY(textureRect) - (CGFloat)active.node.y,
            CjguiComposableTextClipSignature(active)];
#ifdef CJGUI_INTERNAL_TESTING
        self.testInputCallbackTrace.keyConstructionMicros += CjguiMonotonicMicros() - keyStarted;
#endif
        BOOL forceFullBodyPreparation = NO;
#ifdef CJGUI_INTERNAL_TESTING
        forceFullBodyPreparation = self.testForceFullBodyPreparationOnSelection;
#endif
        if (!(active.textTexture || active.textTileTextures.count > 0) || forceFullBodyPreparation ||
            ![active.textTextureCacheKey isEqualToString:key]) {
#ifdef CJGUI_INTERNAL_TESTING
            CjguiInternalTextWorkReason reason = self.testActiveTextWorkReason;
            self.testForceFullBodyPreparationOnSelection = NO;
            if ([self.activeTextTextureRetryKey isEqualToString:key] && self.activeTextTextureRetryCount > 0) {
                reason = CjguiInternalTextWorkReasonRetry;
            }
#endif
            if (![self.activeTextTextureRetryKey isEqualToString:key]) {
                self.activeTextTextureRetryKey = key;
                self.activeTextTextureRetryCount = 0;
                self.activeTextTexturePreparationFailed = NO;
            }
            uint64_t plannedBytes = 0, actualBytes = 0;
            NSArray<NSValue *> *tileRects = CjguiPlanComposableTextTiles(textureRect, scale, &plannedBytes);
            NSMutableArray<id<MTLTexture>> *prepared = [NSMutableArray arrayWithCapacity:tileRects.count];
            NSString *oldKey = active.textTextureCacheKey ?: @"";
            NSRange oldPrefix = [oldKey rangeOfString:@":"];
            NSRange newPrefix = [key rangeOfString:@":"];
            NSRange oldSeparator = oldPrefix.location == NSNotFound ? NSMakeRange(NSNotFound, 0) :
                [oldKey rangeOfString:@":" options:0 range:NSMakeRange(NSMaxRange(oldPrefix),
                                                              oldKey.length - NSMaxRange(oldPrefix))];
            NSRange newSeparator = newPrefix.location == NSNotFound ? NSMakeRange(NSNotFound, 0) :
                [key rangeOfString:@":" options:0 range:NSMakeRange(NSMaxRange(newPrefix),
                                                           key.length - NSMaxRange(newPrefix))];
            BOOL mayReuseOtherTiles = self.activeTextDirtyVisibleRectValid &&
                !self.activeTextTexturePreparationFailed && !forceFullBodyPreparation &&
                oldSeparator.location != NSNotFound && newSeparator.location != NSNotFound &&
                [[oldKey substringFromIndex:NSMaxRange(oldSeparator)]
                    isEqualToString:[key substringFromIndex:NSMaxRange(newSeparator)]] &&
                active.textTileTextures.count == tileRects.count &&
                active.textTileRects.count == tileRects.count;
            BOOL admitted = tileRects.count > 0 &&
                CjguiComposableTextTextureFitsSceneBudget(self.nodes, active, plannedBytes);
#ifdef CJGUI_INTERNAL_TESTING
            if (self.session.forcedComposableTextPreparationFailures > 0) {
                self.session.forcedComposableTextPreparationFailures -= 1;
                admitted = NO;
            } else
#endif
            if (admitted) {
                for (NSUInteger tileIndex = 0; tileIndex < tileRects.count; tileIndex++) {
                    NSValue *rectValue = tileRects[tileIndex];
                    if (mayReuseOtherTiles &&
                        NSEqualRects(active.textTileRects[tileIndex].rectValue, rectValue.rectValue) &&
                        !NSIntersectsRect(self.activeTextDirtyVisibleRect, rectValue.rectValue)) {
                        id<MTLTexture> retained = active.textTileTextures[tileIndex];
                        NSUInteger expectedWidth = 0, expectedHeight = 0, expectedRow = 0;
                        uint64_t expectedBytes = 0;
                        if (retained && CjguiCheckedComposableTextTextureBytes(
                                NSWidth(rectValue.rectValue), NSHeight(rectValue.rectValue), scale, scale,
                                &expectedWidth, &expectedHeight, &expectedRow, &expectedBytes) &&
                            retained.width == expectedWidth && retained.height == expectedHeight) {
                            [prepared addObject:retained];
                            actualBytes += expectedBytes;
                            continue;
                        }
                    }
                    @autoreleasepool {
                        uint64_t tileBytes = 0;
                        id<MTLTexture> texture = [self rasterizeMultilineNode:active active:YES scale:scale
                                          tileRect:rectValue.rectValue
                                          outByteCount:&tileBytes outTextureRect:NULL
#ifdef CJGUI_INTERNAL_TESTING
                                          reason:reason
#endif
                                          ];
                        if (!texture || tileBytes == 0) { admitted = NO; break; }
                        [prepared addObject:texture];
                        actualBytes += tileBytes;
                    }
                }
            }
            if (admitted && prepared.count == tileRects.count && actualBytes == plannedBytes) {
                active.textTexture = prepared.count == 1 ? prepared.firstObject : nil;
                active.textTileTextures = prepared.count > 1 ? [prepared copy] : nil;
                active.textTileRects = prepared.count > 1 ? tileRects : nil;
                active.textTextureByteCount = actualBytes; active.textTextureCacheKey = key;
                active.textTextureRect = textureRect;
                self.activeTextDirtyVisibleRectValid = NO;
                self.activeTextTextureRetryKey = nil;
                self.activeTextTextureRetryCount = 0;
                self.activeTextTexturePreparationFailed = NO;
#ifdef CJGUI_INTERNAL_TESTING
                self.testActiveTextWorkReason = CjguiInternalTextWorkReasonUnknown;
#endif
            } else {
                // Do not discard the accepted projection while a derived
                // active texture allocation fails. One deferred retry handles
                // transient pressure even when the user types nothing else;
                // a repeated failure remains explicit and bounded.
                // Decorations belong to the same accepted content snapshot:
                // do not let a new caret/selection geometry overlay an old
                // retained body while this candidate is still rejected.
                active.textSelectionRects = previousSelectionRects;
                active.textMarkedRects = previousMarkedRects;
                active.textCaretRect = previousCaretRect;
                active.textScrollbarRect = previousScrollbarRect;
                self.activeTextTexturePreparationFailed = YES;
                if (self.activeTextTextureRetryCount < 1) {
                    self.activeTextTextureRetryCount += 1;
                    [self scheduleActiveTextResourcePreparation];
                }
            }
        }
        [metalView setNeedsDisplay:YES];
#ifdef CJGUI_INTERNAL_TESTING
        if (self.session.testMidworkAStartMicros > 0 && self.session.testMidworkAEndMicros == 0)
            self.session.testMidworkAEndMicros = CjguiMonotonicMicros();
        self.testInputCallbackTrace.refreshMicros += CjguiMonotonicMicros() - refreshStarted;
#endif
        return;
    }
    NSString *displayText = CjguiComposableGpuTextValueWithActiveValue(active, activeValue);
    NSUInteger prefixLength = active.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT || active.label.length == 0
        ? 0 : active.label.length + 1;
    NSRange selected = CjguiComposedSelection(activeValue, self.inputProxy.selectedRange.location,
                                              NSMaxRange(self.inputProxy.selectedRange));
    selected.location = MIN(displayText.length, prefixLength + selected.location);
    selected.length = MIN(selected.length, displayText.length - selected.location);
    NSRange marked = self.inputProxy.markedRange;
    if (marked.location != NSNotFound) {
        marked.location = MIN(displayText.length, prefixLength + marked.location);
        marked.length = MIN(marked.length, displayText.length - marked.location);
    }
    BOOL drawsCaret = selected.length == 0 && self.window.firstResponder == self.inputProxy;
    NSArray<NSValue *> *previousSelectionRects = active.textSelectionRects;
    NSArray<NSValue *> *previousMarkedRects = active.textMarkedRects;
    NSRect previousCaretRect = active.textCaretRect;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t decorationsStarted = CjguiMonotonicMicros();
#endif
    [self updateActiveSingleLineTextDecorationsForNode:active displayText:displayText selection:selected
                                            markedRange:marked drawsCaret:drawsCaret];
    [self applyDeclaredInputCaretToNode:active];
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.decorationsMicros += CjguiMonotonicMicros() - decorationsStarted;
    uint64_t keyStarted = CjguiMonotonicMicros();
#endif
    NSRect textureRect = CjguiComposableTextTextureRectForNodeWithText(active, displayText);
    NSString *key = CjguiComposableTextTextureKey(active, scale, scale, displayText, textureRect);
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.keyConstructionMicros += CjguiMonotonicMicros() - keyStarted;
#endif
    if (!active.textTexture || ![active.textTextureCacheKey isEqualToString:key]) {
#ifdef CJGUI_INTERNAL_TESTING
        CjguiInternalTextWorkReason reason = self.testActiveTextWorkReason;
        if ([self.activeTextTextureRetryKey isEqualToString:key] && self.activeTextTextureRetryCount > 0) {
            reason = CjguiInternalTextWorkReasonRetry;
        }
#endif
        if (![self.activeTextTextureRetryKey isEqualToString:key]) {
            self.activeTextTextureRetryKey = key;
            self.activeTextTextureRetryCount = 0;
            self.activeTextTexturePreparationFailed = NO;
        }
        uint64_t byteCount = 0;
        id<MTLTexture> texture = nil;
#ifdef CJGUI_INTERNAL_TESTING
        if (self.session.forcedComposableTextPreparationFailures > 0) {
            self.session.forcedComposableTextPreparationFailures -= 1;
        } else
#endif
        {
            texture = CjguiRasterComposableTextTexture(metalView, active, scale, scale, displayText,
                                                        textureRect, &byteCount, nil
#ifdef CJGUI_INTERNAL_TESTING
                                                        , reason
#endif
                                                        , NULL, 0);
        }
        if (texture && CjguiComposableTextTextureFitsSceneBudget(self.nodes, active, byteCount)) {
            active.textTexture = texture; active.textTextureByteCount = byteCount; active.textTextureCacheKey = key;
            active.textTextureRect = textureRect;
            self.activeTextTextureRetryKey = nil;
            self.activeTextTextureRetryCount = 0;
            self.activeTextTexturePreparationFailed = NO;
#ifdef CJGUI_INTERNAL_TESTING
            self.testActiveTextWorkReason = CjguiInternalTextWorkReasonUnknown;
#endif
        } else {
            // Focused single-line fields share the same accepted-scene budget
            // and bounded recovery contract as focused multiline fields.  The
            // old texture remains installed until an admitted replacement is
            // ready, so an allocation failure cannot blank live input.
            active.textSelectionRects = previousSelectionRects;
            active.textMarkedRects = previousMarkedRects;
            active.textCaretRect = previousCaretRect;
            self.activeTextTexturePreparationFailed = YES;
            if (self.activeTextTextureRetryCount < 1) {
                self.activeTextTextureRetryCount += 1;
                [self scheduleActiveTextResourcePreparation];
            }
        }
    }
    // The TextKit object remains only the first-responder/IME authority. Its
    // glyph body is the derived texture while its transient decorations are
    // regular Metal geometry, and later scene nodes retain painter order.
    [metalView setNeedsDisplay:YES];
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.refreshMicros += CjguiMonotonicMicros() - refreshStarted;
#endif
}
- (void)markActiveTextFallbackRunsDirtyForRange:(NSRange)range {
    self.activeTextFallbackRunsDirty = YES;
    if (self.activeTextFallbackNeedsFullRefresh || range.location == NSNotFound) return;
    if (!self.activeTextFallbackHasDirtyRange) {
        self.activeTextFallbackDirtyRange = range;
        self.activeTextFallbackHasDirtyRange = YES;
        return;
    }
    NSUInteger start = MIN(self.activeTextFallbackDirtyRange.location, range.location);
    NSUInteger leftEnd = NSMaxRange(self.activeTextFallbackDirtyRange);
    NSUInteger rightEnd = NSMaxRange(range);
    if (leftEnd < self.activeTextFallbackDirtyRange.location || rightEnd < range.location) {
        self.activeTextFallbackNeedsFullRefresh = YES;
        self.activeTextFallbackHasDirtyRange = NO;
        return;
    }
    self.activeTextFallbackDirtyRange = NSMakeRange(start, MAX(leftEnd, rightEnd) - start);
}
- (void)markActiveTextFallbackRunsDirtyForWholeValue {
    self.activeTextFallbackRunsDirty = YES;
    self.activeTextFallbackNeedsFullRefresh = YES;
    self.activeTextFallbackHasDirtyRange = NO;
}
- (void)remapActiveTextFallbackDirtyRangeForEditRange:(NSRange)range replacementLength:(NSUInteger)replacementLength {
    if (!self.activeTextFallbackHasDirtyRange || self.activeTextFallbackNeedsFullRefresh ||
        range.location == NSNotFound || range.location > NSUIntegerMax - range.length) return;
    NSRange prior = self.activeTextFallbackDirtyRange;
    if (prior.location == NSNotFound || prior.location > NSUIntegerMax - prior.length) {
        [self markActiveTextFallbackRunsDirtyForWholeValue];
        return;
    }
    NSUInteger editStart = range.location, editEnd = NSMaxRange(range);
    NSUInteger priorStart = prior.location, priorEnd = NSMaxRange(prior);
    if (priorEnd <= editStart) return;
    if (replacementLength > NSUIntegerMax - editStart) {
        [self markActiveTextFallbackRunsDirtyForWholeValue];
        return;
    }
    NSUInteger replacementEnd = editStart + replacementLength;
    NSInteger delta = replacementLength >= range.length
        ? (NSInteger)MIN((NSUInteger)NSIntegerMax, replacementLength - range.length)
        : -(NSInteger)MIN((NSUInteger)NSIntegerMax, range.length - replacementLength);
    NSUInteger mappedStart = priorStart, mappedEnd = priorEnd;
    if (priorStart >= editEnd) {
        if ((delta >= 0 && priorStart > NSUIntegerMax - (NSUInteger)delta) ||
            (delta < 0 && priorStart < (NSUInteger)(-delta)) ||
            (delta >= 0 && priorEnd > NSUIntegerMax - (NSUInteger)delta) ||
            (delta < 0 && priorEnd < (NSUInteger)(-delta))) {
            [self markActiveTextFallbackRunsDirtyForWholeValue];
            return;
        }
        mappedStart = delta >= 0 ? priorStart + (NSUInteger)delta : priorStart - (NSUInteger)(-delta);
        mappedEnd = delta >= 0 ? priorEnd + (NSUInteger)delta : priorEnd - (NSUInteger)(-delta);
    } else {
        // An edit intersects a previously dirty run. Its surviving suffix is
        // shifted into the new document; include both it and replacement.
        mappedStart = MIN(priorStart, editStart);
        if (priorEnd > editEnd) {
            if ((delta >= 0 && priorEnd > NSUIntegerMax - (NSUInteger)delta) ||
                (delta < 0 && priorEnd < (NSUInteger)(-delta))) {
                [self markActiveTextFallbackRunsDirtyForWholeValue];
                return;
            }
            mappedEnd = delta >= 0 ? priorEnd + (NSUInteger)delta : priorEnd - (NSUInteger)(-delta);
        } else {
            mappedEnd = replacementEnd;
        }
        mappedEnd = MAX(mappedEnd, replacementEnd);
    }
    self.activeTextFallbackDirtyRange = NSMakeRange(mappedStart, mappedEnd - mappedStart);
}
- (NSRange)fallbackAffectedRangeAfterEditAt:(NSUInteger)location replacementLength:(NSUInteger)replacementLength
                                      value:(NSString *)value {
    NSUInteger length = value.length;
    if (length == 0) return NSMakeRange(0, 0);
    NSUInteger start = MIN(location, length);
    NSUInteger end = replacementLength > NSUIntegerMax - start ? length : MIN(length, start + replacementLength);
    // Include one adjacent composed sequence on each side: deleting a ZWJ,
    // variation selector or combining mark can join what used to be two runs.
    if (start > 0) start = [value rangeOfComposedCharacterSequenceAtIndex:start - 1].location;
    if (start < length) start = [value rangeOfComposedCharacterSequenceAtIndex:start].location;
    if (end > 0) end = NSMaxRange([value rangeOfComposedCharacterSequenceAtIndex:end - 1]);
    if (end < length) end = NSMaxRange([value rangeOfComposedCharacterSequenceAtIndex:end]);
    return NSMakeRange(start, end - start);
}
- (void)applySystemFallbackRunsToActiveInput {
    if (self.activeNodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT || !self.activeTextBaseFont ||
        self.inputProxy.hasMarkedText) return;
    NSTextStorage *storage = self.inputProxy.textStorage;
    NSString *value = storage.string ?: @"";
    if (value.length == 0) {
        self.activeTextFallbackRunsDirty = NO;
        self.activeTextFallbackNeedsFullRefresh = NO;
        self.activeTextFallbackHasDirtyRange = NO;
        return;
    }
    NSFont *baseFont = self.activeTextBaseFont;
    NSRange requested = self.activeTextFallbackNeedsFullRefresh ? NSMakeRange(0, value.length) :
        (self.activeTextFallbackHasDirtyRange ? self.activeTextFallbackDirtyRange : NSMakeRange(NSNotFound, 0));
    if (requested.location == NSNotFound) {
        self.activeTextFallbackRunsDirty = NO;
        self.activeTextFallbackNeedsFullRefresh = NO;
        self.activeTextFallbackHasDirtyRange = NO;
        return;
    }
    NSUInteger requestedStart = MIN(requested.location, value.length);
    NSUInteger requestedEnd = requested.length > NSUIntegerMax - requestedStart ? value.length :
        MIN(value.length, requestedStart + requested.length);
    // A zero-length deletion still changes the new left/right boundary. The
    // caller normally expands it, but retain a one-cluster fail-safe here.
    if (requestedStart == requestedEnd) {
        if (requestedStart > 0) requestedStart = [value rangeOfComposedCharacterSequenceAtIndex:requestedStart - 1].location;
        if (requestedEnd < value.length) requestedEnd = NSMaxRange([value rangeOfComposedCharacterSequenceAtIndex:requestedEnd]);
    }
    if (requestedStart >= value.length || requestedEnd <= requestedStart) {
        self.activeTextFallbackRunsDirty = NO;
        self.activeTextFallbackNeedsFullRefresh = NO;
        self.activeTextFallbackHasDirtyRange = NO;
        return;
    }
    requested.location = [value rangeOfComposedCharacterSequenceAtIndex:requestedStart].location;
    if (requestedEnd > 0) requestedEnd = NSMaxRange([value rangeOfComposedCharacterSequenceAtIndex:requestedEnd - 1]);
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t fallbackStarted = CjguiMonotonicMicros();
#endif
    BOOL wasApplyingProjection = self.applyingProjection;
    self.applyingProjection = YES;
    [storage beginEditing];
    // Resolved-font cache keyed by the COMPLETE composed sequence string,
    // scoped to this single resolution pass (so a changed font environment or
    // content generation can never hit a stale entry). `CTFontCreateForString`
    // is deterministic for the same base font and same complete range content,
    // and Core Text fallback selection is NOT block/script-based: a cache key
    // may never be a partial sequence or a Unicode block. Large bodies are
    // dominated by a small set of distinct sequences, so this collapses the
    // dominant per-character Core Text calls without changing which font any
    // character resolves to.
    NSMutableDictionary<NSString *, NSFont *> *resolvedCache = [NSMutableDictionary dictionary];
    // First pass: resolve each composed sequence's font (cached), and merge
    // adjacent sequences that resolved to the same font into one run. The
    // input proxy carries a single attribute environment (font is the only
    // field this pass changes), so per-run attributes equal the per-sequence
    // attributes the previous per-sequence writes produced.
    NSMutableArray<NSValue *> *runRanges = [NSMutableArray array];
    NSMutableArray<NSFont *> *runFonts = [NSMutableArray array];
    NSRange pendingRun = NSMakeRange(NSNotFound, 0);
    NSFont *pendingFont = nil;
    for (NSUInteger location = requested.location; location < requestedEnd;) {
        NSRange range = [value rangeOfComposedCharacterSequenceAtIndex:location];
        NSString *sequenceKey = [value substringWithRange:range];
        NSFont *resolvedFont = resolvedCache[sequenceKey];
        if (!resolvedFont) {
            CTFontRef resolved = CTFontCreateForString((__bridge CTFontRef)baseFont,
                                                       (__bridge CFStringRef)value,
                                                       CFRangeMake(range.location, range.length));
            if (resolved) {
                resolvedFont = (__bridge_transfer NSFont *)resolved;
                resolvedCache[sequenceKey] = resolvedFont;
            }
        }
        // Two nil resolutions merge like two equal fonts: the previous
        // implementation skipped unresolved sequences entirely, so a nil run
        // is flushed without any attribute write.
        BOOL sameAsPending = (resolvedFont == nil && pendingFont == nil) ||
            (resolvedFont && pendingFont && [resolvedFont isEqual:pendingFont]);
        if (pendingRun.location == NSNotFound) {
            pendingRun = range;
            pendingFont = resolvedFont;
        } else if (sameAsPending) {
            pendingRun.length = NSMaxRange(range) - pendingRun.location;
        } else {
            [runRanges addObject:[NSValue valueWithRange:pendingRun]];
            [runFonts addObject:pendingFont]; // may be nil: skipped on write
            pendingRun = range;
            pendingFont = resolvedFont;
        }
        location = NSMaxRange(range);
    }
    if (pendingRun.location != NSNotFound) {
        [runRanges addObject:[NSValue valueWithRange:pendingRun]];
        [runFonts addObject:pendingFont];
    }
    // Second pass: only the resolved font belongs to fallback. Copying the
    // first character's entire attribute dictionary across a merged font run
    // would duplicate or erase style-run backgrounds, obliqueness and platform
    // composition attributes at every boundary within that run.
    for (NSUInteger index = 0; index < runRanges.count; index++) {
        NSFont *runFont = runFonts[index];
        if (!runFont) continue;
        NSRange run = runRanges[index].rangeValue;
        [storage addAttribute:NSFontAttributeName value:runFont range:run];
    }
    [storage endEditing];
    self.applyingProjection = wasApplyingProjection;
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.fallbackApplyCount += 1;
    self.testInputCallbackTrace.fallbackCharacters += requestedEnd - requested.location;
    self.testInputCallbackTrace.fallbackMicros += CjguiMonotonicMicros() - fallbackStarted;
#endif
    self.activeTextFallbackRunsDirty = NO;
    self.activeTextFallbackNeedsFullRefresh = NO;
    self.activeTextFallbackHasDirtyRange = NO;
}
// The runs signature the caller published for this node. The session table is
// authoritative (the setter stamps it onto reachable nodes), with the node's
// own stamped field as the fallback for a scene that predates the setter.
- (NSString *)activeTextRunsSignatureForNode:(CJGuiInternalComposableSceneNode *)node {
    NSString *sessionRuns = self.session.composableTextStyleRunsRaw[@(node.node.nodeId)];
    if (sessionRuns) return sessionRuns;
    return node.styleRunsSignature ?: @"";
}

// These private attributes follow a run through TextKit edits. They identify
// precisely which optional decoration was installed by the framework, and
// remember any platform attribute that it temporarily covered. A new scene
// can retire an old run without clearing IME/other TextKit attributes.
static NSString *const CjguiActiveRunBackgroundOwner = @"cjgui.activeRun.backgroundOwner";
static NSString *const CjguiActiveRunObliqueOwner = @"cjgui.activeRun.obliqueOwner";

static void CjguiClearActiveRunAttribute(NSTextStorage *storage, NSString *key,
                                         NSString *ownerKey, NSRange all) {
    NSUInteger cursor = all.location;
    while (cursor < NSMaxRange(all)) {
        NSRange ownedRange = NSMakeRange(0, 0);
        NSDictionary *owner = [storage attribute:ownerKey atIndex:cursor effectiveRange:&ownedRange];
        ownedRange = NSIntersectionRange(ownedRange, all);
        if (ownedRange.length == 0) break;
        if (owner) {
            NSUInteger inner = ownedRange.location;
            while (inner < NSMaxRange(ownedRange)) {
                NSRange currentRange = NSMakeRange(0, 0);
                id current = [storage attribute:key atIndex:inner effectiveRange:&currentRange];
                NSRange slice = NSIntersectionRange(currentRange, ownedRange);
                if (slice.length == 0) break;
                // If the platform changed the decoration after our write,
                // keep that value. Only the exact framework value is retired.
                if (current && [current isEqual:owner[@"applied"]]) {
                    id previous = owner[@"previous"];
                    if (previous == [NSNull null]) {
                        [storage removeAttribute:key range:slice];
                    } else if (previous) {
                        [storage addAttribute:key value:previous range:slice];
                    }
                }
                inner = NSMaxRange(slice);
            }
            [storage removeAttribute:ownerKey range:ownedRange];
        }
        cursor = NSMaxRange(ownedRange);
    }
}

static void CjguiApplyActiveRunAttribute(NSTextStorage *storage, NSString *key,
                                         NSString *ownerKey, id value, NSRange range) {
    NSUInteger cursor = range.location;
    while (cursor < NSMaxRange(range)) {
        NSRange previousRange = NSMakeRange(0, 0);
        id previous = [storage attribute:key atIndex:cursor effectiveRange:&previousRange];
        NSRange slice = NSIntersectionRange(previousRange, range);
        if (slice.length == 0) break;
        NSDictionary *owner = @{ @"applied": value, @"previous": previous ?: [NSNull null] };
        [storage addAttributes:@{ key: value, ownerKey: owner } range:slice];
        cursor = NSMaxRange(slice);
    }
}

// Apply base and style-run attributes without replacing TextKit's whole
// attribute dictionaries. Base font/foreground/paragraph are framework-owned.
// Optional background/oblique belong to individual runs and are retired
// before new runs are layered on; unrelated platform keys survive.
- (void)applyActiveComposableTextAttributesForNode:(CJGuiInternalComposableSceneNode *)node
                                    baseAttributes:(NSDictionary *)baseAttributes {
    NSTextStorage *storage = self.inputProxy.textStorage;
    NSString *value = storage.string ?: @"";
    if (value.length == 0) return;
    NSRange all = NSMakeRange(0, value.length);
    CjguiClearActiveRunAttribute(storage, NSBackgroundColorAttributeName,
                                 CjguiActiveRunBackgroundOwner, all);
    CjguiClearActiveRunAttribute(storage, NSObliquenessAttributeName,
                                 CjguiActiveRunObliqueOwner, all);
    NSArray<NSString *> *frameworkKeys = @[ NSFontAttributeName, NSForegroundColorAttributeName,
                                            NSParagraphStyleAttributeName ];
    for (NSString *key in frameworkKeys) {
        id attributeValue = baseAttributes[key];
        if (attributeValue) [storage addAttribute:key value:attributeValue range:all];
    }
    NSString *encoded = self.session.composableTextStyleRunsRaw[@(node.node.nodeId)];
    NSData *decoded = CjguiComposableDecodeStyleRuns(encoded);
    if (decoded.length == 0) return;
    const CjguiInternalTextStyleRun *runs = (const CjguiInternalTextStyleRun *)decoded.bytes;
    uint32_t runCount = (uint32_t)(decoded.length / sizeof(CjguiInternalTextStyleRun));
    NSAttributedString *attributed = CjguiComposableAttributedText(node, value, baseAttributes, runs, runCount);
    [attributed enumerateAttributesInRange:NSMakeRange(0, attributed.length)
                                   options:0
                                usingBlock:^(NSDictionary<NSAttributedStringKey, id> *attrs,
                                             NSRange range, BOOL *stop) {
        (void)stop;
        NSMutableDictionary *runOwned = [NSMutableDictionary dictionary];
        for (NSString *key in frameworkKeys) {
            id attributeValue = attrs[key];
            if (attributeValue) runOwned[key] = attributeValue;
        }
        if (runOwned.count > 0) [storage addAttributes:runOwned range:range];
        id background = attrs[NSBackgroundColorAttributeName];
        if (background) CjguiApplyActiveRunAttribute(storage, NSBackgroundColorAttributeName,
            CjguiActiveRunBackgroundOwner, background, range);
        id oblique = attrs[NSObliquenessAttributeName];
        if (oblique) CjguiApplyActiveRunAttribute(storage, NSObliquenessAttributeName,
            CjguiActiveRunObliqueOwner, oblique, range);
    }];
}
- (void)prepareActiveMultilineFallbackRunsForNode:(CJGuiInternalComposableSceneNode *)node {
    if (!node || node.node.nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) return;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t preparationStarted = CjguiMonotonicMicros();
#endif
    NSRect contentRect = NSInsetRect(CjguiComposableRect(node, self), 7.0, 6.0);
    // The TextKit storage is the glyph source for BOTH the focused multiline
    // texture and the layout used for selection/caret geometry. Its base
    // foreground is the style-owned OPAQUE colour: the dynamic node alpha is
    // applied exactly once at encode time and must never be baked into the
    // storage, otherwise the focused multiline texture would carry the
    // multiplier and be multiplied again when drawn. A style run's own alpha
    // (style runs) is style-owned and stays on its run.
    NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed green:node.node.textGreen
                                              blue:node.node.textBlue alpha:1.0];
    NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
    paragraph.lineBreakMode = NSLineBreakByWordWrapping;
    NSFont *baseFont = CjguiComposableFont(node);
    NSDictionary *attributes = @{ NSFontAttributeName: baseFont,
                                  NSForegroundColorAttributeName: textColor,
                                  NSParagraphStyleAttributeName: paragraph };
    self.inputProxy.textContainer.maximumNumberOfLines = 0;
    self.inputProxy.textContainer.lineBreakMode = NSLineBreakByWordWrapping;
    self.inputProxy.textContainer.containerSize = NSMakeSize(NSWidth(contentRect), CGFLOAT_MAX);
    self.inputProxy.textContainer.widthTracksTextView = NO;
    NSString *signature = [self activeTextLayoutSignatureForNode:node contentWidth:NSWidth(contentRect)];
    NSString *attributeSignature = [self activeTextAttributeSignatureForNode:node];
    NSString *runsSignature = [self activeTextRunsSignatureForNode:node];
    BOOL attributesChanged = ![attributeSignature isEqualToString:self.activeTextAttributeSignature];
    BOOL layoutChanged = ![signature isEqualToString:self.activeTextLayoutSignature];
    BOOL runsChanged = ![runsSignature isEqualToString:self.activeTextRunsSignature];
    // A composition (preedit) owns the storage while it is live; rewriting the
    // framework attributes then would clobber the input method's own
    // attributes. Defer the rewrite to the first non-composition prepare. The
    // composition event itself bumps the attributed generation, so the texture
    // still invalidates while composing.
    BOOL composing = self.inputProxy.hasMarkedText;
    BOOL storageAttributesChanged = (attributesChanged || runsChanged) && !composing;
    if (layoutChanged || attributesChanged) {
        self.applyingProjection = YES;
        if (storageAttributesChanged) {
            // Only the framework-owned keys and the caller-owned runs are
            // written; other run/composition attributes on the range survive.
            [self applyActiveComposableTextAttributesForNode:node baseAttributes:attributes];
            self.activeTextRunsSignature = runsSignature;
            self.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
            self.testInputCallbackTrace.wholeAttributeWriteCount += 1;
            self.testInputCallbackTrace.wholeAttributeCharacters += self.inputProxy.string.length;
#endif
        }
        self.inputProxy.typingAttributes = attributes;
        self.applyingProjection = NO;
        self.activeTextLayoutSignature = signature;
        // Keep the attribute signature unapplied while composing so the
        // deferred rewrite still fires once the composition ends.
        if (!composing) self.activeTextAttributeSignature = attributeSignature;
        self.activeTextBaseFont = baseFont;
        self.activeTextLayoutNeedsVisibleGlyphs = YES;
        self.activeTextHasExactContentHeight = NO;
        self.activeTextKnownContentHeight = 0.0;
        if (storageAttributesChanged) [self markActiveTextFallbackRunsDirtyForWholeValue];
    } else if (runsChanged && !composing) {
        // Only the caller-owned runs changed; no base layout input moved.
        self.applyingProjection = YES;
        [self applyActiveComposableTextAttributesForNode:node baseAttributes:attributes];
        self.activeTextRunsSignature = runsSignature;
        self.activeTextAttributedGeneration += 1;
        self.applyingProjection = NO;
        [self markActiveTextFallbackRunsDirtyForWholeValue];
    } else if (!self.activeTextBaseFont) {
        // A reused active identity can retain its layout signature across a
        // native focus hand-off; restore the value-owned base deterministically.
        self.activeTextBaseFont = baseFont;
    }
    if (self.activeTextFallbackRunsDirty && !self.inputProxy.hasMarkedText) {
        [self applySystemFallbackRunsToActiveInput];
        self.activeTextFallbackRunsDirty = NO;
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.testInputCallbackTrace.preparationMicros += CjguiMonotonicMicros() - preparationStarted;
#endif
}
- (void)scheduleActiveTextResourcePreparation {
    if (self.activeTextResourcePreparationScheduled ||
        !CjguiComposableNodeIsTextInput(self.activeNodeKind)) return;
    self.activeTextResourcePreparationScheduled = YES;
    __weak CJGuiInternalComposableSceneOverlay *weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        CJGuiInternalComposableSceneOverlay *overlay = weakSelf;
        if (!overlay) return;
        overlay.activeTextResourcePreparationScheduled = NO;
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        if (!overlay.activeTextTexturePreparationFailed) [overlay scheduleAcceptedScenePresent];
    });
}
- (void)scheduleAcceptedScenePresent {
    if (self.acceptedScenePresentScheduled || !self.session || self.session.destroyed) return;
    self.acceptedScenePresentScheduled = YES;
    uint64_t token = self.session.rendererSessionToken;
    uint64_t generation = self.session.sessionGeneration;
    __weak CJGuiInternalComposableSceneOverlay *weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        CJGuiInternalComposableSceneOverlay *overlay = weakSelf;
        if (!overlay) return;
        overlay.acceptedScenePresentScheduled = NO;
        CJGuiInternalSession *live = CjguiLookupSession(token);
        if (!live || live.destroyed || live.sessionGeneration != generation ||
            live.composableSceneOverlay != overlay || !live.view) return;
        // The scroll changed only native viewport/derived glyph textures.
        // Present the already accepted node array without promoting a staged
        // candidate or changing the Cangjie scene owner's version.
        CjguiInternalRendererClearColor clear = { 0.08, 0.16, 0.20, 1.0 };
        (void)cjgui_internal_renderer_present_clear(token, &clear, NULL);
    });
}
- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    for (CJGuiInternalComposableSceneNode *node in self.nodes) {
        NSRect rect = CjguiComposableRect(node, self);
        if (NSIsEmptyRect(NSIntersectionRect(rect, CjguiComposableClipBounds(node)))) continue;
        uint32_t kind = node.node.nodeKind;
        if (kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT &&
            kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BUTTON &&
            kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
            kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
            kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
            kind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_BOOLEAN_INPUT) continue;
        BOOL isActiveTextNode = (node.node.nodeId == self.activeNodeId &&
            node.node.projectionVersion == self.activeProjectionVersion &&
            node.node.resourceId == self.activeNodeResourceId &&
            node.node.nodeKind == self.activeNodeKind &&
            (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT ||
             kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT));
        // Single-line text, including the focused TextKit adapter state, is
        // always submitted through the scene texture above.  The overlay
        // retains only multiline drawing, which still reuses the one TextKit
        // layout graph for scroll/candidate geometry.
        if (CjguiComposableNodeHasGpuText(kind)) continue;
        if (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            [self drawMultilineNode:node active:isActiveTextNode outLayoutMicros:NULL
                    outDrawMicros:NULL outSaveMicros:NULL outClipMicros:NULL
                    outRestoreMicros:NULL outGlyphs:NULL];
            continue;
        }
        NSString *activeValue = isActiveTextNode ? self.inputProxy.string : node.value;
        NSString *text = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ? node.value :
            (node.label.length > 0 ? [NSString stringWithFormat:@"%@ %@", node.label, activeValue] : activeValue);
        NSRect visibleRect = NSIntersectionRect(rect, CjguiComposableClipBounds(node));
        if (NSIsEmptyRect(visibleRect)) continue;
        NSColor *textColor = [NSColor colorWithSRGBRed:node.node.textRed
                                                  green:node.node.textGreen
                                                   blue:node.node.textBlue
                                                  alpha:node.node.textAlpha];
        [NSGraphicsContext saveGraphicsState];
        CjguiClipComposableNode(node, self);
        NSRectClip(visibleRect);
        NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
        paragraph.lineBreakMode = kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT ? NSLineBreakByWordWrapping :
            (kind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT ? NSLineBreakByWordWrapping : NSLineBreakByTruncatingTail);
        NSDictionary *attributes = @{ NSFontAttributeName: CjguiComposableFont(node), NSForegroundColorAttributeName: textColor,
                                      NSParagraphStyleAttributeName: paragraph };
        // Layout reserves four vertical points for text. Keep the actual
        // glyph rect in that declared allowance; inputs retain the larger
        // inset needed for their control chrome.
        CGFloat verticalInset = CjguiComposableNodeUsesLabelTextInset(kind) ? 2.0 : 6.0;
        // Keep this 7pt horizontal inset aligned with
        // CJGUI_COMPOSABLE_UI_TEXT_HORIZONTAL_INSET in composable_ui.cj.
        // Layout measures against the remaining content width before it
        // decides the node's height, so the two paths cannot disagree about
        // wrapping at a narrow boundary.
        NSRect textRect = NSInsetRect(rect, 7.0, verticalInset);
        if (isActiveTextNode) {
            NSUInteger length = activeValue.length;
            NSUInteger selectionStart = MIN(self.inputProxy.selectedRange.location, length);
            NSUInteger selectionEnd = MIN(NSMaxRange(self.inputProxy.selectedRange), length);
            CGFloat prefix = node.label.length > 0 ? [[NSString stringWithFormat:@"%@ ", node.label] sizeWithAttributes:attributes].width : 0.0;
            CGFloat before = [[activeValue substringToIndex:selectionStart] sizeWithAttributes:attributes].width;
            CGFloat selected = [[activeValue substringWithRange:NSMakeRange(selectionStart, selectionEnd - selectionStart)] sizeWithAttributes:attributes].width;
            if (selectionEnd > selectionStart) {
                [[NSColor selectedTextBackgroundColor] setFill];
                NSRectFill(NSMakeRect(NSMinX(textRect) + prefix + before, NSMinY(textRect), MAX(1.0, selected), NSHeight(textRect)));
            } else if (self.window.firstResponder == self.inputProxy) {
                [[NSColor keyboardFocusIndicatorColor] setFill];
                NSRectFill(NSMakeRect(NSMinX(textRect) + prefix + before, NSMinY(textRect) + 2.0, 1.0, MAX(1.0, NSHeight(textRect) - 4.0)));
            }
        }
        [text drawWithRect:textRect
                    options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
                 attributes:attributes];
        if (node.node.nodeId == self.activeNodeId && node.node.resourceId == self.activeNodeResourceId &&
            node.node.nodeKind == self.activeNodeKind &&
            self.window.firstResponder == self) {
            [[NSColor keyboardFocusIndicatorColor] setStroke];
            NSFrameRectWithWidth(NSInsetRect(rect, 1.0, 1.0), 1.0);
        }
        [NSGraphicsContext restoreGraphicsState];
    }
    // Reused COW nodes retain their original per-node capture generation;
    // draw progress belongs to the committed scene snapshot, not the largest
    // mutable node field. Native FIFO events already use this same session
    // generation and Cangjie validates it against its input scene.
    uint64_t drawnVersion = self.session.composableSceneVersion;
    if (drawnVersion > 0) self.lastDrawnProjectionVersion = drawnVersion;
    NSView *diagnostic = (NSView *)self.session.diagnosticOverlay;
    if (diagnostic && !diagnostic.hidden) [diagnostic setNeedsDisplay:YES];
}
@end

// Developer-only paint sits above both the Metal surface and AppKit's
// multiline text. It is absent from scene nodes, hit/AX routing, effect
// replay and backdrop sampling. It stores no application/controller object.
@interface CJGuiInternalDiagnosticOverlay : NSView
@property(nonatomic, weak) CJGuiInternalSession *session;
@property(nonatomic, assign) uint32_t flags;
@property(nonatomic, assign) uint64_t selectedNodeId;
@property(nonatomic, assign) BOOL hasSelection;
@property(nonatomic, assign) uint64_t drawCount;
- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session;
@end

@implementation CJGuiInternalDiagnosticOverlay
- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session {
    self = [super initWithFrame:frame];
    if (self) {
        self.session = session;
        self.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
        self.hidden = YES;
    }
    return self;
}
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return NO; }
- (NSView *)hitTest:(NSPoint)point { (void)point; return nil; }
- (BOOL)isAccessibilityElement { return NO; }
- (NSArray *)accessibilityChildren { return @[]; }
- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    CJGuiInternalSession *ctx = self.session;
    if (!ctx || ctx.destroyed || !self.flags || !ctx.composableSceneOverlay) return;
    NSArray<CJGuiInternalComposableSceneNode *> *nodes = ctx.composableSceneOverlay.nodes;
    NSRect viewport = self.bounds;
    [NSGraphicsContext saveGraphicsState];
    NSRectClip(viewport);
    NSUInteger drawn = 0;
    for (NSUInteger index = 0; index < nodes.count && drawn < 256; index++) {
        CJGuiInternalComposableSceneNode *node = nodes[index];
        CjguiInternalRendererComposableNode value = node.node;
        NSRect layout = NSMakeRect(value.x, value.y, value.width, value.height);
        NSRect output = value.effectGroupPresent
            ? CjguiEffectGroupOutputBounds(nodes, index,
                MIN(nodes.count, index + value.effectGroupSubtreeCount))
            : CjguiEffectNodeOutputBounds(node);
        if (NSIsEmptyRect(NSIntersectionRect(layout, viewport)) &&
            NSIsEmptyRect(NSIntersectionRect(output, viewport))) continue;
        drawn++;
        if ((self.flags & 1u) && !NSIsEmptyRect(layout)) {
            [[NSColor colorWithSRGBRed:0.12 green:0.62 blue:1.0 alpha:0.90] setStroke];
            NSBezierPath *path = [NSBezierPath bezierPathWithRect:layout];
            path.lineWidth = 1.0; [path stroke];
        }
        if (self.flags & 2u) {
            [[NSColor colorWithSRGBRed:0.12 green:0.95 blue:0.48 alpha:0.88] setStroke];
            uint32_t count = CjguiComposableClipConstraintCount(value);
            for (uint32_t clip = 0; clip < count; clip++) {
                CGFloat x, y, width, height, radius;
                CjguiComposableClipConstraintAt(value, clip, &x, &y, &width, &height, &radius);
                if (width <= 0 || height <= 0) continue;
                NSBezierPath *path = [NSBezierPath bezierPathWithRoundedRect:NSMakeRect(x, y, width, height)
                                                              xRadius:radius yRadius:radius];
                path.lineWidth = 1.0; [path stroke];
            }
        }
        if ((self.flags & 4u) && !NSIsEmptyRect(output)) {
            [[NSColor colorWithSRGBRed:1.0 green:0.65 blue:0.08 alpha:0.95] setStroke];
            NSBezierPath *path = [NSBezierPath bezierPathWithRect:output];
            path.lineWidth = 1.0; [path stroke];
        }
        CJGuiInternalComposableEffectTarget *backdrop = node.backdropTarget;
        if ((self.flags & 8u) && backdrop && backdrop.samplePixelWidth && backdrop.samplePixelHeight &&
            ctx.effectSubmittedSceneVersion == ctx.composableSceneVersion &&
            ctx.effectSubmittedFrameIndex == ctx.view.frameIndex &&
            ctx.effectMode == CJGUI_INTERNAL_BACKDROP_BLURRED &&
            ctx.view.lastSubmittedDrawableSize.width > 0 && ctx.view.lastSubmittedDrawableSize.height > 0) {
            CGFloat sx = ctx.view.lastSubmittedPointSize.width / ctx.view.lastSubmittedDrawableSize.width;
            CGFloat sy = ctx.view.lastSubmittedPointSize.height / ctx.view.lastSubmittedDrawableSize.height;
            NSRect sample = NSMakeRect(backdrop.samplePixelX * sx, backdrop.samplePixelY * sy,
                                       backdrop.samplePixelWidth * sx, backdrop.samplePixelHeight * sy);
            [[NSColor colorWithSRGBRed:0.80 green:0.38 blue:1.0 alpha:0.95] setStroke];
            NSBezierPath *path = [NSBezierPath bezierPathWithRect:sample];
            path.lineWidth = 1.0; [path stroke];
        }
        if (self.hasSelection && value.nodeId == self.selectedNodeId && !NSIsEmptyRect(layout)) {
            [[NSColor colorWithSRGBRed:1.0 green:0.12 blue:0.72 alpha:1.0] setStroke];
            NSBezierPath *path = [NSBezierPath bezierPathWithRect:NSInsetRect(layout, -2.0, -2.0)];
            path.lineWidth = 2.0; [path stroke];
        }
    }
    [NSGraphicsContext restoreGraphicsState];
    self.drawCount += 1;
}
@end

@implementation CJGuiInternalComposableInputProxy
- (void)scrollRangeToVisible:(NSRange)range {
    // NSTextView normally realizes layout through the selection so it can
    // scroll its own document view. This proxy is intentionally off-canvas;
    // the composable overlay owns the visible viewport and performs explicit
    // scroll/caret geometry when needed. Letting the hidden view do that work
    // turns every long-document insertion into a whole-range realization.
    (void)range;
}
// A presentation TEXT node has no editable proxy text: NSTextView's own
// select-all would only select this off-canvas adapter's empty storage, so the
// user's visible selection never changes and the product never sees the intent
// (measured 2026-09-27: a real Command-A on the body produced no select_all
// witness). The Edit menu offers Command-A to this first responder before any
// keyDown, so the overlay's own routed action is unreachable while the proxy
// exists -- forward it there. An editable control keeps NSTextView's behaviour.
- (void)selectAll:(id)sender {
    if (self.composableOverlay && [self.composableOverlay composableActiveNodeIsPresentationText]) {
        [self.composableOverlay selectAll:sender];
        return;
    }
    [super selectAll:sender];
}
- (void)setMarkedText:(id)string selectedRange:(NSRange)selectedRange replacementRange:(NSRange)replacementRange {
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    BOOL wasMarked = self.hasMarkedText;
    NSString *text = CjguiInputArgumentText(string) ?: @"";
    NSRange effectiveReplacement = CjguiResolvedPlatformReplacement(self, replacementRange);
    if (!wasMarked) {
        self.compositionBaseString = self.string ?: @"";
        self.compositionBaseSelection = self.selectedRange;
    }
    // A composition that STARTS while the window owns this node is routed to the
    // window-owned session: freeze identity, id and binding epoch now so all its
    // later phases (including a terminal after focus loss) address the same
    // session even though the overlay's active identity may move on.
    if (!wasMarked && text.length > 0 && !self.compositionSessionOwned &&
        !overlay.compositionTerminalInFlight && [overlay activeNodeOwnsCompositionSession]) {
        CJGuiInternalSession *session = overlay.session;
        session.nextCompositionId += 1;
        self.compositionSessionOwned = YES;
        self.compositionSessionId = session.nextCompositionId;
        self.compositionSessionEpoch = session.ownedTextSessionBindingEpoch;
        self.compositionSessionNodeId = overlay.activeNodeId;
        self.compositionSessionResourceId = overlay.activeNodeResourceId;
        self.compositionSessionNodeKind = overlay.activeNodeKind;
    }
    if (wasMarked && text.length == 0 && self.compositionSessionOwned &&
        !overlay.compositionTerminalInFlight) {
        // The input source removed the preedit without inserting anything. On
        // the session side that is a cancellation (zero content transactions);
        // the storage callbacks inside this `super` must not become ordinary
        // text events for a node whose writer is the session.
        overlay.compositionTerminalInFlight = YES;
        [super setMarkedText:string selectedRange:selectedRange replacementRange:replacementRange];
        overlay.compositionTerminalInFlight = NO;
        (void)CjguiEmitProxyCompositionPhase(self,
            CJGUI_INTERNAL_RENDERER_TEXT_COMPOSITION_CANCEL, @"", NSMakeRange(0, 0),
            NSMakeRange(NSNotFound, 0), NSMakeRange(NSNotFound, 0));
        self.compositionSessionOwned = NO;
    } else {
        [super setMarkedText:string selectedRange:selectedRange replacementRange:replacementRange];
        if (text.length > 0 && self.compositionSessionOwned && !overlay.compositionTerminalInFlight) {
            // Post-super marked range is the ACTUAL preedit span; the replacement
            // is the range the platform resolved before mutating.
            (void)CjguiEmitProxyCompositionPhase(self,
                CJGUI_INTERNAL_RENDERER_TEXT_COMPOSITION_UPDATE, text, selectedRange,
                effectiveReplacement, self.markedRange);
        }
    }
    // The composition changed the storage content/attributes: invalidate the
    // derived texture through the attributed generation.
    self.composableOverlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.composableOverlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
    [(id)self.composableOverlay refreshGpuTextForActiveInput];
}
- (void)unmarkText {
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    BOOL wasMarked = self.hasMarkedText;
    if (wasMarked && self.compositionSessionOwned) {
        // AppKit defines unmarkText as ACCEPTING the preedit as ordinary text:
        // one session commit carrying exactly the preedit that becomes normal
        // text. Its internal expansion (remove the marked range, re-insert the
        // preedit) must not emit a cancel plus an ordinary edit.
        NSRange marked = self.markedRange;
        NSString *current = self.string ?: @"";
        NSString *preedit = @"";
        if (marked.location != NSNotFound && NSMaxRange(marked) <= current.length) {
            preedit = [current substringWithRange:marked];
        }
        overlay.compositionTerminalInFlight = YES;
        [super unmarkText];
        overlay.compositionTerminalInFlight = NO;
        (void)CjguiEmitProxyCompositionPhase(self,
            CJGUI_INTERNAL_RENDERER_TEXT_COMPOSITION_COMMIT, preedit, self.selectedRange,
            marked, NSMakeRange(NSNotFound, 0));
        self.compositionSessionOwned = NO;
    } else {
        [super unmarkText];
    }
    self.compositionBaseString = nil;
    self.compositionBaseSelection = NSMakeRange(0, 0);
    self.composableOverlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.composableOverlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
#endif
    [(id)self.composableOverlay refreshGpuTextForActiveInput];
}
- (void)insertText:(id)string replacementRange:(NSRange)replacementRange {
#ifdef CJGUI_INTERNAL_TESTING
    if (!self.hasMarkedText && self.composableOverlay.testUsesBoundedInputLayout) {
        // Test-only control for the retired bounded-edit experiment. The
        // production multiline adapter keeps one wrapping/container contract
        // through super, caret geometry and its texture refresh.
        uint64_t modeStarted = CjguiMonotonicMicros();
        if (self.textContainer.maximumNumberOfLines != 1) {
            self.textContainer.maximumNumberOfLines = 1;
            self.composableOverlay.testInputCallbackTrace.modeChangeCount += 1;
        }
        if (self.textContainer.lineBreakMode != NSLineBreakByTruncatingTail) {
            self.textContainer.lineBreakMode = NSLineBreakByTruncatingTail;
            self.composableOverlay.testInputCallbackTrace.modeChangeCount += 1;
        }
        self.composableOverlay.testInputCallbackTrace.modeChangeMicros += CjguiMonotonicMicros() - modeStarted;
    }
    uint64_t superInsertStarted = CjguiMonotonicMicros();
#endif
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    BOOL wasMarked = self.hasMarkedText;
    if (wasMarked && self.compositionSessionOwned && !overlay.compositionTerminalInFlight) {
        // Inserting while marked text exists IS the platform commit. The final
        // text may legitimately be empty (the IME accepted nothing), which the
        // session must see as an explicit empty commit, not as "use the draft".
        NSString *committed = CjguiInputArgumentText(string) ?: @"";
        NSRange effectiveReplacement = CjguiResolvedPlatformReplacement(self, replacementRange);
        overlay.compositionTerminalInFlight = YES;
        [super insertText:string replacementRange:replacementRange];
        overlay.compositionTerminalInFlight = NO;
        (void)CjguiEmitProxyCompositionPhase(self,
            CJGUI_INTERNAL_RENDERER_TEXT_COMPOSITION_COMMIT, committed, self.selectedRange,
            effectiveReplacement, NSMakeRange(NSNotFound, 0));
        self.compositionSessionOwned = NO;
    } else {
        [super insertText:string replacementRange:replacementRange];
    }
#ifdef CJGUI_INTERNAL_TESTING
    self.composableOverlay.testInputCallbackTrace.superInsertMicros += CjguiMonotonicMicros() - superInsertStarted;
#endif
    self.compositionBaseString = nil;
    self.compositionBaseSelection = NSMakeRange(0, 0);
    self.composableOverlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.composableOverlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
    [(id)self.composableOverlay refreshGpuTextForActiveInput];
}
- (void)cancelMarkedText {
    if (!self.hasMarkedText) return;
    CJGuiInternalComposableSceneOverlay *overlay = self.composableOverlay;
    BOOL sessionOwned = self.compositionSessionOwned;
    NSString *base = self.compositionBaseString ?: @"";
    NSRange selection = CjguiComposedSelection(base, self.compositionBaseSelection.location,
                                                NSMaxRange(self.compositionBaseSelection));
    // This rollback is a platform-side reset, not a human edit: nothing inside
    // it may be delivered as an ordinary text event for a session-owned node.
    overlay.compositionTerminalInFlight = YES;
    // Assigning the preserved committed adapter string avoids treating
    // `unmarkText` as cancellation: TextKit's unmark operation makes the
    // current preedit ordinary text on several input sources.
    self.string = base;
    self.selectedRange = selection;
    self.compositionBaseString = nil;
    self.compositionBaseSelection = NSMakeRange(0, 0);
    // Tell the INPUT CONTEXT the composition is gone. `unmarkText` is an ACCEPT, so a real
    // cancellation is exactly this call; without it the input source can keep a stale
    // conversion session alive after the client already dropped the preedit.
    NSTextInputContext *context = self.inputContext;
    if (context) {
        [context discardMarkedText];
        if (getenv("PHAROS_TRACE_FIRST_RECT") != NULL) {
            fprintf(stderr, "PHAROS_DISCARD_MARKED_TEXT sent=1\n");
        }
    }
    overlay.compositionTerminalInFlight = NO;
    self.compositionSessionOwned = NO;
    if (sessionOwned) {
        // The session has to hear about a platform-side cancellation: without
        // this it would keep a live draft whose preedit no longer exists.
        (void)CjguiEmitProxyCompositionPhase(self,
            CJGUI_INTERNAL_RENDERER_TEXT_COMPOSITION_CANCEL, @"", NSMakeRange(0, 0),
            NSMakeRange(NSNotFound, 0), NSMakeRange(NSNotFound, 0));
    }
    self.composableOverlay.activeTextAttributedGeneration += 1;
#ifdef CJGUI_INTERNAL_TESTING
    self.composableOverlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonActiveContent;
#endif
    [(id)self.composableOverlay refreshGpuTextForActiveInput];
}
// Required by the NSTextInputClient contract and previously MISSING entirely (the probe
// found nothing answering it). The IME asks what text the client can offer for a proposed
// range; out-of-range requests take the intersection, a request with no intersection returns
// nil, and `actualRange` describes what was actually returned.
- (NSAttributedString *)attributedSubstringForProposedRange:(NSRange)range
                                               actualRange:(NSRangePointer)actualRange {
    // Declared inside the proxy itself, so its own string IS the client text.
    NSString *text = self.string ?: @"";
    if (range.location == NSNotFound || text.length == 0) {
        if (actualRange) *actualRange = NSMakeRange(NSNotFound, 0);
        return nil;
    }
    NSRange clamped = NSIntersectionRange(range, NSMakeRange(0, text.length));
    if (clamped.length == 0 && range.length > 0) {
        if (actualRange) *actualRange = NSMakeRange(NSNotFound, 0);
        return nil;
    }
    if (actualRange) *actualRange = clamped;
    return [[NSAttributedString alloc] initWithString:[text substringWithRange:clamped]];
}

- (NSRect)firstRectForCharacterRange:(NSRange)range actualRange:(NSRangePointer)actualRange {
    BOOL answered = NO;
    NSRect rect = [self.composableOverlay candidateRectForCharacterRange:range actualRange:actualRange answered:&answered];
    if (answered) {
        // Trust the drawn layout even when the rect is empty: for a zero-length request a
        // zero-width insertion rect is the CORRECT answer, and the old NSIsEmptyRect test
        // sent exactly that case to the hidden proxy, anchoring the IME candidate window at
        // the proxy instead of the visible caret.
        //
        // AppKit expects SCREEN coordinates here. The answered rect is in the overlay's
        // flipped scene space, so convert scene -> window -> screen explicitly. Returning
        // scene coordinates would place the candidate window at an arbitrary spot (a
        // three-thousand-point error on a tall screen).
        NSWindow *window = self.composableOverlay.window;
        if (window) {
            // Convert through AppKit instead of flipping by hand. Measured with three known
            // scene rects: a manual flip using the overlay's own height produced
            // screen_y = 897 - scene_y, while the content top is 833 -- a constant 64 pt
            // error, which would put the IME candidate window 64 pt away from the caret
            // (and the error is invisible in the rect's shape, only in its position).
            NSView *content = self.composableOverlay.superview ?: self.composableOverlay;
            NSRect inContent = [self.composableOverlay convertRect:rect toView:content];
            NSRect inWindow = [content convertRect:inContent toView:nil];
            NSRect screen = [window convertRectToScreen:inWindow];
            if (getenv("PHAROS_TRACE_FIRST_RECT") != NULL) {
                NSRect overlayFrame = self.composableOverlay.frame;
                NSRect contentFrame = content.frame;
                NSRect windowFrame = window.frame;
                fprintf(stderr,
                        "PHAROS_RECT_CONVERT scene=%.1f,%.1f,%.1f,%.1f overlay=%.1f,%.1f,%.1f,%.1f "
                        "flipped=%d super=%s contentFrame=%.1f,%.1f,%.1f,%.1f windowFrame=%.1f,%.1f,%.1f,%.1f "
                        "inWindow=%.1f,%.1f screen=%.1f,%.1f\n",
                        rect.origin.x, rect.origin.y, rect.size.width, rect.size.height,
                        overlayFrame.origin.x, overlayFrame.origin.y, overlayFrame.size.width,
                        overlayFrame.size.height, self.composableOverlay.isFlipped,
                        NSStringFromClass([content class]).UTF8String,
                        contentFrame.origin.x, contentFrame.origin.y, contentFrame.size.width,
                        contentFrame.size.height, windowFrame.origin.x, windowFrame.origin.y,
                        windowFrame.size.width, windowFrame.size.height,
                        inWindow.origin.x, inWindow.origin.y, screen.origin.x, screen.origin.y);
            }
            return screen;
        }
        return rect;
    }
    if (getenv("PHAROS_TRACE_FIRST_RECT") != NULL) {
        fprintf(stderr, "PHAROS_FIRST_RECT_FALLBACK loc=%lu len=%lu (no drawn text node to answer from)\n",
                (unsigned long)range.location, (unsigned long)range.length);
    }
    return [super firstRectForCharacterRange:range actualRange:actualRange];
}
- (BOOL)handleStandardTextCommandKeyDown:(NSEvent *)event {
    if (CjguiEventIsExactCommandCharacter(event, @"a")) {
        [self selectAll:nil];
        return YES;
    }
    if (CjguiEventIsExactCommandCharacter(event, @"c")) {
        [self copy:nil];
        return YES;
    }
    if (CjguiEventIsExactCommandCharacter(event, @"x")) {
        [self cut:nil];
        return YES;
    }
    if (CjguiEventIsExactCommandCharacter(event, @"v")) {
        [self paste:nil];
        return YES;
    }
    return NO;
}
- (void)keyDown:(NSEvent *)event {
    // Marked text belongs to the active system input source. A framework
    // shortcut must not turn a composition/candidate operation into an
    // application action before the text service has resolved it.
    if (self.hasMarkedText) {
        if (event.keyCode == 53) [self.composableOverlay cancelActiveComposition];
        else [super keyDown:event];
        return;
    }
    if (event.keyCode == 53) {
        // Escape belongs to the current modal layer when one is present;
        // otherwise preserve NSTextView's ordinary cancellation route.
        [self.composableOverlay keyDown:event];
        return;
    }
    // These are NSTextView operations, not composable window commands. The
    // hidden input adapter is intentionally still their execution owner.
    if ([self handleStandardTextCommandKeyDown:event]) return;
    // AppKit does not necessarily ask its delegate about Command equivalents,
    // so pass remaining Command chords through the generic Cangjie shortcut
    // resolver. It will either resolve a declared command or do nothing; no
    // native application command table exists here.
    if (self.composableOverlay && [self.composableOverlay handleWindowCommandKeyDown:event]) return;
// B4(2026-09-26, Sol consult): with no marked text, NAVIGATION keys belong to
// the product caret when the active target is a presentation TEXT node --
// `super keyDown:` would move this adapter's own invisible selection and the
// user sees nothing. Forward so the overlay's caret-intent mapping runs.
if (self.composableOverlay && [self.composableOverlay composableActiveNodeIsPresentationText]) {
    switch (event.keyCode) {
        case 123: /* left  */ case 124: /* right */
        case 125: /* down  */ case 126: /* up    */
        case 115: /* home */ case 119: /* end   */
        case 117: /* forward delete */ case 51: /* delete */
        case 116: /* page up */ case 121: /* page down */
            [self.composableOverlay keyDown:event];
            return;
        default: break;
    }
}
[super keyDown:event];
}
@end

// ---- shared-operation text/input overlay ----
//
// The overlay is deliberately a projection. It receives human input and
// displays the latest POD state supplied by Cangjie; it never owns or mutates
// application records. All user intent returns through pumpEvent.

@interface CJGuiInternalSharedOperationOverlay : NSView
@property(nonatomic, weak) CJGuiInternalSession *session;
@property(nonatomic, assign) uint32_t recordCount;
@property(nonatomic, assign) CjguiInternalRendererSharedOperationState state;
@property(nonatomic, strong) NSMutableArray<NSString *> *titles;
@property(nonatomic, strong) NSMutableArray<CJGuiInternalSharedOperationAccessibilityAction *> *accessibilityActions;
- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session;
- (void)setRecordCountForProjection:(uint32_t)recordCount;
- (void)setTitle:(NSString *)title atIndex:(uint32_t)recordIndex;
- (void)setProjectionState:(CjguiInternalRendererSharedOperationState)state;
- (void)queueInteraction:(uint32_t)kind index:(uint32_t)index;
- (void)queueViewportInteraction:(uint32_t)kind;
- (NSString *)titleForRecordAtIndex:(uint32_t)recordIndex;
- (BOOL)isRecordMarkedAtIndex:(uint32_t)recordIndex;
@end

@implementation CJGuiInternalSharedOperationAccessibilityAction

- (instancetype)initWithOverlay:(CJGuiInternalSharedOperationOverlay *)overlay
                     recordIndex:(uint32_t)recordIndex
                     marksRecord:(BOOL)marksRecord {
    self = [super init];
    if (!self) {
        return nil;
    }
    self.overlay = overlay;
    self.recordIndex = recordIndex;
    self.marksRecord = marksRecord;
    return self;
}

- (id)accessibilityParent {
    return self.overlay;
}

- (NSAccessibilityRole)accessibilityRole {
    return self.marksRecord ? NSAccessibilityCheckBoxRole : NSAccessibilityButtonRole;
}

- (NSString *)accessibilityLabel {
    NSString *title = [self.overlay titleForRecordAtIndex:self.recordIndex];
    return self.marksRecord
        ? [NSString stringWithFormat:@"Mark %@", title]
        : [NSString stringWithFormat:@"Select %@", title];
}

- (id)accessibilityValue {
    if (self.marksRecord) {
        return @([self.overlay isRecordMarkedAtIndex:self.recordIndex]);
    }
    return nil;
}

- (BOOL)isAccessibilityEnabled {
    // NSAccessibilityElement does not infer enabledness from
    // accessibilityPerformPress. This action is usable exactly while its
    // projection and bounded record slot remain valid.
    return self.overlay != nil && self.recordIndex < self.overlay.recordCount;
}

- (NSRect)accessibilityFrame {
    CJGuiInternalSharedOperationOverlay *overlay = self.overlay;
    if (!overlay) {
        return NSZeroRect;
    }
    CGFloat y = 75.0 + (CGFloat)self.recordIndex * 44.0;
    NSRect localFrame = self.marksRecord
        ? NSMakeRect(20.0, y + 3.0, 33.0, 30.0)
        : NSMakeRect(58.0, y + 3.0, MAX(0.0, overlay.bounds.size.width - 78.0), 30.0);
    return NSAccessibilityFrameInView(overlay, localFrame);
}

- (BOOL)accessibilityPerformPress {
    CJGuiInternalSharedOperationOverlay *overlay = self.overlay;
    if (!overlay) {
        return NO;
    }
    [overlay queueInteraction:self.marksRecord
        ? CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_TOGGLE_RECORD
        : CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_SELECT_RECORD
                         index:self.recordIndex];
    return YES;
}

@end

@implementation CJGuiInternalSharedOperationOverlay

- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session {
    self = [super initWithFrame:frame];
    if (!self) {
        return nil;
    }
    self.session = session;
    self.titles = [NSMutableArray array];
    self.accessibilityActions = [NSMutableArray array];
    self.wantsLayer = YES;
    self.layer.backgroundColor = NSColor.clearColor.CGColor;
    return self;
}

- (BOOL)isFlipped {
    return YES;
}

- (BOOL)acceptsFirstResponder {
    return YES;
}

- (void)setRecordCountForProjection:(uint32_t)recordCount {
    // The C ABI validates this as a bounded visible viewport. Do not silently
    // truncate here: a caller accidentally treating this as total data must
    // fail at the ABI boundary rather than receive a misleading projection.
    self.recordCount = recordCount;
    while (self.titles.count < self.recordCount) {
        [self.titles addObject:@"Untitled record"];
    }
    while (self.accessibilityActions.count < self.recordCount * 2) {
        uint32_t actionIndex = (uint32_t)(self.accessibilityActions.count / 2);
        BOOL marksRecord = (self.accessibilityActions.count % 2) == 1;
        [self.accessibilityActions addObject:
            [[CJGuiInternalSharedOperationAccessibilityAction alloc] initWithOverlay:self
                                                                          recordIndex:actionIndex
                                                                          marksRecord:marksRecord]];
    }
    while (self.accessibilityActions.count > self.recordCount * 2) {
        [self.accessibilityActions removeLastObject];
    }
    [self setNeedsDisplay:YES];
}

- (void)setTitle:(NSString *)title atIndex:(uint32_t)recordIndex {
    if (recordIndex >= self.recordCount) {
        return;
    }
    self.titles[recordIndex] = title ?: @"Untitled record";
    [self setNeedsDisplay:YES];
}

- (void)setProjectionState:(CjguiInternalRendererSharedOperationState)state {
    self.state = state;
    [self setNeedsDisplay:YES];
}

- (BOOL)isAccessibilityElement {
    return NO;
}

- (NSAccessibilityRole)accessibilityRole {
    return NSAccessibilityGroupRole;
}

- (NSString *)accessibilityLabel {
    return @"CJGUI shared operation list";
}

- (NSArray<id> *)accessibilityChildren {
    return [self.accessibilityActions copy];
}

- (NSString *)titleForRecordAtIndex:(uint32_t)recordIndex {
    if (recordIndex >= self.titles.count) {
        return @"Untitled record";
    }
    return self.titles[recordIndex];
}

- (BOOL)isRecordMarkedAtIndex:(uint32_t)recordIndex {
    if (recordIndex >= self.recordCount) {
        return NO;
    }
    return (self.state.markedRecordMask & (UINT64_C(1) << recordIndex)) != 0;
}

- (NSDictionary<NSAttributedStringKey, id> *)bodyAttributes {
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:15.0],
        NSForegroundColorAttributeName: NSColor.labelColor
    };
}

- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    [[NSColor colorWithCalibratedWhite:0.97 alpha:0.94] setFill];
    NSRectFill(self.bounds);

    NSDictionary *headingAttributes = @{
        NSFontAttributeName: [NSFont boldSystemFontOfSize:19.0],
        NSForegroundColorAttributeName: NSColor.labelColor
    };
    [@"CJGUI shared operation list" drawAtPoint:NSMakePoint(22, 18)
                                   withAttributes:headingAttributes];
    [@"Click a row to select it. Click its box or press Space to mark it. Scroll or use Page Up/Down to browse."
        drawAtPoint:NSMakePoint(22, 45)
     withAttributes:@{
        NSFontAttributeName: [NSFont systemFontOfSize:12.0],
        NSForegroundColorAttributeName: NSColor.secondaryLabelColor
     }];

    for (uint32_t index = 0; index < self.recordCount; index++) {
        CGFloat y = 75.0 + (CGFloat)index * 44.0;
        BOOL selected = self.state.selectedRecordIndex == index;
        BOOL marked = (self.state.markedRecordMask & (UINT64_C(1) << index)) != 0;
        NSRect rowRect = NSMakeRect(14, y, MAX(0, self.bounds.size.width - 28), 36);
        if (selected) {
            [[NSColor selectedContentBackgroundColor] setFill];
            NSBezierPath *selection = [NSBezierPath bezierPathWithRoundedRect:rowRect
                                                                        xRadius:6
                                                                        yRadius:6];
            [selection fill];
        }

        NSString *mark = marked ? @"☑" : @"☐";
        NSDictionary *rowAttributes = [self bodyAttributes];
        if (selected) {
            rowAttributes = @{
                NSFontAttributeName: [NSFont systemFontOfSize:15.0],
                NSForegroundColorAttributeName: NSColor.alternateSelectedControlTextColor
            };
        }
        [mark drawAtPoint:NSMakePoint(25, y + 8) withAttributes:rowAttributes];
        NSString *title = self.titles[index];
        [title drawAtPoint:NSMakePoint(58, y + 9) withAttributes:rowAttributes];
    }

    uint32_t firstVisible = self.state.totalRecordCount == 0
        ? 0
        : self.state.viewportStart + 1;
    uint32_t lastVisible = self.state.viewportStart + self.recordCount;
    NSString *viewportLabel = [NSString stringWithFormat:@"Showing %u-%u of %u",
        firstVisible, lastVisible, self.state.totalRecordCount];
    [viewportLabel drawAtPoint:NSMakePoint(MAX(260, self.bounds.size.width - 190), 21)
                  withAttributes:@{
        NSFontAttributeName: [NSFont monospacedSystemFontOfSize:11.0 weight:NSFontWeightRegular],
        NSForegroundColorAttributeName: NSColor.secondaryLabelColor
    }];

    NSString *footer = [NSString stringWithFormat:@"Version %llu · selected record %lld",
                         self.state.version, self.state.selectedRecordId];
    [footer drawAtPoint:NSMakePoint(22, MAX(75, self.bounds.size.height - 30))
         withAttributes:@{
            NSFontAttributeName: [NSFont monospacedSystemFontOfSize:12.0 weight:NSFontWeightRegular],
            NSForegroundColorAttributeName: NSColor.secondaryLabelColor
         }];
}

- (void)queueInteraction:(uint32_t)kind index:(uint32_t)index {
    CJGuiInternalSession *session = self.session;
    if (!session || index >= self.recordCount) {
        return;
    }
    (void)CjguiEnqueueInteraction(session, kind, index, @"", 0, 0);
}

- (void)queueViewportInteraction:(uint32_t)kind {
    CJGuiInternalSession *session = self.session;
    if (!session) {
        return;
    }
    (void)CjguiEnqueueInteraction(session, kind, 0, @"", 0, 0);
}

- (void)mouseDown:(NSEvent *)event {
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    if (point.y < 75.0) {
        return;
    }
    uint32_t index = (uint32_t)((point.y - 75.0) / 44.0);
    if (index >= self.recordCount) {
        return;
    }
    if (point.x < 58.0) {
        [self queueInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_TOGGLE_RECORD index:index];
    } else {
        [self queueInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_SELECT_RECORD index:index];
    }
}

- (void)scrollWheel:(NSEvent *)event {
    if (event.scrollingDeltaY > 0.0) {
        [self queueViewportInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_VIEWPORT_PREVIOUS];
    } else if (event.scrollingDeltaY < 0.0) {
        [self queueViewportInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_VIEWPORT_NEXT];
    }
}

- (void)keyDown:(NSEvent *)event {
    if (self.recordCount == 0) {
        return;
    }
    uint32_t selectedIndex = self.state.selectedRecordIndex;
    if (selectedIndex >= self.recordCount) {
        selectedIndex = 0;
    }
    if (event.keyCode == 116) {
        [self queueViewportInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_VIEWPORT_PREVIOUS];
        return;
    }
    if (event.keyCode == 121) {
        [self queueViewportInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_VIEWPORT_NEXT];
        return;
    }
    if (event.keyCode == 125 && selectedIndex + 1 < self.recordCount) {
        [self queueInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_SELECT_RECORD
                         index:selectedIndex + 1];
        return;
    }
    if (event.keyCode == 126 && selectedIndex > 0) {
        [self queueInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_SELECT_RECORD
                         index:selectedIndex - 1];
        return;
    }
    if (event.keyCode == 49 || event.keyCode == 36) {
        [self queueInteraction:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_TOGGLE_RECORD
                         index:selectedIndex];
    }
}

@end

// ---- shared-editing self-drawn form overlay ----
//
// The visible surface is rendered by this NSView. NSTextView is retained only
// as an off-canvas macOS text-input proxy: it supplies IME, clipboard,
// deletion and UTF-16 selection services, but never presents a field or owns
// application content. Cangjie remains the sole applied/draft truth owner.

@class CJGuiInternalSharedEditingFormAccessibilityAction;

@interface CJGuiInternalSharedEditingFormOverlay : NSView <NSTextViewDelegate>
@property(nonatomic, weak) CJGuiInternalSession *session;
@property(nonatomic, assign) uint32_t fieldCount;
@property(nonatomic, strong) NSMutableArray<NSString *> *fieldLabels;
@property(nonatomic, strong) NSMutableArray<NSString *> *draftTexts;
@property(nonatomic, strong) NSMutableArray<NSString *> *validationErrors;
@property(nonatomic, strong) NSMutableArray<NSNumber *> *editorKinds;
@property(nonatomic, strong) NSMutableArray<CJGuiInternalSharedEditingFormAccessibilityAction *> *accessibilityActions;
@property(nonatomic, strong) NSTextView *inputProxy;
@property(nonatomic, assign) BOOL collectionEnabled;
@property(nonatomic, assign) uint32_t collectionRowCount;
@property(nonatomic, strong) NSMutableArray<NSString *> *collectionTitles;
@property(nonatomic, assign) uint32_t collectionSelectedRow;
@property(nonatomic, assign) uint32_t collectionViewportStart;
@property(nonatomic, assign) uint32_t collectionTotalCount;
@property(nonatomic, copy) NSString *collectionFilterText;
@property(nonatomic, copy) NSString *statusText;
@property(nonatomic, copy) NSString *inputNotice;
@property(nonatomic, assign) NSInteger activeTextFieldIndex;
@property(nonatomic, assign) BOOL applyingProjection;
- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session;
- (void)setFieldCountForProjection:(uint32_t)fieldCount;
- (void)setFieldAtIndex:(uint32_t)index label:(NSString *)label draftText:(NSString *)draftText
                   error:(NSString *)error editorKind:(uint32_t)editorKind focused:(BOOL)focused
          selectionStart:(uint32_t)selectionStart selectionEnd:(uint32_t)selectionEnd;
- (void)setStatus:(NSString *)status;
- (NSRect)fieldRectAtIndex:(uint32_t)index;
- (NSRect)applyRect;
- (NSRect)cancelRect;
- (NSRect)collectionRowRectAtIndex:(uint32_t)index;
- (NSRect)collectionCreateRect;
- (NSRect)collectionCopyRect;
- (NSRect)collectionDeleteRect;
- (NSRect)collectionPreviousRect;
- (NSRect)collectionNextRect;
- (NSRect)collectionUndoRect;
- (NSRect)collectionRedoRect;
- (NSRect)collectionSaveRect;
- (NSRect)collectionSaveAsRect;
- (NSRect)collectionOpenRect;
- (NSRect)collectionNewRect;
- (NSRect)collectionDiscardRect;
- (NSRect)collectionCloseRect;
- (NSRect)collectionFilterRect;
- (NSString *)labelAtIndex:(uint32_t)index;
- (NSString *)draftAtIndex:(uint32_t)index;
- (uint32_t)editorKindAtIndex:(uint32_t)index;
- (void)focusTextFieldAtIndex:(uint32_t)index selection:(NSRange)selection enqueueFocus:(BOOL)enqueueFocus;
- (void)toggleBooleanAtIndex:(uint32_t)index;
- (void)accessibilitySetText:(NSString *)text atIndex:(uint32_t)index;
- (void)queue:(uint32_t)kind index:(uint32_t)index text:(NSString *)text selection:(NSRange)selection;
- (void)setCollectionEnabled:(BOOL)enabled visibleRecordCount:(uint32_t)visibleRecordCount;
- (void)setCollectionRowAtIndex:(uint32_t)index title:(NSString *)title selected:(BOOL)selected viewportStart:(uint32_t)viewportStart totalRecordCount:(uint32_t)totalRecordCount;
- (void)setCollectionFilter:(NSString *)filterText;
- (void)focusCollectionFilterEnqueue:(BOOL)enqueue;
- (void)accessibilitySetCollectionFilter:(NSString *)filterText;
- (void)chooseOpenFile;
- (void)chooseSaveAsFile;
- (void)rebuildAccessibilityActions;
@end

@interface CJGuiInternalSharedEditingFormAccessibilityAction : NSAccessibilityElement
@property(nonatomic, weak) CJGuiInternalSharedEditingFormOverlay *overlay;
@property(nonatomic, assign) uint32_t fieldIndex;
@property(nonatomic, assign) uint32_t actionKind;
- (instancetype)initWithOverlay:(CJGuiInternalSharedEditingFormOverlay *)overlay
                      fieldIndex:(uint32_t)fieldIndex actionKind:(uint32_t)actionKind;
@end

// Keep the document consumer's text summary bounded at the Cangjie/native
// boundary. This bridge intentionally exposes only a scalar byte count; the
// caller owns the source and native retains no pointer after returning.
CjguiInternalRendererStatus
cjgui_internal_renderer_composed_prefix_utf8_length(
    const char *utf8, uint64_t inputBytes, uint64_t maxOutputBytes,
    uint64_t maxClusters, uint8_t inputComplete, uint64_t *outPrefixBytes) {
    if (!outPrefixBytes || (!utf8 && inputBytes > 0)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    *outPrefixBytes = 0;
    if (inputBytes == 0 || maxOutputBytes == 0 || maxClusters == 0) {
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    const uint64_t scanLimit = 2048;
    // The Cangjie wrapper supplies a scalar-safe window. Do not repair or
    // repeatedly shorten arbitrary bytes here: a native internal caller that
    // violates the bound/encoding contract receives an explicit failure.
    if (inputBytes > scanLimit) return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
    NSString *value = [[NSString alloc] initWithBytes:utf8 length:(NSUInteger)inputBytes
                                             encoding:NSUTF8StringEncoding];
    if (!value) return CJGUI_INTERNAL_RENDERER_INVALID_UTF8;
    BOOL complete = inputComplete != 0;
    uint64_t prefixBytes = 0;
    uint64_t clusterCount = 0;
    for (NSUInteger location = 0; location < value.length && clusterCount < maxClusters;) {
        NSRange range = [value rangeOfComposedCharacterSequenceAtIndex:location];
        if (!complete && NSMaxRange(range) >= value.length) break;
        NSString *cluster = [value substringWithRange:range];
        NSUInteger clusterBytes = [cluster lengthOfBytesUsingEncoding:NSUTF8StringEncoding];
        if ((uint64_t)clusterBytes > maxOutputBytes - MIN(prefixBytes, maxOutputBytes)) break;
        prefixBytes += (uint64_t)clusterBytes;
        clusterCount += 1;
        location = NSMaxRange(range);
    }
    *outPrefixBytes = prefixBytes;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static NSRange CjguiComposedSelection(NSString *text, NSUInteger start, NSUInteger end) {
    NSUInteger length = text.length;
    start = MIN(start, length);
    end = MIN(MAX(end, start), length);
    if (start > 0 && start < length) {
        NSRange composed = [text rangeOfComposedCharacterSequenceAtIndex:start];
        if (start != composed.location && start != NSMaxRange(composed)) start = composed.location;
    }
    if (end > 0 && end < length) {
        NSRange composed = [text rangeOfComposedCharacterSequenceAtIndex:end];
        if (end != composed.location && end != NSMaxRange(composed)) end = NSMaxRange(composed);
    }
    return NSMakeRange(start, end - start);
}

@implementation CJGuiInternalSharedEditingFormAccessibilityAction

- (instancetype)initWithOverlay:(CJGuiInternalSharedEditingFormOverlay *)overlay
                      fieldIndex:(uint32_t)fieldIndex actionKind:(uint32_t)actionKind {
    self = [super init];
    if (!self) return nil;
    self.overlay = overlay;
    self.fieldIndex = fieldIndex;
    self.actionKind = actionKind;
    return self;
}

- (id)accessibilityParent { return self.overlay; }
- (id)accessibilityWindow { return self.overlay.window; }
- (id)accessibilityTopLevelUIElement { return self.overlay.window; }
- (BOOL)isAccessibilityElement { return YES; }
- (NSAccessibilityRole)accessibilityRole {
    if (self.actionKind == 0 && [self.overlay editorKindAtIndex:self.fieldIndex] == 3) return NSAccessibilityCheckBoxRole;
    if (self.actionKind == 18) return NSAccessibilityTextFieldRole;
    if (self.actionKind != 0) return NSAccessibilityButtonRole;
    return NSAccessibilityTextFieldRole;
}
- (NSString *)accessibilityLabel {
    if (self.actionKind == 2) return @"应用草稿";
    if (self.actionKind == 3) return @"取消并重载";
    if (self.actionKind == 4) return self.fieldIndex < self.overlay.collectionTitles.count ? self.overlay.collectionTitles[self.fieldIndex] : @"记录";
    if (self.actionKind == 5) return @"新增记录";
    if (self.actionKind == 6) return @"删除记录";
    if (self.actionKind == 7) return @"上一页";
    if (self.actionKind == 8) return @"下一页";
    if (self.actionKind == 9) return @"撤销";
    if (self.actionKind == 10) return @"重做";
    if (self.actionKind == 11) return @"保存";
    if (self.actionKind == 12) return @"复制记录";
    if (self.actionKind == 13) return @"新建规则集";
    if (self.actionKind == 14) return @"打开规则集";
    if (self.actionKind == 15) return @"另存为";
    if (self.actionKind == 16) return @"放弃未保存内容";
    if (self.actionKind == 17) return @"关闭窗口";
    if (self.actionKind == 18) return @"筛选记录";
    return [self.overlay labelAtIndex:self.fieldIndex];
}
- (id)accessibilityValue {
    if (self.actionKind == 0 && [self.overlay editorKindAtIndex:self.fieldIndex] == 3) return @([[self.overlay draftAtIndex:self.fieldIndex] isEqualToString:@"true"]);
    if (self.actionKind == 4) return @(self.overlay.collectionSelectedRow == self.fieldIndex);
    if (self.actionKind == 18) return self.overlay.collectionFilterText;
    if (self.actionKind == 0) return [self.overlay draftAtIndex:self.fieldIndex];
    return nil;
}
- (BOOL)isAccessibilityEnabled { return self.overlay != nil; }
- (BOOL)accessibilityIsAttributeSettable:(NSAccessibilityAttributeName)attribute {
    if (![attribute isEqualToString:NSAccessibilityValueAttribute]) return NO;
    if (self.actionKind == 18) return YES;
    return self.actionKind == 0 && [self.overlay editorKindAtIndex:self.fieldIndex] != 3;
}
- (NSArray<NSAccessibilityActionName> *)accessibilityActionNames {
    if (self.actionKind != 0 || [self.overlay editorKindAtIndex:self.fieldIndex] == 3) {
        return @[ NSAccessibilityPressAction ];
    }
    return @[];
}
- (void)accessibilityPerformAction:(NSAccessibilityActionName)action {
    if ([action isEqualToString:NSAccessibilityPressAction]) [self accessibilityPerformPress];
}
- (NSRect)accessibilityFrame {
    if (!self.overlay) return NSZeroRect;
    // Use an explicit view-to-window-to-screen conversion. This keeps the
    // self-drawn controls operable by macOS accessibility clients; returning
    // only a parent-space rectangle made them discoverable but unclickable.
    NSRect inWindow = [self.overlay convertRect:[self accessibilityFrameInParentSpace] toView:nil];
    return [self.overlay.window convertRectToScreen:inWindow];
}
- (NSPoint)accessibilityPosition { return [self accessibilityFrame].origin; }
- (NSSize)accessibilitySize { return [self accessibilityFrame].size; }
- (NSRect)accessibilityFrameInParentSpace {
    if (!self.overlay) return NSZeroRect;
    return self.actionKind == 2 ? [self.overlay applyRect] :
        self.actionKind == 3 ? [self.overlay cancelRect] :
        self.actionKind == 4 ? [self.overlay collectionRowRectAtIndex:self.fieldIndex] :
        self.actionKind == 5 ? [self.overlay collectionCreateRect] :
        self.actionKind == 6 ? [self.overlay collectionDeleteRect] :
        self.actionKind == 7 ? [self.overlay collectionPreviousRect] :
        self.actionKind == 8 ? [self.overlay collectionNextRect] :
        self.actionKind == 9 ? [self.overlay collectionUndoRect] :
        self.actionKind == 10 ? [self.overlay collectionRedoRect] :
        self.actionKind == 11 ? [self.overlay collectionSaveRect] :
        self.actionKind == 12 ? [self.overlay collectionCopyRect] :
        self.actionKind == 13 ? [self.overlay collectionNewRect] :
        self.actionKind == 14 ? [self.overlay collectionOpenRect] :
        self.actionKind == 15 ? [self.overlay collectionSaveAsRect] :
        self.actionKind == 16 ? [self.overlay collectionDiscardRect] :
        self.actionKind == 17 ? [self.overlay collectionCloseRect] :
        self.actionKind == 18 ? [self.overlay collectionFilterRect] :
        [self.overlay fieldRectAtIndex:self.fieldIndex];
}
- (BOOL)accessibilityPerformPress {
    if (!self.overlay) return NO;
    if (self.actionKind == 2) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_APPLY index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 3) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_CANCEL index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 4) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_SELECT index:self.fieldIndex text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 5) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CREATE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 6) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_DELETE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 7) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_PREVIOUS_PAGE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 8) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_NEXT_PAGE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 9) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_UNDO index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 10) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_REDO index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 11) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_SAVE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 12) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_COPY index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 13) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_NEW index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 14) {
        [self.overlay chooseOpenFile];
    } else if (self.actionKind == 15) {
        [self.overlay chooseSaveAsFile];
    } else if (self.actionKind == 16) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_DISCARD index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 17) {
        [self.overlay queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CLOSE index:0 text:@"" selection:NSMakeRange(0, 0)];
    } else if (self.actionKind == 18) {
        [self.overlay focusCollectionFilterEnqueue:YES];
    } else if ([self.overlay editorKindAtIndex:self.fieldIndex] == 3) {
        [self.overlay toggleBooleanAtIndex:self.fieldIndex];
    } else {
        [self.overlay focusTextFieldAtIndex:self.fieldIndex selection:NSMakeRange(0, 0) enqueueFocus:YES];
    }
    return YES;
}
- (void)accessibilitySetValue:(id)value {
    if (self.actionKind == 18 && [value isKindOfClass:[NSString class]]) {
        [self.overlay accessibilitySetCollectionFilter:value];
        return;
    }
    if (self.actionKind == 0 && [value isKindOfClass:[NSString class]]) {
        [self.overlay accessibilitySetText:value atIndex:self.fieldIndex];
    } else if (self.actionKind == 0 && [self.overlay editorKindAtIndex:self.fieldIndex] == 3 && [value respondsToSelector:@selector(boolValue)]) {
        BOOL desired = [value boolValue];
        BOOL current = [[self.overlay draftAtIndex:self.fieldIndex] isEqualToString:@"true"];
        if (desired != current) [self.overlay toggleBooleanAtIndex:self.fieldIndex];
    }
}

@end

@implementation CJGuiInternalSharedEditingFormOverlay

- (instancetype)initWithFrame:(NSRect)frame session:(CJGuiInternalSession *)session {
    self = [super initWithFrame:frame];
    if (!self) return nil;
    self.session = session;
    self.fieldLabels = [NSMutableArray array];
    self.draftTexts = [NSMutableArray array];
    self.validationErrors = [NSMutableArray array];
    self.editorKinds = [NSMutableArray array];
    self.accessibilityActions = [NSMutableArray array];
    self.statusText = @"";
    self.inputNotice = @"";
    self.collectionEnabled = NO;
    self.collectionTitles = [NSMutableArray array];
    self.collectionSelectedRow = UINT32_MAX;
    self.collectionViewportStart = 0;
    self.collectionTotalCount = 0;
    self.collectionFilterText = @"";
    self.activeTextFieldIndex = NSNotFound;
    self.wantsLayer = YES;
    self.layer.backgroundColor = NSColor.clearColor.CGColor;
    self.inputProxy = [[NSTextView alloc] initWithFrame:NSMakeRect(-2.0, -2.0, 1.0, 1.0)];
    self.inputProxy.delegate = self;
    self.inputProxy.drawsBackground = NO;
    self.inputProxy.alphaValue = 0.01;
    self.inputProxy.editable = YES;
    self.inputProxy.selectable = YES;
    self.inputProxy.richText = NO;
    self.inputProxy.usesRuler = NO;
    [self addSubview:self.inputProxy];
    [[NSNotificationCenter defaultCenter] addObserver:self
                                             selector:@selector(inputProxySelectionDidChange:)
                                                 name:NSTextViewDidChangeSelectionNotification
                                               object:self.inputProxy];
    return self;
}

- (void)dealloc { [[NSNotificationCenter defaultCenter] removeObserver:self]; }
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)isAccessibilityElement { return NO; }
- (NSAccessibilityRole)accessibilityRole { return NSAccessibilityGroupRole; }
- (NSString *)accessibilityLabel { return @"CJGUI shared editing form"; }
- (NSArray<id> *)accessibilityChildren { return [self.accessibilityActions copy]; }

- (void)setFieldCountForProjection:(uint32_t)fieldCount {
    self.fieldCount = fieldCount;
    while (self.fieldLabels.count < fieldCount) {
        uint32_t index = (uint32_t)self.fieldLabels.count;
        [self.fieldLabels addObject:@"字段"];
        [self.draftTexts addObject:@""];
        [self.validationErrors addObject:@""];
        [self.editorKinds addObject:@1];
        [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:index actionKind:0]];
    }
    while (self.fieldLabels.count > fieldCount) {
        [self.fieldLabels removeLastObject]; [self.draftTexts removeLastObject];
        [self.validationErrors removeLastObject]; [self.editorKinds removeLastObject];
        [self.accessibilityActions removeLastObject];
    }
    [self rebuildAccessibilityActions];
    [self setNeedsDisplay:YES];
}

- (void)rebuildAccessibilityActions {
    [self.accessibilityActions removeAllObjects];
    for (uint32_t index = 0; index < self.fieldCount; index++) {
        [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:index actionKind:0]];
    }
    [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:0 actionKind:2]];
    [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:0 actionKind:3]];
    if (self.collectionEnabled) {
        for (uint32_t index = 0; index < self.collectionRowCount; index++) {
            [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:index actionKind:4]];
        }
        for (uint32_t kind = 5; kind <= 18; kind++) {
            [self.accessibilityActions addObject:[[CJGuiInternalSharedEditingFormAccessibilityAction alloc] initWithOverlay:self fieldIndex:0 actionKind:kind]];
        }
    }
}

- (void)setCollectionEnabled:(BOOL)enabled visibleRecordCount:(uint32_t)visibleRecordCount {
    self.collectionEnabled = enabled;
    self.collectionRowCount = enabled ? visibleRecordCount : 0;
    while (self.collectionTitles.count < self.collectionRowCount) [self.collectionTitles addObject:@"未命名记录"];
    while (self.collectionTitles.count > self.collectionRowCount) [self.collectionTitles removeLastObject];
    self.collectionSelectedRow = UINT32_MAX;
    self.collectionViewportStart = 0;
    self.collectionTotalCount = 0;
    [self rebuildAccessibilityActions];
    [self setNeedsDisplay:YES];
}

- (void)setCollectionRowAtIndex:(uint32_t)index title:(NSString *)title selected:(BOOL)selected viewportStart:(uint32_t)viewportStart totalRecordCount:(uint32_t)totalRecordCount {
    if (!self.collectionEnabled || index >= self.collectionRowCount) return;
    if (index == 0) self.collectionSelectedRow = UINT32_MAX;
    self.collectionTitles[index] = title ?: @"未命名记录";
    self.collectionViewportStart = viewportStart;
    self.collectionTotalCount = totalRecordCount;
    if (selected) self.collectionSelectedRow = index;
    [self setNeedsDisplay:YES];
}

- (void)setCollectionFilter:(NSString *)filterText {
    NSString *next = filterText ?: @"";
    if ([self.collectionFilterText isEqualToString:next]) return;
    self.collectionFilterText = next;
    if (self.activeTextFieldIndex == -2) {
        BOOL wasApplying = self.applyingProjection;
        self.applyingProjection = YES;
        self.inputProxy.string = next;
        self.inputProxy.selectedRange = CjguiComposedSelection(next, next.length, next.length);
        self.applyingProjection = wasApplying;
    }
    [self setNeedsDisplay:YES];
}

- (NSRect)fieldRectAtIndex:(uint32_t)index {
    CGFloat origin = self.collectionEnabled ? 430.0 : 180.0;
    CGFloat width = MAX(80.0, self.bounds.size.width - origin - 22.0);
    return NSMakeRect(origin, 61.0 + (CGFloat)index * 76.0, width, 28.0);
}
- (CGFloat)bottom { return 64.0 + (CGFloat)self.fieldCount * 76.0; }
- (NSRect)applyRect { return NSMakeRect(self.collectionEnabled ? 270.0 : 22.0, [self bottom] + 32.0, 110.0, 30.0); }
- (NSRect)cancelRect { return NSMakeRect(self.collectionEnabled ? 390.0 : 142.0, [self bottom] + 32.0, 120.0, 30.0); }
- (NSRect)collectionRowRectAtIndex:(uint32_t)index { return NSMakeRect(14.0, 120.0 + (CGFloat)index * 36.0, 236.0, 30.0); }
- (NSRect)collectionFilterRect { return NSMakeRect(14.0, 48.0, 236.0, 26.0); }
- (NSRect)collectionCreateRect { return NSMakeRect(14.0, 82.0, 72.0, 26.0); }
- (NSRect)collectionCopyRect { return NSMakeRect(94.0, 82.0, 72.0, 26.0); }
- (NSRect)collectionDeleteRect { return NSMakeRect(174.0, 82.0, 72.0, 26.0); }
- (NSRect)collectionPreviousRect { return NSMakeRect(14.0, MAX(390.0, self.bounds.size.height - 128.0), 52.0, 26.0); }
- (NSRect)collectionNextRect { return NSMakeRect(74.0, MAX(390.0, self.bounds.size.height - 128.0), 52.0, 26.0); }
- (NSRect)collectionUndoRect { return NSMakeRect(134.0, MAX(390.0, self.bounds.size.height - 128.0), 52.0, 26.0); }
- (NSRect)collectionRedoRect { return NSMakeRect(194.0, MAX(390.0, self.bounds.size.height - 128.0), 52.0, 26.0); }
- (NSRect)collectionSaveRect { return NSMakeRect(14.0, MAX(424.0, self.bounds.size.height - 94.0), 66.0, 26.0); }
- (NSRect)collectionSaveAsRect { return NSMakeRect(88.0, MAX(424.0, self.bounds.size.height - 94.0), 66.0, 26.0); }
- (NSRect)collectionOpenRect { return NSMakeRect(162.0, MAX(424.0, self.bounds.size.height - 94.0), 66.0, 26.0); }
- (NSRect)collectionNewRect { return NSMakeRect(14.0, MAX(458.0, self.bounds.size.height - 60.0), 66.0, 26.0); }
- (NSRect)collectionDiscardRect { return NSMakeRect(88.0, MAX(458.0, self.bounds.size.height - 60.0), 66.0, 26.0); }
- (NSRect)collectionCloseRect { return NSMakeRect(162.0, MAX(458.0, self.bounds.size.height - 60.0), 66.0, 26.0); }
- (NSString *)labelAtIndex:(uint32_t)index { return index < self.fieldLabels.count ? self.fieldLabels[index] : @"字段"; }
- (NSString *)draftAtIndex:(uint32_t)index { return index < self.draftTexts.count ? self.draftTexts[index] : @""; }
- (uint32_t)editorKindAtIndex:(uint32_t)index { return index < self.editorKinds.count ? self.editorKinds[index].unsignedIntValue : 1; }

- (void)setFieldAtIndex:(uint32_t)index label:(NSString *)label draftText:(NSString *)draftText
                   error:(NSString *)error editorKind:(uint32_t)editorKind focused:(BOOL)focused
          selectionStart:(uint32_t)selectionStart selectionEnd:(uint32_t)selectionEnd {
    if (index >= self.fieldCount) return;
    self.applyingProjection = YES;
    self.fieldLabels[index] = label ?: @"字段";
    self.draftTexts[index] = draftText ?: @"";
    self.validationErrors[index] = error ?: @"";
    self.editorKinds[index] = @(editorKind);
    if (focused && editorKind != 3) {
        [self focusTextFieldAtIndex:index
                           selection:CjguiComposedSelection(self.draftTexts[index], selectionStart, selectionEnd)
                        enqueueFocus:NO];
    } else if (self.activeTextFieldIndex == (NSInteger)index && editorKind == 3) {
        self.activeTextFieldIndex = NSNotFound;
    }
    self.applyingProjection = NO;
    [self setNeedsDisplay:YES];
}

- (void)setStatus:(NSString *)status { self.statusText = status ?: @""; [self setNeedsDisplay:YES]; }

- (void)chooseOpenFile {
    NSOpenPanel *panel = [NSOpenPanel openPanel];
    panel.canChooseFiles = YES;
    panel.canChooseDirectories = NO;
    panel.allowsMultipleSelection = NO;
    panel.prompt = @"打开规则集";
    panel.allowedFileTypes = @[ @"cjgui-rules" ];
    if ([panel runModal] == NSModalResponseOK && panel.URL.path.length > 0) {
        [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_OPEN index:0 text:panel.URL.path selection:NSMakeRange(0, 0)];
    }
}

- (void)chooseSaveAsFile {
    NSSavePanel *panel = [NSSavePanel savePanel];
    panel.prompt = @"另存为";
    panel.nameFieldStringValue = @"规则集.cjgui-rules";
    panel.allowedFileTypes = @[ @"cjgui-rules" ];
    if ([panel runModal] == NSModalResponseOK && panel.URL.path.length > 0) {
        [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_SAVE_AS index:0 text:panel.URL.path selection:NSMakeRange(0, 0)];
    }
}

- (void)queue:(uint32_t)kind index:(uint32_t)index text:(NSString *)text selection:(NSRange)selection {
    if (!self.session || self.applyingProjection) return;
    if (!CjguiEnqueueInteraction(self.session, kind, index, text,
                                 (uint32_t)MIN(selection.location, UINT32_MAX),
                                 (uint32_t)MIN(NSMaxRange(selection), UINT32_MAX))) {
        self.inputNotice = @"输入队列已满；未接收的输入请重试";
        [self setNeedsDisplay:YES];
    }
}

- (void)focusTextFieldAtIndex:(uint32_t)index selection:(NSRange)selection enqueueFocus:(BOOL)enqueueFocus {
    if (index >= self.fieldCount || [self editorKindAtIndex:index] == 3) return;
    self.activeTextFieldIndex = index;
    NSString *draft = [self draftAtIndex:index];
    NSRange clamped = CjguiComposedSelection(draft, selection.location, NSMaxRange(selection));
    BOOL wasApplying = self.applyingProjection;
    self.applyingProjection = YES;
    if (![self.inputProxy.string isEqualToString:draft]) self.inputProxy.string = draft;
    [self.window makeFirstResponder:self.inputProxy];
    self.inputProxy.selectedRange = clamped;
    self.applyingProjection = wasApplying;
    if (enqueueFocus) [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_FOCUS index:index text:draft selection:clamped];
    [self setNeedsDisplay:YES];
}

- (void)focusCollectionFilterEnqueue:(BOOL)enqueue {
    if (!self.collectionEnabled) return;
    self.activeTextFieldIndex = -2;
    BOOL wasApplying = self.applyingProjection;
    self.applyingProjection = YES;
    self.inputProxy.string = self.collectionFilterText ?: @"";
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, self.inputProxy.string.length, self.inputProxy.string.length);
    [self.window makeFirstResponder:self.inputProxy];
    self.applyingProjection = wasApplying;
    if (enqueue) [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_FILTER_CHANGED index:0 text:self.inputProxy.string selection:self.inputProxy.selectedRange];
    [self setNeedsDisplay:YES];
}

- (void)toggleBooleanAtIndex:(uint32_t)index {
    if (index >= self.fieldCount || [self editorKindAtIndex:index] != 3) return;
    NSString *next = [[self draftAtIndex:index] isEqualToString:@"true"] ? @"false" : @"true";
    [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_BOOLEAN_CHANGED index:index text:next selection:NSMakeRange(0, 0)];
}

- (void)accessibilitySetText:(NSString *)text atIndex:(uint32_t)index {
    if (index >= self.fieldCount || [self editorKindAtIndex:index] == 3) return;
    [self focusTextFieldAtIndex:index selection:NSMakeRange(text.length, 0) enqueueFocus:YES];
    self.applyingProjection = YES;
    self.inputProxy.string = text ?: @"";
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, self.inputProxy.string.length, self.inputProxy.string.length);
    self.applyingProjection = NO;
    [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_TEXT_CHANGED index:index text:self.inputProxy.string selection:self.inputProxy.selectedRange];
}

- (void)accessibilitySetCollectionFilter:(NSString *)filterText {
    [self focusCollectionFilterEnqueue:NO];
    self.applyingProjection = YES;
    self.inputProxy.string = filterText ?: @"";
    self.inputProxy.selectedRange = CjguiComposedSelection(self.inputProxy.string, self.inputProxy.string.length, self.inputProxy.string.length);
    self.applyingProjection = NO;
    [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_FILTER_CHANGED index:0 text:self.inputProxy.string selection:self.inputProxy.selectedRange];
}

- (void)textDidChange:(NSNotification *)notification {
    (void)notification;
    if (self.applyingProjection || self.activeTextFieldIndex == NSNotFound || self.inputProxy.hasMarkedText) return;
    NSRange selection = CjguiComposedSelection(self.inputProxy.string, self.inputProxy.selectedRange.location, NSMaxRange(self.inputProxy.selectedRange));
    if (self.activeTextFieldIndex == -2) {
        [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_FILTER_CHANGED index:0 text:self.inputProxy.string selection:selection];
        return;
    }
    [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_TEXT_CHANGED index:(uint32_t)self.activeTextFieldIndex text:self.inputProxy.string selection:selection];
}

- (void)inputProxySelectionDidChange:(NSNotification *)notification {
    (void)notification;
    if (self.applyingProjection || self.activeTextFieldIndex == NSNotFound || self.inputProxy.hasMarkedText) return;
    NSRange selection = CjguiComposedSelection(self.inputProxy.string, self.inputProxy.selectedRange.location, NSMaxRange(self.inputProxy.selectedRange));
    if (self.activeTextFieldIndex == -2) {
        [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_FILTER_CHANGED index:0 text:self.inputProxy.string selection:selection];
        return;
    }
    [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_TEXT_CHANGED index:(uint32_t)self.activeTextFieldIndex text:self.inputProxy.string selection:selection];
}

- (void)mouseDown:(NSEvent *)event {
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    if (self.collectionEnabled) {
        if (NSPointInRect(point, [self collectionFilterRect])) { [self focusCollectionFilterEnqueue:YES]; return; }
        if (NSPointInRect(point, [self collectionCreateRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CREATE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionCopyRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_COPY index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionDeleteRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_DELETE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionPreviousRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_PREVIOUS_PAGE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionNextRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_NEXT_PAGE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionUndoRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_UNDO index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionRedoRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_REDO index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionSaveRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_SAVE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionSaveAsRect])) { [self chooseSaveAsFile]; return; }
        if (NSPointInRect(point, [self collectionOpenRect])) { [self chooseOpenFile]; return; }
        if (NSPointInRect(point, [self collectionNewRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_NEW index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionDiscardRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_DISCARD index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        if (NSPointInRect(point, [self collectionCloseRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_CLOSE index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
        for (uint32_t index = 0; index < self.collectionRowCount; index++) {
            if (NSPointInRect(point, [self collectionRowRectAtIndex:index])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_SELECT index:index text:@"" selection:NSMakeRange(0, 0)]; return; }
        }
    }
    if (NSPointInRect(point, [self applyRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_APPLY index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
    if (NSPointInRect(point, [self cancelRect])) { [self queue:CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_FORM_CANCEL index:0 text:@"" selection:NSMakeRange(0, 0)]; return; }
    for (uint32_t index = 0; index < self.fieldCount; index++) {
        if (!NSPointInRect(point, [self fieldRectAtIndex:index])) continue;
        if ([self editorKindAtIndex:index] == 3) [self toggleBooleanAtIndex:index];
        else [self focusTextFieldAtIndex:index selection:NSMakeRange(0, 0) enqueueFocus:YES];
        return;
    }
}

- (void)scrollWheel:(NSEvent *)event {
    if (!self.collectionEnabled || event.scrollingDeltaY == 0.0) { [super scrollWheel:event]; return; }
    uint32_t kind = event.scrollingDeltaY < 0.0 ? CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_NEXT_PAGE : CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COLLECTION_PREVIOUS_PAGE;
    [self queue:kind index:0 text:@"" selection:NSMakeRange(0, 0)];
}

- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    [[NSColor colorWithCalibratedWhite:0.97 alpha:0.96] setFill];
    NSRectFill(self.bounds);
    NSDictionary *heading = @{ NSFontAttributeName: [NSFont boldSystemFontOfSize:19.0], NSForegroundColorAttributeName: NSColor.labelColor };
    CGFloat detailOrigin = self.collectionEnabled ? 270.0 : 22.0;
    [self.collectionEnabled ? @"CJGUI collection editor" : @"CJGUI shared editing form" drawAtPoint:NSMakePoint(detailOrigin, 18.0) withAttributes:heading];
    [@"编辑草稿后应用；输入、选区和校验状态由仓颉领域统一拥有。" drawAtPoint:NSMakePoint(detailOrigin, 43.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:12.0], NSForegroundColorAttributeName: NSColor.secondaryLabelColor }];
    if (self.collectionEnabled) {
        NSDictionary *small = @{ NSFontAttributeName: [NSFont systemFontOfSize:12.0], NSForegroundColorAttributeName: NSColor.secondaryLabelColor };
        [@"记录" drawAtPoint:NSMakePoint(14.0, 18.0) withAttributes:heading];
        NSString *count = [NSString stringWithFormat:@"共 %u 条 · 第 %u 页", self.collectionTotalCount, self.collectionViewportStart / MAX(1u, self.collectionRowCount) + 1];
        [count drawAtPoint:NSMakePoint(14.0, 32.0) withAttributes:small];
        NSRect filterRect = [self collectionFilterRect];
        [[NSColor textBackgroundColor] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:filterRect xRadius:5.0 yRadius:5.0] fill];
        [NSColor.separatorColor setStroke];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(filterRect, 0.5, 0.5) xRadius:5.0 yRadius:5.0] stroke];
        NSString *filterLabel = self.collectionFilterText.length > 0
            ? [NSString stringWithFormat:@"筛选：%@", self.collectionFilterText] : @"筛选记录";
        [filterLabel drawInRect:NSInsetRect(filterRect, 7.0, 6.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:12.0], NSForegroundColorAttributeName: self.collectionFilterText.length > 0 ? NSColor.labelColor : NSColor.placeholderTextColor }];
        for (NSArray *button in @[ @[@"新增", [NSValue valueWithRect:[self collectionCreateRect]]], @[@"复制", [NSValue valueWithRect:[self collectionCopyRect]]], @[@"删除", [NSValue valueWithRect:[self collectionDeleteRect]]], @[@"上一页", [NSValue valueWithRect:[self collectionPreviousRect]]], @[@"下一页", [NSValue valueWithRect:[self collectionNextRect]]], @[@"撤销", [NSValue valueWithRect:[self collectionUndoRect]]], @[@"重做", [NSValue valueWithRect:[self collectionRedoRect]]], @[@"保存", [NSValue valueWithRect:[self collectionSaveRect]]], @[@"另存为", [NSValue valueWithRect:[self collectionSaveAsRect]]], @[@"打开", [NSValue valueWithRect:[self collectionOpenRect]]], @[@"新建", [NSValue valueWithRect:[self collectionNewRect]]], @[@"放弃", [NSValue valueWithRect:[self collectionDiscardRect]]], @[@"关闭", [NSValue valueWithRect:[self collectionCloseRect]]] ]) {
            NSRect rect = [button[1] rectValue];
            [[NSColor controlBackgroundColor] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:5.0 yRadius:5.0] fill];
            [NSColor.separatorColor setStroke];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(rect, 0.5, 0.5) xRadius:5.0 yRadius:5.0] stroke];
            [button[0] drawInRect:NSInsetRect(rect, 6.0, 6.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:12.0 weight:NSFontWeightMedium], NSForegroundColorAttributeName: NSColor.labelColor }];
        }
        for (uint32_t index = 0; index < self.collectionRowCount; index++) {
            NSRect row = [self collectionRowRectAtIndex:index];
            BOOL selected = self.collectionSelectedRow == index;
            [(selected ? NSColor.selectedContentBackgroundColor : NSColor.controlBackgroundColor) setFill];
            [[NSBezierPath bezierPathWithRoundedRect:row xRadius:5.0 yRadius:5.0] fill];
            [self.collectionTitles[index] drawInRect:NSInsetRect(row, 8.0, 7.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:13.0], NSForegroundColorAttributeName: selected ? NSColor.alternateSelectedControlTextColor : NSColor.labelColor }];
        }
        [NSColor.separatorColor setStroke];
        [NSBezierPath strokeLineFromPoint:NSMakePoint(260.0, 14.0) toPoint:NSMakePoint(260.0, self.bounds.size.height - 14.0)];
    }
    for (uint32_t index = 0; index < self.fieldCount; index++) {
        CGFloat top = 64.0 + (CGFloat)index * 76.0;
        NSString *label = [self labelAtIndex:index];
        [label drawInRect:NSMakeRect(detailOrigin, top, self.collectionEnabled ? 145.0 : 150.0, 20.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:14.0 weight:NSFontWeightMedium], NSForegroundColorAttributeName: NSColor.labelColor }];
        NSRect rect = [self fieldRectAtIndex:index];
        BOOL focused = self.activeTextFieldIndex == (NSInteger)index;
        [[NSColor controlBackgroundColor] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:5.0 yRadius:5.0] fill];
        [(focused ? NSColor.keyboardFocusIndicatorColor : NSColor.separatorColor) setStroke];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(rect, 0.5, 0.5) xRadius:5.0 yRadius:5.0] stroke];
        if ([self editorKindAtIndex:index] == 3) {
            BOOL enabled = [[self draftAtIndex:index] isEqualToString:@"true"];
            NSString *check = enabled ? @"☑" : @"☐";
            [check drawAtPoint:NSMakePoint(rect.origin.x + 8.0, rect.origin.y + 5.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:16.0], NSForegroundColorAttributeName: NSColor.labelColor }];
            [label drawAtPoint:NSMakePoint(rect.origin.x + 31.0, rect.origin.y + 7.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:13.0], NSForegroundColorAttributeName: NSColor.labelColor }];
        } else {
            [[self draftAtIndex:index] drawInRect:NSInsetRect(rect, 8.0, 5.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:14.0], NSForegroundColorAttributeName: NSColor.labelColor }];
        }
        NSString *error = self.validationErrors[index];
        if (error.length > 0) [error drawAtPoint:NSMakePoint(rect.origin.x, top + 27.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:11.0], NSForegroundColorAttributeName: NSColor.systemRedColor }];
    }
    NSString *status = self.inputNotice.length > 0 ? self.inputNotice : self.statusText;
    [status drawInRect:NSMakeRect(22.0, [self bottom] + 5.0, MAX(0.0, self.bounds.size.width - 44.0), 18.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:12.0], NSForegroundColorAttributeName: self.inputNotice.length > 0 ? NSColor.systemRedColor : NSColor.secondaryLabelColor }];
    for (NSArray *button in @[ @[@"应用草稿", [NSValue valueWithRect:[self applyRect]]], @[@"取消并重载", [NSValue valueWithRect:[self cancelRect]]] ]) {
        NSRect rect = [button[1] rectValue];
        [[NSColor controlAccentColor] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:6.0 yRadius:6.0] fill];
        [button[0] drawInRect:NSInsetRect(rect, 10.0, 7.0) withAttributes:@{ NSFontAttributeName: [NSFont systemFontOfSize:13.0 weight:NSFontWeightMedium], NSForegroundColorAttributeName: NSColor.alternateSelectedControlTextColor }];
    }
}

@end

// ---- session table ----

static BOOL CjguiIsMainThread(void) {
    return [NSThread isMainThread];
}

// Test-only: run a bounded test-hook body on the AppKit main thread when the
// running Cangjie code is on the runtime worker (the macOS launcher case). The
// gate mirrors the production one: with main-thread dispatch disabled (no
// launcher) the body runs inline, so direct probe execution keeps its previous
// behavior instead of failing.
static void CjguiTestHookOnMainThread(dispatch_block_t block) {
    if (CjguiIsMainThread() || !gCjguiMainThreadDispatchEnabled) {
        block();
        return;
    }
    dispatch_sync(dispatch_get_main_queue(), block);
}

void cjgui_internal_renderer_enable_main_thread_dispatch(void) {
    if (CjguiIsMainThread()) {
        gCjguiMainThreadDispatchEnabled = YES;
    }
}

void cjgui_internal_renderer_request_application_stop(void) {
    dispatch_async(dispatch_get_main_queue(), ^{
        [NSApp stop:nil];
        [NSApp postEvent:[NSEvent otherEventWithType:NSEventTypeApplicationDefined
                                            location:NSZeroPoint
                                       modifierFlags:0
                                           timestamp:0
                                        windowNumber:0
                                             context:nil
                                             subtype:0
                                               data1:0
                                               data2:0]
                atStart:NO];
    });
}

void cjgui_internal_renderer_complete_application_exit_request(void) {
    if (CjguiIsMainThread()) {
        atomic_store_explicit(&gCjguiApplicationExitRequestWasUnkeyed, false, memory_order_release);
        atomic_store_explicit(&gCjguiApplicationExitRequestPending, false, memory_order_release);
        return;
    }
    // This never asks Cangjie to run on AppKit's main thread. It only clears
    // the native coalescing bit after the Cangjie application turn has made
    // its own existing exit decision.
    dispatch_async(dispatch_get_main_queue(), ^{
        atomic_store_explicit(&gCjguiApplicationExitRequestWasUnkeyed, false, memory_order_release);
        atomic_store_explicit(&gCjguiApplicationExitRequestPending, false, memory_order_release);
    });
}

void cjgui_internal_renderer_retain_application_exit_lifecycle_owner(void) {
    uint32_t observed = atomic_load_explicit(&gCjguiApplicationExitLifecycleOwnerCount, memory_order_relaxed);
    while (observed < UINT32_MAX &&
           !atomic_compare_exchange_weak_explicit(&gCjguiApplicationExitLifecycleOwnerCount, &observed, observed + 1,
                                                  memory_order_release, memory_order_relaxed)) {
    }
}

void cjgui_internal_renderer_release_application_exit_lifecycle_owner(void) {
    uint32_t observed = atomic_load_explicit(&gCjguiApplicationExitLifecycleOwnerCount, memory_order_relaxed);
    while (observed > 0 &&
           !atomic_compare_exchange_weak_explicit(&gCjguiApplicationExitLifecycleOwnerCount, &observed, observed - 1,
                                                  memory_order_release, memory_order_relaxed)) {
    }
}

uint8_t cjgui_internal_renderer_has_unkeyed_application_exit_request(void) {
    return atomic_load_explicit(&gCjguiApplicationExitRequestPending, memory_order_acquire) &&
        atomic_load_explicit(&gCjguiApplicationExitRequestWasUnkeyed, memory_order_acquire) &&
        atomic_load_explicit(&gCjguiApplicationExitLifecycleOwnerCount, memory_order_acquire) > 0 ? 1u : 0u;
}

@interface CJGuiInternalApplicationTerminationDelegate : NSObject <NSApplicationDelegate>
@end

@implementation CJGuiInternalApplicationTerminationDelegate

- (NSApplicationTerminateReply)applicationShouldTerminate:(NSApplication *)sender {
    (void)sender;
    if (atomic_load_explicit(&gCjguiApplicationExitRequestPending, memory_order_acquire)) {
        return NSTerminateCancel;
    }
    CJGuiInternalSession *session = CjguiComposableCommandMenuKeySession();
    if (!session) {
        // A CjguiMacosApplication can remain live with every window hidden or
        // otherwise non-key. Its Cangjie lifecycle registry, not focus, owns
        // the decision in that case. A legacy one-window Host does not retain
        // this reference and keeps AppKit's documented no-owner termination.
        if (atomic_load_explicit(&gCjguiApplicationExitLifecycleOwnerCount, memory_order_acquire) == 0) {
            return NSTerminateNow;
        }
        atomic_store_explicit(&gCjguiApplicationExitRequestWasUnkeyed, true, memory_order_release);
        atomic_store_explicit(&gCjguiApplicationExitRequestPending, true, memory_order_release);
        return NSTerminateCancel;
    }
    if (!CjguiEnqueueComposableInteraction(session,
                                            CJGUI_INTERNAL_RENDERER_EVENT_APPLICATION_EXIT_REQUESTED,
                                            0, @"", NSMakeRange(0, 0))) {
        // Do not close a live framework application merely because its FIFO
        // is full. The unchanged owner remains usable and a later Quit can
        // retry after the normal pump drains it.
        return NSTerminateCancel;
    }
    atomic_store_explicit(&gCjguiApplicationExitRequestWasUnkeyed, false, memory_order_release);
    atomic_store_explicit(&gCjguiApplicationExitRequestPending, true, memory_order_release);
    return NSTerminateCancel;
}

@end

static CJGuiInternalApplicationTerminationDelegate *gCjguiApplicationTerminationDelegate;

static void CjguiInstallApplicationTerminationDelegate(NSApplication *app) {
    if (!app) return;
    if (!gCjguiApplicationTerminationDelegate) {
        gCjguiApplicationTerminationDelegate = [[CJGuiInternalApplicationTerminationDelegate alloc] init];
    }
    // The bundled CJGUI launcher owns this NSApplication. Do not overwrite an
    // embedding application's delegate, which would be a materially
    // different lifecycle contract; normal framework bundles start with nil.
    if (!app.delegate || app.delegate == gCjguiApplicationTerminationDelegate) {
        app.delegate = gCjguiApplicationTerminationDelegate;
    }
}

static CjguiInternalRendererStatus CjguiEnsureApp(NSApplication **outApp) {
    NSApplication *app = [NSApplication sharedApplication];
    if (!app) {
        return CJGUI_INTERNAL_RENDERER_APP_INIT_FAILED;
    }
    if (app.activationPolicy == NSApplicationActivationPolicyProhibited) {
        [app setActivationPolicy:NSApplicationActivationPolicyRegular];
    }
    CjguiInstallApplicationTerminationDelegate(app);
    *outApp = app;
    return CJGUI_INTERNAL_RENDERER_OK;
}

static uint64_t CjguiAllocateSession(CJGuiInternalSession *session) {
    for (NSUInteger i = 0; i < kCjguiSessionCapacity; i++) {
        if (!gCjguiSessionOccupied[i]) {
            session.sessionGeneration = gCjguiNextSessionGeneration;
            gCjguiNextSessionGeneration += 1;
            if (gCjguiNextSessionGeneration == 0) gCjguiNextSessionGeneration = 1;
            gCjguiSessionOccupied[i] = YES;
            gCjguiSessions[i] = session;
            // Token = (slot index + 1) so 0 stays the invalid sentinel.
            session.rendererSessionToken = (uint64_t)(i + 1);
            // Bind the view to its session only now: the view was created before
            // the token existed, so the earlier assignment wrote a zero and the
            // raster path could not reach session-scoped presentation data.
            if (session.view) {
                session.view.sessionToken = session.rendererSessionToken;
            }
            return session.rendererSessionToken;
        }
    }
    return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
}

static CJGuiInternalSession *CjguiLookupSession(uint64_t token) {
    if (token == CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN || token > kCjguiSessionCapacity) {
        return nil;
    }
    NSUInteger idx = (NSUInteger)(token - 1);
    if (!gCjguiSessionOccupied[idx]) {
        return nil;
    }
    return gCjguiSessions[idx];
}

static BOOL CjguiWindowReduceTransparency(CJGuiInternalSession *session) {
#ifdef CJGUI_INTERNAL_TESTING
    if (session.testWindowBackgroundEnvironmentOverrideEnabled)
        return session.testWindowBackgroundReduceTransparency;
#endif
    return NSWorkspace.sharedWorkspace.accessibilityDisplayShouldReduceTransparency;
}

static void CjguiSetOpaqueWindowFallback(CJGuiInternalSession *session) {
    if (!session) return;
    session.windowMaterialView.hidden = YES;
    session.windowOpaqueFallbackView.hidden = NO;
    session.windowBackgroundHostAppliedSystem = NO;
}

static uint32_t CjguiWindowColorSchemeForAppearance(NSAppearance *appearance) {
    NSAppearance *resolved = appearance ?: NSApp.effectiveAppearance;
    NSAppearanceName match = [resolved bestMatchFromAppearancesWithNames:
        @[ NSAppearanceNameAqua, NSAppearanceNameDarkAqua ]];
    return [match isEqualToString:NSAppearanceNameDarkAqua] ? 2u : 1u;
}

static void CjguiSetWindowBackgroundScheme(CJGuiInternalSession *session, uint32_t colorScheme) {
    if (!session) return;
    if (colorScheme != 1 && colorScheme != 2) colorScheme = 2;
    if (session.windowMaterialView) {
        session.windowMaterialView.appearance = [NSAppearance appearanceNamed:
            colorScheme == 1 ? NSAppearanceNameAqua : NSAppearanceNameDarkAqua];
    }
    if (session.windowOpaqueFallbackView.wantsLayer) {
        NSColor *color = colorScheme == 1
            ? [NSColor colorWithCalibratedRed:0.94 green:0.95 blue:0.97 alpha:1.0]
            : [NSColor colorWithCalibratedRed:0.08 green:0.16 blue:0.20 alpha:1.0];
        session.windowOpaqueFallbackView.layer.backgroundColor = color.CGColor;
    }
}

// Runs only as part of scene presentation, except that the reduce-transparency
// notification may synchronously reveal the already resident opaque fallback.
// The visual-effect getter proves AppKit host installation, not displayed pixels.
static BOOL CjguiApplyWindowBackground(CJGuiInternalSession *session, uint32_t requestedMode,
                                       uint32_t colorScheme,
                                       uint32_t *outActualMode, uint32_t *outReason) {
    if (outActualMode) *outActualMode = 0;
    if (outReason) *outReason = requestedMode == 0 ? 0 : 3;
    if (!session || !session.windowContentHost || !session.windowOpaqueFallbackView) return NO;
    CjguiSetWindowBackgroundScheme(session, colorScheme);
    if (requestedMode == 0) {
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 0;
        session.windowBackgroundFallbackReason = 0;
        if (outActualMode) *outActualMode = 0;
        if (outReason) *outReason = 0;
        return YES;
    }
    if (requestedMode != 1) return NO;
    BOOL reduce = CjguiWindowReduceTransparency(session);
    session.windowBackgroundReduceTransparency = reduce;
    if (reduce) {
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 2;
        session.windowBackgroundFallbackReason = 2;
        if (outActualMode) *outActualMode = 2;
        if (outReason) *outReason = 2;
        return YES;
    }
    if (!session.windowMaterialView) {
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 2;
        session.windowBackgroundFallbackReason = 3;
        if (outActualMode) *outActualMode = 2;
        if (outReason) *outReason = 3;
        return YES;
    }
#ifdef CJGUI_INTERNAL_TESTING
    if (session.forcedWindowMaterialPrepareFailures > 0) {
        session.forcedWindowMaterialPrepareFailures -= 1;
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 2;
        session.windowBackgroundFallbackReason = 4;
        if (outActualMode) *outActualMode = 2;
        if (outReason) *outReason = 4;
        return YES;
    }
#endif
    NSVisualEffectView *material = session.windowMaterialView;
    material.material = NSVisualEffectMaterialUnderWindowBackground;
    material.blendingMode = NSVisualEffectBlendingModeBehindWindow;
    material.state = NSVisualEffectStateFollowsWindowActiveState;
    if (!material.superview || material.superview != session.windowContentHost) {
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 2;
        session.windowBackgroundFallbackReason = 5;
        if (outActualMode) *outActualMode = 2;
        if (outReason) *outReason = 5;
        return YES;
    }
#ifdef CJGUI_INTERNAL_TESTING
    if (session.forcedWindowMaterialHostApplyFailures > 0) {
        session.forcedWindowMaterialHostApplyFailures -= 1;
        CjguiSetOpaqueWindowFallback(session);
        session.windowBackgroundActualMode = 2;
        session.windowBackgroundFallbackReason = 5;
        if (outActualMode) *outActualMode = 2;
        if (outReason) *outReason = 5;
        return YES;
    }
#endif
    session.windowOpaqueFallbackView.hidden = YES;
    material.hidden = NO;
    session.windowBackgroundHostAppliedSystem = YES;
    session.windowBackgroundActualMode = 1;
    session.windowBackgroundFallbackReason = 1;
    if (outActualMode) *outActualMode = 1;
    if (outReason) *outReason = 1;
    return YES;
}

static void CjguiReleaseSession(uint64_t token) {
    if (token == CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN || token > kCjguiSessionCapacity) {
        return;
    }
    NSUInteger idx = (NSUInteger)(token - 1);
    gCjguiSessionOccupied[idx] = NO;
    gCjguiSessions[idx] = nil;
}

static CJGuiInternalSession *CjguiComposableCommandMenuKeySession(void) {
    NSWindow *keyWindow = NSApp.keyWindow;
    if (!keyWindow) return nil;
    CJGuiInternalSession *session = objc_getAssociatedObject(keyWindow, &CJGuiSessionWindowAssociationKey);
    return session && !session.destroyed ? session : nil;
}

static BOOL CjguiComposableCommandMenuContainsEnabledCommand(CJGuiInternalSession *session, NSString *commandId) {
    if (!session || commandId.length == 0) return NO;
    for (CJGuiInternalComposableCommandMenuItem *item in session.composableCommandMenuItems) {
        if ([item.commandId isEqualToString:commandId]) {
            CJGuiInternalComposableSceneNode *active = [session.composableSceneOverlay activeFocusableNode];
            // Cangjie treats no explicit focus as the base scope. Preserve
            // that route for an initial button/menu declaration, while a real
            // non-base focused layer still suppresses base commands.
            return item.enabled && (active ? item.focusScope == active.node.inputScope : item.focusScope == 0);
        }
    }
    return NO;
}

@implementation CJGuiInternalComposableCommandMenuDispatcher

+ (instancetype)sharedDispatcher {
    static CJGuiInternalComposableCommandMenuDispatcher *dispatcher = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        dispatcher = [[CJGuiInternalComposableCommandMenuDispatcher alloc] init];
    });
    return dispatcher;
}

- (void)invokeComposableCommand:(id)sender {
    if (![sender isKindOfClass:[NSMenuItem class]]) return;
    NSString *commandId = ((NSMenuItem *)sender).representedObject;
    if (![commandId isKindOfClass:[NSString class]] || commandId.length == 0) return;
    // Do not trust the object that originally owned the menu item. A delayed
    // callback from window A is resolved against the *current key window* B;
    // B must still advertise the id as enabled before an intent may enter its
    // FIFO. Cangjie then validates target, scope and projection again.
    CJGuiInternalSession *session = CjguiComposableCommandMenuKeySession();
    if (!CjguiComposableCommandMenuContainsEnabledCommand(session, commandId)) return;
    (void)CjguiEnqueueComposableInteraction(session,
                                             CJGUI_INTERNAL_RENDERER_EVENT_HUMAN_COMPOSABLE_MENU_COMMAND,
                                             0, commandId, NSMakeRange(0, 0));
}

@end

static BOOL CjguiComposableMenuShortcutReservedForText(NSString *shortcut) {
    return [shortcut isEqualToString:@"shortcut:command+c"] ||
           [shortcut isEqualToString:@"shortcut:command+x"] ||
           [shortcut isEqualToString:@"shortcut:command+v"] ||
           [shortcut isEqualToString:@"shortcut:command+a"];
}

static void CjguiConfigureComposableMenuKeyEquivalent(NSMenuItem *menuItem, NSString *shortcut) {
    if (!menuItem || shortcut.length == 0 || CjguiComposableMenuShortcutReservedForText(shortcut)) return;
    NSArray<NSString *> *parts = [shortcut componentsSeparatedByString:@"+"];
    if (parts.count < 2) return;
    NSString *key = parts.lastObject.lowercaseString;
    if (key.length != 1) return;
    NSEventModifierFlags modifiers = 0;
    if ([shortcut rangeOfString:@"control+"].location != NSNotFound) modifiers |= NSEventModifierFlagControl;
    if ([shortcut rangeOfString:@"option+"].location != NSNotFound) modifiers |= NSEventModifierFlagOption;
    if ([shortcut rangeOfString:@"shift+"].location != NSNotFound) modifiers |= NSEventModifierFlagShift;
    if ([shortcut rangeOfString:@"command+"].location != NSNotFound) modifiers |= NSEventModifierFlagCommand;
    if (modifiers == 0) return;
    menuItem.keyEquivalent = key;
    menuItem.keyEquivalentModifierMask = modifiers;
}

static void CjguiAddStandardMenuItem(NSMenu *menu, NSString *title, SEL action, NSString *key,
                                     NSEventModifierFlags modifiers) {
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:key ?: @""];
    item.target = nil;
    item.enabled = YES;
    if (key.length > 0) item.keyEquivalentModifierMask = modifiers;
    [menu addItem:item];
}

static void CjguiAddStandardApplicationMenus(NSMenu *mainMenu,
                                             NSMutableDictionary<NSString *, NSMenu *> *menus) {
    NSString *appName = NSProcessInfo.processInfo.processName;
    if (appName.length == 0) appName = @"CJGUI";
    NSMenu *applicationMenu = [[NSMenu alloc] initWithTitle:appName];
    applicationMenu.autoenablesItems = NO;
    CjguiAddStandardMenuItem(applicationMenu, [@"About " stringByAppendingString:appName],
                             @selector(orderFrontStandardAboutPanel:), @"", 0);
    [applicationMenu addItem:[NSMenuItem separatorItem]];
    CjguiAddStandardMenuItem(applicationMenu, [@"Hide " stringByAppendingString:appName], @selector(hide:), @"h",
                             NSEventModifierFlagCommand);
    CjguiAddStandardMenuItem(applicationMenu, @"Hide Others", @selector(hideOtherApplications:), @"h",
                             NSEventModifierFlagCommand | NSEventModifierFlagOption);
    CjguiAddStandardMenuItem(applicationMenu, @"Show All", @selector(unhideAllApplications:), @"", 0);
    [applicationMenu addItem:[NSMenuItem separatorItem]];
    CjguiAddStandardMenuItem(applicationMenu, [@"Quit " stringByAppendingString:appName], @selector(terminate:), @"q",
                             NSEventModifierFlagCommand);
    NSMenuItem *applicationItem = [[NSMenuItem alloc] initWithTitle:appName action:nil keyEquivalent:@""];
    applicationItem.submenu = applicationMenu;
    [mainMenu addItem:applicationItem];

    NSMenu *editMenu = [[NSMenu alloc] initWithTitle:@"Edit"];
    editMenu.autoenablesItems = NO;
    CjguiAddStandardMenuItem(editMenu, @"Undo", @selector(undo:), @"z", NSEventModifierFlagCommand);
    CjguiAddStandardMenuItem(editMenu, @"Redo", @selector(redo:), @"z",
                             NSEventModifierFlagCommand | NSEventModifierFlagShift);
    [editMenu addItem:[NSMenuItem separatorItem]];
    CjguiAddStandardMenuItem(editMenu, @"Cut", @selector(cut:), @"x", NSEventModifierFlagCommand);
    CjguiAddStandardMenuItem(editMenu, @"Copy", @selector(copy:), @"c", NSEventModifierFlagCommand);
    CjguiAddStandardMenuItem(editMenu, @"Paste", @selector(paste:), @"v", NSEventModifierFlagCommand);
    CjguiAddStandardMenuItem(editMenu, @"Select All", @selector(selectAll:), @"a", NSEventModifierFlagCommand);
    NSMenuItem *editItem = [[NSMenuItem alloc] initWithTitle:@"Edit" action:nil keyEquivalent:@""];
    editItem.submenu = editMenu;
    [mainMenu addItem:editItem];
    [menus setObject:editMenu forKey:@"Edit"];
}

static BOOL CjguiComposableMenuDeclaresShortcut(CJGuiInternalSession *session, NSString *shortcut) {
    if (!session || shortcut.length == 0) return NO;
    for (CJGuiInternalComposableCommandMenuItem *entry in session.composableCommandMenuItems) {
        if ([entry.shortcut isEqualToString:shortcut]) return YES;
    }
    return NO;
}

// Match native command forwarding to the same active scope AppKit projects.
// `enabled` is deliberately not part of this predicate: a disabled declared
// command still owns its chord long enough for Cangjie to reject it against
// the accepted scene.  Falling through to an unrelated copy/paste action
// would turn a disabled command into a different owner operation.
static BOOL CjguiComposableActiveScopeDeclaresShortcut(CJGuiInternalSession *session, NSString *shortcut) {
    if (!session || shortcut.length == 0 || !session.composableSceneOverlay) return NO;
    CJGuiInternalComposableSceneNode *active = [session.composableSceneOverlay activeFocusableNode];
    uint64_t activeScope = active ? active.node.inputScope : 0;
    for (CJGuiInternalComposableCommandMenuItem *entry in session.composableCommandMenuItems) {
        if ([entry.shortcut isEqualToString:shortcut] && entry.focusScope == activeScope) return YES;
    }
    return NO;
}

static BOOL CjguiComposableActiveNonTextTransferOwnsShortcut(CJGuiInternalSession *session,
                                                              NSString *shortcut, uint32_t transferRole) {
    if (!session || !session.composableSceneOverlay || shortcut.length == 0) return NO;
    CJGuiInternalComposableSceneNode *active = [session.composableSceneOverlay activeFocusableNode];
    // Standard AppKit text editing retains Cmd-C/V/A/X.  Only a focused
    // non-text control may reserve the two transfer equivalents.
    if (!active || CjguiComposableNodeIsTextInput(active.node.nodeKind)) return NO;
    if (CjguiComposableActiveScopeDeclaresShortcut(session, shortcut)) return YES;
    return CjguiComposableDataTransferItemForNode(session, active.node.nodeId, active.node.resourceId,
        active.node.nodeKind, transferRole) != nil;
}

static void CjguiSuppressStandardEditShortcut(NSMenu *editMenu, SEL action,
                                              BOOL hasDeclaredOwnerShortcut) {
    if (!editMenu || !action || !hasDeclaredOwnerShortcut) return;
    for (NSInteger index = 0; index < (NSInteger)editMenu.numberOfItems; index++) {
        NSMenuItem *item = [editMenu itemAtIndex:index];
        if (item.action != action) continue;
        // A disabled or layer-covered owner declaration still reserves its
        // chord. Otherwise AppKit's responder chain could silently execute a
        // different Undo/Redo path before the Cangjie owner has a chance to
        // reject it. Text fallback remains available only without an owner
        // declaration for that standard chord.
        item.keyEquivalent = @"";
        item.keyEquivalentModifierMask = 0;
        return;
    }
}

static void CjguiReserveStandardEditShortcutsForComposableOwner(
    NSMutableDictionary<NSString *, NSMenu *> *menus, CJGuiInternalSession *session) {
    NSMenu *editMenu = [menus objectForKey:@"Edit"];
    // Cmd-C/V have two possible non-text owners: an explicitly declared
    // command in the focused scope, or a declared transfer source/target.
    // Suppress AppKit's responder equivalent only at that focused boundary;
    // a text proxy stays on the standard edit route.
    BOOL reserveCopy = CjguiComposableActiveNonTextTransferOwnsShortcut(
        session, @"shortcut:command+c", CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE);
    BOOL reservePaste = CjguiComposableActiveNonTextTransferOwnsShortcut(
        session, @"shortcut:command+v", CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET);
    if (CjguiDataTransferTraceEnabled()) {
        CJGuiInternalComposableSceneNode *active = [session.composableSceneOverlay activeFocusableNode];
        NSLog(@"cjgui: transfer menu window=%ld active=%@ scene=%llu transfer=%llu reserve_copy=%@ reserve_paste=%@",
              (long)(session.window ? session.window.windowNumber : 0),
              active ? @(active.node.nodeId) : @"none",
              (unsigned long long)session.composableSceneVersion,
              (unsigned long long)session.composableDataTransferVersion,
              reserveCopy ? @"yes" : @"no", reservePaste ? @"yes" : @"no");
    }
    CjguiSuppressStandardEditShortcut(editMenu, @selector(copy:), reserveCopy);
    CjguiSuppressStandardEditShortcut(editMenu, @selector(paste:), reservePaste);
    CjguiSuppressStandardEditShortcut(
        editMenu, @selector(undo:),
        CjguiComposableMenuDeclaresShortcut(session, @"shortcut:command+z"));
    CjguiSuppressStandardEditShortcut(
        editMenu, @selector(redo:),
        CjguiComposableMenuDeclaresShortcut(session, @"shortcut:shift+command+z"));
}

static void CjguiRebuildComposableCommandMenuForKeyWindow(void) {
    if (!CjguiIsMainThread()) return;
    NSString *appName = NSProcessInfo.processInfo.processName;
    if (appName.length == 0) appName = @"CJGUI";
    NSMenu *mainMenu = [[NSMenu alloc] initWithTitle:appName];
    mainMenu.autoenablesItems = NO;
    NSMutableDictionary<NSString *, NSMenu *> *menus = [NSMutableDictionary dictionary];
    CJGuiInternalSession *session = CjguiComposableCommandMenuKeySession();
    CjguiAddStandardApplicationMenus(mainMenu, menus);
    CjguiReserveStandardEditShortcutsForComposableOwner(menus, session);
    if (!session) {
        [NSApp setMainMenu:mainMenu];
        return;
    }
    NSMutableDictionary<NSString *, NSNumber *> *lastSections = [NSMutableDictionary dictionary];
    for (CJGuiInternalComposableCommandMenuItem *entry in session.composableCommandMenuItems) {
        if (entry.menuGroup.length == 0) continue;
        NSMenu *submenu = [menus objectForKey:entry.menuGroup];
        if (!submenu) {
            submenu = [[NSMenu alloc] initWithTitle:entry.menuGroup];
            submenu.autoenablesItems = NO;
            NSMenuItem *groupItem = [[NSMenuItem alloc] initWithTitle:entry.menuGroup action:nil keyEquivalent:@""];
            groupItem.submenu = submenu;
            [mainMenu addItem:groupItem];
            [menus setObject:submenu forKey:entry.menuGroup];
        }
        NSNumber *previousSection = [lastSections objectForKey:entry.menuGroup];
        if ((!previousSection && submenu.numberOfItems > 0) ||
            (previousSection && previousSection.unsignedIntValue != entry.menuSection)) {
            [submenu addItem:[NSMenuItem separatorItem]];
        }
        [lastSections setObject:@(entry.menuSection) forKey:entry.menuGroup];
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:entry.title
                                                       action:@selector(invokeComposableCommand:)
                                                keyEquivalent:@""];
        item.target = [CJGuiInternalComposableCommandMenuDispatcher sharedDispatcher];
        item.representedObject = entry.commandId;
        CJGuiInternalComposableSceneNode *active = [session.composableSceneOverlay activeFocusableNode];
        BOOL activeScopeEnabled = entry.enabled && (active ? entry.focusScope == active.node.inputScope :
                                                     entry.focusScope == 0);
        item.enabled = activeScopeEnabled;
        item.state = entry.checked ? NSControlStateValueOn : NSControlStateValueOff;
        [item setAccessibilityIdentifier:[@"cjgui.composable-command." stringByAppendingString:entry.commandId]];
        if (activeScopeEnabled) CjguiConfigureComposableMenuKeyEquivalent(item, entry.shortcut);
        [submenu addItem:item];
    }
    [NSApp setMainMenu:mainMenu];
#ifdef CJGUI_INTERNAL_TESTING
    gCjguiComposableCommandMenuRebuildCount += 1;
#endif
}

static char CJGuiImageDomainsAssociationKey;

static NSMutableArray<CJGuiInternalComposableImageResourceDomain *> *CjguiComposableImageDomains(
    NSApplication *app, BOOL createIfMissing) {
    if (!app) return nil;
    NSMutableArray<CJGuiInternalComposableImageResourceDomain *> *domains =
        objc_getAssociatedObject(app, &CJGuiImageDomainsAssociationKey);
    if (!domains && createIfMissing) {
        domains = [NSMutableArray array];
        objc_setAssociatedObject(app, &CJGuiImageDomainsAssociationKey, domains, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    return domains;
}

static CJGuiInternalComposableImageResourceDomain *CjguiAcquireComposableImageDomain(NSApplication *app,
                                                                                       id<MTLDevice> device) {
    if (!app || !device) return nil;
    NSMutableArray<CJGuiInternalComposableImageResourceDomain *> *domains = CjguiComposableImageDomains(app, YES);
    for (CJGuiInternalComposableImageResourceDomain *domain in domains) {
        if (!domain.destroyed && domain.device == device) return domain;
    }
    // Each domain needs at least one fixed table session, so this cannot grow
    // beyond the pre-existing native capacity even if a future host offers
    // multiple Metal devices.
    if (domains.count >= kCjguiSessionCapacity) return nil;
    CJGuiInternalComposableImageResourceDomain *domain =
        [[CJGuiInternalComposableImageResourceDomain alloc] initWithDevice:device];
    if (domain) [domains addObject:domain];
    return domain;
}

static void CjguiReleaseComposableImageDomain(CJGuiInternalSession *session) {
    CJGuiInternalComposableImageResourceDomain *domain = session.composableImageDomain;
    NSApplication *app = session.app;
    if (!domain || !app) return;
    if (domain.sessionCount > 0) domain.sessionCount -= 1;
    if (domain.sessionCount != 0) return;
    // Removing subscriptions is distinct from cancellation: MetalKit may
    // finish underlying work, but its captured domain sees `destroyed` and
    // cannot resurrect any closed session or publish a completion epoch.
    domain.destroyed = YES;
    [domain.textureCache removeAllObjects];
    [domain.resources removeAllObjects];
    [domain.loaders removeAllObjects];
    [domain.pendingKeys removeAllObjects];
    NSMutableArray<CJGuiInternalComposableImageResourceDomain *> *domains = CjguiComposableImageDomains(app, NO);
    [domains removeObjectIdenticalTo:domain];
    if (domains.count == 0) {
        objc_setAssociatedObject(app, &CJGuiImageDomainsAssociationKey, nil, OBJC_ASSOCIATION_ASSIGN);
    }
}

static BOOL CjguiWindowFrameFitsVisibleArea(NSRect frame, NSRect visibleArea) {
    return NSWidth(frame) > 0.0 && NSHeight(frame) > 0.0 && NSContainsRect(visibleArea, frame);
}

static BOOL CjguiWindowFrameAvoidsVisibleWindows(NSWindow *window, NSRect frame) {
    for (NSWindow *existing in NSApp.windows) {
        if (existing == window || !existing.isVisible || existing.isMiniaturized) continue;
        if (NSIntersectsRect(frame, existing.frame)) return NO;
    }
    return YES;
}

// A regular application can open multiple independent composable windows.
// Centering each one at the same point turns an otherwise valid source/target
// pair into an obscured single-window surface. Prefer one adjacent, entirely
// visible slot when it exists; retain the conventional centred fallback for
// large or crowded displays. This is platform presentation only: it neither
// creates a Cangjie coordinate API nor changes session ownership.
static void CjguiPlaceNewWindowWithoutObscuringVisibleSibling(NSWindow *window) {
    if (!window) return;
    NSScreen *screen = NSScreen.mainScreen ?: NSScreen.screens.firstObject;
    NSRect visibleArea = screen ? screen.visibleFrame : NSZeroRect;
    if (NSIsEmptyRect(visibleArea)) return;
    NSRect original = window.frame;
    for (NSWindow *existing in NSApp.windows) {
        if (existing == window || !existing.isVisible || existing.isMiniaturized) continue;
        NSRect sibling = existing.frame;
        NSRect candidates[] = {
            NSMakeRect(NSMaxX(sibling) + 24.0, NSMinY(sibling), NSWidth(original), NSHeight(original)),
            NSMakeRect(NSMinX(sibling) - 24.0 - NSWidth(original), NSMinY(sibling),
                       NSWidth(original), NSHeight(original)),
            NSMakeRect(NSMinX(sibling), NSMinY(sibling) - 24.0 - NSHeight(original),
                       NSWidth(original), NSHeight(original)),
            NSMakeRect(NSMinX(sibling), NSMaxY(sibling) + 24.0, NSWidth(original), NSHeight(original)),
        };
        for (NSUInteger index = 0; index < sizeof(candidates) / sizeof(candidates[0]); index++) {
            if (CjguiWindowFrameFitsVisibleArea(candidates[index], visibleArea) &&
                CjguiWindowFrameAvoidsVisibleWindows(window, candidates[index])) {
                [window setFrameOrigin:candidates[index].origin];
                return;
            }
        }
    }
}

// ---- ABI: create ----

uint64_t cjgui_internal_renderer_create(const CjguiInternalRendererConfig *config,
                                        CjguiInternalRendererStatus *outStatus) {
    if (outStatus) {
        *outStatus = CJGUI_INTERNAL_RENDERER_OK;
    }

    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        __block uint64_t token = CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            token = cjgui_internal_renderer_create(config, &status);
        });
        if (outStatus) *outStatus = status;
        return token;
    }

    @autoreleasepool {
        NSLog(@"cjgui: bridge init");

        NSApplication *app = nil;
        CjguiInternalRendererStatus appStatus = CjguiEnsureApp(&app);
        if (appStatus != CJGUI_INTERNAL_RENDERER_OK) {
            if (outStatus) *outStatus = appStatus;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }

        id<MTLDevice> device = MTLCreateSystemDefaultDevice();
        if (!device) {
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_METAL_DEVICE_UNAVAILABLE;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        NSLog(@"cjgui: capability check: metal device ok");

        id<MTLCommandQueue> commandQueue = [device newCommandQueue];
        if (!commandQueue) {
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_METAL_COMMAND_QUEUE_UNAVAILABLE;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        NSLog(@"cjgui: capability check: command queue ok");

        uint32_t width = config ? config->windowWidth : 0;
        uint32_t height = config ? config->windowHeight : 0;
        if (width == 0) width = 720;
        if (height == 0) height = 420;

        NSRect frame = NSMakeRect(0, 0, (CGFloat)width, (CGFloat)height);
        NSUInteger style = NSWindowStyleMaskTitled |
                           NSWindowStyleMaskClosable |
                           NSWindowStyleMaskMiniaturizable |
                           NSWindowStyleMaskResizable;

        NSWindow *window = [[NSWindow alloc] initWithContentRect:frame
                                                       styleMask:style
                                                         backing:NSBackingStoreBuffered
                                                           defer:NO];
        if (!window) {
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_WINDOW_CREATE_FAILED;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        window.opaque = NO;
        window.backgroundColor = NSColor.clearColor;
        [window setAcceptsMouseMovedEvents:YES];
        [window setReleasedWhenClosed:NO];
        [window center];
        CjguiPlaceNewWindowWithoutObscuringVisibleSibling(window);
        [window setTitle:@"CJGUI Shared Operation"];
        NSLog(@"cjgui: window created");

        CJGuiInternalMetalView *view = [[CJGuiInternalMetalView alloc]
            initWithFrame:frame device:device commandQueue:commandQueue];
        if (!view) {
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_METAL_LAYER_UNAVAILABLE;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }

        NSView *contentHost = [[NSView alloc] initWithFrame:frame];
        contentHost.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
        NSView *opaqueFallback = [[NSView alloc] initWithFrame:contentHost.bounds];
        opaqueFallback.wantsLayer = YES;
        opaqueFallback.layer.opaque = YES;
        opaqueFallback.layer.backgroundColor = [NSColor colorWithCalibratedRed:0.08 green:0.16 blue:0.20 alpha:1.0].CGColor;
        opaqueFallback.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
        [contentHost addSubview:opaqueFallback];
        NSVisualEffectView *materialView = [[NSVisualEffectView alloc] initWithFrame:contentHost.bounds];
        if (materialView) {
            materialView.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
            materialView.blendingMode = NSVisualEffectBlendingModeBehindWindow;
            materialView.state = NSVisualEffectStateFollowsWindowActiveState;
            materialView.material = NSVisualEffectMaterialUnderWindowBackground;
            materialView.hidden = YES;
            [contentHost addSubview:materialView];
        }
        view.frame = contentHost.bounds;
        view.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
        [contentHost addSubview:view];
        [window setContentView:contentHost];
        NSLog(@"cjgui: metal setup complete");

        [window makeKeyAndOrderFront:nil];
        [app activateIgnoringOtherApps:YES];

        CJGuiInternalSession *session = [[CJGuiInternalSession alloc] init];
        session.app = app;
        session.window = window;
        session.view = view;
        session.windowContentHost = contentHost;
        session.windowMaterialView = materialView;
        session.windowOpaqueFallbackView = opaqueFallback;
        session.windowBackgroundAcceptedSceneVersion = 0;
        session.windowBackgroundRequestedMode = 0;
        session.windowBackgroundColorScheme = CjguiWindowColorSchemeForAppearance(app.effectiveAppearance);
        CjguiSetWindowBackgroundScheme(session, session.windowBackgroundColorScheme);
        session.windowBackgroundActualMode = 0;
        session.windowBackgroundFallbackReason = 0;
        session.windowBackgroundCompletion = 0;
        session.windowBackgroundBackend = materialView ? 1 : 0;
        session.windowBackgroundReduceTransparency = NSWorkspace.sharedWorkspace.accessibilityDisplayShouldReduceTransparency;
        session.windowBackgroundWindowActive = window.isKeyWindow && app.isActive;
        view.sessionToken = session.rendererSessionToken;
        session.device = device;
        session.commandQueue = commandQueue;
        session.composableImageDomain = CjguiAcquireComposableImageDomain(app, device);
        if (!session.composableImageDomain) {
            [view invalidateBridgeResources];
            [window close];
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        [window setDelegate:session];
        // A screen move may leave point bounds unchanged while the backing
        // scale changes. That transition needs the same Cangjie scene/derived
        // resource transaction as an ordinary resize; render-time drawable
        // updates alone would retain text rasterized at the former scale.
        [[NSNotificationCenter defaultCenter] addObserver:session
                                                 selector:@selector(windowDidChangeBackingProperties:)
                                                     name:NSWindowDidChangeBackingPropertiesNotification
                                                   object:window];
        [[NSWorkspace.sharedWorkspace notificationCenter] addObserver:session
             selector:@selector(windowBackgroundEnvironmentDidChange:)
                 name:NSWorkspaceAccessibilityDisplayOptionsDidChangeNotification object:nil];
        [[NSNotificationCenter defaultCenter] addObserver:session
                                                  selector:@selector(windowBackgroundEnvironmentDidChange:)
                                                      name:NSApplicationDidBecomeActiveNotification object:app];
        [[NSNotificationCenter defaultCenter] addObserver:session
                                                  selector:@selector(windowBackgroundEnvironmentDidChange:)
                                                      name:NSApplicationDidResignActiveNotification object:app];
        objc_setAssociatedObject(window, &CJGuiSessionWindowAssociationKey,
                                 session, OBJC_ASSOCIATION_RETAIN_NONATOMIC);

        uint64_t token = CjguiAllocateSession(session);
        if (token == CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN) {
            // Table full: tear down the freshly created resources.
            [view invalidateBridgeResources];
            [window setDelegate:nil];
            [window close];
            objc_setAssociatedObject(window, &CJGuiSessionWindowAssociationKey, nil,
                                     OBJC_ASSOCIATION_ASSIGN);
            CjguiReleaseComposableImageDomain(session);
            session.composableImageDomain = nil;
            if (outStatus) *outStatus = CJGUI_INTERNAL_RENDERER_SESSION_TABLE_FULL;
            return CJGUI_INTERNAL_RENDERER_INVALID_SESSION_TOKEN;
        }
        session.composableImageDomain.sessionCount += 1;

        return token;
    }
}

// ---- ABI: window title ----

static CjguiInternalRendererStatus
CjguiSetWindowTitleOnMain(uint64_t session, const char *title) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.window || !title || title[0] == '\0') {
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    NSString *value = [NSString stringWithUTF8String:title];
    if (!value || value.length == 0) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    [ctx.window setTitle:value];
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_set_window_title(uint64_t session, const char *title) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        }
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiSetWindowTitleOnMain(session, title);
        });
        return status;
    }
    return CjguiSetWindowTitleOnMain(session, title);
}


int32_t
cjgui_internal_renderer_set_composable_range_edit_delta(uint64_t session, int32_t enabled) {
    // The flag is read by the main-thread text delegate, so follow the same
    // main-thread contract as the other session setters: a caller on another
    // thread is served through one main-queue hop when dispatching is enabled,
    // and refused explicitly when it is not.
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block int32_t status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            CJGuiInternalSession *resolved = CjguiLookupSession(session);
            if (!resolved) {
                status = CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
                return;
            }
            resolved.rangeTextEditDeltaDeliveryEnabled = enabled != 0;
            status = CJGUI_INTERNAL_RENDERER_OK;
        });
        return status;
    }
    CJGuiInternalSession *resolved = CjguiLookupSession(session);
    if (!resolved) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    resolved.rangeTextEditDeltaDeliveryEnabled = enabled != 0;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_set_composable_owned_text_session(uint64_t session, uint64_t nodeId,
                                                          int64_t resourceId, uint32_t nodeKind,
                                                          uint64_t bindingEpoch, uint32_t enabled) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_set_composable_owned_text_session(session, nodeId, resourceId,
                                                                               nodeKind, bindingEpoch, enabled);
        });
        return status;
    }
    CJGuiInternalSession *resolved = CjguiLookupSession(session);
    if (!resolved) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (enabled) {
        if (nodeId == 0) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        resolved.ownedTextSessionEnabled = YES;
        resolved.ownedTextSessionNodeId = nodeId;
        resolved.ownedTextSessionResourceId = resourceId;
        resolved.ownedTextSessionNodeKind = nodeKind;
        resolved.ownedTextSessionBindingEpoch = bindingEpoch;
    } else {
        resolved.ownedTextSessionEnabled = NO;
        resolved.ownedTextSessionNodeId = 0;
        resolved.ownedTextSessionResourceId = -1;
        resolved.ownedTextSessionNodeKind = 0;
        resolved.ownedTextSessionBindingEpoch = bindingEpoch;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}
// ---- ABI: presentClear ----

static id<MTLTexture> CjguiComposableMultisampleTarget(CJGuiInternalMetalView *view, id<MTLTexture> drawableTexture) {
    if (!view || !drawableTexture || drawableTexture.width == 0 || drawableTexture.height == 0) return nil;
    id<MTLTexture> existing = view.composableMultisampleTexture;
    if (existing && existing.width == drawableTexture.width && existing.height == drawableTexture.height &&
        existing.pixelFormat == drawableTexture.pixelFormat && existing.sampleCount == 4) {
        return existing;
    }
    MTLTextureDescriptor *descriptor = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:drawableTexture.pixelFormat
                                                                                             width:drawableTexture.width
                                                                                            height:drawableTexture.height
                                                                                         mipmapped:NO];
    descriptor.textureType = MTLTextureType2DMultisample;
    descriptor.sampleCount = 4;
    descriptor.storageMode = MTLStorageModePrivate;
    descriptor.usage = MTLTextureUsageRenderTarget;
    id<MTLTexture> replacement = [view.device newTextureWithDescriptor:descriptor];
    if (!replacement) return nil;
    view.composableMultisampleTexture = replacement;
    return replacement;
}

// MSAA is a vector-edge quality choice, not a blanket cost for text/forms.
// The committed native node array is the same accepted snapshot consumed by
// painter order and hit testing, so this scan cannot observe a partial scene.
static BOOL CjguiComposableSceneNeedsMultisampling(NSArray<CJGuiInternalComposableSceneNode *> *nodes) {
    for (CJGuiInternalComposableSceneNode *node in nodes) {
        if (node.hasVectorGeometry) return YES;
    }
    return NO;
}

// A1 票据协议：macOS 侧是同步提交，从不产生未确认票据（present 返回即已接受
// 或已明确失败）。因此查询只会得到 NONE，确认是幂等的空操作，计数恒为 0。
// 这两个入口存在是为了让共享内部 ABI 在两端同形，核心不必按平台分叉；它们
// 不代表 macOS 也支持延迟提交。
CjguiInternalRendererStatus
cjgui_internal_renderer_query_present(uint64_t session, uint64_t ticketId,
                                      CjguiInternalRendererPresentReceipt *outReceipt) {
    if (outReceipt) memset(outReceipt, 0, sizeof(CjguiInternalRendererPresentReceipt));
    if (ticketId == 0) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (!CjguiLookupSession(session)) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (outReceipt) {
        outReceipt->ticketId = ticketId;
        outReceipt->decision = CJGUI_INTERNAL_RENDERER_PRESENT_DECISION_NONE;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_acknowledge_present(uint64_t session, uint64_t ticketId) {
    if (ticketId == 0) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (!CjguiLookupSession(session)) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_present_ticket_stats(uint64_t session,
                                             CjguiInternalRendererPresentTicketStats *out) {
    if (!out) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    memset(out, 0, sizeof(*out));
    if (!CjguiLookupSession(session)) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    // macOS 同步提交没有票据，计数恒为 0，但 available=1：这些 0 是真实读数，
    // 不是“平台未实现”。
    out->available = 1;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_present_clear(uint64_t session,
                                      const CjguiInternalRendererClearColor *color,
                                      CjguiInternalRendererFrameObservation *outObservation) {
    if (outObservation) {
        memset(outObservation, 0, sizeof(CjguiInternalRendererFrameObservation));
    }
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) {
            return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        }
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_present_clear(session, color, outObservation);
        });
        return status;
    }

    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) {
        return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }

    CJGuiInternalMetalView *view = ctx.view;
    if (!view || view.invalidated || !view.metalLayer || !view.commandQueue) {
        return CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED;
    }

    double red = color ? color->red : 0.0;
    double green = color ? color->green : 0.0;
    double blue = color ? color->blue : 0.0;
    double alpha = color ? color->alpha : 1.0;
    if (ctx.windowBackgroundActualMode == 1) {
        red = 0.0; green = 0.0; blue = 0.0; alpha = 0.0;
    } else if (ctx.windowBackgroundRequestedMode == 1 || ctx.hasStagedWindowBackground) {
        uint32_t scheme = ctx.hasStagedWindowBackground &&
            ctx.stagedWindowBackgroundVersion == ctx.stagedComposableSceneVersion
                ? ctx.stagedWindowBackgroundColorScheme : ctx.windowBackgroundColorScheme;
        if (scheme == 1) { red = 0.94; green = 0.95; blue = 0.97; }
        else { red = 0.08; green = 0.16; blue = 0.20; }
        alpha = 1.0;
    }
    MTLClearColor clearColor = MTLClearColorMake(red, green, blue, alpha);

    @autoreleasepool {
        view.encodedImageTextures = [NSMutableArray array];
        @try {
#ifdef CJGUI_INTERNAL_TESTING
        view.testComposableNextDrawableMicros = 0;
        view.testComposableCommandBufferMicros = 0;
        view.testComposablePresentMicros = 0;
        view.testComposableCommitMicros = 0;
        view.testComposableReadbackWaitMicros = 0;
        view.testComposableReadbackWaited = 0;
#endif
        [view updateDrawableSize];

#ifdef CJGUI_INTERNAL_TESTING
        uint64_t nextDrawableStarted = CjguiMonotonicMicros();
#endif
        id<CAMetalDrawable> drawable = [view.metalLayer nextDrawable];
#ifdef CJGUI_INTERNAL_TESTING
        view.testComposableNextDrawableMicros = CjguiMonotonicMicros() - nextDrawableStarted;
#endif
        if (!drawable) {
            return CJGUI_INTERNAL_RENDERER_METAL_DRAWABLE_UNAVAILABLE;
        }
        CGSize drawableSize = drawable.texture ? CGSizeMake(drawable.texture.width, drawable.texture.height) : CGSizeZero;

#ifdef CJGUI_INTERNAL_TESTING
        uint64_t commandBufferStarted = CjguiMonotonicMicros();
#endif
        id<MTLCommandBuffer> commandBuffer = [view.commandQueue commandBuffer];
#ifdef CJGUI_INTERNAL_TESTING
        view.testComposableCommandBufferMicros = CjguiMonotonicMicros() - commandBufferStarted;
#endif
        if (!commandBuffer) {
            return CJGUI_INTERNAL_RENDERER_METAL_COMMAND_BUFFER_UNAVAILABLE;
        }

        BOOL needsMultisampling = CjguiComposableSceneNeedsMultisampling(view.composableNodes);
        view.composableUsesMultisampling = needsMultisampling;
        BOOL hasEffectGroups = CjguiComposableSceneHasEffectGroups(view.composableNodes);
        NSMutableArray<CJGuiInternalComposableEffectTarget *> *redrawnEffectTargets = [NSMutableArray array];
        if (hasEffectGroups) {
            CjguiInternalRendererStatus effectStatus = CjguiEncodeEffectGroupContents(
                view, commandBuffer, drawableSize, redrawnEffectTargets);
            if (effectStatus != CJGUI_INTERNAL_RENDERER_OK) return effectStatus;
        }
        NSMutableArray<CJGuiInternalComposableEffectTarget *> *backdropScratch = [NSMutableArray array];
        NSMutableArray<CJGuiInternalComposableEffectTarget *> *redrawnBackdrops = [NSMutableArray array];
        CjguiInternalBackdropOutcome backdropOutcome = {0};
        BOOL backdropEncoded = CjguiEncodeBackdrop(view, commandBuffer, drawableSize, clearColor,
                                                    backdropScratch, redrawnBackdrops, &backdropOutcome);
#ifdef CJGUI_INTERNAL_TESTING
        if (backdropEncoded && redrawnBackdrops.count > 0 && ctx.forcedComposableBackdropEncodeFailures > 0) {
            ctx.forcedComposableBackdropEncodeFailures--;
            backdropEncoded = NO;
        }
#endif
        if (!backdropEncoded) {
            backdropOutcome.mode = CJGUI_INTERNAL_BACKDROP_UNBLURRED;
            backdropOutcome.reason = CJGUI_INTERNAL_BACKDROP_REASON_ENCODE_FAILED;
            // A partial replay/compute submission cannot be followed by the
            // main pass. Abandon it, including any foreground target writes,
            // and encode a fresh accepted frame with the declared unblurred
            // fallback. No abandoned target becomes a cache hit.
            for (CJGuiInternalComposableSceneNode *node in view.composableNodes)
                if (node.node.effectBackdropBlurRadiusPoints > 0) node.backdropTarget = nil;
            [backdropScratch removeAllObjects];
            [redrawnBackdrops removeAllObjects];
            // These encodes belonged only to the abandoned command buffer.
            [view.encodedImageTextures removeAllObjects];
#ifdef CJGUI_INTERNAL_TESTING
            view.testBackdropFallbackCount++;
#endif
            commandBuffer = [view.commandQueue commandBuffer];
            if (!commandBuffer) return CJGUI_INTERNAL_RENDERER_METAL_COMMAND_BUFFER_UNAVAILABLE;
            [redrawnEffectTargets removeAllObjects];
            if (hasEffectGroups) {
                CjguiInternalRendererStatus fallbackStatus = CjguiEncodeEffectGroupContents(
                    view, commandBuffer, drawableSize, redrawnEffectTargets);
                if (fallbackStatus != CJGUI_INTERNAL_RENDERER_OK) return fallbackStatus;
            }
        }
#ifdef CJGUI_INTERNAL_TESTING
        if ((redrawnEffectTargets.count > 0 || redrawnBackdrops.count > 0) &&
            ctx.forcedComposableMainEncoderAfterEffectsFailures > 0) {
            ctx.forcedComposableMainEncoderAfterEffectsFailures--;
            return CJGUI_INTERNAL_RENDERER_METAL_ENCODER_UNAVAILABLE;
        }
#endif
        id<MTLTexture> composableTarget = drawable.texture;
        if (needsMultisampling) {
            composableTarget = CjguiComposableMultisampleTarget(view, drawable.texture);
            if (!composableTarget) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        } else {
            // Release the private 4x attachment when the accepted scene no
            // longer contains vectors. The 1x pipelines remain lazily reused.
            view.composableMultisampleTexture = nil;
        }
        MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
        pass.colorAttachments[0].texture = composableTarget;
        pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        pass.colorAttachments[0].resolveTexture = needsMultisampling ? drawable.texture : nil;
        pass.colorAttachments[0].storeAction = needsMultisampling ? MTLStoreActionMultisampleResolve : MTLStoreActionStore;
        pass.colorAttachments[0].clearColor = clearColor;
#ifdef CJGUI_INTERNAL_TESTING
        view.testComposableRenderSampleCount = needsMultisampling ? 4 : 1;
        uint64_t pixels = (uint64_t)drawable.texture.width * (uint64_t)drawable.texture.height;
        view.testComposableMultisampleAttachmentBytes = needsMultisampling && pixels <= UINT64_MAX / 16u ? pixels * 16u : 0;
#endif

        // Probe only a final, visible opaque colour. The scene can contain a
        // clipped row, alpha overlay or image whose centre does not identify
        // one deterministic output pixel; claiming otherwise produced the
        // resize-time scene_color_mismatch reported by the normal rule app.
        CjguiComposableReadbackProbePoint sceneProbePoint = {0};
        CJGuiInternalComposableSceneNode *sceneProbeNode =
            hasEffectGroups ? nil : CjguiComposableSafeOpaqueProbeNode(
                view.composableNodes, view.bounds.size, drawableSize, &sceneProbePoint);
        BOOL sceneHasPotentialMetalDraw = CjguiComposableSceneHasPotentialMetalDraw(view.composableNodes);
        MTLClearColor expectedReadbackColor = clearColor;
        if (sceneProbeNode) {
            CjguiInternalRendererComposableNode sceneValue = sceneProbeNode.node;
            expectedReadbackColor = MTLClearColorMake(sceneValue.fillRed, sceneValue.fillGreen, sceneValue.fillBlue, sceneValue.fillAlpha);
        }
        // A clear-only scene has a known central pixel. A scene that draws but
        // exposes no deterministic opaque point is rendered normally and
        // reported as a skipped diagnostic, not as either a false success or
        // a false rendering failure.
        BOOL readbackSkippedNoDeterministicScenePixel = !view.readbackProbeCompleted && !sceneProbeNode && sceneHasPotentialMetalDraw;
        // Retain the one-shot completion observation even when colour is not
        // derivable. It preserves the first-frame lifecycle fact without
        // manufacturing a pixel match or adding a repeating GPU wait.
        BOOL shouldProbe = !view.readbackProbeCompleted;
        const NSUInteger readbackBytesPerRow = 256;
        id<MTLBuffer> readbackBuffer = nil;
        BOOL readbackBlitEncoded = NO;
        BOOL readbackCompleted = NO;
        BOOL readbackMatched = NO;
        BOOL readbackFailed = NO;
        const char *readbackDegradedReason = "none";
        BOOL readbackHasDegraded = NO;
        BOOL commandBufferWaited = NO;
        NSUInteger readbackSampleX = 0;
        NSUInteger readbackSampleY = 0;
#ifdef CJGUI_INTERNAL_TESTING
        BOOL testDrawablePixelRequested = ctx.testDrawablePixelPending;
        id<MTLBuffer> testDrawablePixelBuffer = nil;
        BOOL testDrawablePixelBlitEncoded = NO;
#endif

        if (shouldProbe) {
            readbackBuffer = [ctx.device newBufferWithLength:readbackBytesPerRow
                                                     options:MTLResourceStorageModeShared];
            if (!readbackBuffer) {
                readbackDegradedReason = "buffer_unavailable";
                readbackHasDegraded = YES;
                readbackFailed = YES;
            }
        }

        id<MTLRenderCommandEncoder> encoder =
            [commandBuffer renderCommandEncoderWithDescriptor:pass];
        if (!encoder) {
            return CJGUI_INTERNAL_RENDERER_METAL_ENCODER_UNAVAILABLE;
        }
#ifdef CJGUI_INTERNAL_TESTING
        uint64_t composableEncodeStarted = CjguiMonotonicMicros();
#endif
        BOOL composableEncoded = [view encodeComposableNodes:encoder
            drawableSize:drawableSize];
#ifdef CJGUI_INTERNAL_TESTING
        view.testComposableEncoderCpuMicros = CjguiMonotonicMicros() - composableEncodeStarted;
#endif
        if (!composableEncoded) {
            [encoder endEncoding];
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        [encoder endEncoding];

        if (shouldProbe && readbackBuffer) {
            NSUInteger textureWidth = drawable.texture.width;
            NSUInteger textureHeight = drawable.texture.height;
            if (textureWidth == 0 || textureHeight == 0) {
                readbackDegradedReason = "empty_texture";
                readbackHasDegraded = YES;
                readbackFailed = YES;
            } else {
                id<MTLBlitCommandEncoder> blit = [commandBuffer blitCommandEncoder];
                if (!blit) {
                    readbackDegradedReason = "blit_encoder_unavailable";
                    readbackHasDegraded = YES;
                    readbackFailed = YES;
                } else {
                    NSUInteger sampleX = textureWidth / 2;
                    NSUInteger sampleY = textureHeight / 2;
                    if (sceneProbeNode) {
                        sampleX = MIN(textureWidth - 1, sceneProbePoint.sampleX);
                        sampleY = MIN(textureHeight - 1, sceneProbePoint.sampleY);
                    }
                    readbackSampleX = sampleX;
                    readbackSampleY = sampleY;
                    MTLOrigin origin = MTLOriginMake(sampleX, sampleY, 0);
                    MTLSize size = MTLSizeMake(1, 1, 1);
                    [blit copyFromTexture:drawable.texture
                              sourceSlice:0
                              sourceLevel:0
                             sourceOrigin:origin
                               sourceSize:size
                                 toBuffer:readbackBuffer
                        destinationOffset:0
                   destinationBytesPerRow:readbackBytesPerRow
                 destinationBytesPerImage:readbackBytesPerRow];
                    [blit endEncoding];
                    readbackBlitEncoded = YES;
                }
            }
        }

#ifdef CJGUI_INTERNAL_TESTING
        if (testDrawablePixelRequested) {
            NSUInteger textureWidth = drawable.texture.width;
            NSUInteger textureHeight = drawable.texture.height;
            if (textureWidth > 0 && textureHeight > 0 &&
                view.bounds.size.width > 0.0 && view.bounds.size.height > 0.0) {
                NSUInteger sampleX = MIN(textureWidth - 1, (NSUInteger)((CGFloat)ctx.testDrawablePixelX * (CGFloat)textureWidth / view.bounds.size.width));
                NSUInteger sampleY = MIN(textureHeight - 1, (NSUInteger)((CGFloat)ctx.testDrawablePixelY * (CGFloat)textureHeight / view.bounds.size.height));
                testDrawablePixelBuffer = [ctx.device newBufferWithLength:readbackBytesPerRow options:MTLResourceStorageModeShared];
                id<MTLBlitCommandEncoder> testBlit = testDrawablePixelBuffer ? [commandBuffer blitCommandEncoder] : nil;
                if (testBlit) {
                    [testBlit copyFromTexture:drawable.texture
                                  sourceSlice:0
                                  sourceLevel:0
                                 sourceOrigin:MTLOriginMake(sampleX, sampleY, 0)
                                   sourceSize:MTLSizeMake(1, 1, 1)
                                      toBuffer:testDrawablePixelBuffer
                             destinationOffset:0
                        destinationBytesPerRow:readbackBytesPerRow
                      destinationBytesPerImage:readbackBytesPerRow];
                    [testBlit endEncoding];
                    testDrawablePixelBlitEncoded = YES;
                }
            }
        }
#endif

        // Hold the exact scene resources through this command buffer's
        // completion. A subsequent Cangjie scene may remove or rebind an
        // image immediately, but the in-flight encoder still owns this
        // generation's texture until Metal signals completion. The captured
        // array contains only native copies, never a Cangjie pointer/handle.
        // Metal may keep a completed command buffer (and its completion block)
        // alive after signalling completion. Drop our strong texture owners in
        // that callback itself; waiting for command-buffer deallocation would
        // retain retired group generations beyond the GPU fence and exhaust
        // the bounded effect budget after repeated replacements.
        __block NSArray<CJGuiInternalComposableSceneNode *> *submittedComposableResources = [view.composableNodes copy];
        __block NSArray<id<MTLTexture>> *submittedImageTextures = [view.encodedImageTextures copy];
        // The node array above is shallow. A later accepted redraw can replace
        // effectTarget on the very same node object, so retain the exact target
        // generations this submission read or wrote, including cache hits.
        NSMutableArray<CJGuiInternalComposableEffectTarget *> *usedEffectTargets = [NSMutableArray array];
        for (CJGuiInternalComposableSceneNode *node in view.composableNodes) {
            CJGuiInternalComposableEffectTarget *target = node.node.effectGroupPresent ? node.effectTarget : nil;
            if (target && ![usedEffectTargets containsObject:target]) [usedEffectTargets addObject:target];
            target = node.node.effectBackdropBlurRadiusPoints > 0 ? node.backdropTarget : nil;
            if (target && ![usedEffectTargets containsObject:target]) [usedEffectTargets addObject:target];
        }
        for (CJGuiInternalComposableEffectTarget *target in backdropScratch)
            if (![usedEffectTargets containsObject:target]) [usedEffectTargets addObject:target];
        __block NSArray<CJGuiInternalComposableEffectTarget *> *submittedEffectTargets = [usedEffectTargets copy];
        NSMutableArray<CJGuiInternalComposableEffectTarget *> *allWritten = [redrawnEffectTargets mutableCopy];
        [allWritten addObjectsFromArray:redrawnBackdrops];
        __block NSArray<CJGuiInternalComposableEffectTarget *> *submittedRedrawnEffects = [allWritten copy];
        __block NSArray<CJGuiInternalComposableEffectTarget *> *submittedRedrawnBackdrops = [redrawnBackdrops copy];
        // Frame identity becomes a submission fact before commit.  The
        // completion block carries only scalars and returns to the main
        // thread before it looks up the session again; it never captures or
        // mutates a domain/controller object.  A slot token alone may be
        // reused after close, so the session generation rejects a late
        // completion from the retired instance.
        const uint64_t submittedFrameIndex = view.frameIndex + 1;
        const uint64_t submittedEffectSceneVersion = ctx.composableSceneVersion;
        const uint64_t submittedBackgroundRequestRevision =
            ctx.hasStagedWindowBackground && ctx.stagedWindowBackgroundVersion == ctx.composableSceneVersion
                ? ctx.stagedWindowBackgroundRequestRevision : ctx.windowBackgroundRequestRevision;
        const uint64_t submittedBackgroundEnvironmentRevision = ctx.windowBackgroundEnvironmentRevision;
        const uint64_t submittedBackgroundSceneVersion = ctx.composableSceneVersion;
        const uint64_t submissionGeneration = ctx.sessionGeneration;
        [commandBuffer addCompletedHandler:^(id<MTLCommandBuffer> completedBuffer) {
            (void)submittedComposableResources;
            (void)submittedImageTextures;
            (void)submittedEffectTargets;
            const MTLCommandBufferStatus completionStatus = completedBuffer.status;
            if (completionStatus == MTLCommandBufferStatusCompleted) {
                for (CJGuiInternalComposableEffectTarget *target in submittedRedrawnBackdrops)
                    target.gpuCompleted = YES;
            }
            NSArray<CJGuiInternalComposableEffectTarget *> *failedRedrawnEffects =
                completionStatus == MTLCommandBufferStatusCompleted ? nil : submittedRedrawnEffects;
            submittedComposableResources = nil;
            submittedImageTextures = nil;
            submittedEffectTargets = nil;
            submittedRedrawnEffects = nil;
            submittedRedrawnBackdrops = nil;
            int64_t gpuDurationMicros = -1;
            if (completionStatus == MTLCommandBufferStatusCompleted) {
                if (@available(macOS 10.15, *)) {
                    const CFTimeInterval gpuStart = completedBuffer.GPUStartTime;
                    const CFTimeInterval gpuEnd = completedBuffer.GPUEndTime;
                    const double duration = (gpuEnd - gpuStart) * 1000000.0;
                    if (isfinite(gpuStart) && isfinite(gpuEnd) && gpuStart > 0.0 && gpuEnd >= gpuStart &&
                        isfinite(duration) && duration >= 0.0 && duration <= (double)LLONG_MAX) {
                        gpuDurationMicros = (int64_t)llround(duration);
                    }
                }
            }
            dispatch_async(dispatch_get_main_queue(), ^{
                CJGuiInternalSession *live = CjguiLookupSession(session);
                if (!live || live.destroyed || live.sessionGeneration != submissionGeneration) return;
                if (completionStatus != MTLCommandBufferStatusCompleted) {
                    for (CJGuiInternalComposableEffectTarget *target in failedRedrawnEffects)
                        target.invalidatedByGpuFailure = YES;
                }
                (void)CjguiEffectLiveTargetBytes(live.view);
                if (completionStatus == MTLCommandBufferStatusCompleted) {
                    if (submittedFrameIndex >= live.observedMetalCompletionFrameIndex) {
                        live.observedMetalCompletionFrameIndex = submittedFrameIndex;
                        live.observedMetalGpuDurationMicros = gpuDurationMicros;
                    }
                } else if (submittedFrameIndex >= live.observedMetalFailureFrameIndex) {
                    live.observedMetalFailureFrameIndex = submittedFrameIndex;
                }
                if (live.effectSubmittedFrameIndex == submittedFrameIndex &&
                    live.effectSubmittedSceneVersion == submittedEffectSceneVersion &&
                    live.effectCompletion == CJGUI_INTERNAL_BACKDROP_COMPLETION_PENDING) {
                    live.effectCompletion = completionStatus == MTLCommandBufferStatusCompleted
                        ? CJGUI_INTERNAL_BACKDROP_COMPLETION_SUCCEEDED
                        : CJGUI_INTERNAL_BACKDROP_COMPLETION_FAILED;
                }
                if (live.windowBackgroundSubmittedFrameIndex == submittedFrameIndex &&
                    live.windowBackgroundSubmittedRequestRevision == submittedBackgroundRequestRevision &&
                    live.windowBackgroundAcceptedSceneVersion == submittedBackgroundSceneVersion) {
                    live.windowBackgroundCompletion = completionStatus == MTLCommandBufferStatusCompleted ? 1u : 2u;
                    if (completionStatus != MTLCommandBufferStatusCompleted &&
                        live.windowBackgroundRequestedMode == CJGUI_INTERNAL_WINDOW_BACKGROUND_SYSTEM_CONTENT_AREA &&
                        live.windowBackgroundEnvironmentRevision == submittedBackgroundEnvironmentRevision) {
                        CjguiSetOpaqueWindowFallback(live);
                        live.windowBackgroundActualMode = 2;
                        live.windowBackgroundFallbackReason = 6;
                    }
                    live.windowBackgroundObservationRevision += 1;
                }
            });
        }];

 #ifdef CJGUI_INTERNAL_TESTING
        uint64_t presentStarted = CjguiMonotonicMicros();
 #endif
        [commandBuffer presentDrawable:drawable];
 #ifdef CJGUI_INTERNAL_TESTING
        view.testComposablePresentMicros = CjguiMonotonicMicros() - presentStarted;
 #endif
 #ifdef CJGUI_INTERNAL_TESTING
        uint64_t commitStarted = CjguiMonotonicMicros();
 #endif
        [commandBuffer commit];
        ctx.effectSubmittedSceneVersion = submittedEffectSceneVersion;
        ctx.effectSubmittedFrameIndex = submittedFrameIndex;
        ctx.effectRequestedRadiusPoints = backdropOutcome.requestedRadiusPoints;
        ctx.effectMode = backdropOutcome.mode;
        ctx.effectFallbackReason = backdropOutcome.reason;
        ctx.effectCompletion = CJGUI_INTERNAL_BACKDROP_COMPLETION_PENDING;
        // No pre-commit exit may publish a reusable content generation. Metal
        // completion failure separately invalidates its written targets.
        for (CJGuiInternalComposableEffectTarget *target in redrawnEffectTargets)
            target.needsRedraw = NO;
        for (CJGuiInternalComposableEffectTarget *target in redrawnBackdrops)
            target.needsRedraw = NO;
        for (CJGuiInternalComposableEffectTarget *target in redrawnBackdrops)
            target.lastRedrawnFrameIndex = submittedFrameIndex;
        view.frameIndex = submittedFrameIndex;
        view.lastSubmittedDrawableSize = drawableSize;
        view.lastSubmittedPointSize = view.bounds.size;
        ctx.windowBackgroundSubmittedFrameIndex = submittedFrameIndex;
        ctx.windowBackgroundSubmittedRequestRevision = submittedBackgroundRequestRevision;
        CjguiPublishAcceptedEffectCache(view);
 #ifdef CJGUI_INTERNAL_TESTING
        view.testComposableCommitMicros = CjguiMonotonicMicros() - commitStarted;
 #endif

        if (shouldProbe) {
            if (readbackBlitEncoded && readbackBuffer) {
 #ifdef CJGUI_INTERNAL_TESTING
                uint64_t readbackWaitStarted = CjguiMonotonicMicros();
 #endif
                [commandBuffer waitUntilCompleted];
 #ifdef CJGUI_INTERNAL_TESTING
                view.testComposableReadbackWaitMicros += CjguiMonotonicMicros() - readbackWaitStarted;
                view.testComposableReadbackWaited = 1;
 #endif
                commandBufferWaited = YES;
                readbackCompleted = commandBuffer.status == MTLCommandBufferStatusCompleted;
                if (readbackCompleted) {
                    const uint8_t *sample = (const uint8_t *)[readbackBuffer contents];
                    if (sample) {
                        uint8_t expectedBlue = CjguiColorChannelToByte(expectedReadbackColor.blue);
                        uint8_t expectedGreen = CjguiColorChannelToByte(expectedReadbackColor.green);
                        uint8_t expectedRed = CjguiColorChannelToByte(expectedReadbackColor.red);
                        uint8_t expectedAlpha = CjguiColorChannelToByte(expectedReadbackColor.alpha);
                        if (readbackSkippedNoDeterministicScenePixel) {
                            readbackDegradedReason = "no_deterministic_scene_pixel";
                            readbackHasDegraded = YES;
                        } else {
                            readbackMatched = CjguiColorByteMatches(sample[0], expectedBlue) &&
                                              CjguiColorByteMatches(sample[1], expectedGreen) &&
                                              CjguiColorByteMatches(sample[2], expectedRed) &&
                                              CjguiColorByteMatches(sample[3], expectedAlpha);
                        }
                        if (!readbackMatched && !readbackHasDegraded) {
                            readbackDegradedReason = sceneProbeNode ? "scene_color_mismatch" : "clear_color_mismatch";
                            readbackHasDegraded = YES;
                            readbackFailed = YES;
                            if (sceneProbeNode) {
                                CjguiInternalRendererComposableNode sceneValue = sceneProbeNode.node;
                                NSLog(@"cjgui: scene readback mismatch: node_index=%u node_id=%llu kind=%u logical=%.3f,%.3f drawable=%lux%lu sample=%lu,%lu node=%.0f,%.0f,%.0f,%.0f clip=%.0f,%.0f,%.0f,%.0f expected_bgra=%u,%u,%u,%u actual_bgra=%u,%u,%u,%u",
                                      sceneProbeNode.index, (unsigned long long)sceneValue.nodeId, sceneValue.nodeKind,
                                      (double)sceneProbePoint.logicalX, (double)sceneProbePoint.logicalY,
                                      (unsigned long)drawable.texture.width, (unsigned long)drawable.texture.height,
                                      (unsigned long)readbackSampleX, (unsigned long)readbackSampleY,
                                      (double)sceneValue.x, (double)sceneValue.y, (double)sceneValue.width, (double)sceneValue.height,
                                      (double)sceneValue.clipX, (double)sceneValue.clipY,
                                      (double)sceneValue.clipWidth, (double)sceneValue.clipHeight,
                                      expectedBlue, expectedGreen, expectedRed, expectedAlpha,
                                      sample[0], sample[1], sample[2], sample[3]);
                            }
                        }
                    } else {
                        readbackDegradedReason = "buffer_contents_unavailable";
                        readbackHasDegraded = YES;
                        readbackFailed = YES;
                    }
                } else {
                    readbackDegradedReason = "command_buffer_not_completed";
                    readbackHasDegraded = YES;
                    readbackFailed = YES;
                }
            } else if (!readbackHasDegraded) {
                readbackDegradedReason = "blit_not_encoded";
                readbackHasDegraded = YES;
                readbackFailed = YES;
            }

            NSLog(@"cjgui: metal readback: requested=true");
            NSLog(@"cjgui: metal readback: command_buffer_completed=%s",
                  readbackCompleted ? "true" : "false");
            NSLog(@"cjgui: metal readback: source=%s", readbackSkippedNoDeterministicScenePixel ? "none" :
                  (sceneProbeNode ? "composable_opaque_scene_probe" : "clear_color_probe"));
            NSLog(@"cjgui: metal readback: pixel_match=%s", readbackSkippedNoDeterministicScenePixel ? "unavailable" :
                  (readbackMatched ? "true" : "false"));
            NSLog(@"cjgui: metal readback: success=%s degraded=%s",
                  readbackMatched ? "true" : "false",
                  readbackHasDegraded ? readbackDegradedReason : "none");
            view.readbackProbeCompleted = YES;
        }

#ifdef CJGUI_INTERNAL_TESTING
        if (testDrawablePixelRequested) {
            if (!commandBufferWaited) {
 #ifdef CJGUI_INTERNAL_TESTING
                uint64_t readbackWaitStarted = CjguiMonotonicMicros();
 #endif
                [commandBuffer waitUntilCompleted];
 #ifdef CJGUI_INTERNAL_TESTING
                view.testComposableReadbackWaitMicros += CjguiMonotonicMicros() - readbackWaitStarted;
                view.testComposableReadbackWaited = 1;
 #endif
                commandBufferWaited = YES;
            }
            ctx.testDrawablePixelPending = NO;
            ctx.testDrawablePixelCompleted = NO;
            if (testDrawablePixelBlitEncoded && commandBuffer.status == MTLCommandBufferStatusCompleted) {
                const uint8_t *sample = (const uint8_t *)[testDrawablePixelBuffer contents];
                if (sample) {
                    ctx.testDrawablePixelBlue = sample[0];
                    ctx.testDrawablePixelGreen = sample[1];
                    ctx.testDrawablePixelRed = sample[2];
                    ctx.testDrawablePixelAlpha = sample[3];
                    ctx.testDrawablePixelCompleted = YES;
                }
            }
        }
#endif

        if (readbackCompleted) {
            ctx.observedMetalCompletionFrameIndex = view.frameIndex;
        }
        CGFloat scale = view.metalLayer.contentsScale;
        NSLog(@"cjgui: frame metadata: index=%llu drawable=%.0fx%.0f scale=%.2f pixel_format=%s clear_color=%.2f,%.2f,%.2f,%.2f submitted=true committed=unknown attempts=%llu success=true degraded=%s",
              (unsigned long long)view.frameIndex,
              (double)drawableSize.width,
              (double)drawableSize.height,
              (double)scale,
              "BGRA8Unorm",
              clearColor.red, clearColor.green, clearColor.blue, clearColor.alpha,
              (unsigned long long)view.frameIndex,
              readbackSkippedNoDeterministicScenePixel ? "no_deterministic_scene_pixel" :
              ((readbackFailed && readbackHasDegraded) ? readbackDegradedReason : "none"));

        if (view.frameIndex == 1) {
            NSLog(@"cjgui: first frame rendered");
        }

        if (outObservation) {
            outObservation->frameIndex = view.frameIndex;
            outObservation->drawableWidthPixels = (uint32_t)drawableSize.width;
            outObservation->drawableHeightPixels = (uint32_t)drawableSize.height;
            outObservation->contentsScale = scale;
            outObservation->readbackAttempted = shouldProbe ? 1 : 0;
            outObservation->readbackCompleted = readbackCompleted ? 1 : 0;
            outObservation->readbackColorMatched = readbackMatched ? 1 : 0;
        }

        if (shouldProbe && readbackFailed) {
            return CJGUI_INTERNAL_RENDERER_READBACK_FAILED;
        }
        return CJGUI_INTERNAL_RENDERER_OK;
        } @finally {
            // Also runs on every pre-commit failure. No partial command may
            // retain image generations as if it had been submitted.
            view.encodedImageTextures = nil;
        }
    }
}

// ---- ABI: generic composable command menu ----

static BOOL CjguiComposableCommandMenuStagingIsComplete(CJGuiInternalSession *ctx) {
    if (!ctx || ctx.stagedComposableCommandMenuVersion == 0) return NO;
    for (CJGuiInternalComposableCommandMenuItem *item in ctx.stagedComposableCommandMenuItems) {
        if (item.commandId.length == 0 || item.title.length == 0) return NO;
    }
    return YES;
}

static BOOL CjguiComposableCommandMenuItemsEqual(
    NSArray<CJGuiInternalComposableCommandMenuItem *> *left,
    NSArray<CJGuiInternalComposableCommandMenuItem *> *right) {
    if (left.count != right.count) return NO;
    for (NSUInteger index = 0; index < left.count; index++) {
        CJGuiInternalComposableCommandMenuItem *a = left[index];
        CJGuiInternalComposableCommandMenuItem *b = right[index];
        if (![a.commandId isEqualToString:b.commandId] || ![a.title isEqualToString:b.title] ||
            ![a.menuGroup isEqualToString:b.menuGroup] || ![a.shortcut isEqualToString:b.shortcut] ||
            a.menuSection != b.menuSection || a.focusScope != b.focusScope || a.enabled != b.enabled ||
            a.checked != b.checked) {
            return NO;
        }
    }
    return YES;
}

static uint64_t CjguiComposableCommandMenuActiveFocusScope(CJGuiInternalSession *ctx) {
    CJGuiInternalComposableSceneNode *active = [ctx.composableSceneOverlay activeFocusableNode];
    return active ? active.node.inputScope : 0;
}

static BOOL CjguiCommitStagedComposableCommandMenu(CJGuiInternalSession *ctx) {
    BOOL changed = !CjguiComposableCommandMenuItemsEqual(
        ctx.composableCommandMenuItems, ctx.stagedComposableCommandMenuItems);
    ctx.composableCommandMenuItems = [ctx.stagedComposableCommandMenuItems mutableCopy] ?: [NSMutableArray array];
    ctx.composableCommandMenuVersion = ctx.stagedComposableCommandMenuVersion;
    return changed;
}

static CjguiInternalRendererStatus CjguiConfigureComposableCommandMenuOnMain(
    uint64_t session, uint64_t projectionVersion, uint32_t itemCount) {
    if (projectionVersion == 0 || itemCount > 128) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.window || ctx.destroyed) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    NSMutableArray<CJGuiInternalComposableCommandMenuItem *> *staged =
        [NSMutableArray arrayWithCapacity:itemCount];
    for (uint32_t index = 0; index < itemCount; index++) {
        CJGuiInternalComposableCommandMenuItem *item = [[CJGuiInternalComposableCommandMenuItem alloc] init];
        if (!item) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        item.commandId = @""; item.title = @""; item.menuGroup = @""; item.shortcut = @"";
        item.menuSection = 0; item.enabled = NO; item.checked = NO;
        [staged addObject:item];
    }
    ctx.stagedComposableCommandMenuItems = staged;
    ctx.stagedComposableCommandMenuVersion = projectionVersion;
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_configure_composable_command_menu(
    uint64_t session, uint64_t projectionVersion, uint32_t itemCount) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiConfigureComposableCommandMenuOnMain(session, projectionVersion, itemCount);
        });
        return status;
    }
    return CjguiConfigureComposableCommandMenuOnMain(session, projectionVersion, itemCount);
}

static CjguiInternalRendererStatus CjguiSetComposableCommandMenuItemOnMain(
    uint64_t session, uint32_t itemIndex, const char *commandId, const char *title,
    const char *menuGroup, const char *shortcut, uint32_t menuSection, uint64_t focusScope, uint8_t enabled,
    uint8_t checked) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (ctx.destroyed || itemIndex >= ctx.stagedComposableCommandMenuItems.count || !commandId || !title ||
        !menuGroup || !shortcut || ctx.stagedComposableCommandMenuVersion == 0) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    NSString *nativeCommandId = [NSString stringWithUTF8String:commandId];
    NSString *nativeTitle = [NSString stringWithUTF8String:title];
    NSString *nativeMenuGroup = [NSString stringWithUTF8String:menuGroup];
    NSString *nativeShortcut = [NSString stringWithUTF8String:shortcut];
    if (nativeCommandId.length == 0 || nativeTitle.length == 0 || !nativeMenuGroup || !nativeShortcut) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CJGuiInternalComposableCommandMenuItem *item = ctx.stagedComposableCommandMenuItems[itemIndex];
    item.commandId = nativeCommandId;
    item.title = nativeTitle;
    item.menuGroup = nativeMenuGroup;
    item.shortcut = nativeShortcut;
    item.menuSection = menuSection;
    item.focusScope = focusScope;
    item.enabled = enabled != 0;
    item.checked = checked != 0;
    return CJGUI_INTERNAL_RENDERER_OK;
}

