static CjguiInternalRendererStatus CjguiSetComposableSceneNodeOnMain(
    uint64_t session, uint32_t nodeIndex, const CjguiInternalRendererComposableNode *node,
    const char *label, const char *value, const char *imageResourcePath,
    const char *imageResourceId, uint64_t imageResourceVersion, NSData *imageEncodedData) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    if (!node || nodeIndex >= ctx.stagedComposableNodes.count || node->projectionVersion != ctx.stagedComposableSceneVersion ||
        node->width < 0 || node->height < 0 || node->clipWidth < 0 || node->clipHeight < 0) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
#ifdef CJGUI_INTERNAL_TESTING
    if (ctx.forcedComposableSceneNodeFailures > 0) {
        ctx.forcedComposableSceneNodeFailures -= 1;
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
#endif
    CJGuiInternalComposableSceneNode *copy = ctx.stagedComposableNodes[nodeIndex];
    // A setter is the COW boundary. It runs only for Cangjie nodes whose
    // rendered/input state changed, so untouched staged entries still point
    // to the accepted live snapshot and cannot be mutated by this candidate.
    CJGuiInternalComposableSceneNode *live = nodeIndex < ctx.composableNodes.count
        ? ctx.composableNodes[nodeIndex] : nil;
    if (copy == live) {
        copy = CjguiCloneComposableSceneNode(ctx, live, nodeIndex, node->projectionVersion);
        if (!copy) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        ctx.stagedComposableNodes[nodeIndex] = copy;
    }
    copy.node = *node; copy.index = nodeIndex;
    if (ctx.composableSceneNodeUpdateCount < UINT64_MAX) ctx.composableSceneNodeUpdateCount += 1;
    if (copy.node.preservesActiveLocalText != 0 && copy.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
        ctx.composableLocalAcknowledgementCount += 1;
    }
    copy.label = label ? [NSString stringWithUTF8String:label] : @"";
    copy.value = value ? [NSString stringWithUTF8String:value] : @"";
    copy.imageResourcePath = imageResourcePath ? [NSString stringWithUTF8String:imageResourcePath] : @"";
    copy.imageEncodedData = [imageEncodedData copy];
    if ([copy.imageResourcePath hasPrefix:@"cjgui-transfer:"] &&
        (copy.imageEncodedData.length == 0 || copy.imageEncodedData.length > 512u * 1024u)) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    copy.imageResourceId = imageResourceId ? [NSString stringWithUTF8String:imageResourceId] : copy.imageResourcePath;
    copy.imageResourceVersion = imageResourceVersion;
    if (copy.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_VECTOR_GRAPHIC) {
        CjguiInternalComposableVectorGeometry geometry = {0};
        if (!CjguiParseComposableVectorGeometry(copy.value, &geometry)) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        // Local triangles are independent of paint but not of path/stroke
        // geometry. Keep a COW-reused cache only through paint/layout/clip
        // changes; a changed path gets exactly one new preparation on draw.
        if (!copy.hasVectorPreparedGeometry ||
            !CjguiComposableVectorPreparationGeometryEquals(copy.vectorPreparedGeometry, geometry)) {
            copy.vectorPreparedTriangles = nil;
            copy.vectorPreparedVertexBuffer = nil;
            copy.vectorPreparedVertexCount = 0;
            copy.vectorPreparedVertexBytes = 0;
            copy.hasVectorPreparedGeometry = NO;
            CjguiInternalComposableVectorGeometry emptyPreparedGeometry = {0};
            copy.vectorPreparedGeometry = emptyPreparedGeometry;
        }
        copy.vectorGeometry = geometry;
        copy.hasVectorGeometry = YES;
    } else {
        copy.hasVectorGeometry = NO;
        CjguiInternalComposableVectorGeometry emptyGeometry = {0};
        copy.vectorGeometry = emptyGeometry;
        copy.vectorPreparedTriangles = nil;
        copy.vectorPreparedVertexBuffer = nil;
        copy.vectorPreparedVertexCount = 0;
        copy.vectorPreparedVertexBytes = 0;
        copy.hasVectorPreparedGeometry = NO;
        copy.vectorPreparedGeometry = emptyGeometry;
    }
    if (copy.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_IMAGE) {
        NSString *resolved = nil;
        NSString *declaredCacheKey = CjguiComposableImageCacheKey(copy.imageResourcePath, copy.imageResourceId,
                                                                   copy.imageResourceVersion, &resolved);
        id<MTLTexture> previousTexture = copy.imageTexture;
        if (declaredCacheKey && previousTexture && [copy.imageTextureContentKey isEqualToString:declaredCacheKey]) {
            // A cache eviction drops only reuse ownership. The live/staged
            // node already has the exact declared texture, so a completion
            // for some other resource must not start it again.
            copy.imageTextureCacheKey = declaredCacheKey;
        } else {
        NSString *cacheKey = nil;
        uint32_t resourceState = CjguiComposableImageResourceFailed;
        id<MTLTexture> texture = CjguiComposableImageTexture(ctx, session, copy.imageResourcePath,
            copy.imageResourceId, copy.imageResourceVersion, copy.imageEncodedData, &cacheKey, &resourceState);
        copy.imageTextureCacheKey = cacheKey ?: @"";
        // Loading/failed resources are accepted projection states, never a
        // reason to reject a user action. Preserve a prior texture as a
        // visible fallback until the keyed completion causes one normal
        // refresh; a first load renders its declared fill/placeholder only.
            if (texture) {
                copy.imageTexture = texture;
                copy.imageTextureContentKey = cacheKey ?: @"";
            } else if (!previousTexture) {
                copy.imageTexture = nil;
                copy.imageTextureContentKey = @"";
            }
        }
    } else {
        copy.imageTexture = nil; copy.imageTextureCacheKey = @""; copy.imageTextureContentKey = @"";
    }
#ifdef CJGUI_INTERNAL_TESTING
    ctx.testComposableSceneSetMicros += CjguiMonotonicMicros() - started;
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_set_composable_scene_node(
    uint64_t session, uint32_t nodeIndex, const CjguiInternalRendererComposableNode *node,
    const char *label, const char *value, const char *imageResourcePath,
    const char *imageResourceId, uint64_t imageResourceVersion) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiSetComposableSceneNodeOnMain(session, nodeIndex, node, label, value, imageResourcePath,
                                                        imageResourceId, imageResourceVersion, nil);
        });
        return status;
    }
    return CjguiSetComposableSceneNodeOnMain(session, nodeIndex, node, label, value, imageResourcePath,
                                              imageResourceId, imageResourceVersion, nil);
}

CjguiInternalRendererStatus cjgui_internal_renderer_set_composable_scene_node_bytes(
    uint64_t session, uint32_t nodeIndex, const CjguiInternalRendererComposableNode *node,
    const char *label, const char *value, const char *imageResourcePath,
    const char *imageResourceId, uint64_t imageResourceVersion,
    const uint8_t *bytes, uint32_t length) {
    if (!bytes || length == 0 || length > 512u * 1024u) return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    // Copy before crossing to another thread; the Cangjie raw-array borrow
    // ends when this call returns, never in the dispatched block.
    NSData *encoded = [NSData dataWithBytes:bytes length:length];
    if (!encoded) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiSetComposableSceneNodeOnMain(session, nodeIndex, node, label, value,
                imageResourcePath, imageResourceId, imageResourceVersion, encoded);
        });
        return status;
    }
    return CjguiSetComposableSceneNodeOnMain(session, nodeIndex, node, label, value,
        imageResourcePath, imageResourceId, imageResourceVersion, encoded);
}

// Stores the accepted public semantic identity of one staged composable node.
// The identity is what a human-facing driver or assistant addresses an instance
// by; the rendered caption is only a projection and two instances can share it.
// This is a separate entry point so every existing node-setter caller (probes,
// native tests, the platform lab copy) keeps its signature.
static CjguiInternalRendererStatus CjguiSetComposableNodeSemanticIdentityOnMain(
    uint64_t session, uint32_t nodeIndex, const char *semanticId) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (nodeIndex >= ctx.stagedComposableNodes.count) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneNode *copy = ctx.stagedComposableNodes[nodeIndex];
    CJGuiInternalComposableSceneNode *live = nodeIndex < ctx.composableNodes.count
        ? ctx.composableNodes[nodeIndex] : nil;
    // Same COW boundary as the node setter: an identity update must never mutate
    // a snapshot the accepted scene still presents.
    if (copy == live) {
        copy = CjguiCloneComposableSceneNode(ctx, live, nodeIndex,
                                            live ? live.node.projectionVersion : 0);
        if (!copy) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        ctx.stagedComposableNodes[nodeIndex] = copy;
    }
    copy.semanticId = semanticId ? [NSString stringWithUTF8String:semanticId] : @"";
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_set_composable_node_semantic_identity(uint64_t session, uint32_t nodeIndex,
                                                              const char *semanticId) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiSetComposableNodeSemanticIdentityOnMain(session, nodeIndex, semanticId);
        });
        return status;
    }
    return CjguiSetComposableNodeSemanticIdentityOnMain(session, nodeIndex, semanticId);
}

static CjguiInternalRendererStatus CjguiSetComposableNodeSemanticMetadataOnMain(
    uint64_t session, uint32_t nodeIndex, const char *bindingKey, const char *rowKey,
    const char *parentRowKey, const char *semanticLabel) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx) return CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    if (nodeIndex >= ctx.stagedComposableNodes.count) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneNode *copy = ctx.stagedComposableNodes[nodeIndex];
    CJGuiInternalComposableSceneNode *live = nodeIndex < ctx.composableNodes.count
        ? ctx.composableNodes[nodeIndex] : nil;
    if (copy == live) {
        copy = CjguiCloneComposableSceneNode(ctx, live, nodeIndex,
                                            live ? live.node.projectionVersion : 0);
        if (!copy) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        ctx.stagedComposableNodes[nodeIndex] = copy;
    }
    copy.semanticBindingKey = bindingKey ? [NSString stringWithUTF8String:bindingKey] : @"";
    copy.semanticRowKey = rowKey ? [NSString stringWithUTF8String:rowKey] : @"";
    copy.semanticParentRowKey = parentRowKey ? [NSString stringWithUTF8String:parentRowKey] : @"";
    copy.semanticLabel = semanticLabel ? [NSString stringWithUTF8String:semanticLabel] : @"";
    if (!copy.semanticBindingKey || !copy.semanticRowKey || !copy.semanticParentRowKey || !copy.semanticLabel) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    return CJGUI_INTERNAL_RENDERER_OK;
}

CjguiInternalRendererStatus cjgui_internal_renderer_set_composable_node_semantic_metadata(
    uint64_t session, uint32_t nodeIndex, const char *bindingKey, const char *rowKey,
    const char *parentRowKey, const char *semanticLabel) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = CjguiSetComposableNodeSemanticMetadataOnMain(session, nodeIndex, bindingKey, rowKey,
                                                                  parentRowKey, semanticLabel);
        });
        return status;
    }
    return CjguiSetComposableNodeSemanticMetadataOnMain(session, nodeIndex, bindingKey, rowKey, parentRowKey,
                                                        semanticLabel);
}

CjguiInternalRendererStatus
cjgui_internal_renderer_focus_composable_node(uint64_t session, uint64_t nodeId) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_focus_composable_node(session, nodeId);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    return [ctx.composableSceneOverlay focusCommittedNodeId:nodeId]
        ? CJGUI_INTERNAL_RENDERER_OK : CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_restore_composable_selection(uint64_t session, uint64_t nodeId,
                                                     int64_t resourceId, uint32_t nodeKind,
                                                     uint64_t sceneVersion, const char *expectedValue,
                                                     uint32_t selectionStart, uint32_t selectionEnd,
                                                     uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !expectedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_restore_composable_selection(session, nodeId, resourceId, nodeKind,
                sceneVersion, expectedValue, selectionStart, selectionEnd, outSelectionStart, outSelectionEnd);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.composableSceneVersion != sceneVersion || selectionEnd < selectionStart ||
        (nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
         nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *expected = [NSString stringWithUTF8String:expectedValue];
    if (!expected || overlay.inputProxy.hasMarkedText || ctx.window.firstResponder != overlay.inputProxy) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0 ||
            overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        if (![node.value isEqualToString:expected] || ![overlay.inputProxy.string isEqualToString:expected] ||
            selectionStart > expected.length || selectionEnd > expected.length) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange applied = CjguiComposedSelection(expected, selectionStart, selectionEnd);
        overlay.applyingProjection = YES;
        overlay.inputProxy.selectedRange = applied;
        overlay.applyingProjection = NO;
        applied = overlay.inputProxy.selectedRange;
        if (applied.location > UINT32_MAX || NSMaxRange(applied) > UINT32_MAX) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        *outSelectionStart = (uint32_t)applied.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(applied);
        [overlay revealActiveMultilineCaret:node];
#ifdef CJGUI_INTERNAL_TESTING
        overlay.testActiveTextWorkReason = CjguiInternalTextWorkReasonSelectionCaret;
#endif
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_read_composable_selection(uint64_t session, uint64_t nodeId,
                                                  int64_t resourceId, uint32_t nodeKind,
                                                  uint64_t sceneVersion, const char *expectedValue,
                                                  uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !expectedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_read_composable_selection(session, nodeId, resourceId, nodeKind,
                sceneVersion, expectedValue, outSelectionStart, outSelectionEnd);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (ctx.composableSceneVersion != sceneVersion) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *expected = [NSString stringWithUTF8String:expectedValue];
    if (!expected || ctx.window.firstResponder != overlay.inputProxy || overlay.inputProxy.hasMarkedText) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0 ||
            overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        if (![node.value isEqualToString:expected] || ![overlay.inputProxy.string isEqualToString:expected]) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange selected = overlay.inputProxy.selectedRange;
        if (selected.location > UINT32_MAX || NSMaxRange(selected) > UINT32_MAX) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        *outSelectionStart = (uint32_t)selected.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(selected);
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}


// Roll back the hidden text proxy after the application REFUSED a range edit.
//
// A refused edit leaves the platform proxy holding local text the owner never
// accepted. The ordinary projection path cannot repair it: the Cangjie scene is
// unchanged (so the semantic fast path and per-node reuse skip staging), and the
// native value check treats "candidate == previous value" plus "proxy != previous
// value" as a local edit that must be preserved. This entry repairs exactly that
// transient state:
//   - the target must still be the ACTIVE node with the same identity and
//     projection version,
//   - the accepted value must still be the value the committed node carries,
//   - no composition may be in flight.
// It installs the accepted text under projection suppression (so no synthetic
// human edit event is produced), installs a grapheme-safe collapsed caret, and
// invalidates the derived text resources, accessibility value and paint. It
// never invents document truth: it only restores what the owner already
// accepted. Returns the installed UTF-16 selection through the out parameters.
CjguiInternalRendererStatus
cjgui_internal_renderer_recover_active_text_proxy(uint64_t session, uint64_t nodeId,
                                                  int64_t resourceId, uint32_t nodeKind,
                                                  const char *acceptedValue,
                                                  uint32_t *outSelectionStart, uint32_t *outSelectionEnd) {
    if (!outSelectionStart || !outSelectionEnd || !acceptedValue) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    *outSelectionStart = 0; *outSelectionEnd = 0;
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_recover_active_text_proxy(session, nodeId, resourceId, nodeKind,
                acceptedValue, outSelectionStart, outSelectionEnd);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay || !ctx.window) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_INTEGER_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT &&
        nodeKind != CJGUI_INTERNAL_RENDERER_COMPOSABLE_TEXT) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CJGuiInternalComposableSceneOverlay *overlay = ctx.composableSceneOverlay;
    NSString *accepted = [NSString stringWithUTF8String:acceptedValue];
    if (!accepted) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    // Never clobber an in-flight composition, and never repair an unfocused
    // node: the intent only ever describes the active speculative edit.
    if (overlay.inputProxy.hasMarkedText || ctx.window.firstResponder != overlay.inputProxy) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    for (CJGuiInternalComposableSceneNode *node in ctx.composableNodes) {
        if (node.node.nodeId != nodeId || node.node.resourceId != resourceId ||
            node.node.nodeKind != nodeKind || node.node.isInteractive == 0 || node.node.isReadOnly != 0 ||
            overlay.activeNodeId != nodeId || overlay.activeNodeIndex != node.index ||
            overlay.activeNodeResourceId != resourceId || overlay.activeNodeKind != nodeKind ||
            overlay.activeProjectionVersion != node.node.projectionVersion) continue;
        // The committed node is the accepted truth; anything else means the
        // scene moved on and the caller must use the normal projection path.
        if (![node.value isEqualToString:accepted]) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        NSRange applied = CjguiComposedSelection(accepted, accepted.length, accepted.length);
        overlay.applyingProjection = YES;
        overlay.inputProxy.string = accepted;
        overlay.inputProxy.selectedRange = applied;
        overlay.applyingProjection = NO;
        overlay.activeTextFallbackHasPendingEdit = NO;
        overlay.activeTextRangeEditPending = NO;
        // The accepted value is installed below, so nothing is awaiting the owner any more.
        overlay.activeLocalEditAwaitingOwner = NO;
        overlay.activeLocalEditProjectionVersion = 0;
        overlay.activeTextLayoutNeedsVisibleGlyphs = YES;
        overlay.activeTextHasExactContentHeight = NO;
        if (node.node.nodeKind == CJGUI_INTERNAL_RENDERER_COMPOSABLE_MULTILINE_TEXT_INPUT) {
            [overlay markActiveTextFallbackRunsDirtyForWholeValue];
        }
        applied = overlay.inputProxy.selectedRange;
        if (applied.location > UINT32_MAX || NSMaxRange(applied) > UINT32_MAX) {
            return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
        }
        *outSelectionStart = (uint32_t)applied.location;
        *outSelectionEnd = (uint32_t)NSMaxRange(applied);
        [overlay postAccessibilityValueChangedForNode:node];
        [overlay postAccessibilitySelectionChangedForNode:node];
        [overlay refreshGpuTextForActiveInput];
        [overlay setNeedsDisplay:YES];
        return CJGUI_INTERNAL_RENDERER_OK;
    }
    return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
}

CjguiInternalRendererStatus
cjgui_internal_renderer_cancel_composable_pointer_capture(uint64_t session) {
    if (!CjguiIsMainThread()) {
        if (!gCjguiMainThreadDispatchEnabled) return CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        __block CjguiInternalRendererStatus status = CJGUI_INTERNAL_RENDERER_NOT_MAIN_THREAD;
        dispatch_sync(dispatch_get_main_queue(), ^{
            status = cjgui_internal_renderer_cancel_composable_pointer_capture(session);
        });
        return status;
    }
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.composableSceneOverlay) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    [ctx.composableSceneOverlay cancelPointerCapture];
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiCommitComposableSceneOnMain(uint64_t session) {
    CJGuiInternalSession *ctx = CjguiLookupSession(session);
    if (!ctx || !ctx.view || !ctx.composableSceneOverlay || ctx.stagedComposableNodes.count == 0) {
        return ctx ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
#ifdef CJGUI_INTERNAL_TESTING
    uint64_t started = CjguiMonotonicMicros();
#endif
    for (CJGuiInternalComposableSceneNode *node in ctx.stagedComposableNodes) {
        // Reused COW entries intentionally keep their original capture
        // version. Only a never-initialized slot is invalid; native FIFO
        // provenance comes from the committed session version below.
        if (node.node.projectionVersion == 0) return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    CjguiInternalRendererStatus effectTopology = CjguiValidateEffectGroupTopology(ctx.stagedComposableNodes);
    if (effectTopology != CJGUI_INTERNAL_RENDERER_OK) return effectTopology;
    if (ctx.stagedComposableCommandMenuVersion != 0 &&
        (ctx.stagedComposableCommandMenuVersion != ctx.stagedComposableSceneVersion ||
         !CjguiComposableCommandMenuStagingIsComplete(ctx))) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    if (ctx.stagedComposableDataTransferVersion != ctx.stagedComposableSceneVersion) {
        return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
    }
    for (CJGuiInternalComposableDataTransferItem *item in ctx.stagedComposableDataTransferItems) {
        CjguiInternalRendererComposableDataTransferItem itemValue = item.item;
        if (!CjguiComposableDataTransferFormatIsValid(item.format) ||
            itemValue.projectionVersion != ctx.stagedComposableSceneVersion ||
            !CjguiComposableStagedNodeMatchesDataTransferItem(ctx, &itemValue)) {
            return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
        }
        NSData *payload = [item.payload dataUsingEncoding:NSUTF8StringEncoding];
        BOOL png = [item.format isEqualToString:@"image/png"];
        if (!payload || payload.length > item.item.maximumPayloadBytes ||
            (png && item.item.bindingEpoch == 0) ||
            (png && item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE &&
             (item.binaryPayload.length == 0 || item.binaryPayload.length > item.item.maximumPayloadBytes)) ||
            (png && item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET && item.binaryPayload.length != 0) ||
            (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_TARGET && (payload.length != 0 ||
             item.sourceKind.length != 0 || item.sourceIdentity.length != 0 || item.item.sourceId >= 0)) ||
            (item.item.role == CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_SOURCE && (item.sourceKind.length == 0 ||
             item.sourceIdentity.length == 0 || item.item.sourceId < 0))) {
            return CJGUI_INTERNAL_RENDERER_DATA_TRANSFER_REJECTED;
        }
    }
    // Text resources are prepared while admitting the immutable scene, never
    // from the Metal encoder.  This keeps AppKit text shaping out of the
    // frame-critical command-buffer path and lets the encoder only reuse a
    // committed texture.
    CjguiInternalRendererStatus textStatus = CjguiPrepareComposableTextResources(ctx);
    if (textStatus != CJGUI_INTERNAL_RENDERER_OK) return textStatus;
    BOOL imageContentChanged = CjguiComposableImageContentChanged(ctx.composableNodes, ctx.stagedComposableNodes);
    uint64_t previousMenuFocusScope = CjguiComposableCommandMenuActiveFocusScope(ctx);
    BOOL menuProjectionChanged = NO;
    ctx.composableSceneVersion = ctx.stagedComposableSceneVersion;
    ctx.composableNodes = [ctx.stagedComposableNodes mutableCopy];
    ctx.composableDataTransferItems = [ctx.stagedComposableDataTransferItems mutableCopy];
    ctx.composableDataTransferVersion = ctx.stagedComposableDataTransferVersion;
#ifdef CJGUI_INTERNAL_TESTING
    CjguiUpdateTestDataTransferRetentionPeaks(ctx);
#endif
    if (ctx.stagedComposableCommandMenuVersion == ctx.composableSceneVersion) {
        menuProjectionChanged = CjguiCommitStagedComposableCommandMenu(ctx);
    }
    // This is the only promotion boundary for image subscribers. Candidate
    // configure/set failures and present rollback keep the old committed
    // subscriptions intact, while the newly accepted scene replaces them
    // atomically before a later completion can wake this window.
    CjguiReconcileCommittedComposableImageSubscribers(ctx);
    CjguiPruneComposableImageTextureCache(CjguiComposableImageDomainForSession(ctx), NO);
    ctx.view.composableNodes = [ctx.composableNodes copy];
    if (imageContentChanged) {
        ctx.view.readbackProbeCompleted = NO;
    }
    // A readback is a first-frame rendering diagnostic, not normal editing
    // work. Scene updates still submit Metal commands, but do not force a
    // synchronous GPU readback after every keystroke or lightweight refresh.
    ctx.sharedOperationOverlay.hidden = YES;
    ctx.sharedEditingFormOverlay.hidden = YES;
    // The renderer may encode this candidate, but AppKit input/AX is still
    // owned by the prior accepted scene until present returns success. A
    // pre-commit encoder failure must not publish focus or AX notifications.
    uint64_t currentMenuFocusScope = CjguiComposableCommandMenuActiveFocusScope(ctx);
    if (ctx.window == NSApp.keyWindow &&
        (menuProjectionChanged || previousMenuFocusScope != currentMenuFocusScope)) {
        CjguiRebuildComposableCommandMenuForKeyWindow();
    }
    // Title ownership is the application-host configuration. A scene commit
    // may refresh business content but must not overwrite that declaration.
#ifdef CJGUI_INTERNAL_TESTING
    ctx.testComposableSceneCommitMicros += CjguiMonotonicMicros() - started;
#endif
    return CJGUI_INTERNAL_RENDERER_OK;
}

static CjguiInternalRendererStatus CjguiStageWindowBackgroundOnMain(uint64_t sessionToken,
                                                                     uint64_t projectionVersion,
                                                                     uint32_t mode,
                                                                     uint32_t colorScheme) {
    CJGuiInternalSession *session = CjguiLookupSession(sessionToken);
    if (!session || session.destroyed || !session.window) {
        return session ? CJGUI_INTERNAL_RENDERER_VIEW_INVALIDATED : CJGUI_INTERNAL_RENDERER_INVALID_SESSION;
    }
    if (projectionVersion == 0 || mode > CJGUI_INTERNAL_WINDOW_BACKGROUND_SYSTEM_CONTENT_AREA ||
        (colorScheme != 1 && colorScheme != 2)) {
        return CJGUI_INTERNAL_RENDERER_INTERNAL_ERROR;
    }
    session.stagedWindowBackgroundVersion = projectionVersion;
    session.stagedWindowBackgroundMode = mode;
    session.stagedWindowBackgroundColorScheme = colorScheme;
    session.stagedWindowBackgroundRequestRevision = session.windowBackgroundRequestRevision +
        ((session.windowBackgroundRequestedMode != mode ||
          session.windowBackgroundColorScheme != colorScheme) ? 1u : 0u);
    session.hasStagedWindowBackground = YES;
    return CJGUI_INTERNAL_RENDERER_OK;
}

